INSERT INTO dialogue_role (id,lesson_id,code,name_vi,name_ja,description,voice_code) SELECT 7400000000+dr.id,7000001018,dr.code,dr.name_vi,dr.name_ja,dr.description,dr.voice_code FROM dialogue_role dr WHERE dr.lesson_id=@dialogue_src_n3 ON DUPLICATE KEY UPDATE name_vi=VALUES(name_vi),name_ja=VALUES(name_ja),description=VALUES(description),voice_code=VALUES(voice_code);
INSERT INTO lesson_section (id,lesson_id,title,section_type,order_index) SELECT DISTINCT 7400000000+ls.id,7000001018,ls.title,ls.section_type,100+ls.order_index FROM lesson_section ls JOIN content_item ci ON ci.section_id=ls.id JOIN dialogue_line_detail d ON d.content_item_id=ci.id WHERE ls.lesson_id=@dialogue_src_n3 ON DUPLICATE KEY UPDATE title=VALUES(title),order_index=VALUES(order_index);
INSERT INTO content_item (id,section_id,content_type,topic_tag_id,title,content,translated_text,order_index) SELECT 7400000000+ci.id,7400000000+ci.section_id,ci.content_type,ci.topic_tag_id,ci.title,ci.content,ci.translated_text,ci.order_index FROM content_item ci JOIN lesson_section ls ON ls.id=ci.section_id JOIN dialogue_line_detail d ON d.content_item_id=ci.id WHERE ls.lesson_id=@dialogue_src_n3 ON DUPLICATE KEY UPDATE title=VALUES(title),content=VALUES(content),translated_text=VALUES(translated_text),order_index=VALUES(order_index);
INSERT INTO dialogue_line_detail (content_item_id,dialogue_role_id,scene_code,bubble_side,bubble_x,bubble_y) SELECT 7400000000+d.content_item_id,CASE WHEN d.dialogue_role_id IS NULL THEN NULL ELSE 7400000000+d.dialogue_role_id END,d.scene_code,d.bubble_side,d.bubble_x,d.bubble_y FROM dialogue_line_detail d JOIN content_item ci ON ci.id=d.content_item_id JOIN lesson_section ls ON ls.id=ci.section_id WHERE ls.lesson_id=@dialogue_src_n3 ON DUPLICATE KEY UPDATE dialogue_role_id=VALUES(dialogue_role_id),scene_code=VALUES(scene_code),bubble_side=VALUES(bubble_side);
INSERT INTO dialogue_line_chunk (id,content_item_id,order_index,surface,meaning_vi) SELECT 7400000000+c.id,7400000000+c.content_item_id,c.order_index,c.surface,c.meaning_vi FROM dialogue_line_chunk c JOIN content_item ci ON ci.id=c.content_item_id JOIN lesson_section ls ON ls.id=ci.section_id WHERE ls.lesson_id=@dialogue_src_n3 ON DUPLICATE KEY UPDATE surface=VALUES(surface),meaning_vi=VALUES(meaning_vi);
INSERT INTO content_audio (id,owner_type,owner_id,voice_code,audio_url,merged_url,start_ms,end_ms) SELECT 7400000000+a.id,a.owner_type,7400000000+a.owner_id,a.voice_code,a.audio_url,a.merged_url,a.start_ms,a.end_ms FROM content_audio a JOIN content_item ci ON a.owner_type='CONTENT_ITEM' AND ci.id=a.owner_id JOIN dialogue_line_detail d ON d.content_item_id=ci.id JOIN lesson_section ls ON ls.id=ci.section_id WHERE ls.lesson_id=@dialogue_src_n3 ON DUPLICATE KEY UPDATE audio_url=VALUES(audio_url),merged_url=VALUES(merged_url);
INSERT INTO assessment_question (source_code,conversion_rule_id,knowledge_tag_id,topic_tag_id,outcome_id,grammar_point_id,vocabulary_entry_id,skill,jlpt_level,difficulty,question_type,title,passage_html,audio_url,image_url,question_text,answer_text,option_1,option_2,option_3,option_4,correct_option,explanation,context_json,quiz_id,order_index,is_active) SELECT CONCAT('LP-OWNED-JLAS-N3-C18-READ-P1',SUBSTRING(q.source_code,30)),q.conversion_rule_id,q.knowledge_tag_id,q.topic_tag_id,q.outcome_id,q.grammar_point_id,q.vocabulary_entry_id,q.skill,q.jlpt_level,q.difficulty,q.question_type,q.title,q.passage_html,q.audio_url,q.image_url,q.question_text,q.answer_text,q.option_1,q.option_2,q.option_3,q.option_4,q.correct_option,q.explanation,JSON_SET(COALESCE(q.context_json,'{}'),'$.compiled_from',q.source_code,'$.labels',CAST(CONVERT(X'' USING utf8mb4) AS JSON)),q.quiz_id,q.order_index,1 FROM assessment_question q WHERE q.source_code LIKE 'LP-OWNED-SPEED-N3-C18-READ-P1-%' AND q.is_active=1 ON DUPLICATE KEY UPDATE knowledge_tag_id=VALUES(knowledge_tag_id),skill=VALUES(skill),jlpt_level=VALUES(jlpt_level),difficulty=VALUES(difficulty),question_type=VALUES(question_type),title=VALUES(title),passage_html=VALUES(passage_html),audio_url=VALUES(audio_url),image_url=VALUES(image_url),question_text=VALUES(question_text),answer_text=VALUES(answer_text),option_1=VALUES(option_1),option_2=VALUES(option_2),option_3=VALUES(option_3),option_4=VALUES(option_4),correct_option=VALUES(correct_option),explanation=VALUES(explanation),context_json=VALUES(context_json),is_active=1;
