INSERT INTO `jpath_level` (`level`, `sort_order`) VALUES
('N3', 3)
INSERT INTO `jpath_skill_type` (`code`, `level`, `skill`, `name_vi`, `name_ja`, `sort_order`, `questions_in_exam`, `needs_image`, `chars_min`, `chars_max`, `speakers`, `seconds_typical`, `seed_version`) VALUES
('N3-R-SHORT', 'N3', 'READING', 'Đọc hiểu đoạn văn ngắn', '内容理解（短文）', 1, 4, 0, 150, 250, NULL, NULL, 'bc8b069c0ce9'),
('N3-R-MEDIUM', 'N3', 'READING', 'Đọc hiểu đoạn văn trung bình', '内容理解（中文）', 2, 6, 0, 330, 520, NULL, NULL, 'bc8b069c0ce9'),
('N3-R-LONG', 'N3', 'READING', 'Đọc hiểu đoạn văn dài', '内容理解（長文）', 3, 4, 0, 550, 850, NULL, NULL, 'bc8b069c0ce9'),
('N3-R-INFO', 'N3', 'READING', 'Tìm kiếm thông tin', '情報検索', 4, 2, 0, 380, 720, NULL, NULL, 'bc8b069c0ce9'),
('N3-L-TASK', 'N3', 'LISTENING', 'Nghe hiểu nhiệm vụ', '課題理解', 1, 6, 0, NULL, NULL, 2, 65, 'bc8b069c0ce9'),
('N3-L-POINT', 'N3', 'LISTENING', 'Nghe hiểu điểm chính', 'ポイント理解', 2, 6, 0, NULL, NULL, 2, 65, 'bc8b069c0ce9'),
('N3-L-SUMMARY', 'N3', 'LISTENING', 'Nghe hiểu khái quát', '概要理解', 3, 3, 0, NULL, NULL, 1, 60, 'bc8b069c0ce9'),
('N3-L-UTTERANCE', 'N3', 'LISTENING', 'Biểu đạt phát ngôn', '発話表現', 4, 4, 1, NULL, NULL, 1, 30, 'bc8b069c0ce9'),
('N3-L-RESPONSE', 'N3', 'LISTENING', 'Phản xạ tức thời', '即時応答', 5, 9, 0, NULL, NULL, 2, 20, 'bc8b069c0ce9')
INSERT INTO `jpath_skill_lesson` (`type_code`, `title_vi`, `goal_vi`, `steps_json`, `traps_json`, `tips_json`, `example_json`, `example_answer_index`, `check_question_vi`, `check_options_json`, `check_answer_index`, `check_explanation_vi`, `example_audio_path`, `example_audio_sha256`, `status`, `authored`, `seed_version`) VALUES
('N3-L-POINT', 'Chiến thuật nghe hiểu điểm chính N3 (ポイント理解)', 'Nhận diện đúng lý do cốt lõi, điều kiện quan trọng nhất hoặc sự thay đổi ý kiến trong hội thoại và thông báo N3.', '["Bước 1: Đọc nhanh 4 lựa chọn chữ trong thời gian nghỉ để xác định điểm khác nhau giữa các phương án.","Bước 2: Nghe kỹ câu hỏi đầu bài xem đề hỏi lý do (どうして), điểm hài lòng nhất (何が一番よかった), hay điều kiện cần chú ý.","Bước 3: Khi nghe băng, phân biệt các lý do phụ (〜もそうですが / 〜もいいんですが) với lý do chính đứng sau (何より / 一番〜なのは / 実は).","Bước 4: Chọn phương án diễn đạt lại đúng ý chính đó bằng từ vựng tương đương."]', '["Bẫy lý do phụ: nhân vật khen cả A và B nhưng nhấn mạnh \\"Điều làm tôi quyết định chọn lại là C\\" (何よりCが決め手でした).","Bẫy thông tin giả định hoặc tin đồn (〜と思っていたら, 〜と聞いていたが) trái ngược với thực tế khi trải nghiệm.","Bẫy khớp từ mặt chữ nhưng sai quan hệ nhân quả."]', '["Các từ khóa báo hiệu đáp án trong ポイント理解 N3 gồm: 実は (thật ra là), 何より (hơn hết là), 一番の理由は (lý do lớn nhất là), ただ (chỉ có điều là).","Hãy tập thói quen nghe hiểu ý (paraphrase) thay vì chờ nghe đúng từ in trên giấy."]', '{"options":["昔から本を読むのが大好きだから。","ほかの店より時給が高いから。","自分の都合に合わせて働く時間を調整できるから。","家から近くて通いやすいから。"],"question_ja":"男の人がこのアルバイトを選んだ一番の理由は何ですか。","script_ja":"質問：男の人がこのアルバイトを選んだ一番の理由は何ですか。\\n女：アンさん、先月から本屋でアルバイトを始めたそうですね。もともと本が好きだからですか。\\n男：ええ、それもありますが、一番の理由はシフトの時間を自由に決められることなんです。大学の授業やレポートが忙しい週は、働く時間を減らせるんですよ。\\n女：へえ、それは便利ですね。時給もいいんですか。\\n男：時給はほかの店とあまり変わりませんし、家からも少し遠いんですが、勉強と両立しやすいのでとても助かっています。\\n質問：男の人がこのアルバイトを選んだ一番の理由は何ですか。","translation_vi":"Câu hỏi: Lý do lớn nhất mà người đàn ông chọn công việc làm thêm này là gì?\\nNữ: Bạn An này, nghe nói bạn mới bắt đầu làm thêm ở hiệu sách từ tháng trước à. Có phải vì vốn dĩ bạn thích sách không?\\nNam: Vâng, cũng có lý do đó, nhưng lý do lớn nhất là vì mình có thể tự do sắp xếp thời gian ca làm. Những tuần bận học trên trường hay bận làm báo cáo thì có thể giảm bớt số giờ làm được đấy.\\nNữ: Ồ, thế thì tiện quá nhỉ. Lương theo giờ có cao không?\\nNam: Lương theo giờ thì cũng không khác các tiệm khác mấy, lại còn hơi xa nhà một chút nữa, nhưng vì dễ cân bằng với việc học nên giúp ích cho mình rất nhiều.","walkthrough_vi":["Câu hỏi: Lý do lớn nhất (一番の理由) người nam chọn công việc làm thêm này là gì?","Người nữ hỏi có phải vì thích sách không -> người nam đáp 「ええ、それもありますが、一番の理由は…」 (Vâng, cũng có lý do đó, nhưng lý do lớn nhất là...) -> loại đáp án 1 (chỉ là lý do phụ).","Lý do lớn nhất người nam nêu là: 「シフトの時間を自由に決められることなんです」 (có thể tự do quyết định giờ ca làm, tuần nào bận học ở trường thì giảm giờ làm được).","Câu này được paraphrase ở lựa chọn 3 thành 「自分の都合に合わせて働く時間を調整できるから」 (vì có thể điều chỉnh thời gian làm việc theo lịch cá nhân) -> Chọn đáp án 3."]}', 2, 'Trong phần ポイント理解 N3, khi nhân vật nói 「ええ、それもありますが、一番の理由は〜」 thì phần thông tin đứng trước 「それもありますが」 là gì?', '["Là đáp án chính xác nhất của câu hỏi.","Chỉ là lý do phụ được công nhận một phần (bẫy rất phổ biến), còn đáp án đúng nằm ở vế sau 「一番の理由は」.","Là thông tin hoàn toàn không có thật.","Là câu hỏi dành cho người nghe."]', 1, 'Cấu trúc 「それもありますが、一番は／何より〜」 dùng để thừa nhận nhẹ ý kiến của người đối thoại rồi mới đưa ra lý do trọng tâm nhất, nên đáp án luôn nằm ở vế sau.', NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE', 'Chiến thuật phản xạ tức thời N3 (即時応答)', 'Nắm bắt nhanh các dạng rút gọn khẩu ngữ, kính ngữ và hàm ý cảm xúc trong câu nói ngắn N3 để chọn câu phản hồi tự nhiên nhất.', '["Bước 1: Lắng nghe toàn bộ câu phát ngôn đầu tiên, đặc biệt chú ý các dạng rút gọn trong hội thoại tự nhiên (〜ちゃった = 〜てしまった, 〜といて = 〜ておいて, 〜なきゃ = 〜なければ, 〜っけ = xác nhận lại điều quên).","Bước 2: Chú ý ngữ điệu cuối câu (lên giọng để hỏi xác nhận hay xuống giọng để cảm thán/đồng tình).","Bước 3: Xác định mục đích của người nói (than thở vì lỡ việc, nhờ làm sẵn, hỏi xác nhận trí nhớ, hay khen ngợi gián tiếp).","Bước 4: Chọn phương án khớp cả về mặt ngữ pháp lẫn mạch cảm xúc hội thoại."]', '["Bẫy âm rút gọn: không nhận ra 〜ちゃった (đã lỡ làm mất rồi) hoặc 〜といたよ (đã làm sẵn rồi) nên chọn câu trả lời ngược thời gian.","Bẫy câu hỏi tu từ/đồng tình (〜じゃない？ xuống giọng = \\"Chẳng phải là ... hay sao?\\"): đáp án nhiễu lại trả lời như câu phủ định.","Bẫy từ vựng đa nghĩa hoặc quán dụng ngữ ngắn trong giao tiếp."]', '["Học thuộc hệ thống rút gọn khẩu ngữ N3: 〜ておく -> 〜とく, 〜てしまう -> 〜ちゃう, 〜ては -> 〜ちゃ, 〜なければ -> 〜なきゃ / 〜ないと.","Khi người nói dùng 「〜っけ？」 (ví dụ: 会議は何時からだっけ？), đó là lúc họ đang quên và hỏi lại thông tin, hãy chọn câu cung cấp thông tin đó."]', '{"options":["じゃあ、今から急いで返しに行こう。","ええ、きのう返しておいてよかったね。","うん、来週借りに行けばいいよ。","いいえ、図書館は毎日開いているよ。"],"question_ja":"女の人の発言に対する返事として、最も適切なものはどれですか。","script_ja":"女：あ、いけない！図書館の本、今日までに返さなきゃいけなかったんだ。\\n1. じゃあ、今から急いで返しに行こう。\\n2. ええ、きのう返しておいてよかったね。\\n3. うん、来週借りに行けばいいよ。","translation_vi":"Nữ: Ôi thôi chết! Sách thư viện mình phải trả muộn nhất là trong hôm nay mất rồi.\\n1. Vậy thì bây giờ mau đi trả ngay đi.\\n2. Ừ, may mà hôm qua cậu đã trả sẵn rồi nhỉ.\\n3. Ừ, tuần sau đi mượn là được mà.","walkthrough_vi":["Phân tích câu nói đầu: 「あ、いけない！」 (Ôi thôi chết rồi!) + 「今日までに返さなきゃいけなかったんだ」 (返さなきゃ = 返さなければ: Đáng lẽ phải trả sách thư viện hạn chót là hôm nay mà quên mất).","Lựa chọn 2 sai vì người nữ chưa trả sách; lựa chọn 3 sai vì đang nói chuyện trả sách (返す) chứ không phải đi mượn (借りる).","Lựa chọn 1 「じゃあ、今から急いで返しに行こう」 (Vậy thì bây giờ mau đi trả ngay đi) khớp hoàn toàn với tình huống vừa sực nhớ ra hạn trả sách."]}', 0, 'Trong phần 即時応答 N3, cách nói khẩu ngữ 「返さなきゃいけなかった」 tương đương với cấu trúc đầy đủ nào?', '["返さなければいけなかった (Phải trả / Đáng lẽ phải trả).","返さなくてもよかった (Không cần trả cũng được).","返してしまった (Đã lỡ trả mất rồi).","返しておいた (Đã trả sẵn từ trước)."]', 0, 'Trong hội thoại N3, 〜なきゃ là dạng rút gọn của 〜なければ (〜なきゃいけない = 〜なければいけない: phải làm gì đó).', NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY', 'Chiến thuật nghe hiểu khái quát N3 (概要理解)', 'Nắm bắt chủ đề chính hoặc thông điệp cốt lõi của cả đoạn độc thoại/hội thoại khi không được biết trước câu hỏi và lựa chọn.', '["Bước 1: Vì đề không in sẵn câu hỏi lẫn lựa chọn, ngay khi đoạn nghe bắt đầu, hãy chú ý câu mở đầu để xác định chủ đề chung (đang nói về cái gì?).","Bước 2: Trong lúc nghe phần thân bài, không cố nhớ từng con số nhỏ mà hãy theo dõi mạch chuyển ý (しかし, そこで, つまり, このように).","Bước 3: Tập trung cao độ vào 1–2 câu cuối cùng của đoạn độc thoại vì đó là nơi người nói chốt lại điều muốn truyền đạt nhất.","Bước 4: Nghe kỹ câu hỏi (hỏi chủ đề 何について hay hỏi ý kiến 一番言いたいこと) rồi so sánh 4 lựa chọn được đọc lên để chọn câu bao quát nhất."]', '["Bẫy lấy một ví dụ nhỏ hoặc một chi tiết số liệu trong bài làm chủ đề chính của toàn bài.","Bẫy chọn câu có chứa từ xuất hiện ở đầu bài nhưng mang ý nghĩa ngược với kết luận cuối bài.","Bẫy nhầm giữa bài nói về \\"nguyên nhân của vấn đề\\" với bài nói về \\"cách giải quyết vấn đề\\"."]', '["Hãy ghi nhanh 3 gạch đầu dòng ngắn gọn ra nháp khi nghe: (1) Chủ đề mở bài, (2) Từ nối chuyển ý ở giữa, (3) Câu kết luận cuối bài.","Nếu câu hỏi là 「何について話していますか」 (Đang nói về chủ đề gì?), hãy chọn đáp án có tính khái quát bao trùm toàn bộ đoạn nói."]', '{"options":["毎日一万歩以上歩くことが一番大切だ。","ゆっくり長く歩いた方が体にいい。","歩くときは歩数よりも歩き方や速さが大切だ。","健康のために歩くのはやめた方がいい。"],"question_ja":"女の人が一番言いたいことは何ですか。","script_ja":"女：最近、健康のために毎日一万歩以上歩こうと頑張っている人が多いようです。しかし、専門家の話によると、ただ長く歩けばいいというわけではないそうです。だらだらとゆっくり歩くだけでは、あまり運動の効果が上がらないのです。反対に、背筋を伸ばして、少し息がはずむぐらいの速さで二十分から三十分歩く方が、体にはずっとよい効果があるそうです。みなさんも、歩く「距離」や「歩数」ばかりを気にするのではなく、「歩き方」や「速さ」を意識してみてはいかがでしょうか。\\n質問：女の人が一番言いたいことは何ですか。\\n1. 毎日一万歩以上歩くことが一番大切だ。\\n2. ゆっくり長く歩いた方が体にいい。\\n3. 歩くときは歩数よりも歩き方や速さが大切だ。\\n4. 健康のために歩くのはやめた方がいい。","translation_vi":"Nữ: Gần đây, có vẻ nhiều người đang cố gắng đi bộ trên 10.000 bước mỗi ngày vì sức khỏe. Tuy nhiên, theo lời chuyên gia, không phải cứ đi bộ lâu là tốt. Nếu chỉ đi bộ thong thả, chậm rãi thì hiệu quả vận động sẽ không cao. Ngược lại, việc giữ thẳng lưng và đi bộ với tốc độ hơi thở nhanh hơn một chút trong khoảng 20 đến 30 phút lại mang đến hiệu quả tốt hơn nhiều cho cơ thể. Mọi người cũng đừng chỉ bận tâm đến \\"quãng đường\\" hay \\"số bước chân\\", mà hãy thử lưu ý đến \\"tư thế đi\\" và \\"tốc độ đi\\" xem sao nhé.\\nCâu hỏi: Điều người phụ nữ muốn nói nhất là gì?\\n1. Việc đi bộ trên 10.000 bước mỗi ngày là quan trọng nhất.\\n2. Đi bộ chậm và lâu sẽ tốt cho cơ thể hơn.\\n3. Khi đi bộ, tư thế và tốc độ đi quan trọng hơn số bước chân.\\n4. Nên ngừng việc đi bộ vì sức khỏe.","walkthrough_vi":["Theo dõi mở bài: Nhiều người cố đi bộ trên 10.000 bước mỗi ngày vì sức khỏe.","Theo dõi chuyển ý (しかし): Chuyên gia cho biết không phải cứ đi bộ dài/nhiều bước là tốt; đi thẳng lưng với tốc độ hơi gấp nhịp thở trong 20–30 phút hiệu quả hơn nhiều.","Theo dõi câu kết (〜てみてはいかがでしょうか): Khuyên mọi người thay vì chỉ để ý số bước hay quãng đường thì hãy chú ý đến \\"cách đi\\" và \\"tốc độ đi\\".","Nghe câu hỏi (Người phụ nữ muốn nói điều gì nhất?) và 4 lựa chọn -> Lựa chọn 3 tóm tắt chính xác thông điệp cốt lõi."]}', 2, 'Vì sao khi làm dạng 概要理解 N3 bạn không nên cố ghi chép từng con số hay ví dụ nhỏ lẻ?', '["Vì đề thi cấm dùng bút chì.","Vì dạng 概要理解 chỉ hỏi chủ đề bao quát hoặc thông điệp chính của cả bài; mải ghi chi tiết nhỏ sẽ làm lỡ câu chuyển ý (しかし) và câu kết luận ở cuối bài.","Vì đoạn nghe chỉ dài 5 giây.","Vì đáp án luôn là câu số 1."]', 1, 'Trong phần 概要理解, câu hỏi chỉ xuất hiện ở cuối bài và hỏi về ý khái quát/quan điểm chính, nên việc nắm cấu trúc Mở – Chuyển ý – Kết quan trọng hơn nhiều so với chi tiết vụn vặt.', NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK', 'Chiến thuật nghe hiểu nhiệm vụ N3 (課題理解)', 'Theo dõi quá trình bàn bạc và phân công nhiều đầu việc trong hội thoại N3 để xác định đúng việc nhân vật cần làm ngay sau đó.', '["Bước 1: Nghe câu hỏi mở đầu để xác định rõ đề hỏi việc của người nam hay người nữ, và hỏi việc làm \\"đầu tiên\\" (まず) hay việc làm \\"sau đây\\" (このあと).","Bước 2: Trong thời gian dừng băng, đọc nhanh 4 lựa chọn chữ; gạch chân các động từ chính ở cuối mỗi lựa chọn.","Bước 3: Khi nghe hội thoại, đánh dấu từng đầu việc theo 3 nhóm: (a) Đã làm xong rồi, (b) Người kia sẽ làm, (c) Nhân vật được hỏi sẽ làm.","Bước 4: Chú ý các cụm từ chốt việc ở cuối hội thoại như じゃあ、まずは〜からお願いします, 〜はあとでいいから先に〜."]', '["Bẫy đề xuất bị hoãn lại: nhân vật định làm việc A ngay nhưng cấp trên bảo \\"Việc đó để chiều/ngày mai cũng được, bây giờ hãy làm việc B trước\\".","Bẫy đổi vai: ban đầu giao cho người nam nhưng sau đó người nữ nhận làm thay vì tiện đường.","Bẫy điều kiện cần: muốn làm việc A nhưng phát hiện thiếu thông tin nên phải đi hỏi/xác nhận thông tin B trước."]', '["Ở cấp N3, cả 4 lựa chọn đều sẽ được nhắc tới trong đoạn hội thoại; tuyệt đối không chọn ngay phương án đầu tiên vừa nghe thấy.","Tập trung cao độ vào 2 lượt lời cuối cùng trước khi hội thoại kết thúc vì đó là lúc chốt lại phân công."]', '{"options":["案内ポスターを印刷する。","受付の前にポスターを貼る。","参加者の名簿を印刷する。","マイクが使えるか確認する。"],"question_ja":"女の人はこのあとまず、何をしますか。","script_ja":"質問：女の人はこのあとまず、何をしますか。\\n女：先輩、来週のセミナーの準備ですが、会場の案内ポスターはもうできましたか。\\n男：うん、ポスターはさっき印刷が終わったから、あとは受付の前に貼るだけだよ。\\n女：じゃあ、私が今から貼ってきますね。それから、参加者の名簿も印刷しましょうか。\\n男：あ、名簿は今日の夕方までに人数がもう一度変わるかもしれないから、明日の朝にして。それより、ポスターを貼る前に、セミナーで使うマイクがちゃんと使えるか確認してくれない？さっき少し調子が悪かったんだ。\\n女：わかりました。じゃあ、先にそれを見に行きます。\\n質問：女の人はこのあとまず、何をしますか。","translation_vi":"Câu hỏi: Sau đây, đầu tiên người phụ nữ sẽ làm gì?\\nNữ: Tiền bối ơi, về việc chuẩn bị cho buổi hội thảo tuần sau, áp phích hướng dẫn hội trường đã làm xong chưa ạ?\\nNam: Ừ, áp phích vừa mới in xong lúc nãy rồi, giờ chỉ còn dán ở trước quầy lễ tân nữa thôi.\\nNữ: Vậy để em đi dán ngay bây giờ nhé. À, em in luôn cả danh sách người tham gia nữa nhé ạ?\\nNam: À, danh sách thì đến chiều tối nay có thể số lượng người sẽ còn thay đổi lần nữa nên để sáng mai hẵng in. Hơn nữa, trước khi dán áp phích, em kiểm tra giúp anh xem micro dùng trong hội thảo có hoạt động bình thường không được không? Lúc nãy nó hơi trục trặc một chút.\\nNữ: Vâng, em hiểu rồi ạ. Vậy em đi kiểm tra cái đó trước đây ạ.","walkthrough_vi":["Câu hỏi: Người phụ nữ sau đây trước tiên (まず) sẽ làm gì?","Việc in poster (ポスターを印刷する) đã xong rồi -> loại đáp án 1.","Việc in danh sách người tham gia (名簿を印刷する) được dặn để sáng mai làm (明日の朝にして) -> loại đáp án 3.","Người nữ định đi dán poster ngay, nhưng tiền bối nói 「それより、ポスターを貼る前に、セミナーで使うマイクがちゃんと使えるか確認してくれない？」 (Trước khi dán poster, em kiểm tra giúp anh xem micro có dùng tốt không nhé) và người nữ đồng ý làm trước -> Chọn đáp án 4."]}', 3, 'Trong bài nghe 課題理解 N3, khi một nhân vật nói 「それより、〜前に、…してくれない？」 thì điều đó có ý nghĩa gì?', '["Hủy bỏ toàn bộ kế hoạch của buổi hội thảo.","Đưa ra một việc mới cần ưu tiên làm trước việc vừa nhắc tới (đây thường là đáp án cho câu hỏi まず何をしますか).","Nhận tự mình làm hết mọi việc.","Khen ngợi công việc người kia đã làm hôm qua."]', 1, 'Cấu trúc 「それより、Aの前に、Bをしてくれない？」 làm thay đổi thứ tự ưu tiên: yêu cầu thực hiện việc B trước việc A, nên B chính là hành động đầu tiên (まず).', NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE', 'Chiến thuật biểu đạt phát ngôn N3 (発話表現)', 'Chọn đúng câu phát ngôn phù hợp với ngữ cảnh giao tiếp xã hội/công sở và sử dụng chuẩn xác kính ngữ (tôn kính ngữ – khiêm nhường ngữ) ở trình độ N3.', '["Bước 1: Quan sát tranh để xác định vị thế giữa người nói (có mũi tên) và người nghe (khách hàng, trưởng phòng, tiền bối, đồng nghiệp hay người lạ).","Bước 2: Nghe kỹ lời dẫn để xác định hành động thuộc về ai (mình làm hay người nghe làm) và mục đích câu nói (nhờ kiểm tra, xin phép dùng đồ, đề nghị hỗ trợ, nhắc nhở khi đánh rơi đồ).","Bước 3: Kiểm tra kính ngữ và hướng cho – nhận trong 3 phương án âm thanh: mình làm cho người trên thì dùng お〜しましょうか / 〜させていただきませんか; nhờ người trên làm cho mình thì dùng 〜ていただけませんか / 〜てくださいますか.","Bước 4: Loại ngay các câu dùng sai chiều kính ngữ hoặc thiếu lịch sự với người trên."]', '["Bẫy nhầm lẫn giữa 〜ていただけますか (nhờ người nghe làm) và 〜させていただけますか (xin phép cho mình làm).","Bẫy gắn お/ご〜になる hoặc 〜てくださる vào hành động của chính người nói.","Bẫy dùng 〜てあげる với cấp trên hoặc khách hàng (gây cảm giác bề trên, thiếu lịch sự)."]', '["Quy tắc nhớ nhanh: \\"Mình xin phép làm\\" -> 〜させていただけませんか / お〜しましょうか; \\"Nhờ người trên làm\\" -> 〜ていただけませんか / お〜ください.","Khi báo cho người lạ biết họ đánh rơi đồ trên đường/tàu điện, câu tự nhiên là 「あのう、〜が落ちましたよ」 hoặc 「〜を落とされましたよ」."]', '{"image_description_vi":"Trong phòng làm việc, một nữ nhân viên đang cầm bản báo cáo đứng trước bàn của trưởng phòng để nhờ trưởng phòng xem qua. Mũi tên chỉ vào nữ nhân viên.","options":["部長、レポートを書いたんですが、見ていただけませんか。","部長、レポートを書いたんですが、見せていただけませんか。","部長、レポートを書いたんですが、拝見しましょうか。","部長、レポートを書いたんですが、見てあげましょうか。"],"question_ja":"部長に何と言いますか。","script_ja":"会議のレポートを書きました。部長にチェックしてもらいたいです。何と言いますか。\\n1. 部長、レポートを書いたんですが、見ていただけませんか。\\n2. 部長、レポートを書いたんですが、見せていただけませんか。\\n3. 部長、レポートを書いたんですが、拝見しましょうか。","translation_vi":"Bạn đã viết xong bản báo cáo cuộc họp và muốn nhờ trưởng phòng kiểm tra giúp. Bạn sẽ nói gì?\\n1. Thưa trưởng phòng, tôi đã viết xong báo cáo rồi, nhờ trưởng phòng xem qua giúp tôi có được không ạ?\\n2. Thưa trưởng phòng, tôi đã viết xong báo cáo rồi, trưởng phòng cho tôi xem có được không ạ?\\n3. Thưa trưởng phòng, tôi đã viết xong báo cáo rồi, để tôi xin phép xem qua nhé ạ?","walkthrough_vi":["Xác định tình huống: Nữ nhân viên đã viết xong báo cáo và muốn nhờ trưởng phòng xem/kiểm tra giúp (チェックしてもらいたいです).","Người thực hiện hành động \\"xem báo cáo\\" là trưởng phòng -> cần dùng mẫu nhờ vả lịch sự 「見ていただけませんか」 (hoặc ご覧になっていただけませんか).","Lựa chọn 2 (見せていただけませんか) nghĩa là \\"Cho phép tôi xem báo cáo của trưởng phòng được không?\\"; lựa chọn 3 dùng 拝見する (khiêm nhường ngữ của mình xem) đều sai chủ thể -> Chọn đáp án 1."]}', 0, 'Trong phần 発話表現 N3, sự khác biệt cốt lõi giữa 「見ていただけませんか」 và 「見せていただけませんか」 là gì?', '["見ていただけませんか là nhờ người nghe xem giúp thứ của mình; còn 見せていただけませんか là xin người nghe cho phép mình được xem thứ của họ.","Hai câu có nghĩa hoàn toàn giống nhau.","拝見しましょうか dùng khi nhờ cấp trên xem báo cáo của mình.","見てあげましょうか là cách nói kính ngữ lịch sự nhất với giám đốc."]', 0, '見る (xem) + ていただけませんか = nhờ người nghe xem; 見せる (cho xem) + ていただけませんか = nhờ người nghe cho phép mình xem. Phân biệt động từ thường và dạng sai khiến giúp tránh bẫy kính ngữ N3.', NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO', 'Chiến thuật tìm kiếm thông tin N3 (情報検索)', 'Xử lý nhanh các bảng hướng dẫn, quy định dịch vụ hoặc thông báo sự kiện dài (380–720 ký tự) có nhiều điều kiện kết hợp và ngoại lệ.', '["Bước 1: Đọc kỹ câu hỏi trước, tách yêu cầu của nhân vật thành danh sách các tiêu chí kiểm tra (ai, khi nào, mục đích gì, ngân sách/điều kiện).","Bước 2: Nhìn bố cục văn bản (tiêu đề mục 1, 2, 3, bảng so sánh, mục đăng ký, mục lưu ý) để biết thông tin cần tìm nằm ở khu vực nào.","Bước 3: Đối chiếu tiêu chí của nhân vật với bảng chính để thu hẹp xuống còn 1–2 phương án.","Bước 4: Đọc kỹ các điều khoản có từ khóa ngoại lệ (ただし, 〜を除く, 〜に限る, 〜場合は, ※) để chốt đáp án cuối cùng."]', '["Bẫy giảm giá/miễn phí có điều kiện: đủ điều kiện về độ tuổi hoặc số người nhưng lại đi vào ngày cuối tuần (không áp dụng ưu đãi).","Bẫy thời hạn đăng ký trước (〜日前までに予約が必要) trong khi nhân vật muốn đi ngay ngày mai.","Bẫy kết hợp 2 bảng nhỏ trong cùng 1 bài (ví dụ: bảng 1 chọn gói dịch vụ, bảng 2 chọn mức phí theo khung giờ)."]', '["Gạch chân ngay các từ chỉ giới hạn như 「平日のみ」 (chỉ ngày thường), 「要予約」 (cần đặt trước), 「〜以上」 (từ ... trở lên), 「〜未満」 (dưới ...).","Tuyệt đối không đọc những mục trong thông báo mà câu hỏi không hỏi tới."]', '{"options":["1,300円","1,700円","2,200円","3,400円"],"passage_ja":"【市立文化センター・貸し会議室のご利用案内】\\n当センターの会議室は、市内にお住まいの方、または市内の会社や学校に通っている方がご利用いただけます（市外の方はご利用になれません）。\\n■ 会議室の種類と基本料金（2時間あたり）\\n・第1会議室（3階・定員10名まで）：1,000円（ホワイトボード1台あり）\\n・第2会議室（3階・定員20名まで）：1,800円（ホワイトボード・プロジェクターあり）\\n・第3会議室（4階・定員40名まで）：3,000円（マイク2本・プロジェクターあり）\\n■ ご利用上の注意と追加料金について\\n※ 土曜日・日曜日・祝日に利用する場合は、上記の基本料金にそれぞれ400円が追加されます。\\n※ プロジェクターのない部屋（第1会議室）でプロジェクターを借りる場合は、別途300円かかります。\\n※ 予約は利用日の3日前までに、1階の受付窓口またはインターネットで行ってください。","question_ja":"市内の会社で働くタオさんは、来週の土曜日に8人で2時間、プロジェクターを使って会議をしたいと考えています。最も安く利用できる部屋を選んだ場合、料金はいくらになりますか。","translation_vi":"[Trung tâm Văn hóa Thành phố - Hướng dẫn sử dụng phòng họp]\\nPhòng họp của trung tâm phục vụ cho người cư trú hoặc làm việc trong thành phố.\\n■ Các loại phòng họp và mức phí (cho mỗi 2 tiếng)\\n・Phòng họp số 1 (sức chứa 10 người): 1.000 yên (có bảng trắng)\\n・Phòng họp số 2 (sức chứa 20 người): 1.800 yên (có bảng trắng và máy chiếu)\\n・Phòng họp số 3 (sức chứa 40 người): 3.000 yên (có micro và máy chiếu)\\n■ Lưu ý khi sử dụng\\n* Vào Thứ Bảy và Chủ nhật, mỗi phòng sẽ cộng thêm 400 yên vào mức giá trên.\\n* Trường hợp mượn máy chiếu ở phòng chưa có sẵn máy chiếu sẽ tính thêm 300 yên.\\n* Vui lòng đặt phòng tại quầy hoặc qua internet muộn nhất là 3 ngày trước ngày sử dụng.","walkthrough_vi":["Nắm điều kiện: Bạn Thảo làm việc trong thành phố (đủ điều kiện), họp vào thứ Bảy tuần sau (đặt trước kịp, nhưng bị cộng phụ phí cuối tuần +400円), nhóm 8 người, dùng 2 tiếng, cần máy chiếu (プロジェクター), muốn chọn phương án rẻ nhất.","Xét Phòng họp số 1 (sức chứa 10 người -> đủ cho 8 người): Giá gốc 1,000円 + phụ phí thứ Bảy 400円 + thuê thêm máy chiếu 300円 (theo lưu ý 2) = 1,700円.","Xét Phòng họp số 2 (sức chứa 20 người, có sẵn máy chiếu): Giá gốc 1,800円 + phụ phí thứ Bảy 400円 = 2,200円.","So sánh hai phương án hợp lệ: Phòng số 1 với tổng chi phí 1,700円 rẻ hơn -> Chọn đáp án 2 (1,700円)."]}', 1, 'Khi câu hỏi trong bài 情報検索 N3 yêu cầu chọn phương án "rẻ nhất" (最も安く) hoặc "nhanh nhất", bạn cần lưu ý điều gì?', '["Chỉ nhìn con số nhỏ nhất trong bảng chính mà không cần cộng phụ phí.","Tính tổng chi phí (bao gồm cả phụ phí cuối tuần hoặc phí thuê thêm thiết bị ở phần lưu ý ※) của các phương án đủ điều kiện rồi mới so sánh.","Luôn chọn phương án cuối cùng trong bảng.","Bỏ qua điều kiện về số lượng người tham gia."]', 1, 'Đề N3 thường thiết kế để phương án có sẵn thiết bị và phương án thuê rời thiết bị chênh lệch nhau sau khi cộng phụ phí ở mục ※, nên phải tính tổng thực tế của từng phương án hợp lệ.', NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG', 'Chiến thuật đọc hiểu đoạn văn dài N3 (長文)', 'Làm chủ bài đọc dài 550–850 ký tự bằng kỹ thuật đọc theo từng đoạn kết hợp trả lời cuốn chiếu 4 câu hỏi mà không bị quá tải thông tin.', '["Bước 1: Không đọc hết cả bài dài một mạch từ đầu đến cuối; hãy đọc câu hỏi 1 trước rồi đọc đoạn 1–2 để giải quyết ngay câu hỏi 1.","Bước 2: Tiếp tục đọc câu hỏi 2 rồi đọc tiếp đoạn 2–3; cứ làm cuốn chiếu như vậy đến hết bài.","Bước 3: Đánh dấu sự chuyển biến tâm lý hoặc nhận thức của nhân vật/tác giả qua các mốc: Trước kia (以前は) -> Sự việc bước ngoặt (あるとき / きっかけ) -> Hiện tại (今では).","Bước 4: Với câu hỏi cuối cùng (thường hỏi ý chính toàn bài: 筆者が一番言いたいこと), ghép nội dung câu kết của đoạn cuối với luận điểm chính ở phần thân bài."]', '["Bẫy chi tiết phụ: một ví dụ minh họa nhỏ ở đoạn giữa được phóng đại thành thông điệp chính của toàn bài.","Bẫy đảo ngược trước – sau: gán suy nghĩ của tác giả trước khi xảy ra sự việc bước ngoặt thành kết luận hiện tại.","Bẫy từ vựng cảm xúc: chọn đáp án mang thái độ tức giận hoặc phê phán gay gắt trong khi giọng văn tác giả nhẹ nhàng, tích cực."]', '["Hãy chia bài đọc dài thành 3 phần rõ rệt: Mở đầu (nêu vấn đề/trải nghiệm cũ) – Bước ngoặt (nhận ra điều mới) – Kết luận (bài học chung).","Những câu chứa 「つまり」 (tóm lại là), 「要するに」 (nói ngắn gọn là) hoặc câu hỏi tu từ 「〜のではないだろうか」 ở đoạn cuối luôn là chìa khóa cho câu hỏi tổng kết."]', '{"options":["どんな仕事でも、最初から最後まで全部一人でやった方が成長できること。","一人で無理をして仕事が遅れる方が、かえって周りの人に迷惑をかけてしまうこと。","先輩や後輩には、できるだけ仕事を頼まない方がいいということ。","大きなイベントの準備は、前日になってから始めた方がいいということ。"],"passage_ja":"私は小さいころから、人にものを頼むのがとても苦手だった。何か困ったことがあっても、「相手に迷惑をかけてしまうのではないか」「自分でやるべきだ」と考えてしまい、どんなことでも全部一人でやろうとしていた。今の会社に入ってからもその性格はなかなか変わらず、自分の仕事が多すぎて夜遅くまで会社に残って残業することがよくあった。\\nそんなある日、会社の大きなイベントの準備を一人で抱え込んでしまい、イベントの前日になっても資料の準備や会場の連絡が終わらずに本当に困っていた。すると、隣の席の先輩が私の様子に気づいて、「どうしてそんなに大変なのに早く言わなかったの？私たちは一つのチームで仕事をしているんだから、困ったときはお互いに助け合うのが当たり前だよ」と言って、夜遅くまで一緒に準備を手伝ってくれた。そのとき私は、一人で無理をして仕事が遅れたりミスをしたりする方が、かえって周りの人たちに大きな迷惑をかけてしまうということに初めて気がついた。\\nそれからは、自分一人でできる量を超えそうなときは、我慢しないで早めに周りの先輩や同僚に相談するようにしている。また、逆にかつての私のように一人で悩んでいる後輩がいれば、自分から進んで声をかけて手伝うようにしている。人に頼ることは決して恥ずかしいことでも悪いことでもなく、お互いに助け合うことで、チーム全体としてよりよい仕事ができるのだと思う。","question_ja":"先輩に手伝ってもらったとき、筆者はどんなことに気がつきましたか。","translation_vi":"Từ nhỏ tôi đã rất ngại việc nhờ vả người khác. Dù gặp chuyện gì khó khăn, tôi cũng lo rằng \\"Liệu mình có làm phiền người ta không nhỉ\\" nên toàn cố tự làm một mình hết. Sau khi vào công ty, tính cách đó vẫn không thay đổi, nhiều khi việc quá nhiều khiến tôi thường xuyên phải làm thêm đến tận đêm muộn.\\nThế rồi một hôm, tôi ôm đồm chuẩn bị một sự kiện lớn một mình, đến tận hôm trước ngày diễn ra vẫn chưa xong nên vô cùng bối rối. Lúc ấy, người tiền bối ngồi cạnh bảo tôi: \\"Sao em không nói sớm? Chúng ta làm việc theo nhóm nên lúc khó khăn giúp đỡ lẫn nhau là chuyện đương nhiên mà\\", rồi ở lại giúp tôi đến tận khuya. Khi đó tôi mới nhận ra rằng, việc tự mình cố quá sức để rồi công việc bị chậm trễ ngược lại còn làm phiền mọi người xung quanh nhiều hơn.\\nKể từ đó, mỗi khi khối lượng việc có vẻ vượt quá sức một mình, tôi đều chủ động trao đổi sớm với mọi người xung quanh. Ngược lại, nếu thấy hậu bối nào đang loay hoay một mình giống như tôi trước đây, tôi cũng chủ động bắt chuyện và hỗ trợ. Tôi nghĩ rằng dựa vào người khác hoàn toàn không phải là điều xấu, mà nhờ giúp đỡ lẫn nhau, chúng ta có thể làm việc hiệu quả hơn.","walkthrough_vi":["Đọc câu hỏi: Khi được tiền bối giúp đỡ, tác giả đã nhận ra điều gì (どんなことに気がつきましたか)?","Định vị đoạn 2 (đoạn kể về việc tiền bối giúp đỡ) và tìm cụm từ khóa 「気がついた」 ở câu cuối đoạn 2.","Đọc nguyên câu đó: 「そのとき私は、一人で無理をして仕事が遅れる方が、かえって周りに迷惑をかけてしまうということに気がついた」 (Lúc đó tôi nhận ra rằng việc cố quá sức một mình rồi để công việc bị trễ ngược lại còn gây phiền cho mọi người xung quanh hơn).","Đối chiếu với 4 lựa chọn: lựa chọn 2 khớp hoàn toàn."]}', 1, 'Cách phân bổ việc đọc hiệu quả nhất khi làm bài Đọc hiểu đoạn văn dài (長文) N3 là gì?', '["Đọc hết toàn bộ bài văn 3 lần rồi mới nhìn xuống câu hỏi.","Đọc từng câu hỏi trước rồi đọc cuốn chiếu từng đoạn tương ứng trong bài, đồng thời chú ý câu nhận thức mới (気がついた) và đoạn kết luận.","Chỉ đọc câu đầu tiên của đoạn 1 và câu cuối cùng của đoạn cuối.","Chọn đáp án dựa theo cảm tính mà không cần đối chiếu với bài."]', 1, 'Vì các câu hỏi của bài 長文 được sắp xếp theo đúng thứ tự các đoạn văn từ trên xuống dưới, phương pháp đọc câu hỏi -> đọc đoạn tương ứng giúp giữ sự tập trung và tìm đúng bằng chứng nhanh nhất.', NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM', 'Chiến thuật đọc hiểu đoạn văn trung bình N3 (中文)', 'Phân tích mạch lập luận gồm 2–4 đoạn văn (330–520 ký tự) để giải quyết trọn vẹn 3 câu hỏi về chi tiết, phần gạch chân và ý chính.', '["Bước 1: Đọc câu hỏi số 1 và số 2 trước (chưa cần đọc câu 3 ngay), gạch chân từ khóa hoặc đánh dấu câu có gạch chân trong bài.","Bước 2: Đọc đoạn 1 và đoạn 2 để trả lời câu hỏi số 1; chú ý sự đối lập giữa \\"quan niệm thông thường\\" (一般に〜と思われている) và \\"ý kiến của tác giả\\" (しかし、私は〜と思う).","Bước 3: Khi giải câu hỏi về phần gạch chân, đọc kỹ câu chứa phần gạch chân cộng thêm 1 câu trước và 1 câu sau để tìm nguyên nhân hoặc lời giải thích tương đương.","Bước 4: Đọc đoạn cuối cùng để nắm thông điệp tổng kết của tác giả và trả lời câu hỏi số 3."]', '["Bẫy lấy ý kiến của số đông (多くの人は〜と言う / よく〜と思われがちだ) ở đoạn đầu làm ý kiến của tác giả.","Bẫy ghép một nửa câu đúng ở đoạn trên với một nửa câu sai ở đoạn dưới.","Bẫy suy diễn cảm xúc: chọn đáp án nghe có vẻ đạo lý nhưng tác giả không hề đề cập trong bài."]', '["Các câu hỏi trong bài 中文 N3 luôn sắp xếp theo đúng trình tự đoạn văn: câu 1 ở đoạn đầu, câu 2 ở đoạn giữa, câu 3 ở đoạn cuối hoặc toàn bài.","Hãy đặc biệt chú ý các mẫu câu thể hiện lập trường của tác giả như 〜のではないだろうか, 〜と言える, 〜が大切だ."]', '{"options":["ノートにできるだけたくさん書いて、手が疲れるまで練習する。","漢字の練習はやめて、友だちと話す練習だけをする。","ただ何回も書くだけでなく、短い日記などで実際に言葉を使ってみる。","毎日新しい言葉を十個以上選んで、辞書で意味を調べる。"],"passage_ja":"新しい外国語の言葉を覚えるとき、ノートに同じ言葉を何回も書いて覚えようとする人が多い。確かに、手を動かしてノートいっぱいに書くと、「今日もたくさん勉強した」という満足した気持ちになりやすい。しかし、きれいに書くことばかりに集中してしまうと、手が疲れるだけで、頭の中にはあまり残らないことも少なくない。\\n私はそれよりも、覚えた言葉を実際の会話や短い文の中で使ってみる方がいいと思う。たとえば、今日覚えた三つの言葉を使って、寝る前に三行だけその日の日記を書いてみるのだ。自分の生活に関係がある文を自分で考えて作ると、言葉の正しい意味や使い方が自然に頭に入ってくる。\\nもちろん、漢字の正しい形を覚えるために書く練習も必要だが、言葉を本当に自分のものにするためには、「使う練習」をもっと増やすべきではないだろうか。","question_ja":"筆者は、新しい言葉を覚えるためにどうするのがよいと言っていますか。","translation_vi":"Khi học từ mới, có nhiều người cố gắng nhớ bằng cách viết đi viết lại nhiều lần vào vở. Đúng là khi cử động tay để viết, ta dễ có cảm giác rằng \\"mình đã học được rất nhiều\\". Tuy nhiên, nếu chỉ tập trung vào việc viết thì đôi khi chỉ mỏi tay thôi chứ không đọng lại trong đầu được bao nhiêu.\\nSo với cách đó, tôi cho rằng thử sử dụng những từ đã học vào hội thoại thực tế hoặc các câu văn ngắn sẽ tốt hơn. Chẳng hạn, hãy thử dùng 3 từ mới học hôm nay để viết vỏn vẹn 3 dòng nhật ký trước khi đi ngủ. Khi tự đặt câu gắn liền với cuộc sống của chính mình, ý nghĩa và cách dùng của từ sẽ tự nhiên đi vào đầu.\\nTất nhiên, để nhớ mặt chữ Hán thì việc luyện viết cũng cần thiết, nhưng để biến từ vựng thực sự thành của mình thì chẳng phải chúng ta nên tăng cường \\"luyện tập sử dụng\\" nhiều hơn hay sao?","walkthrough_vi":["Đọc câu hỏi: Tác giả nói nên làm thế nào để nhớ từ mới?","Đoạn 1 nêu cách nhiều người hay làm (viết nhiều lần ra vở) nhưng tác giả phản biện bằng 「しかし」 -> loại đáp án 1.","Đoạn 2 nêu ý kiến của tác giả: 「私はそれよりも、覚えた言葉を実際の会話や短い文の中で使ってみる方がいいと思う」 (tốt hơn là thử dùng từ đã học trong hội thoại thực tế hoặc câu ngắn như viết nhật ký 3 dòng).","Đoạn 3 khẳng định vẫn cần tập viết chữ Hán nhưng nên tăng luyện tập sử dụng -> loại đáp án 2 (bỏ hẳn luyện chữ Hán). Vậy đáp án 3 là chính xác nhất."]}', 2, 'Trong bài đọc nghị luận trung bình (中文) N3, khi đoạn mở đầu viết 「〜という人が多い。確かに〜。しかし…」 thì ý kiến thật sự của tác giả nằm ở đâu?', '["Nằm ở câu 「〜という人が多い」.","Nằm ở câu đứng sau 「確かに」.","Nằm ở phần sau từ nối chuyển ý 「しかし」 và được khẳng định lại ở đoạn kết.","Không có trong bài, người đọc phải tự đoán."]', 2, 'Cấu trúc "Nhiều người nghĩ A -> Đúng là A có một phần hợp lý (確かに) -> Tuy nhiên (しかし) tôi lại nghĩ B" là khuôn mẫu lập luận phổ biến nhất ở N3; ý chính của tác giả luôn nằm sau しかし.', NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT', 'Chiến thuật đọc hiểu đoạn văn ngắn N3 (短文)', 'Xác định chính xác thông điệp trọng tâm trong email công việc, thông báo hành chính hoặc đoạn văn nghị luận ngắn N3 (150–250 ký tự).', '["Bước 1: Đọc câu hỏi trước để nhận biết dạng câu hỏi (hỏi mục đích email, hỏi điều người đọc cần làm, hay hỏi ý kiến tác giả).","Bước 2: Quét nhanh cấu trúc văn bản: nếu là thư/email công việc, bỏ qua câu chào xã giao đầu bài (いつもお世話になっております) và đi thẳng vào câu nêu vấn đề (さて / つきましては / 実は).","Bước 3: Trong đoạn văn nghị luận ngắn, chú ý các từ nối chuyển ý (しかし, ところが, むしろ) và các mẫu nhấn mạnh ý kiến (〜べきだ, 〜ことが大切だ, 〜のではないだろうか).","Bước 4: Đối chiếu câu chủ đề vừa tìm được với 4 lựa chọn và chọn câu diễn đạt lại (paraphrase) sát nghĩa nhất."]', '["Bẫy câu chào hỏi hoặc bối cảnh mở đầu: lựa chọn nhiễu chép lại nguyên văn phần lý do dẫn nhập nhưng không phải là yêu cầu chính.","Bẫy phủ định một phần (〜とは限らない, 〜わけではない): bài viết nói \\"không hẳn lúc nào cũng...\\" nhưng đáp án lại đổi thành \\"tuyệt đối không...\\".","Bẫy nhầm lẫn giữa việc người gửi sẽ làm và việc người gửi yêu cầu người nhận làm."]', '["Trong email nội bộ N3, câu nằm ngay sau 「つきましては」 hoặc câu có mẫu 「〜ていただけますでしょうか」「〜をお願いいたします」 luôn chứa đáp án.","Ở đoạn văn nêu quan điểm, câu đứng ngay sau 「しかし」 hoặc câu cuối cùng của đoạn thường là kết luận của tác giả."]', '{"options":["来月から、すべての会議で紙の資料をまったく使わなくなること。","来月から、社内の会議では原則として資料を紙に印刷しないこと。","来月から、会議にはパソコンを持ってきてはいけないこと。","社外のお客様にも、パソコンで資料を見てもらうこと。"],"passage_ja":"社員のみなさまへ。いつも業務にご協力いただきありがとうございます。来月より、社内のゴミを減らし環境を守るため、会議資料は原則として紙に印刷せず、各自のパソコンやタブレットの画面で見ていただくことになりました。ただし、社外のお客様がいらっしゃる会議では、これまで通り印刷した資料を配ります。最初は少し不便かもしれませんが、ご協力をお願いいたします。","question_ja":"このメールで伝えたいことは何ですか。","translation_vi":"Gửi toàn thể nhân viên. Từ tháng sau, nhằm giảm thiểu lượng rác trong công ty, tài liệu cuộc họp về nguyên tắc sẽ không in ra giấy nữa mà mỗi người sẽ xem trên máy tính hoặc máy tính bảng cá nhân. Tuy nhiên, trong các cuộc họp có khách hàng bên ngoài tới dự, chúng ta vẫn phát tài liệu in như từ trước đến nay. Thời gian đầu có thể hơi bất tiện một chút, nhưng rất mong nhận được sự hợp tác của mọi người.","walkthrough_vi":["Đọc câu hỏi: Email này muốn truyền đạt điều gì?","Tìm câu nêu quy định mới: Từ tháng sau, để giảm rác thải trong công ty, tài liệu họp về nguyên tắc sẽ không in ra giấy mà xem trên máy tính/máy tính bảng cá nhân.","Kiểm tra câu ngoại lệ sau 「ただし」: Với cuộc họp có khách bên ngoài thì vẫn phát tài liệu in như trước -> loại đáp án 1 (tất cả cuộc họp đều không dùng giấy) và đáp án 4.","Đáp án 2 khớp hoàn toàn với nội dung thông báo."]}', 1, 'Trong đoạn văn ngắn N3 có từ nối 「ただし」 (tuy nhiên / với điều kiện là), vai trò của câu đứng sau 「ただし」 là gì?', '["Là câu chào xã giao không có ý nghĩa về mặt nội dung.","Nêu điều kiện ngoại lệ hoặc giới hạn phạm vi áp dụng của quy định vừa nêu ở câu trước, giúp loại các đáp án vơ đũa cả nắm (すべて / かならず).","Phủ định hoàn toàn toàn bộ mục đích của email.","Chỉ dùng để trang trí câu văn."]', 1, 'Từ ただし nêu ngoại lệ cho quy tắc chung. Đề thi N3 rất hay dùng chi tiết sau ただし để bẫy những lựa chọn chứa từ tuyệt đối hóa như すべて, だれでも, いつも.', NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9')
INSERT INTO `jpath_skill_set` (`code`, `type_code`, `level`, `skill`, `sort_order`, `passage_ja`, `passage_vi`, `script_json`, `script_vi`, `image_description_vi`, `new_words_json`, `char_count`, `question_count`, `audio_path`, `audio_sha256`, `audio_seconds`, `status`, `authored`, `seed_version`) VALUES
('N3-R-SHORT-001', 'N3-R-SHORT', 'N3', 'READING', 1, '営業部の皆様へ。来週月曜日の午前十時から予定していた営業会議ですが、本社の田中部長が急な出張で参加できなくなったため、同じ日の午後三時からに変更いたします。また、これまで使っていた三階の1番会議室は別の課が使うことになったので、五階の大会議室に集まってください。会議で配る資料は、当日の正午までに一人ずつ自分で印刷して持参してください。', 'Gửi toàn thể phòng Kinh doanh. Cuộc họp kinh doanh dự kiến từ 10 giờ sáng thứ Hai tuần tới sẽ được đổi sang 3 giờ chiều cùng ngày do Trưởng phòng Tanaka ở trụ sở chính có chuyến công tác đột xuất không thể tham gia. Ngoài ra, phòng họp số 1 ở tầng 3 vốn dùng từ trước tới nay đã có bộ phận khác sử dụng, nên xin vui lòng tập trung tại phòng họp lớn ở tầng 5. Tài liệu phát trong cuộc họp xin mỗi người tự in và mang theo trước 12 giờ trưa ngày hôm đó.', NULL, NULL, NULL, '[{"expression":"資料","reading":"しりょう","meaning_vi":"tài liệu"},{"expression":"当日","reading":"とうじつ","meaning_vi":"đúng ngày hôm đó"},{"expression":"正午","reading":"しょうご","meaning_vi":"chính ngọ"}]', 168, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-002', 'N3-R-SHORT', 'N3', 'READING', 2, '最近、スマートフォンの画面ばかり見ていて、夜なかなか眠れないという人が増えているそうだ。寝る直前まで強い光を見ていると、脳がまだ昼間だと勘違いしてしまい、深く休むことができなくなるらしい。ぐっすり眠って次の日の朝気持ちよく起きるためには、寝る一時間前には電源を切るか別の部屋に置いて、静かな音楽を聞いたり本を読んだりして過ごすのがとても効果がある。', 'Nghe nói gần đây ngày càng có nhiều người suốt ngày nhìn vào màn hình điện thoại thông minh nên ban đêm mãi không ngủ được. Có vẻ như nếu nhìn ánh sáng mạnh đến sát lúc đi ngủ, não bộ sẽ hiểu lầm rằng vẫn còn là ban ngày và không thể nghỉ ngơi sâu được. Để ngủ ngon giấc và thức dậy sảng khoái vào sáng hôm sau, việc tắt nguồn hoặc để điện thoại ở phòng khác trước khi ngủ 1 tiếng rồi nghe nhạc nhẹ hoặc đọc sách là rất hiệu quả.', NULL, NULL, NULL, '[{"expression":"画面","reading":"がめん","meaning_vi":"màn hình"},{"expression":"電源","reading":"でんげん","meaning_vi":"nguồn điện"},{"expression":"効果","reading":"こうか","meaning_vi":"hiệu quả"}]', 174, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-003', 'N3-R-SHORT', 'N3', 'READING', 3, 'さくらマンションの住民の皆様へ。今月二十日の水曜日、午前九時から正午まで、マンション全体の電気設備のチェックと修理を行います。この時間帯はエレベーターが完全に止まるほか、それぞれの部屋の電気や水道もしばらくの間使えなくなります。お出かけの予定がある方は階段をご利用いただくか、午前九時より前に外出されるようお願いいたします。ご不便をおかけしますが、ご協力をお願いします。', 'Gửi cư dân chung cư Sakura. Thứ Tư ngày 20 tháng này, từ 9 giờ sáng đến 12 giờ trưa, chúng tôi sẽ tiến hành kiểm tra và sửa chữa thiết bị điện của toàn chung cư. Trong khung giờ này, ngoài việc thang máy ngừng hoạt động hoàn toàn, điện và nước ở từng căn hộ cũng tạm thời không sử dụng được. Những ai có lịch ra ngoài xin vui lòng sử dụng cầu thang bộ hoặc ra ngoài trước 9 giờ sáng. Rất mong quý cư dân thông cảm và hợp tác.', NULL, NULL, NULL, '[{"expression":"住民","reading":"じゅうみん","meaning_vi":"cư dân"},{"expression":"設備","reading":"せつび","meaning_vi":"thiết bị"},{"expression":"完全","reading":"かんぜん","meaning_vi":"hoàn toàn"}]', 185, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-004', 'N3-R-SHORT', 'N3', 'READING', 4, '「忙しいから時間がない」と口にする人は多いが、本当に一分も余裕がないのだろうか。一日を振り返ってみると、目的もなくテレビを眺めていたり、電車の中でなんとなくゲームをしていたりする時間が意外とあるはずだ。そのような五分や十分の短い時間を集めれば、一日に一時間近くになることもある。大切なのは、時間がないとなげくことではなく、短い時間をどう活かすか工夫することだ。', 'Có nhiều người hay mở miệng nói "Vì bận nên không có thời gian", nhưng liệu có thực sự không dư ra nổi một phút nào không? Nếu nhìn lại một ngày, hẳn sẽ có kha khá thời gian ta nhìn vô định vào tivi không mục đích hoặc chơi game vu vơ trên tàu điện. Nếu gom những khoảng thời gian ngắn 5 hay 10 phút như thế lại, có khi cũng được gần một tiếng mỗi ngày. Điều quan trọng không phải là than thở không có thời gian, mà là tìm cách tận dụng những khoảng thời gian ngắn đó.', NULL, NULL, NULL, '[{"expression":"余裕","reading":"よゆう","meaning_vi":"sự dư dả"},{"expression":"意外","reading":"いがい","meaning_vi":"bất ngờ"},{"expression":"目的","reading":"もくてき","meaning_vi":"mục đích"}]', 180, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-005', 'N3-R-SHORT', 'N3', 'READING', 5, '人事課からのお知らせです。来月一日から、社員証を忘れた場合の社内への入り方が変わります。これまでは一階の受付で名前を書くだけで一時通行証を借りることができましたが、来月からは安全管理を厳しくするため、自分の課の上司に内線電話で連絡し、本人確認をしてもらうことが必要になります。朝の忙しい時間に受付が混雑することが予想されますので、出勤前に必ず社員証をご確認ください。', 'Thông báo từ Phòng Nhân sự. Từ ngày mùng 1 tháng sau, cách thức vào công ty trong trường hợp quên thẻ nhân viên sẽ thay đổi. Từ trước đến nay chỉ cần ghi tên ở quầy lễ tân tầng 1 là có thể mượn thẻ ra vào tạm thời, nhưng từ tháng sau để thắt chặt quản lý an ninh, nhân viên cần gọi điện thoại nội bộ cho cấp trên của bộ phận mình để xác nhận nhân thân. Dự kiến quầy lễ tân sẽ đông đúc vào giờ cao điểm buổi sáng, nên xin hãy kiểm tra kỹ thẻ nhân viên trước khi đi làm.', NULL, NULL, NULL, '[{"expression":"確認","reading":"かくにん","meaning_vi":"xác nhận"},{"expression":"上司","reading":"じょうし","meaning_vi":"cấp trên"},{"expression":"管理","reading":"かんり","meaning_vi":"quản lý"}]', 183, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-006', 'N3-R-SHORT', 'N3', 'READING', 6, '誰かに相談されたとき、ついすぐに自分の意見や解決の方法を言ってしまう人がいる。しかし、相談する側は必ずしも答えを求めているとは限らない。むしろ、自分の不安な気持ちや苦労をただ最後まで聞いてほしいだけという場合も多いのだ。相手の話を途中で止めてアドバイスをするよりも、まずは「それは大変だったね」と気持ちを受け止めて聞くことの方が、相手の心を軽くするのではないだろうか。', 'Khi được ai đó tâm sự hỏi ý kiến, có những người cứ buột miệng nói ngay ý kiến hay cách giải quyết của mình. Thế nhưng, người tâm sự không hẳn lúc nào cũng tìm kiếm câu trả lời. Ngược lại, có nhiều trường hợp họ chỉ muốn được lắng nghe trọn vẹn nỗi bất an hay vất vả của mình mà thôi. Hơn là cắt ngang lời đối phương giữa chừng để đưa lời khuyên, việc trước tiên đón nhận cảm xúc và lắng nghe "Chắc hẳn bạn đã vất vả lắm nhỉ" chẳng phải sẽ giúp lòng họ nhẹ nhõm hơn sao.', NULL, NULL, NULL, '[{"expression":"意見","reading":"いけん","meaning_vi":"ý kiến"},{"expression":"解決","reading":"かいけつ","meaning_vi":"giải quyết"},{"expression":"場合","reading":"ばあい","meaning_vi":"trường hợp"}]', 184, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-007', 'N3-R-SHORT', 'N3', 'READING', 7, 'みどり市立図書館をご利用の皆様へ。現在、図書館のホームページの修理を行っているため、今月十五日の午後十時から次の日の朝午前六時まで、インターネットで本を検索することや貸し出し予約がすべて利用できなくなります。なお、すでに予約されている本の取り置き期間や返却期限には影響ありません。ご不便をおかけいたしますが、インターネットでの手続きは上記の時間を避けて行っていただきますようお願いいたします。', 'Gửi quý độc giả sử dụng Thư viện thành phố Midori. Hiện tại do đang tiến hành sửa chữa trang chủ của thư viện, nên từ 10 giờ đêm ngày 15 tháng này đến 6 giờ sáng hôm sau, toàn bộ việc tra cứu sách và đặt mượn trước qua internet sẽ không thể sử dụng được. Ngoài ra, thời hạn giữ sách đã đặt trước và hạn trả sách không bị ảnh hưởng. Xin lỗi vì sự bất tiện này, mong quý độc giả thực hiện các thủ tục trực tuyến tránh khung giờ nêu trên.', NULL, NULL, NULL, '[{"expression":"期間","reading":"きかん","meaning_vi":"thời hạn; khoảng thời gian"},{"expression":"期限","reading":"きげん","meaning_vi":"kỳ hạn"},{"expression":"影響","reading":"えいきょう","meaning_vi":"ảnh hưởng"}]', 196, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-008', 'N3-R-SHORT', 'N3', 'READING', 8, '買い物に行ったとき、「今だけ半額」「三つ買うと一つ無料」といった言葉を見ると、予定になかった物までつい買ってしまうことがある。安く買えたときは得をした気分になるが、家に帰ってから結局使わずに捨ててしまえば、お金を無駄にしたのと同じだ。値段が安いかどうかで選ぶのではなく、「今の自分に本当に必要かどうか」を考えてから買う習慣をつけたいものだ。', 'Khi đi mua sắm, hễ nhìn thấy những dòng chữ như "Chỉ giảm nửa giá lúc này" hay "Mua 3 tặng 1", ta lại hay lỡ mua cả những thứ không có trong dự định. Lúc mua được rẻ thì có cảm giác hời, nhưng nếu về nhà rốt cuộc lại không dùng mà vứt đi thì cũng chẳng khác nào lãng phí tiền bạc. Thay vì chọn mua vì giá rẻ hay không, tôi muốn rèn thói quen suy nghĩ xem "Hiện tại mình có thực sự cần nó không" trước khi mua.', NULL, NULL, NULL, '[{"expression":"半額","reading":"はんがく","meaning_vi":"nửa giá"},{"expression":"結局","reading":"けっきょく","meaning_vi":"rốt cuộc; kết cục"},{"expression":"習慣","reading":"しゅうかん","meaning_vi":"thói quen"}]', 170, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-009', 'N3-R-SHORT', 'N3', 'READING', 9, '高橋様。先日はお忙しい中、私どもの会社の新しい商品の説明会にお越しいただき、本当にありがとうございました。当日ご質問いただいた「商品の保証期間と修理サービス」についての詳しい資料が準備できましたので、このメールに添付してお送りいたします。なお、今月末までにご注文いただいた場合には、初期費用が二割引きになるキャンペーンも実施しております。ぜひご検討くださいますようお願い申し上げます。', 'Kính gửi anh/chị Takahashi. Hôm trước dù bận rộn nhưng anh/chị vẫn đến dự buổi giới thiệu sản phẩm mới của công ty chúng tôi, xin chân thành cảm ơn. Tài liệu chi tiết về "Thời hạn bảo hành và dịch vụ sửa chữa sản phẩm" mà anh/chị đặt câu hỏi hôm đó đã chuẩn bị xong, nên tôi xin đính kèm vào email này gửi tới anh/chị. Ngoài ra, nếu đặt hàng trước cuối tháng này, chúng tôi đang có chương trình giảm 20% chi phí ban đầu. Rất mong anh/chị xem xét.', NULL, NULL, NULL, '[{"expression":"先日","reading":"せんじつ","meaning_vi":"hôm trước"},{"expression":"費用","reading":"ひよう","meaning_vi":"chi phí"},{"expression":"期間","reading":"きかん","meaning_vi":"thời hạn"}]', 192, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-010', 'N3-R-SHORT', 'N3', 'READING', 10, '新しい習慣を始めようとするとき、最初から高い目標を立てすぎて失敗する人は少なくない。例えば、運動不足だからといって急に毎日五キロ走ろうとすれば、三日も続かないだろう。それよりも、「エレベーターではなく階段を使う」「寝る前に五分だけ体操をする」といった、少しの努力でできることから始める方がよい。小さな成功を毎日積み重ねることこそが、長く続けるための大切なこつなのだ。', 'Khi định bắt đầu một thói quen mới, không ít người thất bại vì đặt mục tiêu quá cao ngay từ đầu. Ví dụ, nếu vì thiếu vận động mà đột nhiên định chạy bộ 5km mỗi ngày thì chắc chẳng duy trì nổi đến 3 ngày. Thay vào đó, nên bắt đầu từ những việc chỉ cần chút ít nỗ lực là làm được như "Dùng cầu thang bộ thay vì thang máy" hay "Tập thể dục 5 phút trước khi ngủ". Việc tích lũy từng thành công nhỏ mỗi ngày chính là bí quyết quan trọng để duy trì lâu dài.', NULL, NULL, NULL, '[{"expression":"習慣","reading":"しゅうかん","meaning_vi":"thói quen"},{"expression":"目標","reading":"もくひょう","meaning_vi":"mục tiêu"},{"expression":"努力","reading":"どりょく","meaning_vi":"nỗ lực"}]', 183, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-011', 'N3-R-SHORT', 'N3', 'READING', 11, 'お客様へのお知らせ。いつも「あおぞらクリーニング駅前店」をご利用いただきありがとうございます。大変勝手ながら、店内の機械の入れ替え工事を行うため、十一月十日（月）から十一月十三日（木）までの四日間、臨時休業とさせていただきます。なお、お預かりしている服のお渡しや、お急ぎの洗濯物につきましては、歩いて五分の場所にある「北口店」にていつも通り受け付けますので、そちらをご利用ください。', 'Thông báo gửi quý khách hàng. Cảm ơn quý khách đã luôn sử dụng "Tiệm giặt khô Aozora chi nhánh trước ga". Chúng tôi xin phép nghỉ tạm thời 4 ngày từ thứ Hai ngày 10/11 đến thứ Năm ngày 13/11 để thi công thay mới máy móc trong tiệm. Ngoài ra, việc trả quần áo đang nhận giữ hoặc đồ giặt gấp vẫn được tiếp nhận bình thường tại "Chi nhánh cửa Bắc" cách đó 5 phút đi bộ, xin quý khách vui lòng sử dụng chi nhánh đó.', NULL, NULL, NULL, '[{"expression":"臨時","reading":"りんじ","meaning_vi":"tạm thời; đột xuất"},{"expression":"洗濯物","reading":"せんたくもの","meaning_vi":"đồ giặt"},{"expression":"駅前","reading":"えきまえ","meaning_vi":"trước ga"}]', 191, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-012', 'N3-R-SHORT', 'N3', 'READING', 12, 'パソコンやスマートフォンで簡単に文字が打てる時代になり、手で字を書く機会がすっかり減った。しかし、会議で聞いたことや思いついたアイデアを整理したいときは、今でも紙の手帳にペンで書く方が頭に入りやすいと感じる。線の太さを変えたり、大事な言葉を丸で囲んだり、矢印でつないだりしながら書くと、考えが自然にまとまっていくからだ。便利な道具が増えても、手書きの良さは失われないと思う。', 'Bước vào thời đại có thể gõ chữ dễ dàng bằng máy tính hay điện thoại thông minh, cơ hội viết chữ bằng tay đã giảm đi hẳn. Tuy nhiên, khi muốn sắp xếp những điều nghe được trong cuộc họp hay ý tưởng chợt nảy ra, đến nay tôi vẫn cảm thấy viết bằng bút lên sổ giấy dễ vào đầu hơn. Bởi lẽ vừa viết vừa thay đổi độ đậm nhạt của nét, khoanh tròn từ quan trọng hay nối bằng mũi tên sẽ giúp suy nghĩ tự nhiên được hệ thống lại. Dù công cụ tiện lợi có tăng lên thì ưu điểm của viết tay vẫn không mất đi.', NULL, NULL, NULL, '[{"expression":"機会","reading":"きかい","meaning_vi":"cơ hội; dịp"},{"expression":"文字","reading":"もじ","meaning_vi":"chữ viết"},{"expression":"矢印","reading":"やじるし","meaning_vi":"mũi tên"}]', 187, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-013', 'N3-R-SHORT', 'N3', 'READING', 13, '社員の皆様へ。来週の水曜日と木曜日に、社内での秋の健康診断を実施します。対象となる方は、事前に配られた質問の紙に必要なことを記入の上、当日必ず受付にお出しください。なお、血液検査があるため、午前に受ける方は前日の夜九時以降、午後に受ける方は当日の朝七時以降、食事をしないでください。ただし、水やお茶などの砂糖が入っていない飲み物は、検査の三十分前まで飲んでも構いません。', 'Gửi toàn thể nhân viên. Thứ Tư và thứ Năm tuần sau, công ty sẽ tổ chức khám sức khỏe mùa thu. Những người thuộc diện khám vui lòng điền đầy đủ thông tin cần thiết vào phiếu câu hỏi đã phát trước và nhất định phải nộp tại quầy tiếp nhận vào ngày khám. Ngoài ra, vì có xét nghiệm máu nên người khám buổi sáng không được ăn từ sau 9 giờ tối hôm trước, người khám buổi chiều không được ăn từ sau 7 giờ sáng ngày khám. Tuy nhiên, đồ uống không đường như nước lọc hay trà thì có thể uống đến trước khi khám 30 phút.', NULL, NULL, NULL, '[{"expression":"健康診断","reading":"けんこうしんだん","meaning_vi":"khám sức khỏe"},{"expression":"血液","reading":"けつえき","meaning_vi":"máu"},{"expression":"対象","reading":"たいしょう","meaning_vi":"đối tượng"}]', 185, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-014', 'N3-R-SHORT', 'N3', 'READING', 14, '初めての土地を旅行するとき、有名な観光地をできるだけたくさん回ろうとして、分単位で予定を詰め込む人がいる。しかし、移動ばかりに追われていると、途中で見つけた素敵な喫茶店に入ることも、地元の人と立ち話をすることもできない。あえて予定を入れない時間を少し残しておき、その日の気分で路地を歩いてみる方が、心に残る思いがけない発見に出会えるのではないだろうか。', 'Khi đi du lịch đến một vùng đất mới lần đầu, có những người cố đi qua thật nhiều điểm tham quan nổi tiếng nên xếp lịch dày đặc từng phút. Thế nhưng, nếu chỉ mải chạy theo việc di chuyển, ta sẽ chẳng thể ghé vào một quán nước tuyệt đẹp bắt gặp trên đường hay đứng trò chuyện với người dân địa phương. Chủ động chừa lại một chút thời gian trống không lên lịch trước và thử dạo bước qua các con hẻm theo tâm trạng ngày hôm đó chẳng phải sẽ giúp ta bắt gặp những khám phá bất ngờ đọng lại trong tim hay sao.', NULL, NULL, NULL, '[{"expression":"土地","reading":"とち","meaning_vi":"vùng đất; đất đai"},{"expression":"地元","reading":"じもと","meaning_vi":"địa phương"},{"expression":"単位","reading":"たんい","meaning_vi":"đơn vị"}]', 176, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-015', 'N3-R-SHORT', 'N3', 'READING', 15, 'さくら市環境課からのお知らせ。来月から、プラスチックごみの出し方のルールが一部変わります。これまで汚れが落ちにくい弁当の容器やマヨネーズの袋は「燃えるごみ」として出していただいていましたが、リサイクルの技術が進んだため、少し水で洗えばすべて「プラスチック資源」の日に出せるようになります。ただし、中に食べ残しが入ったままのものは回収できませんので、必ず空にしてから出してください。', 'Thông báo từ Phòng Môi trường thành phố Sakura. Từ tháng sau, quy tắc phân loại rác nhựa sẽ thay đổi một phần. Từ trước đến nay, hộp cơm hay túi sốt mayonnaise khó rửa sạch vết bẩn được vứt vào "rác cháy được", nhưng nhờ công nghệ tái chế phát triển nên chỉ cần tráng qua bằng nước là tất cả đều có thể đem bỏ vào ngày thu gom "tài nguyên nhựa". Tuy nhiên, những thứ bên trong vẫn còn thức ăn thừa sẽ không được thu gom, nên nhất định phải làm trống hoàn toàn trước khi đem vứt.', NULL, NULL, NULL, '[{"expression":"環境","reading":"かんきょう","meaning_vi":"môi trường"},{"expression":"資源","reading":"しげん","meaning_vi":"tài nguyên"},{"expression":"技術","reading":"ぎじゅつ","meaning_vi":"kỹ thuật; công nghệ"}]', 190, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-016', 'N3-R-SHORT', 'N3', 'READING', 16, '子どもが失敗したとき、親が先回りして助けてしまうのは簡単だ。しかし、転ばないように周りの石をすべて取り除いてしまうと、子どもは自分の力で立ち上がる方法を学べないまま大人になってしまう。もちろん危険なことから守るのは大人の責任だが、小さな失敗まで奪ってはいけない。うまくいかずに悔しい思いをし、どうすれば次はできるかを自分で考える経験こそが、子どもを大きく成長させるのだ。', 'Khi con trẻ thất bại, việc cha mẹ chạy trước đón đầu để giúp đỡ thì rất dễ dàng. Thế nhưng, nếu dọn sạch mọi hòn đá xung quanh để con khỏi ngã, đứa trẻ sẽ lớn lên mà không học được cách tự đứng dậy bằng sức mình. Tất nhiên bảo vệ trẻ khỏi nguy hiểm là trách nhiệm của người lớn, nhưng không được tước đi cả những thất bại nhỏ của trẻ. Chính trải nghiệm cảm thấy tiếc nuối khi làm chưa tốt và tự suy nghĩ xem lần sau phải làm thế nào mới giúp trẻ trưởng thành vượt bậc.', NULL, NULL, NULL, '[{"expression":"立ち上がる","reading":"たちあがる","meaning_vi":"đứng dậy"},{"expression":"責任","reading":"せきにん","meaning_vi":"trách nhiệm"},{"expression":"悔しい","reading":"くやしい","meaning_vi":"cay cú; tiếc nuối"}]', 185, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-017', 'N3-R-SHORT', 'N3', 'READING', 17, '経理部より社内の皆様へのお知らせ。出張にかかった交通費や宿泊費の精算は、これまで毎月末にまとめて紙の書類で提出していただいていましたが、今月からは社内システムで出張から戻った後五日以内に申請するルールに変わりました。なお、ホテルの領収書や新幹線の切符の控えは、スマートフォンのカメラで撮影してシステムに添付するとともに、元の紙も捨てずに経理部の箱へ入れてください。', 'Thông báo từ Phòng Kế toán gửi toàn thể nhân viên trong công ty. Việc thanh toán chi phí đi lại và lưu trú khi đi công tác từ trước đến nay được nộp gộp bằng giấy tờ vào cuối mỗi tháng, nhưng từ tháng này đã đổi sang quy tắc đăng ký trên hệ thống nội bộ trong vòng 5 ngày sau khi đi công tác về. Ngoài ra, hóa đơn khách sạn và cuống vé tàu Shinkansen vừa phải chụp bằng camera điện thoại để đính kèm lên hệ thống, vừa phải giữ lại bản giấy gốc để bỏ vào hộp của Phòng Kế toán chứ không được vứt đi.', NULL, NULL, NULL, '[{"expression":"交通費","reading":"こうつうひ","meaning_vi":"chi phí đi lại"},{"expression":"領収書","reading":"りょうしゅうしょ","meaning_vi":"hóa đơn; biên lai"},{"expression":"月末","reading":"げつまつ","meaning_vi":"cuối tháng"}]', 182, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-018', 'N3-R-SHORT', 'N3', 'READING', 18, '料理のレシピ本を見ると、「塩少々」と「塩ひとつまみ」という言葉がよく出てくる。同じ意味だと思っている人も意外と多いが、実は量が違う。「ひとつまみ」は親指と人差し指と中指の三本の指でつまんだ量で、約一グラムにあたる。一方、「少々」は親指と人差し指の二本だけでつまんだ量で、「ひとつまみ」の半分ぐらいだ。この小さな違いを知っておくと、毎日の料理の味がぐっと決まりやすくなる。', 'Khi xem sách dạy nấu ăn, ta thường bắt gặp cụm từ "một chút muối (shoushou)" và "một nhúm muối (hitotsumami)". Đáng ngạc nhiên là có nhiều người tưởng hai từ này cùng nghĩa, nhưng thực ra lượng của chúng khác nhau. "Một nhúm (hitotsumami)" là lượng kẹp bằng 3 ngón tay gồm ngón cái, ngón trỏ và ngón giữa, tương đương khoảng 1 gam. Ngược lại, "một chút (shoushou)" là lượng chỉ kẹp bằng 2 ngón cái và ngón trỏ, bằng khoảng một nửa của "hitotsumami". Biết được sự khác biệt nhỏ này sẽ giúp hương vị món ăn hằng ngày chuẩn vị hơn hẳn.', NULL, NULL, NULL, '[{"expression":"少々","reading":"しょうしょう","meaning_vi":"một chút"},{"expression":"一方","reading":"いっぽう","meaning_vi":"mặt khác"},{"expression":"半分","reading":"はんぶん","meaning_vi":"một nửa"}]', 185, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-019', 'N3-R-SHORT', 'N3', 'READING', 19, '「みどり市民講座・秋の焼き物体験」にお申し込みいただいた皆様へ。来週土曜日の講座ですが、当日はねんどを使ってお皿や茶碗を作りますので、汚れても構わない服装でお越しいただくか、エプロンをご持参ください。また、作られた器は講座のあとでこちらで乾かして焼くため、当日持ち帰ることはできません。完成した器のお渡しは一か月後の土曜日になりますので、あらかじめご理解ください。', 'Gửi các học viên đã đăng ký "Khóa học công dân Midori - Trải nghiệm làm đồ gốm mùa thu". Về buổi học thứ Bảy tuần sau, vì hôm đó sẽ dùng đất sét để nặn đĩa và bát ăn cơm nên xin quý vị mặc trang phục có lỡ bẩn cũng không sao hoặc mang theo tạp dề. Ngoài ra, đồ gốm làm ra sau buổi học sẽ được chúng tôi phơi khô và nung, nên chưa thể mang về ngay trong ngày hôm đó. Việc trao trả sản phẩm hoàn thiện sẽ diễn ra vào thứ Bảy một tháng sau, mong quý vị hiểu trước cho.', NULL, NULL, NULL, '[{"expression":"服装","reading":"ふくそう","meaning_vi":"trang phục"},{"expression":"当日","reading":"とうじつ","meaning_vi":"đúng ngày hôm đó"},{"expression":"講座","reading":"こうざ","meaning_vi":"khóa học; buổi học chuyên đề"}]', 182, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-020', 'N3-R-SHORT', 'N3', 'READING', 20, 'メールやチャットは、相手の都合を気にせずいつでも用件を送れる便利な道具だ。しかし、文字だけのやり取りでは声の調子や表情が伝わらないため、短い文を送ったつもりが「怒っているのではないか」と誤解されてしまうことがある。特におわびや断りなど、相手の気持ちに気配りが必要な場面では、文字だけで済ませようとせず、直接会うか電話で声を届ける方が、お互いの信頼を守ることにつながる。', 'Email hay tin nhắn chat là công cụ tiện lợi có thể gửi việc cần bàn bất cứ lúc nào mà không phải bận tâm hoàn cảnh lúc đó của đối phương. Thế nhưng, việc trao đổi chỉ bằng chữ viết không truyền tải được giọng điệu hay nét mặt, nên nhiều khi chỉ định gửi câu ngắn gọn lại bị hiểu lầm là "Có phải đang tức giận không". Đặc biệt trong những tình huống cần sự tinh tế với cảm xúc đối phương như xin lỗi hay từ chối, thay vì chỉ giải quyết bằng chữ viết, việc gặp trực tiếp hoặc gọi điện thoại sẽ giúp giữ gìn sự tin cậy lẫn nhau.', NULL, NULL, NULL, '[{"expression":"表情","reading":"ひょうじょう","meaning_vi":"biểu cảm; nét mặt"},{"expression":"場面","reading":"ばめん","meaning_vi":"tình huống; bối cảnh"},{"expression":"文字","reading":"もじ","meaning_vi":"chữ viết"}]', 184, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-001', 'N3-R-MEDIUM', 'N3', 'READING', 1, '私はこれまで、休日はできるだけ予定を入れて外出しなければもったいないと思っていた。せっかく仕事が休みなのだから、映画を見たり友人と食事をしたりして、朝から夜まで何か特別なことをしないと時間を無駄にしているような気がしていたのだ。\nしかしあるとき、週末に予定を詰め込みすぎて、月曜日の朝に強い疲れを感じている自分に気づいた。体を休めるはずの休日が、かえって疲れを増やす原因になっていたのである。それ以来、土曜日に出かけたら日曜日はあえて予定を入れず、家でゆっくり料理をしたり近所を散歩したりして静かに過ごすようにした。\n何もしない時間を作るようになってから、気持ちに余裕が生まれ、平日の仕事にも以前よりずっと集中できるようになった。休日は「何か特別なことをする日」ではなく、「心と体を元の元気な状態に戻す日」なのだと今は思っている。', 'Từ trước đến nay, tôi vẫn nghĩ rằng ngày nghỉ mà không lên lịch ra ngoài càng nhiều càng tốt thì thật lãng phí. Vì được nghỉ làm nên tôi có cảm giác nếu không làm điều gì đó đặc biệt từ sáng đến tối như xem phim hay ăn uống với bạn bè thì như đang lãng phí thời gian.\nThế nhưng có một lần, vì nhồi nhét quá nhiều lịch trình vào cuối tuần nên tôi nhận ra bản thân cảm thấy vô cùng mệt mỏi vào sáng thứ Hai. Ngày nghỉ vốn để cơ thể nghỉ ngơi lại trở thành nguyên nhân làm tăng thêm sự mệt mỏi. Kể từ đó, nếu thứ Bảy đã đi ra ngoài thì Chủ nhật tôi chủ động không xếp lịch, mà ở nhà thong thả nấu ăn hoặc đi dạo gần nhà.\nTừ khi tạo ra khoảng thời gian không làm gì cả, tâm trí tôi trở nên thư thái hơn và cũng tập trung hơn hẳn vào công việc ngày thường. Giờ đây tôi nghĩ ngày nghỉ không phải là "ngày để làm điều gì đặc biệt", mà là "ngày đưa tâm trí và cơ thể trở lại trạng thái khỏe khoắn ban đầu".', NULL, NULL, NULL, '[{"expression":"休日","reading":"きゅうじつ","meaning_vi":"ngày nghỉ"},{"expression":"原因","reading":"げんいん","meaning_vi":"nguyên nhân"},{"expression":"状態","reading":"じょうたい","meaning_vi":"trạng thái"}]', 363, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-002', 'N3-R-MEDIUM', 'N3', 'READING', 2, '近所の商店街に、昔から続く小さな八百屋がある。スーパーのように品物が袋に入ってきれいに並んでいるのではなく、店主のおじさんが毎朝早く市場から仕入れてきた新鮮な野菜が、大きなかごの中に山のように積まれている。\n最初は値段の札も少ないし、どうやって買えばいいのかわからなくて少し入りにくかった。ところが、勇気を出して「今日はどの野菜がおいしいですか」と聞いてみると、おじさんは笑顔で「このトマトは今朝届いたばかりで甘いよ」と教えてくれ、家庭でのおいしい食べ方まで丁寧に説明してくれたのだ。\nスーパーなら誰とも話さずに数分で買い物が終わる。しかし、お店の人と言葉を交わしながら季節の野菜を選ぶ時間は、私の毎日の暮らしに温かさと小さな楽しみを与えてくれている。これからもこの店に長く通い続けたいと思う。', 'Ở khu phố mua sắm gần nhà có một tiệm rau nhỏ mở từ xưa. Hàng hóa không được đóng túi xếp ngay ngắn như ở siêu thị, mà rau củ tươi ngon do bác chủ tiệm nhập từ chợ về mỗi sáng sớm được chất đầy như núi trong những chiếc rổ lớn.\nLúc đầu bảng giá cũng ít, tôi không biết phải mua thế nào nên hơi ngại bước vào. Thế nhưng, khi lấy hết can đảm hỏi thử "Hôm nay loại rau nào ngon ạ?", bác chủ tiệm liền mỉm cười bảo "Cà chua này vừa về sáng nay ngọt lắm đấy" rồi giải thích tận tình cả cách chế biến sao cho ngon ở nhà.\nNếu ở siêu thị thì chẳng cần nói chuyện với ai, chỉ vài phút là mua sắm xong. Tuy nhiên, khoảng thời gian vừa trò chuyện với người bán hàng vừa chọn rau củ theo mùa đang mang lại sự ấm áp và niềm vui nho nhỏ cho cuộc sống hằng ngày của tôi. Từ nay về sau tôi vẫn muốn gắn bó lâu dài với tiệm rau này.', NULL, NULL, NULL, '[{"expression":"市場","reading":"いちば","meaning_vi":"chợ"},{"expression":"勇気","reading":"ゆうき","meaning_vi":"dũng khí; can đảm"},{"expression":"新鮮","reading":"しんせん","meaning_vi":"tươi mới"}]', 345, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-003', 'N3-R-MEDIUM', 'N3', 'READING', 3, '私はこれまで、本は汚れないようにきれいに読むべきだと思っており、ページを折ったりペンで線を引いたりすることは絶対にしなかった。読み終わったあとも、買ったときと同じようにきれいな状態で本棚に並べるのが好きだったのだ。\nしかし昨年、尊敬する職場の先輩から一冊の本を借りたとき、その考えが変わった。その本のページには、先輩が感動した部分に青い線が引かれ、ページの端には「自分の仕事にも活かしたい」といった感想が小さな字でたくさん書き込まれていた。それを読んだとき、先輩がその本と真剣に向き合い、対話しながら読んでいたことが強く伝わってきた。\nそれ以来、私も自分で買った本には、気になった言葉に線を引き、そのとき考えたことを書き込むようになった。あとで読み返したとき、当時の自分の気持ちまで思い出せるのが一番の魅力だ。', 'Từ trước đến nay, tôi luôn nghĩ sách phải đọc thật giữ gìn để không bị bẩn nên tuyệt đối không bao giờ gấp trang hay dùng bút gạch chân. Sau khi đọc xong, tôi thích xếp sách lên giá trong tình trạng sạch đẹp giống hệt lúc mới mua.\nThế nhưng năm ngoái, khi mượn một cuốn sách từ người tiền bối ở chỗ làm mà tôi kính trọng, suy nghĩ đó đã thay đổi. Trên trang sách ấy, những đoạn tiền bối tâm đắc đều được gạch chân màu xanh, còn ở mép trang sách có viết rất nhiều cảm nghĩ bằng chữ nhỏ như "Muốn áp dụng vào công việc của mình". Khi đọc những dòng đó, tôi cảm nhận rõ rệt tiền bối đã đối diện nghiêm túc và trò chuyện cùng cuốn sách khi đọc.\nKể từ đó, với những cuốn sách tự mua, tôi cũng bắt đầu gạch chân các câu chữ tâm đắc và ghi lại điều mình nghĩ lúc ấy. Khi đọc lại về sau, việc có thể nhớ lại cả cảm xúc của bản thân thời điểm đó chính là sức hấp dẫn lớn nhất.', NULL, NULL, NULL, '[{"expression":"状態","reading":"じょうたい","meaning_vi":"trạng thái"},{"expression":"真剣","reading":"しんけん","meaning_vi":"nghiêm túc"},{"expression":"当時","reading":"とうじ","meaning_vi":"thời điểm đó"}]', 353, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-004', 'N3-R-MEDIUM', 'N3', 'READING', 4, '最近、駅やスーパーのレジで、店員の代わりに機械でお金を払う「セルフレジ」が急速に増えている。最初は操作の仕方がわからず、後ろに並んでいる人に迷惑をかけそうで緊張したが、慣れてみると財布から小銭を探す手間も減り、短い時間で買い物が済むのでとても便利だ。\n一方で、先日うちの近くにある古いパン屋へ行ったときのことだ。レジのおばさんが焼きたてのパンを袋に入れながら、「いつもありがとう。今日は風が強くて寒いから気をつけて帰ってね」と優しく声をかけてくれた。たったそれだけの言葉なのに、冷えていた体まで温かくなるような気がした。\n機械による効率化は、店の仕事を手伝って私たちの時間を節約してくれる素晴らしい技術だ。しかし、人と人が顔を合わせて言葉を交わすことで生まれる安心感も、社会から消えてほしくないと強く思う。', 'Gần đây, tại nhà ga hay quầy thu ngân siêu thị, "quầy tự thanh toán" trả tiền bằng máy thay cho nhân viên đang tăng lên nhanh chóng. Lúc đầu không biết cách thao tác, sợ làm phiền người xếp hàng phía sau nên tôi khá căng thẳng, nhưng khi quen rồi thì đỡ mất công tìm tiền lẻ trong ví và mua sắm xong nhanh chóng nên rất tiện lợi.\nMặt khác, hôm trước khi tôi đến tiệm bánh mì cũ gần nhà, cô thu ngân vừa cho bánh mì mới nướng vào túi vừa dịu dàng nói: "Cảm ơn cháu lúc nào cũng ghé mua nhé. Hôm nay gió mạnh trời lạnh đấy, về cẩn thận nha". Chỉ đôi lời ngắn ngủi thế thôi mà tôi cảm tưởng như cả cơ thể đang lạnh cũng ấm lên.\nViệc nâng cao hiệu suất bằng máy móc là công nghệ tuyệt vời giúp hỗ trợ công việc của cửa hàng và tiết kiệm thời gian cho chúng ta. Thế nhưng, tôi tha thiết mong rằng cảm giác an tâm sinh ra từ việc con người gặp mặt và trao đổi lời nói với nhau cũng sẽ không biến mất khỏi xã hội.', NULL, NULL, NULL, '[{"expression":"急速","reading":"きゅうそく","meaning_vi":"nhanh chóng"},{"expression":"小銭","reading":"こぜに","meaning_vi":"tiền lẻ"},{"expression":"技術","reading":"ぎじゅつ","meaning_vi":"kỹ thuật; công nghệ"}]', 351, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-005', 'N3-R-MEDIUM', 'N3', 'READING', 5, '子どもの頃、私は雨の日が大嫌いだった。学校の運動場で友だちとサッカーができないし、傘をさして歩いても靴やズボンの下の方が濡れて冷たくなるからだ。窓の外の暗い空を見ては、早く晴れないかなとため息ばかりついていた。\nところが、社会人になって一人暮らしを始めてから、雨の日の過ごし方が大きく変わった。雨の休日は「今日は無理に出かけなくてもいい日だ」と割り切って、普段はなかなかできない部屋の片づけをしたり、温かいコーヒーをいれて好きな音楽を聞いたりするようになったのだ。\n外の通りが静まり返り、窓に当たる雨の音だけが聞こえる部屋で本を読んでいると、晴れの日よりもかえって深く集中できることに気づいた。見方を少し変えるだけで、嫌いだった雨の日が、今では私にとって大切な休息の時間になっている。', 'Hồi còn nhỏ, tôi cực kỳ ghét những ngày mưa. Bởi lẽ tôi không thể đá bóng cùng bạn bè ở sân trường, mà dù có che ô đi bộ thì giày và phần dưới ống quần vẫn bị ướt lạnh. Cứ nhìn bầu trời xám xịt ngoài cửa sổ là tôi lại thở dài mong trời mau nắng.\nThế nhưng, từ khi đi làm và bắt đầu sống một mình, cách trải qua ngày mưa của tôi đã thay đổi hẳn. Vào ngày nghỉ trời mưa, tôi tự nhủ "Hôm nay là ngày không cần cố đi ra ngoài cũng được", rồi dọn dẹp phòng ốc vốn ngày thường ít khi làm được, hoặc pha cà phê nóng và nghe nhạc yêu thích.\nGiữa căn phòng khi đường phố bên ngoài tĩnh lặng, chỉ nghe thấy tiếng mưa rơi bên khung cửa sổ mà ngồi đọc sách, tôi nhận ra mình còn tập trung sâu hơn cả ngày nắng. Chỉ cần thay đổi góc nhìn một chút, ngày mưa từng đáng ghét giờ đây đã trở thành khoảng thời gian nghỉ ngơi quý giá đối với tôi.', NULL, NULL, NULL, '[{"expression":"社会人","reading":"しゃかいじん","meaning_vi":"người đi làm"},{"expression":"普段","reading":"ふだん","meaning_vi":"thường ngày"},{"expression":"一人暮らし","reading":"ひとりぐらし","meaning_vi":"sống một mình"}]', 340, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-006', 'N3-R-MEDIUM', 'N3', 'READING', 6, '料理を始めたばかりの頃、私は料理本の通りに調味料をきっちり計量スプーンで量って作っていた。それなのに、同じレシピで作っても、日によって味が濃すぎたり薄すぎたりして、なかなか安定したおいしい味にならなかった。\n不思議に思って料理が得意な母に相談したところ、「野菜は季節や大きさによって水分の量が違うのよ。だから、最後に必ず自分の舌で味見をして調整しなさい」と教えられた。私は本に書かれた数字ばかりを信じて、一番大切な「味を自分の舌で確かめること」をすっかり忘れていたのだ。\nそれからは、レシピの分量を基本にしつつも、火を止める前に必ず一口食べてみて、塩や醤油を少しずつ足すようにした。数字に頼りすぎず、自分の感覚を使って仕上げることの大切さを、毎日の料理を通して学んだ気がする。', 'Hồi mới tập nấu ăn, tôi luôn dùng thìa đong đo gia vị chuẩn xác y hệt như trong sách dạy nấu ăn. Ấy vậy mà dù nấu theo cùng một công thức, tùy từng ngày vị lại quá đậm hoặc quá nhạt, mãi không giữ được hương vị ngon ổn định.\nThấy lạ nên tôi đem chuyện hỏi mẹ vốn nấu ăn rất khéo, mẹ liền bảo: "Rau củ tùy theo mùa và kích cỡ mà lượng nước bên trong khác nhau đấy con ạ. Vì thế, cuối cùng nhất định phải tự nếm thử bằng lưỡi của mình để điều chỉnh". Hóa ra tôi chỉ mải tin vào những con số viết trong sách mà quên bẵng việc quan trọng nhất là "kiểm tra hương vị bằng chính lưỡi của mình".\nTừ đó trở đi, dù vẫn lấy định lượng trong công thức làm cơ sở, trước khi tắt bếp tôi luôn nếm thử một miếng rồi mới thêm từng chút muối hay nước tương. Qua việc nấu ăn hằng ngày, tôi cảm thấy mình đã học được tầm quan trọng của việc dùng cảm giác của chính mình để hoàn thiện thay vì quá phụ thuộc vào con số.', NULL, NULL, NULL, '[{"expression":"調味料","reading":"ちょうみりょう","meaning_vi":"gia vị"},{"expression":"水分","reading":"すいぶん","meaning_vi":"lượng nước; độ ẩm"},{"expression":"感覚","reading":"かんかく","meaning_vi":"cảm giác"}]', 336, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-007', 'N3-R-MEDIUM', 'N3', 'READING', 7, '先日、十年ぶりに小学校の頃の友人と会うことになり、私たちが昔よく遊んだ公園の近くにある小さな喫茶店で待ち合わせをした。会う前は、「十年の間に仕事も住む環境も変わったから、話すことがなくて気まずくなったらどうしよう」と少し心配していた。\nしかし、店のドアを開けて友人の顔を見た瞬間、そんな不安はすぐに消えてしまった。「全然変わらないね」と笑い合い、当時の先生の話や運動会の懐かしい思い出を話し始めると、まるで昨日も会っていたかのように楽しく会話が弾んだのである。\nもちろん、お互いに大人になり、仕事の悩みや将来の計画など、昔とは違う話題も増えた。それでも、自分の利益ばかりを考えずに何でも正直に話せる関係は、長い時間が経っても変わらないのだと知り、心がとても温かくなった。', 'Hôm trước, tôi có dịp gặp lại người bạn thời tiểu học sau 10 năm xa cách, và chúng tôi hẹn nhau tại một quán nước nhỏ gần công viên mà ngày xưa hai đứa thường chơi. Trước khi gặp, tôi hơi lo lắng: "Trong suốt 10 năm cả công việc lẫn môi trường sống đều đã thay đổi, nhỡ không có chuyện gì để nói rồi trở nên gượng gạo thì biết làm sao".\nThế nhưng, khoảnh khắc mở cửa quán và nhìn thấy gương mặt bạn, nỗi bất an ấy lập tức tan biến. Hai đứa cùng cười bảo "Cậu chẳng thay đổi chút nào nhỉ", rồi khi bắt đầu nhắc lại chuyện thầy cô ngày ấy hay kỷ niệm hội thao thân thương, cuộc trò chuyện trở nên rôm rả vui vẻ cứ như thể mới hôm qua còn gặp nhau.\nTất nhiên, cả hai đều đã trưởng thành, cũng có thêm những chủ đề khác xưa như nỗi trăn trở trong công việc hay kế hoạch tương lai. Dù vậy, nhận ra mối quan hệ có thể thẳng thắn chia sẻ mọi điều không tính toán lợi ích riêng vẫn chẳng hề thay đổi sau ngần ấy năm khiến lòng tôi vô cùng ấm áp.', NULL, NULL, NULL, '[{"expression":"瞬間","reading":"しゅんかん","meaning_vi":"khoảnh khắc"},{"expression":"話題","reading":"わだい","meaning_vi":"chủ đề câu chuyện"},{"expression":"当時","reading":"とうじ","meaning_vi":"thời điểm đó"}]', 333, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-008', 'N3-R-MEDIUM', 'N3', 'READING', 8, '英語や日本語などの外国語を熱心に勉強している人から、「単語帳で言葉をたくさん覚えたのに、実際の会話になると何も言えなくなる」という悩みをよく聞く。知識として頭に入っている言葉と、会話の中で実際に使える言葉には大きな差があるのだ。\n言葉を本当に使えるようにするためには、覚えた単語を使って「自分のこと」を短い文にしてみる練習がとても役に立つ。例えば、「残念」という言葉を覚えたら、教科書の例文をただ読むだけでなく、「昨日楽しみにしていた試合が雨で中止になって残念だった」と自分の出来事に置き換えて声に出して言ってみるのである。\n自分の気持ちや実際の経験と結びついた言葉は、記憶に深く残るだけでなく、次に似た場面に出会ったときに自然と口から出てくるようになる。毎日三つだけでも自分の文を作る習慣を続ければ、話す力は確実に伸びていくはずだ。', 'Từ những người đang chăm chỉ học ngoại ngữ như tiếng Anh hay tiếng Nhật, tôi thường nghe nỗi trăn trở rằng: "Dù đã nhớ rất nhiều từ trong sổ từ vựng, nhưng khi vào hội thoại thực tế lại chẳng nói được câu nào". Giữa từ ngữ nằm trong đầu dưới dạng kiến thức và từ ngữ thực sự sử dụng được trong giao tiếp có một khoảng cách rất lớn.\nĐể có thể thực sự sử dụng được từ ngữ, việc luyện tập dùng từ vừa học đặt thành câu ngắn nói về "chuyện của chính mình" rất hữu ích. Ví dụ, khi học từ "đáng tiếc (zannen)", thay vì chỉ đọc câu ví dụ trong sách giáo khoa, hãy thử thay bằng sự việc của bản thân và nói thành tiếng: "Hôm qua trận đấu tôi hằng mong đợi bị hủy vì mưa nên thật đáng tiếc".\nNhững từ ngữ gắn liền với cảm xúc và trải nghiệm thực tế của bản thân không chỉ lưu lại sâu trong trí nhớ, mà lần tới khi gặp tình huống tương tự chắc chắn cũng sẽ tự nhiên bật ra khỏi miệng.', NULL, NULL, NULL, '[{"expression":"知識","reading":"ちしき","meaning_vi":"kiến thức"},{"expression":"実際","reading":"じっさい","meaning_vi":"thực tế"},{"expression":"単語","reading":"たんご","meaning_vi":"từ vựng"}]', 365, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-009', 'N3-R-MEDIUM', 'N3', 'READING', 9, 'うちの会社では先月から、毎週水曜日の午後を「会議をしない時間帯」と決めた。それまでは、毎日いくつもの会議が続いて自分の仕事をする時間が取れず、夕方になってから残業をして書類を作る社員が大変多かったからだ。\nこの取り組みが始まった当初は、「急に相談したいことができたら困るのではないか」と反対する声もあった。しかし実際にやってみると、みんなが水曜日の午後に向けて前もって連絡や確認を済ませるようになり、かえって仕事の段取りが良くなったのである。\nさらに、誰にも邪魔されずに三時間続けて集中できる時間があることで、新しい計画をじっくり考えたり、たまっていた仕事を片づけたりできるようになった。今では水曜日の残業がほとんどなくなり、早く帰って家族と過ごせると社員からもとても評判が良い。', 'Tại công ty tôi từ tháng trước đã quy định chiều thứ Tư hằng tuần là "khung giờ không họp hành". Bởi lẽ trước đó, ngày nào cũng có hàng loạt cuộc họp nối tiếp nhau khiến nhân viên không có thời gian làm việc của mình, đến chiều muộn lại phải làm thêm giờ để soạn tài liệu.\nKhi hoạt động này mới bắt đầu, cũng có ý kiến phản đối vì lo rằng "Nhỡ đột nhiên có việc cần bàn gấp thì sẽ gay go mất". Thế nhưng khi thực hiện thực tế, mọi người đều chủ động liên lạc và xác nhận công việc từ trước để chuẩn bị cho chiều thứ Tư, nhờ vậy việc sắp xếp quy trình làm việc trái lại còn tốt hơn.\nHơn nữa, nhờ có 3 tiếng liên tục tập trung mà không bị ai làm phiền, nhân viên có thể suy nghĩ kỹ các kế hoạch mới hoặc giải quyết dứt điểm công việc tồn đọng. Giờ đây việc làm thêm giờ vào thứ Tư hầu như không còn và được nhân viên đánh giá rất cao.', NULL, NULL, NULL, '[{"expression":"確認","reading":"かくにん","meaning_vi":"xác nhận"},{"expression":"評判","reading":"ひょうばん","meaning_vi":"đánh giá; tiếng tăm"},{"expression":"済ませる","reading":"すませる","meaning_vi":"làm cho xong"}]', 338, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-010', 'N3-R-MEDIUM', 'N3', 'READING', 10, '春になると、駅の近くにある桜並木が美しいピンク色の花を咲かせる。私は毎日その道を通って通勤しているが、花が咲いている一週間ほどの間は、普段より十分早く家を出てゆっくり歩くようにしている。\nところが不思議なことに、満開の桜が散ってしまったあと、緑の葉が増える五月の桜の木を見上げる人はほとんどいない。しかし私は、太陽の光を受けてきらきらと輝く若い緑の葉や、夏の強い日差しを止めて涼しい木陰を作ってくれる姿も、花に負けないくらい強い魅力があると思う。\n美しい花の季節だけでなく、秋に葉が赤や黄色に変わり、冬に葉を落として厳しい寒さを我慢する姿も含めて、一本の木は一年中さまざまな表情を見せてくれる。足元ばかり見て急いで歩くのではなく、時には空を見上げて季節の移り変わりを感じたい。', 'Mỗi độ xuân về, hàng cây hoa anh đào gần nhà ga lại nở rộ sắc hồng tươi đẹp. Hằng ngày tôi đều đi làm qua con đường đó, và trong khoảng một tuần hoa nở, tôi thường ra khỏi nhà sớm hơn ngày thường 10 phút để thong thả dạo bước.\nThế nhưng có một điều kỳ lạ là sau khi hoa anh đào mãn khai rụng hết, hầu như chẳng có ai ngước nhìn những cây anh đào xanh um lá vào tháng Năm. Tuy vậy, tôi cho rằng những tán lá non xanh mướt lấp lánh dưới ánh mặt trời, hay dáng vẻ che chắn nắng gắt mùa hè để tạo bóng râm mát mẻ cũng có sức cuốn hút chẳng kém gì lúc nở hoa.\nKhông chỉ mùa hoa tươi đẹp, mà tính cả lúc lá chuyển sang đỏ vàng vào mùa thu và rụng hết lá chịu đựng giá lạnh khắc nghiệt mùa đông, một cái cây cho ta thấy biết bao sắc thái suốt bốn mùa trong năm. Thay vì chỉ nhìn xuống chân bước vội, đôi khi tôi muốn ngước nhìn bầu trời để cảm nhận sự chuyển mình của đất trời.', NULL, NULL, NULL, '[{"expression":"太陽","reading":"たいよう","meaning_vi":"mặt trời"},{"expression":"表情","reading":"ひょうじょう","meaning_vi":"biểu cảm; sắc thái"},{"expression":"普段","reading":"ふだん","meaning_vi":"thường ngày"}]', 336, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-011', 'N3-R-MEDIUM', 'N3', 'READING', 11, '先日、部屋の本棚とクローゼットを整理していたら、何年も使っていないかばんや一度しか着ていない服が次から次へと出てきた。買ったときは「いつか使うだろう」と思っていたのに、結局存在すら忘れて奥にしまい込んでいたのだ。\nこのままではいけないと思い、思い切って一年以上使っていない物をリサイクルショップへ持っていき、まだ読めるきれいな本は市の図書館に寄付することにした。作業には丸一日かかったが、部屋の床が広く見えるようになると、不思議と心まで明るくすっきりした気がした。\n今回の片づけを通して、物をたくさん持つことが豊かさなのではなく、自分が本当に好きで大切に使える物だけに囲まれて暮らすことこそが、毎日の気持ちを穏やかにして心地よい生活につながるということに深く気づかされた。', 'Hôm trước, khi dọn dẹp giá sách và tủ quần áo trong phòng, hết chiếc túi nhiều năm không dùng lại đến những bộ quần áo mới mặc đúng một lần cứ thế lộ ra. Lúc mua thì nghĩ "Chắc có lúc sẽ dùng đến", vậy mà rốt cuộc tôi quên bẵng cả sự tồn tại của chúng và cất sâu vào trong góc.\nNghĩ bụng cứ thế này mãi không ổn, tôi quyết định mạnh dạn mang những món đồ đã hơn một năm không dùng đến tiệm đồ cũ, còn những cuốn sách sạch đẹp vẫn đọc tốt thì quyên tặng cho thư viện thành phố. Công việc mất trọn một ngày, nhưng khi nhìn sàn phòng trở nên rộng rãi, kỳ lạ thay tôi cảm thấy lòng mình cũng tươi sáng hẳn lên.\nQua đợt dọn dẹp lần này, tôi nhận ra rằng sở hữu thật nhiều đồ đạc không phải là sự sung túc, mà sống giữa những món đồ mình thực sự yêu thích và trân trọng sử dụng mới chính là điều dẫn đến một cuộc sống hằng ngày dễ chịu.', NULL, NULL, NULL, '[{"expression":"結局","reading":"けっきょく","meaning_vi":"rốt cuộc"},{"expression":"先日","reading":"せんじつ","meaning_vi":"hôm trước"},{"expression":"穏やか","reading":"おだやか","meaning_vi":"êm dịu"}]', 334, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-012', 'N3-R-MEDIUM', 'N3', 'READING', 12, '私はこれまで、朝は一分でも長く寝ていたいタイプで、いつも出発の二十分前に慌てて起き、朝ごはんも食べずに駅まで走っていた。当然、会社に着く頃にはすでに疲れており、午前中はなかなか仕事に身が入らなかった。\nしかし半年ほど前、医師から「朝食を抜くと体も脳も目を覚まさないよ」と注意されたのをきっかけに、思い切って毎朝三十分早く起きるようにした。最初は眠くてつらかったが、窓を開けて冷たい空気を吸い、温かいスープとパンを食べるようになると、一週間ほどで体が慣れてきた。\n不思議なことに、朝ゆっくり食事をしてから家を出ると、電車が少し遅れてもイライラしなくなり、午前中から頭がすっきり働いて仕事が速く進むようになった。朝のわずか三十分の違いが、一日全体の質を大きく変えるのだと実感している。', 'Từ trước đến nay, tôi vốn thuộc tuýp người buổi sáng muốn ngủ cố thêm dù chỉ một phút, nên lúc nào cũng cuống cuồng dậy trước giờ xuất phát 20 phút, chẳng kịp ăn sáng mà cứ thế chạy ra ga. Tất nhiên, đến lúc tới công ty thì đã mệt nhoài, suốt buổi sáng mãi không tập trung vào công việc được.\nThế nhưng khoảng nửa năm trước, nhân dịp bị bác sĩ nhắc nhở "Bỏ bữa sáng thì cả cơ thể lẫn não bộ đều không tỉnh táo được đâu", tôi đã quyết tâm dậy sớm hơn 30 phút mỗi sáng. Lúc đầu buồn ngủ rất vất vả, nhưng khi mở cửa sổ hít thở không khí mát lành rồi ăn súp nóng với bánh mì, chỉ khoảng một tuần là cơ thể đã quen.\nKỳ lạ thay, khi thong thả ăn sáng rồi mới ra khỏi nhà, dù tàu điện có trễ một chút tôi cũng không còn cáu gắt, đầu óc tỉnh táo ngay từ buổi sáng nên công việc tiến triển nhanh hẳn. Tôi thực sự thấm thía rằng chỉ 30 phút khác biệt vào buổi sáng lại làm thay đổi lớn chất lượng của cả một ngày.', NULL, NULL, NULL, '[{"expression":"慌てる","reading":"あわてる","meaning_vi":"vội vàng; cuống cuồng"},{"expression":"医師","reading":"いし","meaning_vi":"bác sĩ"},{"expression":"全体","reading":"ぜんたい","meaning_vi":"toàn bộ; toàn thể"}]', 338, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-013', 'N3-R-MEDIUM', 'N3', 'READING', 13, '先日、市の美術館へ絵画の展覧会を見に行ったときのことだ。私は最初、それぞれの絵の横に貼ってある説明書きばかりを熱心に読んでいた。「この画家は何年に生まれ、どんな方法を使ったか」という文字の情報を読むことで、絵を深く理解したつもりになっていたのだ。\nところが、ふと隣を見ると、小学生ぐらいの男の子が説明書きには目もくれず、一枚の大きな海の絵の前でじっと立ち止まっていた。そして母親に「この波、今にも僕たちの方へ飛び出してきそうだね」と目を輝かせながら楽しそうに話しかけたのである。\n私ははっとした。芸術を楽しむのに、難しい知識ばかりを先に頭に入れる必要はなかったのだ。それからは説明を読む前に、まず絵の前に立って色や形の美しさを自分の目でそのまま感じてみるようにしている。', 'Chuyện xảy ra hôm trước khi tôi đến bảo tàng mỹ thuật thành phố xem triển lãm tranh. Lúc đầu, tôi chỉ chăm chú đọc phần bảng thuyết minh dán bên cạnh mỗi bức tranh. Qua việc đọc thông tin chữ viết như "Họa sĩ này sinh năm nào, sử dụng phương pháp gì", tôi cứ ngỡ mình đã hiểu sâu bức tranh.\nThế nhưng, chợt nhìn sang bên cạnh, tôi thấy một cậu bé trạc tuổi tiểu học chẳng hề ngó ngàng tới bảng thuyết minh mà chỉ đứng lặng trước một bức tranh biển lớn. Rồi cậu bé mắt sáng lên vui vẻ nói với mẹ: "Ngọn sóng này trông như sắp nhảy bổ về phía mẹ con mình đến nơi rồi mẹ nhỉ".\nTôi chợt giật mình nhận ra. Để thưởng thức nghệ thuật, đâu cần phải nhồi nhét những kiến thức khó hiểu vào đầu trước. Từ lúc đó trở đi, trước khi đọc thuyết minh, tôi luôn đứng trước bức tranh và cảm nhận nguyên vẹn vẻ đẹp của màu sắc, hình khối bằng chính đôi mắt của mình.', NULL, NULL, NULL, '[{"expression":"絵画","reading":"かいが","meaning_vi":"hội họa; tranh vẽ"},{"expression":"芸術","reading":"げいじゅつ","meaning_vi":"nghệ thuật"},{"expression":"母親","reading":"ははおや","meaning_vi":"người mẹ"}]', 333, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-014', 'N3-R-MEDIUM', 'N3', 'READING', 14, '私はこれまで、人から仕事を頼まれると、自分の仕事がどんなに忙しくても「いいですよ」と引き受けてしまっていた。断ったら相手に嫌われるのではないか、冷たい人だと思われるのではないかと怖かったからだ。\nしかし先月、いくつもの仕事を同時に抱え込んだ結果、疲れ果てて大切な書類にミスをしてしまい、かえって周りの人に大きな迷惑をかけてしまった。そのとき上司から、「できないときに正直に状況を伝えて断ることも、責任ある仕事のやり方だよ」と言われ、目が覚める思いがした。\nそれからは、自分の手持ちの仕事の量と締め切りを確かめ、無理なときは「今は別の急ぎの仕事があるため、明日以降なら手伝えます」と具体的に伝えるようにしている。きちんと理由を説明すれば、相手との関係が悪くなることはないのだとわかった。', 'Từ trước đến nay, hễ được người khác nhờ việc gì là dù công việc của mình có bận đến mấy tôi cũng nhận lời "Vâng, được chứ ạ". Bởi tôi sợ nếu từ chối thì sẽ bị đối phương ghét hoặc bị nghĩ là người lạnh lùng.\nThế nhưng tháng trước, hậu quả của việc ôm đồm quá nhiều việc cùng lúc là tôi kiệt sức và mắc lỗi trong một tài liệu quan trọng, trái lại còn gây phiền phức lớn cho những người xung quanh. Khi ấy, cấp trên đã nói với tôi: "Khi không làm xuể mà thẳng thắn báo rõ tình hình để từ chối cũng là cách làm việc có trách nhiệm đấy", khiến tôi như bừng tỉnh.\nKể từ đó, tôi luôn kiểm tra khối lượng công việc hiện có và thời hạn hoàn thành, khi quá sức sẽ trao đổi cụ thể: "Hiện tôi đang có việc gấp khác, nếu từ ngày mai trở đi thì tôi có thể phụ giúp". Tôi đã hiểu ra rằng chỉ cần giải thích lý do đàng hoàng thì mối quan hệ với đối phương sẽ chẳng hề xấu đi.', NULL, NULL, NULL, '[{"expression":"引き受ける","reading":"ひきうける","meaning_vi":"nhận lời; đảm nhận"},{"expression":"断る","reading":"ことわる","meaning_vi":"từ chối"},{"expression":"状況","reading":"じょうきょう","meaning_vi":"tình hình; tình trạng"}]', 340, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-015', 'N3-R-MEDIUM', 'N3', 'READING', 15, '最近、駅前の図書館の隣に、コーヒーを飲みながら本が読めるスペースが新しく作られた。これまでの図書館といえば、飲食は一切禁止で、ページをめくる音にも気を使うような静まり返った場所というイメージが強かった。\nもちろん、静かに集中して調べ物をしたい人のために、二階と三階はこれまで通り私語も飲食も禁止の読書室になっている。新しくできた一階のスペースでは、小さな音楽が流れる中、親子が絵本を読んで笑い合ったり、学生が飲み物を片手に友人と意見を交わしたりすることができる。\nこのスペースができてから、普段はあまり図書館に来なかった若い人や家族連れの姿が目に見えて増えたという。時代に合わせて場所の使い方を自由に変えていくことで、本に親しむ人が増えるのはとても喜ばしいことだ。', 'Gần đây, bên cạnh thư viện trước nhà ga mới mở thêm một không gian vừa uống cà phê vừa đọc sách. Nhắc đến thư viện từ trước tới nay, người ta thường có ấn tượng mạnh về một nơi tĩnh lặng tuyệt đối, nghiêm cấm ăn uống và đến tiếng lật trang sách cũng phải ý tứ.\nTất nhiên, để phục vụ những người muốn yên tĩnh tập trung tra cứu, tầng 2 và tầng 3 vẫn giữ nguyên là phòng đọc cấm nói chuyện riêng và ăn uống như trước. Tại không gian mới ở tầng 1, trong tiếng nhạc nhẹ nhàng, cha mẹ và con cái có thể cùng đọc sách tranh cười nói, hay sinh viên vừa cầm đồ uống vừa trao đổi ý kiến với bạn bè.\nNghe nói từ khi có không gian này, bóng dáng những người trẻ tuổi hay các gia đình vốn ít khi đến thư viện đã tăng lên trông thấy. Việc thay đổi cách sử dụng không gian phù hợp với thời đại để ngày càng có nhiều người làm quen với sách quả là điều rất đáng mừng.', NULL, NULL, NULL, '[{"expression":"禁止","reading":"きんし","meaning_vi":"cấm"},{"expression":"意見","reading":"いけん","meaning_vi":"ý kiến"},{"expression":"親子","reading":"おやこ","meaning_vi":"mẫu tử"}]', 330, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-016', 'N3-R-MEDIUM', 'N3', 'READING', 16, '今年の春から、ベランダの小さな箱でミニトマトを育て始めた。最初は「毎日水をやっていれば、勝手に大きく育って実がなるだろう」と簡単に考えていた。しかし、毎日たっぷり水をあげていたところ、葉が黄色くなって元気がなくなってしまった。\n慌てて園芸の本を調べてみると、トマトはもともと乾燥した土地の植物なので、水をやりすぎると根が腐ってしまうことがわかった。土の表面がしっかり乾いてから水をやるように変え、日当たりの良い場所に箱を動かしたところ、やがて元気を取り戻して黄色い小さな花を咲かせた。\n一か月後、真っ赤に甘くなった実を初めて収穫して食べたときの味と香りは忘れられない。相手の性質をよく知らずにただお世話をしても、かえって負担になることがあるのだと、小さなトマトから教えられた。', 'Từ mùa xuân năm nay, tôi bắt đầu trồng cà chua bi trong chiếc hộp nhỏ ngoài ban công. Lúc đầu tôi chỉ nghĩ đơn giản là "Cứ tưới nước hằng ngày thì cây sẽ tự khắc lớn lên và ra quả thôi". Thế nhưng, khi ngày nào tôi cũng tưới thật đẫm nước, lá cây lại ngả vàng và mất dần sức sống.\nHoảng hốt tra sách làm vườn, tôi mới biết cà chua vốn là loài thực vật ở vùng đất khô ráo, nên nếu tưới quá nhiều nước thì rễ sẽ bị úng thối. Khi tôi đổi sang chỉ tưới sau khi bề mặt đất đã khô hẳn và chuyển hộp trồng cây ra chỗ nhiều nắng, chẳng bao lâu cây đã hồi phục sức sống và nở những bông hoa nhỏ màu vàng.\nMột tháng sau, hương vị khi lần đầu thu hoạch và thưởng thức trái chín đỏ ngọt lịm thật không thể nào quên. Cây cà chua nhỏ đã dạy cho tôi rằng nếu không hiểu rõ đặc tính của đối phương mà cứ chăm sóc theo ý mình thì đôi khi lại trở thành gánh nặng.', NULL, NULL, NULL, '[{"expression":"植物","reading":"しょくぶつ","meaning_vi":"thực vật"},{"expression":"表面","reading":"ひょうめん","meaning_vi":"bề mặt"},{"expression":"日当たり","reading":"ひあたり","meaning_vi":"độ nắng chiếu vào"}]', 336, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-017', 'N3-R-MEDIUM', 'N3', 'READING', 17, '買い物をするとき、以前の私はデザインや色ばかりを見て、服や靴をすぐに買ってしまうことがよくあった。しかし、そうやって買った靴は、実際に履いて長く歩くと足が痛くなったり、服も洗濯するとすぐに形が崩れたりして、結局あまり使わなくなってしまうことが多かった。\nあるとき、父が十年以上大切に使っている革のかばんを見て、「どうしてそんなに長く使えるの」と聞いたことがある。父は「買う前に、縫い目がしっかりしているか、持ったときに重すぎないかをよく確かめて、本当に納得したものだけを買うからだよ」と教えてくれた。\nそれ以来、私も見た目だけで飛びつかず、生地の丈夫さや使いやすさを確かめてから買うようにしている。少し値段は高くても、良い物を長く使う方が、結局お金の節約にもなり満足感も高い。', 'Khi đi mua sắm, trước đây tôi thường chỉ nhìn vào kiểu dáng hay màu sắc rồi mua ngay quần áo, giày dép. Thế nhưng, những đôi giày mua theo cách đó khi thực sự xỏ vào đi bộ lâu lại làm đau chân, còn quần áo giặt xong cũng nhanh mất dáng, rốt cuộc chẳng mấy khi dùng đến nữa.\nCó một lần, nhìn chiếc cặp da mà bố đã trân trọng sử dụng suốt hơn 10 năm, tôi liền hỏi: "Sao bố có thể dùng bền đến thế ạ?". Bố bảo: "Vì trước khi mua, bố luôn kiểm tra kỹ xem đường may có chắc chắn không, cầm lên có bị nặng quá không, chỉ mua thứ mình thực sự ưng ý thôi".\nTừ đó trở đi, tôi cũng không vội mua chỉ vì vẻ bề ngoài mà luôn kiểm tra độ bền của chất vải và sự tiện dụng trước khi mua. Dù giá có đắt hơn một chút, nhưng dùng đồ tốt được lâu dài thì rốt cuộc vừa tiết kiệm tiền bạc lại vừa mang lại sự hài lòng cao hơn.', NULL, NULL, NULL, '[{"expression":"実際","reading":"じっさい","meaning_vi":"thực tế"},{"expression":"結局","reading":"けっきょく","meaning_vi":"rốt cuộc"},{"expression":"以前","reading":"いぜん","meaning_vi":"trước đây"}]', 336, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-018', 'N3-R-MEDIUM', 'N3', 'READING', 18, '子どもの頃、私は人前で話すのが大の苦手で、授業中に先生から指されると顔が真っ赤になり、声が震えてしまった。大学に入ってからもそれは変わらず、ゼミでの発表の日は朝から暗い気持ちで仕方がなかった。\nそんな私に、指導教授が「うまく話そうとしなくていい。聞き手に何を一番伝えたいか、その一つだけに絞って準備しなさい」とアドバイスをくれた。私はそれまで、自分が恥ずかしい思いをしないように、難しい言葉を並べて完全な発表のメモを作ることばかり考えていたのだ。\n次の発表では、書いた文を丸暗記するのをやめ、自分が一番面白いと思った調査結果を図にして、友人に説明するような気持ちで話してみた。すると、聞き手がうなずきながら聞いてくれるのが見え、初めて人前で話すことの楽しさを感じることができた。', 'Hồi còn nhỏ, tôi cực kỳ sợ nói trước đám đông, trong giờ học hễ bị thầy cô gọi tên là mặt lại đỏ bừng và giọng run lập cập. Khi vào đại học điều đó vẫn chẳng thay đổi, ngày phải thuyết trình ở lớp chuyên đề là tôi buồn bã nặng nề ngay từ sáng.\nVới một người như tôi, giáo sư hướng dẫn đã khuyên: "Em không cần cố nói cho thật trơn tru. Hãy chỉ lọc ra đúng một điều quan trọng nhất muốn truyền đạt tới người nghe rồi chuẩn bị thôi". Từ trước đến lúc ấy, vì sợ bản thân bị xấu hổ nên tôi chỉ chăm chăm xếp thật nhiều từ ngữ khó để soạn một bản ghi chú thuyết trình hoàn chỉnh.\nTrong buổi thuyết trình tiếp theo, tôi bỏ việc học thuộc lòng từng chữ đã viết, mà vẽ biểu đồ kết quả khảo sát mình thấy thú vị nhất rồi trình bày với tâm thế như đang giải thích cho bạn bè. Thế là tôi nhìn thấy người nghe vừa gật đầu vừa lắng nghe, và lần đầu tiên cảm nhận được niềm vui của việc nói trước mọi người.', NULL, NULL, NULL, '[{"expression":"教授","reading":"きょうじゅ","meaning_vi":"giáo sư"},{"expression":"感じる","reading":"かんじる","meaning_vi":"cảm thấy"},{"expression":"友人","reading":"ゆうじん","meaning_vi":"bạn"}]', 337, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-019', 'N3-R-MEDIUM', 'N3', 'READING', 19, '冬の寒い時期になると、うちでは週に二回は鍋料理が登場する。鍋料理の良いところは、何といっても準備が簡単で、たくさんの種類の野菜や肉、魚を一度に温かく食べられることだ。\n一人暮らしを始めたばかりの頃は、野菜を一袋買っても使い切れずに冷蔵庫の中で傷ませてしまうことがよくあった。しかし、鍋料理を作るようになってからは、キャベツでもキノコでも豆腐でも、残っている材料を何でも切って鍋に入れるだけで立派な夕食になるので、食べ物を無駄にすることがなくなった。\nさらに、同じ材料でも、魚や野菜のだしにしたり、みそ味やキムチ味に変えたりすれば、毎日食べても飽きることがない。寒さが厳しい季節を健康に、そしてお金を節約しながら乗り切るために、体も心も温まる鍋料理は私にとって欠かせない味方だ。', 'Khi bước vào mùa đông giá lạnh, ở nhà tôi mỗi tuần có đến hai lần món lẩu xuất hiện. Điểm tuyệt vời của món lẩu trước hết nằm ở chỗ chuẩn bị đơn giản, lại có thể ăn nóng cùng lúc nhiều loại rau củ, thịt và cá.\nHồi mới bắt đầu sống một mình, tôi thường mua một túi rau về nhưng không dùng hết nên để hỏng trong tủ lạnh. Thế nhưng từ khi nấu món lẩu, dù là bắp cải, nấm hay đậu phụ, cứ còn nguyên liệu nào đem cắt cho vào nồi là thành bữa tối thịnh soạn, nên tôi không còn làm lãng phí đồ ăn nữa.\nHơn nữa, dù cùng nguyên liệu đó nhưng chỉ cần đổi sang nước dùng cá hay rau củ, vị tương miso hay vị kim chi thì có ăn mỗi ngày cũng chẳng ngán. Để vượt qua mùa lạnh khắc nghiệt một cách khỏe mạnh và tiết kiệm tiền bạc, món lẩu là người bạn đồng hành không thể thiếu đối với tôi.', NULL, NULL, NULL, '[{"expression":"種類","reading":"しゅるい","meaning_vi":"chủng loại"},{"expression":"冷蔵庫","reading":"れいぞうこ","meaning_vi":"tủ lạnh"},{"expression":"材料","reading":"ざいりょう","meaning_vi":"nguyên liệu"}]', 336, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-020', 'N3-R-MEDIUM', 'N3', 'READING', 20, '電車の座席に座っているときやエレベーターに乗るとき、周りの人のことを少し意識するだけで、お互いが気持ちよく過ごせる場面は多い。例えば、座席で荷物をひざの上に置いたり、足を組まずに座ったりすれば、隣にもう一人座れるあいた場所ができる。\n先日、雨の日に満員電車に乗ったときのことだ。私の前に立っていた若い女性が、自分の濡れた傘が周りの人の服に当たらないよう、傘をたたんで自分の体の前にまっすぐ持って立っていた。そのさりげない気配りを見て、近くにいた人たちも自然と自分の荷物や傘の位置を静かに直し始めたのである。\n「マナーを守りなさい」と強い言葉で注意するよりも、誰か一人の思いやりのある行動が、周りの人の心を動かして車内に温かい良い空気を作っていくのだと強く感じた出来事だった。', 'Khi ngồi trên ghế tàu điện hay khi đi thang máy, chỉ cần để ý một chút đến những người xung quanh là có rất nhiều tình huống giúp mọi người cùng cảm thấy dễ chịu. Ví dụ, nếu đặt túi xách lên đùi hoặc ngồi không bắt chéo chân trên ghế tàu, sẽ tạo ra khoảng trống để thêm một người nữa ngồi được bên cạnh.\nChuyện xảy ra hôm trước khi tôi đi tàu đông nghịt vào một ngày mưa. Một cô gái trẻ đứng trước mặt tôi đã gấp gọn chiếc ô ướt của mình và cầm thẳng phía trước người để chiếc ô không chạm vào quần áo của những người xung quanh. Nhìn thấy sự tinh tế nhẹ nhàng đó, những người đứng gần cũng tự nhiên chỉnh lại vị trí túi xách và ô của mình.\nĐó là sự việc giúp tôi cảm nhận sâu sắc rằng: hơn là nhắc nhở bằng lời lẽ gay gắt "Hãy giữ phép lịch sự", chính hành động giàu lòng quan tâm của một người sẽ lay động trái tim những người xung quanh và tạo nên bầu không khí tốt đẹp.', NULL, NULL, NULL, '[{"expression":"座席","reading":"ざせき","meaning_vi":"ghế ngồi"},{"expression":"位置","reading":"いち","meaning_vi":"vị trí"},{"expression":"先日","reading":"せんじつ","meaning_vi":"hôm trước"}]', 335, 3, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-001', 'N3-R-LONG', 'N3', 'READING', 1, 'インターネットで買い物をすると、過去に買った商品の記録をもとに「あなたへのおすすめ」が画面に次々と表示される。読みたい本や見たい映画を探すときも、自分の好みに合ったものを機械が自動で選んでくれるため、迷う時間が減って大変便利になったと感じる人は多いだろう。\nしかし、先日ふと自分の部屋の本棚を眺めてみたとき、あることに気づいて少し怖くなった。そこに並んでいる二十冊以上の本が、どれも似たようなテーマや同じような意見のビジネスの本ばかりだったのだ。便利さに頼って「おすすめ」ばかりを選んでいた結果、私は知らず知らずのうちに自分の興味のある狭い世界に閉じこもっていたのである。\nそれに対して、週末に町の大きな書店へ足を運び、棚の間をゆっくり歩いてみると、普段なら絶対に調べないような歴史の小説や科学の絵本が自然と目に入ってくる。たまたま美しい表紙の絵やタイトルに引かれて手に取った一冊が、それまでの自分の考え方を大きく広げてくれることも少なくない。\nもちろん、忙しい毎日の中で無駄なく情報を集めるために、インターネットの便利な機能を活用するのは賢い方法だ。けれども、時には機械の提案から少し離れ、自分の足で歩いて思いがけない本との偶然の出会いを楽しむことこそが、私たちの心をより豊かにしてくれるのではないだろうか。', 'Khi mua sắm trên internet, dựa trên lịch sử các mặt hàng đã mua trước đó, mục "Gợi ý dành cho bạn" sẽ lần lượt hiện ra trên màn hình. Khi tìm sách muốn đọc hay phim muốn xem cũng vậy, vì máy móc tự động chọn ra những thứ hợp sở thích nên hẳn nhiều người cảm thấy thời gian phân vân giảm bớt và vô cùng tiện lợi.\nThế nhưng, hôm trước khi bất chợt ngắm nhìn giá sách trong phòng mình, tôi nhận ra một điều và thấy hơi đáng sợ. Hơn 20 cuốn sách xếp ở đó cuốn nào cũng toàn là sách kinh doanh có chủ đề na ná nhau hoặc cùng một kiểu quan điểm. Hệ quả của việc ỷ lại vào sự tiện lợi và chỉ chọn theo "gợi ý" là tôi đã vô tình tự nhốt mình trong thế giới hẹp của những điều bản thân sẵn có hứng thú.\nNgược lại, khi đặt chân đến hiệu sách lớn trong thành phố vào cuối tuần và thong thả dạo bước giữa các kệ sách, những cuốn tiểu thuyết lịch sử hay sách tranh khoa học mà ngày thường tôi tuyệt đối không bao giờ tìm kiếm lại tự nhiên lọt vào mắt. Không ít lần một cuốn sách tình cờ cầm lên vì bị bìa sách thu hút lại giúp mở rộng cách suy nghĩ từ trước đến nay của tôi.\nTất nhiên, giữa cuộc sống bận rộn hằng ngày, việc tận dụng tính năng tiện lợi của internet để thu thập thông tin không lãng phí là cách làm khôn ngoan. Tuy nhiên, đôi khi rời xa những đề xuất của máy móc, tự mình dạo bước và tận hưởng những cuộc gặp gỡ tình cờ chẳng phải mới chính là điều làm tâm hồn chúng ta trở nên phong phú hơn hay sao.', NULL, NULL, NULL, '[{"expression":"過去","reading":"かこ","meaning_vi":"quá khứ"},{"expression":"記録","reading":"きろく","meaning_vi":"ghi chép; lịch sử"},{"expression":"偶然","reading":"ぐうぜん","meaning_vi":"tình cờ"}]', 552, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-002', 'N3-R-LONG', 'N3', 'READING', 2, '私は大学を卒業してから三年間、東京の大きな食品会社で働いていた。毎日の仕事は忙しかったがやりがいもあり、将来もずっとこの街で働き続けるつもりだった。ところが、故郷で暮らす祖父が足を悪くしたという知らせを受け、家族と相談した末に、故郷の町へ戻って地元の小さな工場で働くことを決めた。\n故郷へ戻ったばかりの頃は、東京との違いにとまどうことばかりだった。電車は一時間に一本しか来ないし、夜八時を過ぎると駅前の商店街も閉まって真っ暗になる。にぎやかで何でもあった東京の生活が恋しくなり、「やはり戻ってくるのは早すぎたのではないか」と後悔する夜もあった。\nしかし、地元の工場で働き始めて半年ほど経った頃、私の気持ちに変化が生まれた。その工場では、近くの農家が大切に育てた果物を使ってジャムを作っており、生産者の顔がすぐ近くに見える。ある日、農家のおじさんから「君たちが作ってくれたジャム、孫がおいしいと喜んで食べていたよ」と声をかけられたとき、自分の仕事が誰かの笑顔に直接つながっていることを強く実感したのだ。\n都会には都会の便利さや刺激がある一方で、地方には人と人との距離の近さや、豊かな自然の良さを感じながら働ける喜びがある。場所が変わっても、自分が毎日の仕事にどう向き合うかによって、どこでも幸せな人生を作れるのだと今は思っている。', 'Sau khi tốt nghiệp đại học, tôi đã làm việc 3 năm tại một công ty thực phẩm lớn ở Tokyo. Công việc hằng ngày tuy bận rộn nhưng rất đáng làm, và tôi cứ định sẽ tiếp tục làm việc ở thành phố này mãi trong tương lai. Thế nhưng, khi nhận được tin ông nội sống ở quê bị đau chân, sau khi bàn bạc với gia đình, tôi quyết định trở về quê hương và làm việc tại một nhà máy nhỏ ở địa phương.\nHồi mới về quê, tôi toàn bỡ ngỡ trước sự khác biệt so với Tokyo. Tàu điện mỗi tiếng mới có một chuyến, còn quá 8 giờ tối là khu phố mua sắm trước ga cũng đóng cửa tối om. Tôi nhớ cuộc sống nhộn nhịp cái gì cũng có ở Tokyo, có những đêm từng hối hận tự hỏi "Phải chăng mình trở về quê là quá sớm?".\nTuy nhiên, khoảng nửa năm sau khi bắt đầu làm việc tại nhà máy địa phương, trong lòng tôi đã có sự thay đổi. Tại nhà máy đó, chúng tôi làm mứt từ trái cây do các hộ nông dân gần đó dày công vun trồng, nên nhìn thấy rất rõ gương mặt của người sản xuất. Một hôm, khi được bác nông dân bắt chuyện: "Mứt các cháu làm, đứa cháu nội của bác khen ngon và thích thú ăn lắm đấy", tôi đã cảm nhận sâu sắc rằng công việc của mình đang kết nối trực tiếp với nụ cười của ai đó.\nThành phố lớn có sự tiện lợi và sức hấp dẫn của thành phố lớn, mặt khác địa phương lại có sự gần gũi giữa người với người và niềm vui được làm việc giữa vẻ đẹp của thiên nhiên trù phú. Giờ đây tôi nghĩ rằng dù ở nơi đâu, tùy thuộc vào cách ta đối diện với công việc hằng ngày mà ta đều có thể tạo dựng một cuộc sống hạnh phúc.', NULL, NULL, NULL, '[{"expression":"故郷","reading":"こきょう","meaning_vi":"quê hương"},{"expression":"農家","reading":"のうか","meaning_vi":"nhà nông; hộ nông dân"},{"expression":"距離","reading":"きょり","meaning_vi":"khoảng cách"}]', 561, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-003', 'N3-R-LONG', 'N3', 'READING', 3, '子どもの頃、母に連れられて近所のスーパーへ買い物に行くと、母は牛乳や豆腐を棚から取るとき、いつも一番手前ではなく少し奥にある品物に手を伸ばしていた。理由を聞くと、「奥にある方が新しく店に並んだもので、賞味期限が長いからよ」と教えてくれた。そのため、私も大人になって一人暮らしを始めてから、ずっと同じように奥から取るのが当たり前だと思っていた。\nところが先日、大学時代の友人がスーパーで店長として働いていると聞き、久しぶりに食事をしたときのことだ。友人は「お客さんがみんな奥から商品を取るので、手前にある日付の近い商品が売れ残ってしまい、毎日まだ食べられるたくさんの食品を捨てなければならないんだ」と寂しそうに話してくれたのだ。\n私はその言葉を聞いて、自分の小さな行動が食品の無駄につながっていたことに初めて気づき、大変恥ずかしい気持ちになった。考えてみれば、その日の夜や次の日の朝にすぐ食べてしまう牛乳や豆腐なら、賞味期限が一日や二日長くても短くても、私にとってはまったく同じことなのである。\nそれ以来、私はすぐ使う予定の食品を買うときは、必ず棚の一番手前にあるものから順番に選ぶようにしている。一人一人が「いつ食べるか」を考えて買い物をするだけで、社会全体で捨てられる食品を大きく減らすことができるはずだ。', 'Hồi còn nhỏ, mỗi lần được mẹ dẫn đi mua sắm ở siêu thị gần nhà, khi lấy sữa tươi hay đậu phụ trên kệ, mẹ tôi lúc nào cũng với tay lấy món đồ nằm hơi sâu bên trong chứ không lấy món ở ngay ngoài cùng. Khi tôi hỏi lý do, mẹ bảo: "Đồ để bên trong là đồ mới xếp lên kệ, hạn sử dụng dài hơn đấy con". Vì thế, khi lớn lên và bắt đầu sống một mình, tôi vẫn luôn nghĩ việc lấy đồ từ bên trong ra như vậy là chuyện đương nhiên.\nThế nhưng hôm trước, nghe tin người bạn thời đại học đang làm cửa hàng trưởng tại một siêu thị, nhân dịp lâu ngày đi ăn cùng nhau, bạn ấy đã buồn bã tâm sự: "Vì khách hàng ai cũng lấy sản phẩm từ phía trong ra, nên những sản phẩm có ngày gần hơn ở phía ngoài bị ế lại, khiến ngày nào bọn mình cũng phải vứt bỏ rất nhiều thực phẩm vẫn còn ăn được".\nNghe những lời đó, lần đầu tiên tôi nhận ra hành động nhỏ của mình lại đang góp phần gây lãng phí thực phẩm và cảm thấy vô cùng xấu hổ. Nghĩ kỹ mà xem, nếu là sữa tươi hay đậu phụ sẽ ăn ngay vào tối hôm đó hoặc sáng hôm sau, thì hạn sử dụng có dài hơn hay ngắn hơn một hai ngày đối với tôi cũng chẳng khác gì nhau.\nKể từ đó, khi mua những thực phẩm dự định dùng ngay, tôi luôn chọn món nằm ở ngoài cùng của kệ. Chỉ cần mỗi người suy nghĩ xem "Khi nào mình sẽ ăn" lúc mua sắm thôi, chắc chắn toàn xã hội có thể giảm thiểu đáng kể lượng thực phẩm bị vứt bỏ.', NULL, NULL, NULL, '[{"expression":"期限","reading":"きげん","meaning_vi":"kỳ hạn; thời hạn"},{"expression":"食品","reading":"しょくひん","meaning_vi":"thực phẩm"},{"expression":"先日","reading":"せんじつ","meaning_vi":"hôm trước"}]', 551, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-004', 'N3-R-LONG', 'N3', 'READING', 4, '近年、多くの会社で「仕事と生活の調和」が大切だと言われるようになり、残業を減らして定時に帰ることを勧める職場が増えてきた。私の働く会社でも、昨年から午後七時にはオフィスの電気を消すというルールが決まり、最初は「これで自分の自由な時間が増える」と社員の誰もが喜んでいた。\nしかし、始まって三か月ほど経つと、思わぬ問題が見えてきた。仕事の量そのものは以前と変わっていないのに、帰る時間だけが厳しく制限されたため、昼休みを削ってパソコンに向かったり、終わらなかった仕事を家に持ち帰って夜遅くまで続けたりする人が出てきたのだ。これでは、ただ仕事をする場所が会社から家に移っただけで、本当の意味で休めているとは言えない。\nそこで私たちの課では、なぜ時間が足りなくなるのかを全員で話し合ってみた。すると、誰も読んでいないような長い報告書を毎週作っていたり、メールで済むような簡単な確認のために毎回三十分の会議を開いていたりすることに気づいたのである。\n私たちは思い切ってそれらの無駄な作業をやめ、一人の人に仕事が集中しないようにお互いの進み具合を毎朝五分で共有するようにした。早く帰るという形だけを決めるのではなく、毎日の仕事のやり方そのものを見直すことこそが、働く人の健康と大切な時間を守るために本当に必要なのだと実感している。', 'Những năm gần đây, tại nhiều công ty người ta thường nói đến tầm quan trọng của "sự hài hòa giữa công việc và cuộc sống", ngày càng nhiều nơi làm việc khuyến khích giảm làm thêm giờ và tan làm đúng giờ. Ở công ty tôi đang làm cũng vậy, từ năm ngoái đã đặt ra quy định tắt điện văn phòng lúc 7 giờ tối, ban đầu nhân viên ai nấy đều vui mừng nghĩ rằng "Thế là mình sẽ có thêm thời gian tự do".\nThế nhưng, khi thực hiện được khoảng 3 tháng thì một vấn đề không ngờ tới đã lộ ra. Khối lượng công việc vốn chẳng hề thay đổi so với trước, vậy mà chỉ có giờ về bị giới hạn nghiêm ngặt, nên xuất hiện những người phải cắt xén giờ nghỉ trưa để ngồi trước máy tính, hoặc mang việc chưa xong về nhà làm tiếp đến tận đêm khuya. Như thế này thì chỉ là chuyển chỗ làm việc từ công ty về nhà, chứ chẳng thể nói là được nghỉ ngơi đúng nghĩa.\nVì vậy, tại phòng ban của chúng tôi, tất cả mọi người đã cùng nhau bàn bạc xem tại sao lại thiếu thời gian. Qua đó, chúng tôi nhận ra mình vẫn đang hàng tuần làm những bản báo cáo dài dòng chẳng ai đọc, hay mỗi lần lại mở cuộc họp 30 phút chỉ để xác nhận những việc đơn giản có thể giải quyết qua email.\nChúng tôi đã mạnh dạn bỏ đi những công việc lãng phí đó, đồng thời mỗi sáng dành 5 phút chia sẻ tiến độ của nhau để công việc không bị dồn vào một người. Không phải chỉ quy định hình thức về sớm, mà chính việc xem xét lại bản thân cách thức làm việc mới là điều thực sự cần thiết để bảo vệ sức khỏe và thời gian của người lao động.', NULL, NULL, NULL, '[{"expression":"職場","reading":"しょくば","meaning_vi":"nơi làm việc"},{"expression":"昨年","reading":"さくねん","meaning_vi":"năm trước"},{"expression":"見直す","reading":"みなおす","meaning_vi":"xem lại"}]', 556, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-005', 'N3-R-LONG', 'N3', 'READING', 5, '子どもの頃、私は自転車に乗れるようになるまで周りの友達よりずっと時間がかかった。近くの広い公園で練習するたびに何度も転んでひざをすりむき、痛さと悔しさで泣きながら「もう自転車なんて一生乗れなくてもいい」と自転車を地面に放り出したこともある。\nそんなとき、後ろで自転車をずっと支えてくれていた父は、決して私を叱らなかった。ただ静かに私の隣に座り、「昨日よりも三メートル長く進めたよ。転んだのは、前に進もうとしてペダルを強く踏んだしるしじゃないか」と優しく言って私を元気づけてくれたのだ。その温かい言葉に力を得て、私は涙を拭いてもう一度ハンドルを強く握り、夕方遅くまで何度も練習を続けた。\nそして一週間後の夕方、父が後ろから手を離していることにも気づかず、公園の端から端まで風を切って一人で走れたときの深い感動は、二十年経った今でもはっきりと覚えている。自分の力で最後まで乗り切れたという大きな喜びは、その後の私の強い自信になった。\n大人になった今、仕事で新しいことに挑戦して失敗すると、当時の父の優しい声と言葉を思い出す。失敗することは決して恥ずかしいことではなく、前に進もうと自分の力で最後まで努力しているしるしなのだと思えば、あきらめずにもう一度やってみようという勇気が心の中から自然とわいてくるのである。', 'Hồi còn nhỏ, tôi mất nhiều thời gian hơn hẳn bạn bè xung quanh mới biết đi xe đạp. Mỗi lần tập ở công viên rộng gần nhà là tôi lại ngã lên ngã xuống trầy xước cả đầu gối, có lần vừa khóc vì đau và tức tưởi vừa quẳng xe xuống đất mà nói "Con chẳng cần biết đi xe đạp suốt đời nữa đâu".\nNhững lúc như thế, bố tôi — người vẫn giữ yên xe phía sau cho tôi — chưa bao giờ trách mắng tôi. Bố chỉ lặng lẽ ngồi xuống cạnh tôi và dịu dàng nói để khích lệ: "Hôm nay con đã đi xa hơn hôm qua được 3 mét rồi đấy. Bị ngã chẳng phải là dấu hiệu cho thấy con đã đạp mạnh bàn đạp để tiến về phía trước hay sao". Tiếp thêm sức mạnh từ lời nói ấm áp ấy, tôi lau nước mắt và nắm chặt tay lái một lần nữa.\nRồi vào buổi chiều một tuần sau đó, tôi thậm chí chẳng nhận ra bố đã buông tay từ phía sau, cảm xúc sâu sắc khi tự mình lướt gió đạp một mạch từ đầu này sang đầu kia công viên dù đã 20 năm trôi qua tôi vẫn nhớ rõ mồn một. Niềm vui lớn lao khi tự làm được đến cùng bằng sức mình đã trở thành sự tự tin vững chắc cho tôi về sau.\nGiờ đây khi đã trưởng thành, mỗi lần thử sức với việc mới trong công việc mà gặp thất bại, tôi lại nhớ về lời bố năm xưa. Khi nghĩ rằng thất bại chẳng phải điều gì đáng xấu hổ mà là dấu hiệu cho thấy mình đang nỗ lực tiến về phía trước, lòng can đảm muốn thử lại lần nữa lại dâng lên từ trong tim.', NULL, NULL, NULL, '[{"expression":"自信","reading":"じしん","meaning_vi":"tự tin"},{"expression":"努力","reading":"どりょく","meaning_vi":"nỗ lực"},{"expression":"当時","reading":"とうじ","meaning_vi":"thời điểm đó"}]', 551, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-006', 'N3-R-LONG', 'N3', 'READING', 6, '家で料理をするとき、人参や大根の皮をむいてそのままごみ箱に捨ててしまう人は多いだろう。私も以前は、野菜の皮やキャベツの外側の硬い葉、ブロッコリーの太い真ん中の部分などは「食べられないごみ」だと思い込み、何の疑問も持たずに毎回捨てていた。\nしかしある日、料理上手な祖母の家で夕食の手伝いをしていたとき、祖母がむいた大根の皮を細く切って、ごま油と醤油で炒め始めたのを見て驚いた。食べてみると、シャキシャキとした歯ごたえがあり、白い実の部分よりも味が濃くて白いご飯にぴったりだったのだ。祖母は「皮のすぐ下に栄養も香りも一番詰まっているんだよ。捨てるなんてとんでもない」と笑った。\nさらに祖母は、ブロッコリーの太い部分も外側の硬いところだけを取ってスープに入れ、残った野菜の端は細かく切って温かいみそ汁の実にしてしまった。私が普段ならごみ袋にいっぱい出していたはずの野菜の残りが、祖母の手にかかるとほとんど残らずおいしい家庭料理に変わってしまったのである。\nそれ以来、私も自宅の台所で野菜を切るときは、「この部分は本当に食べられないだろうか」と一度立ち止まって考えるようになった。少しの工夫で毎日の食費が減るだけでなく、家庭から出るごみも減って環境にも優しいこの素晴らしい知恵を、私もこれからずっと大切に守っていきたい。', 'Khi nấu ăn ở nhà, hẳn có nhiều người gọt vỏ cà rốt hay củ cải rồi vứt thẳng vào thùng rác. Trước đây tôi cũng từng mặc định vỏ rau củ, lá già bên ngoài của bắp cải hay phần lõi dày ở giữa của súp lơ xanh là "rác không ăn được", nên lần nào cũng vứt đi mà chẳng chút thắc mắc.\nThế nhưng một hôm, khi phụ giúp làm bữa tối ở nhà bà ngoại vốn nấu ăn rất khéo, tôi đã vô cùng ngạc nhiên khi thấy bà thái sợi phần vỏ củ cải vừa gọt rồi đem xào với dầu vừng và nước tương. Khi ăn thử, món ăn giòn sần sật, đậm vị hơn cả phần củ trắng bên trong và cực kỳ hợp với cơm trắng. Bà ngoại cười bảo: "Dinh dưỡng và hương thơm tập trung nhiều nhất ở ngay dưới lớp vỏ đấy cháu ạ. Vứt đi thì phí phạm quá".\nHơn thế nữa, phần lõi dày của súp lơ xanh bà cũng chỉ tước bỏ lớp vỏ cứng bên ngoài rồi cho vào nấu súp, còn các mẩu đầu thừa đuôi thẹo của rau củ thì thái nhỏ làm cái cho món canh tương miso ấm nóng. Đống vụn rau củ mà bình thường ở nhà tôi hẳn đã vứt đầy một túi rác, qua bàn tay của bà ngoại hầu như chẳng bỏ đi chút nào mà biến thành những món ăn gia đình ngon lành.\nKể từ đó, khi cắt rau củ trong căn bếp nhà mình, tôi cũng luôn dừng lại suy nghĩ một chút xem "Phần này có thực sự không ăn được không nhỉ". Nhờ chút khéo léo mà không chỉ giảm tiền chợ mỗi ngày, giảm lượng rác thải và thân thiện với môi trường, bí quyết sống này tôi muốn trân trọng gìn giữ mãi về sau.', NULL, NULL, NULL, '[{"expression":"疑問","reading":"ぎもん","meaning_vi":"nghi vấn; thắc mắc"},{"expression":"栄養","reading":"えいよう","meaning_vi":"dinh dưỡng"},{"expression":"環境","reading":"かんきょう","meaning_vi":"môi trường"}]', 553, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-007', 'N3-R-LONG', 'N3', 'READING', 7, '知らない土地へ出かけたとき、今の私たちはスマートフォンの地図アプリを開けば、目的地までの最短の道順もかかる時間も一瞬で調べることができる。青い線の通りに歩いていけば、誰にも道を尋ねることなく、迷わずにたどり着けるのだから本当に便利な世の中だ。\nしかし先日、古いお寺を見に行こうと郊外の町を歩いていたとき、運悪くスマートフォンの電池が切れてしまった。周りにコンビニも見当たらず困り果てた私は、庭で花に水をやっていたおばあさんに思い切って道を尋ねた。するとおばあさんは、「大通りを行くより、そこの川の横の小道を通ると静かで気持ちがいいよ。今ちょうど白い花が満開だから見てごらん」と笑顔で教えてくれたのだ。\n言われた通りに川の横の小道を歩いてみると、きれいな水の音とともに甘い花の香りが広がり、古い石橋や小さな水車など、まるで昔話の世界に入り込んだような美しい風景が続いていた。もしスマートフォンの地図通りに大通りを歩いていたら、五分早く着いたかもしれないが、この素晴らしい景色には絶対に出会えなかっただろう。\n最短の距離で無駄なく目的地に着くことは、仕事の移動ではもちろん大切だ。けれども、画面の矢印ばかりを見つめて歩くのではなく、時には人に道を尋ねたり遠回りをしたりする中にこそ、旅を本当に豊かにする発見が隠れているのだと感じた。', 'Khi đi đến một vùng đất lạ, ngày nay chúng ta chỉ cần mở ứng dụng bản đồ trên điện thoại thông minh là có thể tra cứu trong chớp mắt cả lộ trình ngắn nhất lẫn thời gian di chuyển tới đích. Cứ đi theo đường kẻ màu xanh là chẳng cần hỏi đường ai cũng tới nơi mà không bị lạc, quả là một thế giới vô cùng tiện lợi.\nThế nhưng hôm trước, khi đang đi bộ ở một thị trấn ngoại ô để tới thăm một ngôi chùa cổ, chẳng may điện thoại của tôi lại hết pin. Xung quanh chẳng thấy cửa hàng tiện lợi nào, đang lúc bí quá tôi đành đánh bạo hỏi đường một cụ bà đang tưới hoa trong sân. Cụ bà liền mỉm cười chỉ dẫn: "Thay vì đi đường lớn, cháu đi theo lối nhỏ ven con sông đằng kia vừa yên tĩnh vừa dễ chịu lắm. Ngay lúc này hoa trắng đang nở rộ đấy, cháu qua ngắm thử xem".\nKhi đi bộ theo con đường nhỏ ven sông đúng như lời cụ dặn, cùng với tiếng nước chảy trong trẻo là hương hoa ngọt ngào lan tỏa, một khung cảnh tuyệt đẹp như bước vào thế giới truyện cổ tích với cây cầu đá cổ kính và guồng nước nhỏ nối tiếp nhau. Nếu tôi cứ đi theo đường lớn như bản đồ điện thoại chỉ dẫn, có lẽ sẽ tới sớm hơn được 5 phút, nhưng chắc chắn sẽ không bao giờ bắt gặp khung cảnh tuyệt vời này.\nViệc đến đích theo quãng đường ngắn nhất không chút lãng phí tất nhiên rất quan trọng khi di chuyển trong công việc. Tuy nhiên, thay vì chỉ chăm chăm nhìn vào mũi tên trên màn hình mà bước đi, đôi khi chính trong việc hỏi đường người dân hay đi đường vòng lại ẩn chứa những khám phá làm cho chuyến đi thực sự trở nên phong phú.', NULL, NULL, NULL, '[{"expression":"風景","reading":"ふうけい","meaning_vi":"phong cảnh"},{"expression":"距離","reading":"きょり","meaning_vi":"khoảng cách; cự ly"},{"expression":"先日","reading":"せんじつ","meaning_vi":"hôm trước"}]', 561, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-008', 'N3-R-LONG', 'N3', 'READING', 8, '私は昔から「明日やればいいや」と面倒なことを後回しにする癖があり、学生時代も夏休みの宿題を八月の終わりになって泣きながら片づけるタイプだった。社会人になってからもその性格はなかなか直らず、提出期限までまだ二週間ある書類を机の隅に置いたままにして、締め切りの前日に慌てて残業することがたびたびあった。\nしかしあるとき、いつも仕事を余裕をもって終わらせている隣の席の先輩のやり方を観察して、大きな違いに気づいた。私は「三時間かかる大きな仕事だ」と思うと始めるのが嫌になってしまうのだが、先輩は書類を受け取るとすぐに五分だけ時間を取り、見出しを書いたり必要な資料のリストを作ったりと、ごく小さな最初の作業だけをその日のうちに済ませていたのだ。\n先輩に理由を聞くと、「人間は一度でも手をつけたことは、続きが気になって自然と進めたくなるものなんだよ。ゼロのままにしておくのが一番重荷になるんだ」と教えてくれた。なるほど、私は仕事を始める前の「心の壁」を自分で高くしてしまっていたのである。\nそれからは、どんなに気が進まない仕事でも、頼まれたその日のうちに「ファイルを作って一行だけ書く」というルールを自分に決めるようにした。不思議なことに、たった一行書いただけで気持ちの負担がすっと消え、次の日にはすんなりと続きに取りかかれるようになった。', 'Từ xưa tôi đã có tật hay trì hoãn những việc phiền phức với suy nghĩ "Để mai làm cũng được", thời đi học cũng thuộc tuýp người đợi đến cuối tháng Tám mới vừa khóc vừa giải quyết bài tập nghỉ hè. Khi đi làm rồi tính cách đó vẫn mãi không sửa được, những tài liệu còn 2 tuần nữa mới đến hạn nộp tôi cứ để ở góc bàn, để rồi hôm trước ngày hết hạn lại cuống cuồng làm thêm giờ.\nThế nhưng có một lần, quan sát cách làm việc của người tiền bối ngồi bàn bên cạnh vốn lúc nào cũng hoàn thành công việc rất dư dả thời gian, tôi đã nhận ra một sự khác biệt lớn. Tôi hễ nghĩ "Đây là việc lớn mất tới 3 tiếng đồng hồ" là lại đâm ra ngại bắt đầu, còn tiền bối ngay khi nhận tài liệu liền dành ra đúng 5 phút để làm ngay trong ngày phần việc khởi đầu thật nhỏ như viết tiêu đề hoặc lập danh sách tài liệu cần thiết.\nKhi tôi hỏi lý do, tiền bối bảo: "Con người ta một khi đã chạm tay vào làm dù chỉ một chút cũng sẽ bận tâm đến phần tiếp theo và tự nhiên muốn làm tiếp. Để nguyên ở con số không mới là gánh nặng lớn nhất". Thì ra bấy lâu nay chính tôi đã tự dựng cao "bức tường tâm lý" trước khi bắt đầu công việc.\nTừ đó trở đi, dù là công việc ngại làm đến mấy, tôi cũng đặt ra quy tắc cho bản thân là ngay trong ngày được giao phải "tạo file và viết đúng một dòng". Kỳ lạ thay, chỉ mới viết đúng một dòng thôi mà gánh nặng tâm lý đã tan biến, giúp ngày hôm sau tôi bắt tay vào làm tiếp một cách nhẹ nhàng.', NULL, NULL, NULL, '[{"expression":"性格","reading":"せいかく","meaning_vi":"tính cách"},{"expression":"期限","reading":"きげん","meaning_vi":"kỳ hạn"},{"expression":"前日","reading":"ぜんじつ","meaning_vi":"ngày trước"}]', 562, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-009', 'N3-R-LONG', 'N3', 'READING', 9, '数年前、私は自宅の近くにある市民の畑を少しだけ借りて、季節の野菜を育てることにした。スーパーへ行けば、泥もついていない真っすぐなきゅうりや、同じ大きさのきれいなトマトが一年中いつでも安く買える。それなのにわざわざ土を掘って種をまくなんて、手間がかかるばかりで無駄ではないかと最初は家族にも言われた。\n確かに、実際にやってみると想像以上に大変だった。夏は毎朝早く起きて草を抜き、虫がつかないように葉の裏まで確かめなければならない。強い台風が来て、大切に育てていた枝が折れてしまい、がっかりして畑の前で立ち止まったこともあった。\nけれども、苦労の末に初めて収穫したきゅうりをその場で水で洗ってかじったとき、これまでのきゅうりとは比べものにならないほどみずみずしくて甘い味が口いっぱいに広がった。さらに、形が少し曲がっていたり大きさが同じでなかったりする野菜を見ると、農家の方々がどれほどの手間をかけてスーパーのきれいな野菜を育てているのかが、身をもって理解できるようになったのだ。\n自分の手で土に触れ、一つの野菜が育つまでの長い時間を知ることは、毎日の食事に対する感謝の気持ちを教えてくれる。今では家族も私が収穫した新鮮な野菜を誰よりも楽しみにしており、毎日の食卓での会話も以前よりずっと明るく温かく豊かになった。', 'Vài năm trước, tôi thuê một mảnh vườn nhỏ dành cho công dân ở gần nhà để trồng rau theo mùa. Chỉ cần ra siêu thị là lúc nào quanh năm cũng có thể mua rẻ những quả dưa chuột thẳng tắp không dính chút bùn đất hay những quả cà chua đẹp đẽ đều tăm tắp. Vậy mà lại cất công đào đất gieo hạt, ban đầu ngay cả người nhà cũng bảo tôi làm thế chẳng phải chỉ tốn công vô ích hay sao.\nQuả thực, khi bắt tay vào làm mới thấy vất vả hơn tưởng tượng rất nhiều. Mùa hè sáng nào cũng phải dậy sớm nhổ cỏ, kiểm tra tận mặt sau của lá để phòng sâu bệnh. Có lần bão lớn về làm gãy mất cành cây đang dày công chăm bẵm, khiến tôi thất vọng đứng sững trước mảnh vườn.\nThế nhưng, sau bao vất vả, khi rửa sạch bằng nước và cắn thử trái dưa chuột thu hoạch lần đầu tiên ngay tại vườn, vị ngọt mát mọng nước không gì sánh bằng lan tỏa khắp khoang miệng. Hơn thế nữa, khi nhìn những củ quả hơi cong hay kích cỡ không đều nhau, tôi mới thấu hiểu bằng chính trải nghiệm của mình rằng những người nông dân đã tốn biết bao công sức để trồng ra rau củ đẹp đẽ bán ở siêu thị.\nTự tay chạm vào đất và biết được khoảng thời gian dài để một cây rau lớn lên đã dạy cho tôi lòng biết ơn đối với bữa ăn hằng ngày. Giờ đây, gia đình tôi lại là những người mong chờ đám rau củ do tôi thu hoạch hơn bất cứ ai, và câu chuyện bên bàn ăn cũng trở nên phong phú hơn trước rất nhiều.', NULL, NULL, NULL, '[{"expression":"実際","reading":"じっさい","meaning_vi":"thực tế"},{"expression":"農家","reading":"のうか","meaning_vi":"nhà nông; hộ nông dân"},{"expression":"手間","reading":"てま","meaning_vi":"công sức"}]', 552, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-010', 'N3-R-LONG', 'N3', 'READING', 10, '最近、電車の中や喫茶店で、耳に小さなイヤホンをつけて音楽やラジオを聞いている人をよく見かける。私も以前は、家を出てから会社に着くまでの約一時間、ずっと好きな音楽を流して周囲の音を止めていた。退屈な移動時間を楽しく過ごすためには、それが一番良い方法だと思っていたのだ。\nところが先月、うっかりイヤホンを家に忘れて出かけてしまった日があった。仕方なく何もつけずに歩いていると、普段は気づかなかったいろいろな音が耳に入ってきた。道の木の葉が風に揺れる音、遠くの小学校から聞こえてくる子どもたちの元気な声、そしてパン屋の前を通ったときに聞こえた「いらっしゃいませ」という明るい声だ。\nそれだけではない。駅の階段で重そうなベビーカーを運ぼうとしている母親が、後ろの人に「すみません、少し手伝っていただけますか」と声をかけているのにもすぐに気づき、一緒に運んであげることができた。もしイヤホンで耳をふさいでいたら、その声に気づかず通り過ぎてしまっていただろう。\n音楽を聞いて自分の世界に入る時間も確かに心地よい。しかし、耳を開いて周囲の音に意識を向けてみると、季節の移り変わりや周りの人の小さなサインに気づくことができる。それ以来、私は通勤の行きと帰りのどちらか一方は、イヤホンをポケットにしまって歩くようにしている。', 'Gần đây, trên tàu điện hay trong quán nước, ta thường bắt gặp những người đeo tai nghe nhỏ để nghe nhạc hoặc đài radio. Trước đây tôi cũng vậy, suốt khoảng một tiếng đồng hồ từ lúc ra khỏi nhà đến khi tới công ty, tôi luôn bật nhạc yêu thích để ngăn cách âm thanh xung quanh. Tôi từng nghĩ đó là cách tốt nhất để trải qua thời gian di chuyển nhàm chán một cách vui vẻ.\nThế nhưng tháng trước, có một ngày tôi lỡ để quên tai nghe ở nhà khi đi làm. Đành đi bộ mà không đeo gì, tôi chợt nghe thấy biết bao âm thanh mà ngày thường mình không để ý. Tiếng lá cây bên đường xào xạc trong gió, tiếng trẻ em reo vui khỏe khoắn vọng lại từ trường tiểu học phía xa, và cả giọng chào "Xin mời vào" tươi tắn khi đi ngang qua tiệm bánh mì.\nKhông chỉ có vậy. Tại cầu thang nhà ga, tôi còn kịp thời nhận ra một người mẹ đang loay hoay định bê chiếc xe đẩy em bé nặng nhọc lên tiếng nhờ người phía sau "Xin lỗi, anh/chị giúp tôi một chút được không ạ", và tôi đã có thể cùng khiêng giúp chị ấy. Nếu tôi bịt kín tai bằng tai nghe, có lẽ tôi đã chẳng nhận ra lời nhờ cậy đó mà cứ thế lướt qua mất rồi.\nKhoảng thời gian nghe nhạc bước vào thế giới riêng quả thực rất dễ chịu. Tuy nhiên, khi mở rộng đôi tai và hướng sự chú ý đến âm thanh xung quanh, ta có thể nhận ra sự chuyển mình của các mùa cũng như những tín hiệu nhỏ từ mọi người quanh mình. Kể từ đó, vào lượt đi hoặc lượt về khi đi làm, tôi luôn cất tai nghe vào túi áo để bước đi.', NULL, NULL, NULL, '[{"expression":"周囲","reading":"しゅうい","meaning_vi":"xung quanh"},{"expression":"意識","reading":"いしき","meaning_vi":"ý thức; sự chú ý"},{"expression":"母親","reading":"ははおや","meaning_vi":"người mẹ"}]', 550, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-011', 'N3-R-LONG', 'N3', 'READING', 11, 'スマートフォンのカメラを使えば、誰でも失敗せずにきれいな写真が何百枚でも撮れる時代になった。旅行先や友人との食事の席でも、気に入った場面があれば何十枚も連続でシャッターを切り、あとから一番よく撮れている一枚を選ぶのが当たり前になっている。\nところが先日、実家の押し入れを片づけていたとき、父が若い頃に使っていた古いフィルムカメラと、数冊の厚いアルバムを見つけた。父に話を聞くと、昔のフィルムは一本で二十四枚か三十六枚しか撮れず、しかも写真屋に出して現像してみるまでどんな風に写っているかわからなかったという。そのため、一枚撮るたびに光や角度をよく確かめ、「ここぞ」という大切な瞬間だけを慎重に撮っていたそうだ。\nアルバムのページをめくってみると、そこには少しピントがずれていたり、誰かが目をつぶっていたりする写真も混じっていた。しかし不思議なことに、どの一枚からも当時の家族の笑い声や空気感が生き生きと伝わってきて、私は何百枚も入っている自分のスマートフォンの中の写真よりもずっと強い魅力を感じたのである。\n簡単にたくさん撮れることはもちろん便利だが、枚数が限られていたからこそ、昔の人々は目の前の景色や人との時間をより深く見つめていたのかもしれない。次の旅行では、すぐにカメラを向けるのではなく、まず自分の目でしっかり景色を焼きつけてから一枚だけシャッターを切ってみようと思う。', 'Chúng ta đã bước vào thời đại chỉ cần dùng camera điện thoại thông minh là ai cũng có thể chụp hàng trăm bức ảnh đẹp mà không sợ hỏng. Tại nơi du lịch hay trong bữa ăn cùng bạn bè, hễ có cảnh ưng ý là người ta lại bấm máy liên tiếp hàng chục tấm, rồi sau đó mới chọn ra một tấm đẹp nhất như chuyện đương nhiên.\nThế nhưng hôm trước, khi dọn dẹp tủ tường ở nhà bố mẹ, tôi tìm thấy chiếc máy ảnh phim cũ bố từng dùng thời trẻ cùng vài cuốn album dày. Nghe bố kể lại, mỗi cuộn phim ngày xưa chỉ chụp được 24 hoặc 36 kiểu, hơn nữa cho đến khi mang ra tiệm ảnh tráng rửa xong thì vẫn chẳng biết ảnh chụp ra trông thế nào. Vì vậy, mỗi lần chụp một tấm đều phải kiểm tra kỹ ánh sáng và góc độ, chỉ cẩn thận bấm máy vào đúng khoảnh khắc thực sự quan trọng.\nKhi lật giở từng trang album, ở đó lẫn cả những bức ảnh hơi lệch nét hoặc có ai đó đang nhắm mắt. Thế nhưng kỳ lạ thay, từ bất kỳ bức ảnh nào cũng truyền tải sống động tiếng cười và bầu không khí của gia đình thời ấy, khiến tôi cảm nhận được sức cuốn hút mạnh mẽ hơn hẳn hàng trăm bức ảnh nằm trong chiếc điện thoại của mình.\nViệc có thể chụp nhiều ảnh một cách dễ dàng tất nhiên rất tiện lợi, nhưng có lẽ chính vì số lượng ảnh bị giới hạn nên con người ngày xưa đã ngắm nhìn khung cảnh trước mắt và khoảng thời gian bên nhau sâu sắc hơn. Trong chuyến du lịch tới, thay vì lập tức giơ máy lên, tôi muốn thử ngắm nhìn thật kỹ khung cảnh bằng chính đôi mắt mình trước rồi mới bấm máy đúng một tấm mà thôi.', NULL, NULL, NULL, '[{"expression":"連続","reading":"れんぞく","meaning_vi":"liên tiếp; liên tục"},{"expression":"慎重","reading":"しんちょう","meaning_vi":"thận trọng"},{"expression":"当時","reading":"とうじ","meaning_vi":"thời điểm đó"}]', 587, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-012', 'N3-R-LONG', 'N3', 'READING', 12, '冬の寒い朝、温かい布団から出るのは誰にとってもつらいものだ。私も以前は、目覚まし時計が鳴っても布団の中で三十分以上ぐずぐずしてしまい、部屋の空気が冷たいのを理由に、休日は昼近くまで何もせずに布団の中でスマートフォンを見て過ごすことが多かった。\nしかし昨年の冬、北のヨーロッパの国に暮らす友人から「寒い冬こそ、家の中の小さな楽しみを増やすんだよ」と教わったのをきっかけに、私の冬の過ごし方が大きく変わった。友人の国では冬の昼の時間が短く外も厳しい寒さになるため、人々は暖かい色の照明を使ったり、お気に入りのコップで香り高い紅茶やココアを飲んだりと、家の中の時間を心地よくする工夫をとても大切にしているそうだ。\nそこで私も、前の晩に好きな香りのコーヒー豆を用意しておき、朝起きたらすぐにお湯を沸かして部屋中にいい香りを広げるようにしてみた。さらに、足元を温める厚手の靴下と柔らかい毛布を机の周りに置いたところ、「あの温かいコーヒーを飲むために起きよう」と、寒い朝でも自然と布団から出られるようになったのである。\n季節の寒さそのものを変えることはできないが、自分の身の回りに小さな楽しみを用意することはいつでもできる。朝の光の中で温かい飲み物をゆっくり味わう習慣ができたおかげで、工夫一つでただ我慢するだけだった冬が、今では心穏やかに過ごせる大好きな季節になった。', 'Vào buổi sáng mùa đông giá lạnh, việc chui ra khỏi chăn ấm đối với bất kỳ ai cũng thật vất vả. Trước đây tôi cũng vậy, dù đồng hồ báo thức có kêu vẫn cứ nằm lần lữa trong chăn hơn 30 phút, lấy cớ không khí trong phòng lạnh lẽo nên vào ngày nghỉ thường nằm nguyên trong chăn xem điện thoại đến gần trưa mà chẳng làm gì.\nThế nhưng mùa đông năm ngoái, nhân dịp được một người bạn sống ở một nước Bắc Âu bảo rằng "Chính vào mùa đông lạnh giá lại càng phải tăng thêm những niềm vui nho nhỏ trong nhà", cách trải qua mùa đông của tôi đã thay đổi hẳn. Ở đất nước của bạn tôi, thời gian ban ngày vào mùa đông rất ngắn và bên ngoài lạnh khắc nghiệt, nên mọi người rất coi trọng việc chăm chút cho khoảng thời gian trong nhà trở nên dễ chịu, như dùng đèn ánh sáng ấm áp hay thưởng thức trà thơm và ca cao nóng bằng chiếc cốc yêu thích.\nThế là tôi cũng thử chuẩn bị sẵn hạt cà phê có hương thơm mình thích từ tối hôm trước, sáng ngủ dậy liền đun nước ngay để hương thơm lan tỏa khắp phòng. Hơn nữa, khi để sẵn đôi tất dày giữ ấm chân và chiếc chăn mềm quanh bàn làm việc, tôi đã có thể tự nhiên bước ra khỏi chăn ngay cả vào buổi sáng lạnh giá với suy nghĩ "Hãy dậy để uống tách cà phê ấm áp ấy nào".\nTa không thể thay đổi cái lạnh của thời tiết, nhưng lúc nào cũng có thể chuẩn bị những niềm vui nhỏ quanh mình. Nhờ có thói quen thong thả thưởng thức đồ uống ấm áp trong nắng sớm, chỉ với một chút khéo léo, mùa đông vốn trước kia chỉ biết chịu đựng nay đã trở thành mùa yêu thích giúp tôi sống thật bình yên.', NULL, NULL, NULL, '[{"expression":"穏やか","reading":"おだやか","meaning_vi":"ôn hòa; bình yên"},{"expression":"昨年","reading":"さくねん","meaning_vi":"năm trước"},{"expression":"味わう","reading":"あじわう","meaning_vi":"nếm"}]', 576, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-013', 'N3-R-LONG', 'N3', 'READING', 13, '私はこれまで、料理でも掃除でも「人に頼らず自分の力だけで完全にやること」が自立した大人の姿だと思っていた。そのため、仕事がどんなに忙しくて疲れ切っていても、週末には一人で家中の掃除をし、毎日時間をかけて食事を作ろうとして、いつも心のどこかでイライラしていた。\nそんなある日、風邪をひいて三日間寝込んでしまったことがあった。高熱で起き上がれず、台所に立つこともできないでいたとき、同じマンションに住む友人が温かいおかゆと果物を持って見舞いに来てくれた。私は最初、「風邪がうつったら申し訳ないし、邪魔になってしまって恥ずかしい」と何度も謝った。\nすると友人は、「そんなに謝らないで。私が先月足にけがをしたとき、あなたに買い物をお願いしてどれだけ助かったか覚えているでしょう。困ったときに助け合うのはお互い様だよ」と笑って言ってくれた。その言葉を聞いたとき、肩の力がすっと抜けて、温かいおかゆと一緒に友人の優しさが胸にしみた。\n考えてみれば、私は誰かを助けることは喜んでしていたのに、自分が誰かに頼ることは「弱いこと」だと勝手に決めつけていたのだ。完全に一人で頑張りすぎて笑顔を失うよりも、できないときは素直に「助けて」と言い、元気なときにその分お返しをする方が、人と人とのつながりもずっと温かくなるのだと気づいた。', 'Từ trước đến nay, dù là nấu nướng hay dọn dẹp, tôi luôn nghĩ "không dựa dẫm vào ai mà tự làm trọn vẹn bằng sức mình" mới là hình ảnh của một người trưởng thành tự lập. Vì thế, dù công việc có bận rộn và mệt nhoài đến mấy, cuối tuần tôi vẫn một mình dọn khắp nhà, mỗi ngày đều cố dành thời gian nấu nướng, để rồi trong lòng lúc nào cũng âm ỉ bực bội.\nThế rồi một hôm, tôi bị cảm lạnh phải nằm liệt giường suốt 3 ngày. Khi đang sốt cao không dậy nổi, cũng chẳng thể đứng bếp, một người bạn sống cùng chung cư đã mang cháo nóng và trái cây sang thăm. Lúc đầu, tôi cứ xin lỗi mãi vì nghĩ "Nhỡ lây cảm sang bạn thì có lỗi quá, lại còn làm phiền bạn thật đáng xấu hổ".\nNghe vậy, bạn tôi liền mỉm cười bảo: "Đừng xin lỗi nhiều thế. Tháng trước khi mình bị thương ở chân, nhờ cậu đi chợ giúp mà mình đỡ vất vả biết bao, cậu còn nhớ không? Lúc khó khăn giúp đỡ lẫn nhau là chuyện có qua có lại mà". Nghe những lời ấy, đôi vai đang gồng cứng của tôi chợt thả lỏng, cùng với bát cháo ấm nóng là sự dịu dàng của người bạn thấm sâu vào lòng.\nNghĩ kỹ lại thì tôi vốn rất vui vẻ khi giúp đỡ người khác, nhưng lại tự ý áp đặt rằng việc bản thân dựa vào ai đó là "yếu đuối". Thay vì cố gồng mình làm trọn vẹn một mình đến mức đánh mất nụ cười, khi không làm xuể hãy thành thật nói "Hãy giúp mình với" rồi lúc khỏe mạnh đáp lễ lại phần đó, như vậy mối gắn kết giữa người với người sẽ ấm áp hơn biết bao.', NULL, NULL, NULL, '[{"expression":"完全","reading":"かんぜん","meaning_vi":"hoàn toàn; trọn vẹn"},{"expression":"素直","reading":"すなお","meaning_vi":"thành thật; ngoan ngoãn"},{"expression":"失う","reading":"うしなう","meaning_vi":"đánh mất"}]', 552, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-014', 'N3-R-LONG', 'N3', 'READING', 14, '町の古い商店街を歩いていると、五十年以上続いている小さな文房具屋がある。最近の大きな店では、ペンやノートが種類ごとにきれいに並び、客が自分で商品をかごに入れてレジへ持っていくのが当たり前だ。しかしその店では、万年筆や珍しい色のインクがガラスのケースの中に並んでおり、店主のおじいさんに声をかけて出してもらう仕組みになっている。\n高校生の頃、私は初めて自分の小遣いで少し良い万年筆を買おうと思い、ドキドキしながらその店の戸を開けた。どれにすればいいかわからずケースの前で立ち止まっていると、おじいさんは「毎日どんなノートに、どんな目的で書くのかい」と優しく尋ねてくれた。私が「英語の単語や日記をたくさん書きたいです」と答えると、三本のペンを出して実際に紙に試し書きをさせてくれ、私の手の大きさに一番合う一本を一緒に選んでくれたのだ。\nさらに、インクの入れ方やペン先を長持ちさせる洗い方まで丁寧に教えてくれ、「もし書きにくくなったら、いつでも持ってきなさい。直してあげるから」と言ってくれた。その言葉通り、私は大学を卒業して社会人になった今でも、年に一度はその店へ行ってペン先の調整をしてもらっている。\nインターネットなら同じ万年筆が数百円安く買えたかもしれない。しかし、道具を大切に使う知識と、困ったときにいつでも相談できる安心感は、この店でしか手に入らないかけがえのない価値なのだ。', 'Khi dạo bước trên khu phố mua sắm cũ của thị trấn, có một tiệm văn phòng phẩm nhỏ đã mở suốt hơn 50 năm qua. Ở những cửa hàng lớn gần đây, bút và vở được xếp ngay ngắn theo từng chủng loại, khách tự bỏ hàng vào giỏ rồi mang ra quầy thu ngân là chuyện bình thường. Thế nhưng ở tiệm này, bút máy và các lọ mực màu hiếm được bày trong tủ kính, theo cơ chế khách lên tiếng nhờ ông cụ chủ tiệm lấy ra giúp.\nHồi học cấp 3, lần đầu tiên tôi định dùng tiền tiêu vặt của mình để mua một cây bút máy tốt một chút, nên vừa hồi hộp vừa mở cửa tiệm. Khi tôi đang đứng tần ngần trước tủ kính chưa biết chọn cây nào, ông cụ liền dịu dàng hỏi: "Cháu định viết vào cuốn sổ thế nào, với mục đích gì mỗi ngày?". Khi tôi đáp "Cháu muốn viết thật nhiều từ vựng tiếng Anh và nhật ký ạ", ông lấy ra 3 cây bút cho tôi viết thử lên giấy, rồi cùng chọn ra một cây vừa vặn nhất với cỡ tay của tôi.\nHơn nữa, ông còn chỉ dẫn tận tình từ cách bơm mực cho tới cách rửa giúp ngòi bút bền lâu, rồi dặn: "Nếu có lúc nào thấy khó viết thì cứ mang tới đây bất cứ lúc nào. Ông sẽ chỉnh lại cho". Đúng như lời ông nói, ngay cả hiện tại khi đã tốt nghiệp đại học và đi làm, mỗi năm một lần tôi vẫn ghé tiệm nhờ ông chỉnh lại ngòi bút.\nNếu mua trên mạng có lẽ đã mua được cây bút máy giống hệt với giá rẻ hơn vài trăm yên. Thế nhưng, kiến thức để trân trọng sử dụng món đồ cùng cảm giác an tâm luôn có nơi để hỏi han khi gặp trục trặc chính là giá trị vô giá chỉ có thể tìm thấy ở tiệm này.', NULL, NULL, NULL, '[{"expression":"種類","reading":"しゅるい","meaning_vi":"chủng loại"},{"expression":"目的","reading":"もくてき","meaning_vi":"mục đích"},{"expression":"価値","reading":"かち","meaning_vi":"giá trị"}]', 588, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-015', 'N3-R-LONG', 'N3', 'READING', 15, '私たちの周りには「聞き上手」と呼ばれる人がいる。そういう人と話をしていると、不思議とこちらの気持ちが明るくなり、「またあの人と話したいな」と思うようになる。以前の私は、会話を盛り上げるためには自分が面白い話題をたくさん用意して、絶えず話し続けなければならないと思い込んでいた。\nしかしあるとき、社内で一番相談しやすいと評判の山本先輩と一緒に昼食をとる機会があった。観察していると、山本先輩は自分の話をほとんどせず、相手の言葉に「なるほど、それでどうなったの」「それは大変だったね」とタイミングよく相づちを打ち、相手が話しやすい質問を少しずつ投げかけていたのである。その結果、普段はあまり自分のことを話さない同僚が、目を輝かせて楽しそうに趣味の話を続けていた。\n私はそれまで、会話の主役は「話す人」だとばかり思っていた。けれども実際には、相手の言葉をしっかり受け止め、関心を持って耳を傾ける「聞く人」がいて初めて、生き生きとした会話が生まれるのだと気づかされた。\nそれからは、友人と会うときも「次に何を話そうか」と自分の頭の中ばかりを考えるのをやめ、相手の表情や声の調子に注意を向けて最後までじっくり聞くように心がけている。すると、以前よりも相手の考えが深く理解できるようになり、会話のあとの満足感もずっと大きくなった。', 'Xung quanh chúng ta có những người được gọi là "người khéo lắng nghe". Khi trò chuyện với những người như vậy, kỳ lạ thay tâm trạng của ta trở nên tươi sáng hơn và nghĩ bụng "Muốn được nói chuyện với người ấy lần nữa quá". Trước đây tôi từng mặc định rằng để làm cho cuộc trò chuyện sôi nổi, bản thân phải chuẩn bị thật nhiều chủ đề thú vị và phải nói liên tục không ngừng.\nThế nhưng có một lần, tôi có dịp ăn trưa cùng tiền bối Yamamoto — người nổi tiếng trong công ty là dễ tâm sự nhất. Quan sát mới thấy, tiền bối Yamamoto hầu như không nói chuyện của mình, mà chỉ gật gù hưởng ứng đúng lúc trước lời của đối phương như "Ra vậy, thế sau đó ra sao?", "Chắc hẳn vất vả lắm nhỉ", đồng thời nêu ra từng câu hỏi nhỏ giúp đối phương dễ trải lòng. Kết quả là người đồng nghiệp ngày thường vốn ít nói về bản thân lại mắt sáng lên vui vẻ kể tiếp câu chuyện về sở thích của mình.\nTừ trước đến lúc đó, tôi cứ ngỡ nhân vật chính của cuộc hội thoại là "người nói". Thế nhưng thực tế, tôi đã nhận ra rằng chỉ khi có "người nghe" biết đón nhận trọn vẹn lời nói của đối phương và lắng ngheด้วย sự quan tâm thì cuộc trò chuyện sống động mới được sinh ra.\nKể từ đó, mỗi khi gặp bạn bè, tôi không còn chỉมải nghĩ trong đầu xem "Tiếp theo mình sẽ nói gì", mà luôn chú ý đến nét mặt, giọng điệu của đối phương để chăm chú lắng nghe đến cuối. Nhờ vậy, tôi hiểu sâu sắc hơn suy nghĩ của đối phương so với trước kia, và cảm giác hài lòng sau mỗi cuộc trò chuyện cũng lớn hơn rất nhiều.', NULL, NULL, NULL, '[{"expression":"評判","reading":"ひょうばん","meaning_vi":"danh tiếng; tiếng tăm"},{"expression":"関心","reading":"かんしん","meaning_vi":"sự quan tâm"},{"expression":"生まれ","reading":"うまれ","meaning_vi":"nơi sinh"}]', 556, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-016', 'N3-R-LONG', 'N3', 'READING', 16, '子どもの頃、冬になると私の家の居間には大きなこたつが出され、その上にはいつも黄色いみかんが山盛りに置かれていた。テレビを見ながら家族みんなでみかんの皮をむき、手が黄色くなるまでいくつも食べた思い出がある。しかし、大学進学を機に東京で一人暮らしを始めてからは、果物を箱で買うこともなくなり、冬にみかんを食べる習慣もいつの間にかなくなっていた。\nところが先週、田舎で暮らす母から重い段ボール箱が一つ届いた。開けてみると、新聞紙の下に大小さまざまなみかんがぎっしり詰まっており、一番上には「今年は天気がよくて甘くできたから、風邪をひかないように毎日食べなさい」という母の手紙が入っていた。早速一つむいて口に入れると、爽やかな香りと優しい甘酸っぱさが広がり、懐かしい実家の居間の風景が一瞬でよみがえった。\nとはいえ、一人で百近いみかんを食べ切るのは到底無理だ。そこで私は、職場の同僚やマンションの隣の部屋に住む老夫婦に少しずつ袋に入れて分けることにした。すると、お礼に手作りの料理をいただいたり、普段は挨拶しかしていなかった同僚と故郷の話で盛り上がったりと、思いがけない交流が生まれたのである。\n母が送ってくれた一箱のみかんは、私の体を風邪から守ってくれただけでなく、都会での少し寂しい一人暮らしに、人との温かいつながりまで運んできてくれたようだ。', 'Hồi còn nhỏ, cứ mỗi độ đông về là phòng khách nhà tôi lại bày chiếc bàn sưởi kotatsu lớn, phía trên lúc nào cũng có một rổ quýt vàng ươm chất đầy. Tôi vẫn nhớ kỷ niệm cả nhà vừa xem tivi vừa bóc vỏ quýt, ăn hết quả này đến quả khác cho tới khi vàng cả tay. Thế nhưng, từ khi lên Tokyo sống một mình nhân dịp vào đại học, tôi không còn mua trái cây theo thùng nữa, và thói quen ăn quýt vào mùa đông cũng tự lúc nào chẳng còn.\nVậy mà tuần trước, có một thùng các-tông nặng trịch từ mẹ tôi ở quê gửi lên. Mở ra xem thì bên dưới lớp giấy báo là đủ các quả quýt lớn nhỏ xếp chật kín, trên cùng có bức thư tay của mẹ viết: "Năm nay thời tiết tốt nên quýt ngọt lắm, con nhớ ăn mỗi ngày để khỏi bị cảm nhé". Tôi liền bóc ngay một quả bỏ vào miệng, hương thơm thanh mát cùng vị chua ngọt dịu dàng lan tỏa, khung cảnh phòng khách thân thương ở quê nhà lập tức sống dậy trong chớp mắt.\nDẫu vậy, một mình ăn hết gần một trăm quả quýt là điều hoàn toàn không thể. Thế là tôi quyết định chia nhỏ vào túi để biếu đồng nghiệp ở chỗ làm và vợ chồng cụ già sống ở căn hộ bên cạnh. Nhờ đó, tôi được tặng lại món dưa muối tự làm để cảm ơn, lại còn trò chuyện rôm rả về quê hương với những đồng nghiệp mà ngày thường chỉ chào hỏi xã giao, tạo nên sự giao lưu bất ngờ.\nThùng quýt mẹ gửi không chỉ bảo vệ cơ thể tôi khỏi cơn cảm lạnh, mà dường như còn mang đến cả sợi dây gắn kết ấm áp giữa người với người cho cuộc sống một mình nơi phố thị vốn đôi chút cô đơn.', NULL, NULL, NULL, '[{"expression":"故郷","reading":"こきょう","meaning_vi":"quê hương"},{"expression":"夫婦","reading":"ふうふ","meaning_vi":"vợ chồng"},{"expression":"生まれ","reading":"うまれ","meaning_vi":"nơi sinh"}]', 567, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-017', 'N3-R-LONG', 'N3', 'READING', 17, '私の家の近くに、季節ごとに違う花が咲く大きな公園がある。三年前の春、健康のために毎朝三十分ほどその公園を歩くことにしたのだが、最初の数日はただ時計を見ながら早足で歩いているだけで、正直なところ少し退屈だった。\nそんなある朝、公園のベンチの周りで、青いぼうしをかぶったお年寄りのグループが熱心に地面の草を抜いたり、枯れた花びらを拾ったりしているのを見かけた。私が「毎朝早くからご苦労さまですね」と声をかけると、その中の一人が「私たちは市のボランティアでね、みんなが気持ちよく散歩できるように花の手入れをしているんだよ。来週にはこの赤いチューリップが満開になるから楽しみにしていてね」と笑顔で教えてくれた。\n私はそれまで、公園の花は最初からそこにある当たり前の景色だと思っており、誰かが毎朝早く起きて手入れをしていることなど想像もしなかった。その日以来、私の朝の散歩はただの運動ではなくなった。花の場所の前を通るたびに「今日はつぼみが少し膨らんだな」と確かめ、ボランティアの方々に「おはようございます。いつもありがとうございます」と挨拶をするようになったのである。\n誰かの見えない努力によって私たちの心地よい環境が守られていることに気づくと、見慣れた町の景色が急に温かく感じられる。来年の春からは、私も休日の朝にそのボランティアの仲間に加えてもらおうと考えている。', 'Gần nhà tôi có một công viên lớn mỗi mùa lại nở những loài hoa khác nhau. Mùa xuân 3 năm trước, để rèn luyện sức khỏe tôi quyết định mỗi sáng đi bộ khoảng 30 phút ở công viên đó, nhưng vài ngày đầu chỉ vừa nhìn đồng hồ vừa bước nhanh nên thành thật mà nói tôi thấy hơi buồn tẻ.\nThế rồi vào một buổi sáng, quanh ghế đá công viên, tôi bắt gặp một nhóm các cụ già đội mũ xanh đang chăm chú nhổ cỏ trên mặt đất và nhặt những cánh hoa khô. Khi tôi lên tiếng chào "Các bác vất vả từ sáng sớm quá ạ", một cụ trong nhóm liền mỉm cười bảo: "Chúng tôi là tình nguyện viên của thành phố đấy, đang chăm sóc hoa để mọi người có thể đi dạo thật dễ chịu. Tuần sau đám hoa tulip đỏ này sẽ nở rộ, cháu hãy đón chờ nhé".\nTừ trước đến lúc đó, tôi cứ nghĩ hoa trong công viên là khung cảnh đương nhiên vốn có sẵn ở đó, chứ chưa từng tưởng tượng rằng có ai đó dậy sớm mỗi sáng để chăm sóc. Kể từ ngày hôm ấy, buổi đi dạo sáng của tôi không còn đơn thuần chỉ là tập thể dục nữa. Mỗi lần đi ngang qua bồn hoa, tôi lại ngắm xem "Hôm nay nụ hoa đã hé thêm một chút rồi nhỉ", và chào hỏi các bác tình nguyện viên "Cháu chào các bác. Cảm ơn các bác lúc nào cũng chăm sóc hoa ạ".\nKhi nhận ra môi trường dễ chịu của chúng ta đang được gìn giữ bởi nỗ lực thầm lặng của ai đó, khung cảnh phố phường quen thuộc bỗng trở nên ấm áp lạ thường. Từ mùa xuân năm tới, tôi đang tính sẽ xin tham gia vào đội ngũ tình nguyện viên ấy vào các buổi sáng ngày nghỉ.', NULL, NULL, NULL, '[{"expression":"努力","reading":"どりょく","meaning_vi":"nỗ lực"},{"expression":"仲間","reading":"なかま","meaning_vi":"đồng đội"},{"expression":"環境","reading":"かんきょう","meaning_vi":"môi trường"}]', 577, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-018', 'N3-R-LONG', 'N3', 'READING', 18, '最近、会議の記録を取るために、パソコンを持ち込んで人の話をそのまま速く打ち込む人が増えている。私も入社してすぐの頃は、上司や先輩が言った言葉を一つも落とさずに記録しようと、会議の間ずっと画面を見つめてキーボードを叩き続けていた。\nしかし、そのやり方には大きな問題があった。文字を打つことばかりに気を取られてしまい、話の内容をその場で深く理解することができなかったのだ。そのため、会議が終わったあとに「この部分はどういう意味ですか」と質問することもできず、せっかく作った長い記録も、あとから読み返すとどこが本当に大切な結論なのか一目でわからなかったのである。\nそれを見かねた課長が、「会議はタイピングの練習をする場所じゃないよ。まず人の話をしっかり聞いて理解し、ノートには決定したことと、次に誰が何をするかだけを短い言葉で書き留めなさい」と教えてくれた。そこで次の会議からはパソコンを閉じ、紙のノートに大事な要点だけを矢印や番号を使って書くようにしてみた。\nすると、書く量が減った分だけ相手の話に集中できるようになり、疑問に思ったことをその場で質問して確かめられるようになった。さらに会議のあとも、短いメモを見返すだけでやるべき仕事がすぐにわかり、周りへの連絡もずっと速くなった。記録とは、すべての言葉をそのまま残すことではなく、次の行動に必要な情報を整理して残すことなのだと学んだ。', 'Gần đây, để ghi biên bản cuộc họp, ngày càng có nhiều người mang máy tính vào và gõ lại nguyên văn lời người khác nói thật nhanh. Hồi mới vào công ty tôi cũng vậy, để không bỏ sót bất kỳ lời nào của cấp trên hay tiền bối, suốt buổi họp tôi cứ nhìn chằm chằm vào màn hình và gõ bàn phím liên tục.\nThế nhưng, cách làm đó lại có một vấn đề lớn. Vì quá mải mê với việc gõ chữ nên tôi không thể hiểu sâu nội dung câu chuyện ngay tại chỗ. Do đó, khi cuộc họp kết thúc tôi cũng chẳng thể đặt câu hỏi "Phần này có ý nghĩa là gì ạ?", mà bản ghi chép dài dòng dày công gõ ra đến lúc đọc lại cũng chẳng thể nhìn ra ngay đâu mới thực sự là kết luận quan trọng.\nThấy vậy không đành, trưởng phòng đã chỉ bảo tôi: "Cuộc họp không phải là nơi luyện gõ phím đâu. Trước hết hãy lắng nghe kỹ để hiểu lời mọi người nói, còn trong sổ chỉ cần ghi ngắn gọn những điều đã quyết định và tiếp theo ai sẽ làm việc gì thôi". Thế là từ buổi họp sau, tôi gập máy tính lại, thử chỉ ghi những điểm chính quan trọng vào sổ giấy bằng các mũi tên và con số.\nNhờ lượng chữ phải viết giảm đi, tôi tập trung hơn vào lời đối phương nói và có thể hỏi lại ngay tại chỗ những điều còn thắc mắc. Hơn nữa sau cuộc họp, chỉ cần nhìn lại phần ghi chú ngắn gọn là tôi nắm được ngay việc cần làm và liên lạc với mọi người xung quanh cũng nhanh hơn hẳn. Tôi đã học được rằng ghi chép không phải là giữ lại nguyên xi mọi câu chữ, mà là sắp xếp và lưu lại những thông tin cần thiết cho hành động tiếp theo.', NULL, NULL, NULL, '[{"expression":"記録","reading":"きろく","meaning_vi":"ghi chép; biên bản"},{"expression":"結論","reading":"けつろん","meaning_vi":"kết luận"},{"expression":"決定","reading":"けってい","meaning_vi":"quyết định"}]', 588, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-019', 'N3-R-LONG', 'N3', 'READING', 19, '外国へ旅行に行くと、有名な城や美しい美術館を回るのも楽しいが、私が一番楽しみにしているのは、その街の人々が普段利用している「地元のスーパーや市場」を訪れることだ。観光地のお土産屋には並ばないような、その土地ならではの珍しい野菜や果物、調味料、そしてお菓子の袋を見ているだけで、そこに暮らす人々の毎日の食卓が想像できてワクワクするからだ。\n昨年、アジアのある国を旅したときも、ホテルの近くにある朝の市場へ早起きして出かけてみた。そこでは、見たこともないような緑色の果物や、さまざまな香りのスパイスが山のように積まれ、朝から買い物客と店員の元気な声が飛び交っていた。私が一つの果物の前で「どうやって食べるのだろう」と不思議そうに眺めていると、隣にいた地元の主婦が身ぶり手ぶりで「皮をむいて、塩を少しつけて食べるとおいしいよ」と教えてくれたのだ。\nさらに店主のおじさんが、ナイフでその果物を一口切って「食べてごらん」と差し出してくれた。口に入れると、りんごのようにシャキシャキしてさっぱりした甘みがあり、とてもおいしかった。言葉はほとんど通じなかったが、みんなで顔を見合わせて笑ったあの温かい時間は、どの有名な観光地の景色よりも深く私の心に残っている。\nガイドブックに載っている場所を順番に確認するだけの旅も悪くはない。しかし、地元の人々の暮らしの中に少しだけ足を踏み入れてみると、教科書やインターネットでは決して味わえない生きた文化と人の優しさに出会うことができるのである。', 'Khi đi du lịch nước ngoài, việc dạo quanh những tòa lâu đài nổi tiếng hay bảo tàng mỹ thuật tuyệt đẹp cũng rất vui, nhưng điều tôi mong đợi nhất lại là ghé thăm "siêu thị hoặc khu chợ địa phương" nơi người dân thành phố đó sử dụng hằng ngày. Bởi chỉ cần ngắm nhìn những loại rau củ, trái cây, gia vị đặc trưng của vùng đất ấy hay những gói bánh kẹo vốn không bày bán ở tiệm quà lưu niệm khu du lịch thôi, tôi đã có thể hình dung ra mâm cơm mỗi ngày của người dân nơi đó và cảm thấy vô cùng hào hứng.\nNăm ngoái, khi du lịch tới một quốc gia châu Á, tôi cũng dậy sớm tìm đến khu chợ sáng gần khách sạn. Ở đó, những loại trái cây màu xanh chưa từng thấy bao giờ cùng đủ loại gia vị thơm nồng được chất cao như núi, tiếng người mua kẻ bán rộn ràng khỏe khoắn ngay từ sáng sớm. Khi tôi đang đứng tần ngần trước một loại quả vàงम tự hỏi "Không biết ăn thế nào nhỉ", một bà nội trợ địa phương đứng cạnh đã dùng cử chỉ tay chân chỉ cho tôi rằng "Gọt vỏ đi, chấm thêm chút muối ăn ngon lắm đấy".\nHơn nữa, bác chủ sạp còn lấy dao cắt một miếng nhỏ đưa cho tôi bảo "Ăn thử xem". Khi bỏ vào miệng, miếng quả giòn mát như quả lê với vị ngọt thanh rất ngon. Dù hầu như chẳng hiểu ngôn ngữ của nhau, nhưng khoảnh khắc ấm áp khi mọi người cùng nhìn nhau mỉm cười ấy lại đọng lại sâu đậm trong tim tôi hơn bất kỳ thắng cảnh nổi tiếng nào.\nMột chuyến đi chỉ lần lượt đi kiểm tra các địa điểm in trong sách hướng dẫn du lịch cũng không tệ. Thế nhưng, nếu thử bước chân một chút vào nhịp sống thường ngày của người dân bản xứ, ta sẽ có thể bắt gặp nền văn hóa sống động và lòng tốt của con người mà sách giáo khoa hay internet không bao giờ mang lại được.', NULL, NULL, NULL, '[{"expression":"文化","reading":"ぶんか","meaning_vi":"văn hóa"},{"expression":"出会う","reading":"であう","meaning_vi":"gặp gỡ"},{"expression":"昨年","reading":"さくねん","meaning_vi":"năm trước"}]', 632, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-020', 'N3-R-LONG', 'N3', 'READING', 20, '私はこれまで、何か新しいことを学ぶには、まとまったお金と時間をかけて専門の学校に通わなければならないと思っていた。そのため、「いつか時間ができたら料理やプログラミングを習いたいな」と言いながら、忙しい仕事を理由に何年も何も始められずにいた。\nしかし昨年、定年退職したばかりのおじに会ったとき、おじが自分で作ったという美しい木の椅子を見せてくれて驚いた。どこかの教室に通ったのかと尋ねると、おじは「いや、図書館で木工の基本の本を三冊借りて、あとはインターネットの無料動画を見ながら、毎晩三十分ずつ自分の部屋で作ったんだよ」と笑ったのだ。おじは六十歳を過ぎてからまったく一人で勉強して道具の使い方を覚え、半年で立派な家具を作れるようになっていたのである。\nその姿を見て、私は自分が「時間がない」「お金がかかる」と言い訳をして、始める前からあきらめていただけだったことに気づかされた。今の時代、図書館へ行けばあらゆる分野の入門書が無料で借りられるし、基礎を教えてくれる動画や記事も簡単に手に入る。大切なのは、環境が準備できるのを待つことではなく、「今日から毎日十五分だけやってみよう」と一歩を踏み出す気持ちなのだ。\nおじに刺激を受けた私は、その日の帰りに書店で一冊のテキストを買い、毎晩寝る前の二十分間だけプログラミングの練習を始めた。半年経った今では、仕事で使う簡単な計算の道具を自分で作れるようになり、学ぶことの喜びを毎日実感している。', 'Từ trước đến nay, tôi vẫn nghĩ rằng để học một điều gì mới thì phải bỏ ra một khoản tiền và thời gian kha khá để theo học tại trường lớp chuyên môn. Vì thế, miệng thì nói "Có lúc nào rảnh rỗi mình muốn học nấu ăn hay lập trình quá", nhưng lại lấy cớ công việc bận rộn nên suốt bao năm chẳng bắt đầu được việc gì.\nThế nhưng năm ngoái, khi gặp người chú vừa nghỉ hưu, tôi đã vô cùng kinh ngạc khi chú cho xem chiếc ghế gỗ tuyệt đẹp do chính tay chú đóng. Khi tôi hỏi có phải chú đã theo học lớp nào đó không, chú liền cười bảo: "Không đâu, chú mượn 3 cuốn sách cơ bản về nghề mộc ở thư viện, rồi cứ thế xem thêm video miễn phí trên mạng và tự làm trong phòng mình mỗi tối 30 phút đấy". Ở tuổi ngoài 60, chú hoàn toàn tự học cách sử dụng dụng cụ và chỉ sau nửa năm đã có thể đóng được món đồ nội thất ra trò.\nNhìn hình ảnh ấy, tôi nhận ra bản thân bấy lâu nay chỉ viện cớ "không có thời gian", "tốn tiền" để bỏ cuộc ngay từ trước khi bắt đầu. Thời đại ngày nay, chỉ cần ra thư viện là có thể mượn miễn phí sách nhập môn của mọi lĩnh vực, mà video hay bài viết hướng dẫn cơ bản cũng dễ dàng tìm thấy. Điều quan trọng không phải là chờ đợi đến khi có đủ điều kiện hoàn hảo, mà là tinh thần dám bước ra bước đầu tiên: "Hãy thử làm mỗi ngày 15 phút bắt đầu từ hôm nay".\nĐược chú truyền cảm hứng, ngay trên đường về hôm đó tôi đã ghé hiệu sách mua một cuốn giáo trình và bắt đầu luyện lập trình 20 phút mỗi tối trước khi đi ngủ. Sau nửa năm, giờ đây tôi đã có thể tự tạo ra công cụ tính toán đơn giản dùng trong công việc và cảm nhận niềm vui học tập mỗi ngày.', NULL, NULL, NULL, '[{"expression":"専門","reading":"せんもん","meaning_vi":"chuyên môn"},{"expression":"刺激","reading":"しげき","meaning_vi":"kích thích; truyền cảm hứng"},{"expression":"昨年","reading":"さくねん","meaning_vi":"năm trước"}]', 614, 4, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-001', 'N3-R-INFO', 'N3', 'READING', 1, '【みどり市市民体育館・会議室および体育室の貸し出し案内】\n当館では、市内の団体および個人に部屋を貸し出しています。利用日の三か月前から三日前までに窓口またはホームページで予約してください。\n1. 1番会議室（定員30名・机と椅子あり）：\n   ・午前（9:00〜12:00）：1,500円 ／ 午後（13:00〜17:00）：2,000円 ／ 夜間（18:00〜21:00）：2,500円\n2. 2番会議室（定員60名・放送設備あり）：\n   ・午前：3,000円 ／ 午後：4,000円 ／ 夜間：5,000円\n3. 小体育室（定員50名・卓球やダンスなど）：\n   ・午前：2,500円 ／ 午後：3,500円 ／ 夜間：4,500円\n※利用者の半数以上がみどり市内に住んでいるか通勤・通学している場合は上記の料金ですが、それ以外の団体（市外団体）は基本料金が二倍になります。\n※冷暖房を使用する場合は、どの部屋も一区分につき500円が追加で必要です（ただし、小体育室の夜間利用に限り、冷暖房費は基本料金に含まれています）。\n※予約の取り消しは、利用日の四日前までは無料ですが、三日前からは基本料金の半額をいただきます。', '[Nhà thi đấu Công dân thành phố Midori - Hướng dẫn cho thuê Phòng họp và Phòng thể chất]\nNhà thi đấu cho các đoàn thể và cá nhân trong thành phố thuê phòng. Vui lòng đặt trước từ 3 tháng đến chậm nhất 3 ngày trước ngày sử dụng tại quầy hoặc trên trang chủ.\n1. Phòng họp số 1 (Sức chứa 30 người - có bàn ghế):\n   ・Sáng (9:00~12:00): 1.500 yên / Chiều (13:00~17:00): 2.000 yên / Tối (18:00~21:00): 2.500 yên\n2. Phòng họp số 2 (Sức chứa 60 người - có thiết bị loa đài):\n   ・Sáng: 3.000 yên / Chiều: 4.000 yên / Tối: 5.000 yên\n3. Phòng thể chất nhỏ (Sức chứa 50 người - bóng bàn, khiêu vũ...):\n   ・Sáng: 2.500 yên / Chiều: 3.500 yên / Tối: 4.500 yên\n*Nếu từ một nửa số người sử dụng trở lên sống hoặc đi làm, đi học tại thành phố Midori thì áp dụng mức giá trên; các đoàn thể khác (đoàn thể ngoài thành phố) giá cơ bản sẽ gấp đôi.\n*Trường hợp sử dụng điều hòa nóng/lạnh, bất kỳ phòng nào cũng cần thêm 500 yên cho mỗi ca (tuy nhiên, riêng ca tối của Phòng thể chất nhỏ thì phí điều hòa đã bao gồm trong giá cơ bản).\n*Hủy đặt phòng: miễn phí đến trước ngày sử dụng 4 ngày, từ 3 ngày trước ngày sử dụng sẽ thu một nửa giá cơ bản.', NULL, NULL, NULL, '[{"expression":"団体","reading":"だんたい","meaning_vi":"đoàn thể; nhóm"},{"expression":"定員","reading":"ていいん","meaning_vi":"sức chứa; định biên"},{"expression":"設備","reading":"せつび","meaning_vi":"thiết bị"}]', 478, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-002', 'N3-R-INFO', 'N3', 'READING', 2, '【あおぞら書店・カフェ一緒の店のアルバイト募集】\n新しく駅前にオープンする書店とカフェが一緒になったお店で、スタッフを募集しています。\n1. 書店スタッフ（本のレジ・棚の整理・注文の受付）：\n   ・時給：1,050円（午後6時以降は時給が100円上がります）\n   ・勤務時間：①午前9:00〜午後2:00 ／ ②午後2:00〜午後6:00 ／ ③午後6:00〜午後10:00\n2. カフェスタッフ（コーヒーの準備・お菓子の販売・席の片づけ）：\n   ・時給：1,100円（土曜日・日曜日はすべての時間帯で時給が100円上がります）\n   ・勤務時間：午前10:00〜午後8:00の間で、1日4時間以上から選べます。\n※どちらの仕事も、週に3日以上働ける方（高校生は不可・大学生や主婦は歓迎）に限ります。\n※交通費は1日800円まで実費をお支払いします。また、1日に6時間以上働く日には、カフェの飲み物とサンドイッチを無料で出します。採用後、最初の20時間は研修期間となり、どの時間帯・曜日でも基本の時給から50円引きになります。', '[Hiệu sách Aozora - Tuyển nhân viên làm thêm tại chi nhánh kết hợp Quán cà phê]\nCửa hàng kết hợp hiệu sách và quán cà phê mới khai trương trước nhà ga đang tuyển nhân viên.\n1. Nhân viên hiệu sách (Thu ngân sách, sắp xếp kệ, nhận đặt sách):\n   ・Lương giờ: 1.050 yên (từ sau 6 giờ tối lương giờ tăng thêm 100 yên)\n   ・Giờ làm việc: ① 9:00 sáng ~ 2:00 chiều / ② 2:00 chiều ~ 6:00 tối / ③ 6:00 tối ~ 10:00 tối\n2. Nhân viên quán cà phê (Pha cà phê, bán bánh ngọt, dọn bàn ghế):\n   ・Lương giờ: 1.100 yên (Thứ Bảy và Chủ nhật tăng thêm 100 yên ở mọi khung giờ)\n   ・Giờ làm việc: Tự chọn từ 4 tiếng/ngày trở lên trong khoảng 10:00 sáng ~ 8:00 tối.\n*Cả hai công việc đều chỉ giới hạn cho người làm được từ 3 ngày/tuần trở lên (không tuyển học sinh cấp 3; hoan nghênh sinh viên đại học và nội trợ).\n*Chi phí đi lại được thanh toán thực tế tối đa 800 yên/ngày. Ngoài ra, vào ngày làm việc từ 6 tiếng trở lên sẽ được phục vụ miễn phí đồ uống và bánh sandwich của quán. Sau khi trúng tuyển, 20 tiếng đầu tiên là thời gian đào tạo, lương giờ ở mọi khung giờ/ngày trong tuần sẽ giảm 50 yên so với mức cơ bản.', NULL, NULL, NULL, '[{"expression":"以降","reading":"いこう","meaning_vi":"từ đó về sau"},{"expression":"期間","reading":"きかん","meaning_vi":"khoảng thời gian"},{"expression":"時給","reading":"じきゅう","meaning_vi":"lương theo giờ"}]', 439, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-003', 'N3-R-INFO', 'N3', 'READING', 3, '【さくら家電・パソコン修理サービスのご案内】\n当店でお買い上げいただいたパソコンはもちろん、他店で買われたパソコンの修理も受け付けます。\n基本のチェックの料金：1台につき 2,000円（原因を調べて見積もりを出すための料金です）\n修理メニューと作業料（部品代を含む）：\n・A：画面の割れ・表示の故障の修理 …… 15,000円（作業日数：約5日）\n・B：電池の交換（充電がすぐ切れる場合）…… 8,000円（作業日数：当日お渡し・約90分）\n・C：キーボードの交換・修理 …… 10,000円（作業日数：約3日）\n※当店でお買い上げのパソコンで、買った日から1年以内の保証書をお持ちの場合は、基本のチェックの料金が無料になり、上記の作業料も半額になります（ただし、水をこぼしたり落としたりして壊れた場合は保証の対象外となり、通常の料金がかかります）。\n※チェックの結果、修理をせずにそのままお返しする場合でも、基本のチェックの料金2,000円はお支払いいただきます。修理期間中に代わりのパソコンを借りたい方は、1日500円でお貸しします。', '[Điện máy Sakura - Hướng dẫn dịch vụ sửa chữa máy tính]\nChúng tôi nhận sửa chữa không chỉ máy tính mua tại cửa hàng mà cả máy tính mua ở cửa hàng khác.\nPhí kiểm tra cơ bản: 2.000 yên/máy (phí kiểm tra nguyên nhân và lập báo giá)\nDanh mục sửa chữa và phí dịch vụ (đã bao gồm tiền linh kiện):\n・A: Sửa vỡ màn hình, lỗi hiển thị ...... 15.000 yên (Số ngày sửa: khoảng 5 ngày)\n・B: Thay pin (trường hợp nhanh hết pin) ...... 8.000 yên (Số ngày sửa: trả ngay trong ngày, khoảng 90 phút)\n・C: Thay thế, sửa chữa bàn phím ...... 10.000 yên (Số ngày sửa: khoảng 3 ngày)\n*Đối với máy tính mua tại cửa hàng và có phiếu bảo hành trong vòng 1 năm kể từ ngày mua: miễn phí kiểm tra cơ bản và giảm một nửa phí sửa chữa nêu trên (tuy nhiên, trường hợp hỏng do làm đổ nước hoặc đánh rơi sẽ không thuộc diện bảo hành và phải trả mức phí thông thường).\n*Sau khi kiểm tra, kể cả trường hợp khách không sửa mà nhận lại máy luôn thì vẫn phải thanh toán 2.000 yên phí kiểm tra cơ bản. Khách muốn thuê máy tính dùng tạm trong thời gian sửa sẽ được cho thuê với giá 500 yên/ngày.', NULL, NULL, NULL, '[{"expression":"半額","reading":"はんがく","meaning_vi":"giảm nửa giá"},{"expression":"期間","reading":"きかん","meaning_vi":"khoảng thời gian"},{"expression":"画面","reading":"がめん","meaning_vi":"màn hình"}]', 455, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-004', 'N3-R-INFO', 'N3', 'READING', 4, '【山川自然公園・秋のキャンプ場利用案内】\n当キャンプ場は、4月1日から11月30日まで営業しています（毎週火曜日は休場日ですが、火曜日が祝日の場合は営業し、翌日の水曜日が休みになります）。\n1. テントサイト（自分のテントを張る場所・1区画あたり6人まで）：\n   ・一晩の料金：平日 3,000円 ／ 金曜日・土曜日・祝日の前日 4,500円\n2. 木の家バンガロー（ベッド・電気付きの小さな家・1つあたり4人まで）：\n   ・一晩の料金：平日 8,000円 ／ 金曜日・土曜日・祝日の前日 10,000円\n※上記の一晩の料金のほかに、場所の管理費として大人（高校生以上）1人につき500円、小・中学生1人につき200円が別に必要です（小学生未満の幼児は無料です）。\n※バーベキューの道具と火をおこすすみのセットは、1セット2,000円で貸し出しています（前日までに電話で予約が必要・当日申し込みは不可）。なお、夜9時以降は周りの方の邪魔になりますので、花火や音楽は禁止です。', '[Công viên Tự nhiên Yamakawa - Hướng dẫn sử dụng Khu cắm trại mùa thu]\nKhu cắm trại mở cửa từ ngày 01/04 đến 30/11 (Thứ Ba hằng tuần nghỉ, nhưng nếu thứ Ba là ngày lễ thì vẫn mở cửa và nghỉ bù vào thứ Tư hôm sau).\n1. Khu dựng lều (chỗ tự căng lều của mình - tối đa 6 người/ô):\n   ・Giá 1 đêm: Ngày thường 3.000 yên / Thứ Sáu, Thứ Bảy, Ngày trước lễ 4.500 yên\n2. Nhà gỗ Bungalow (nhà nhỏ có giường và điện - tối đa 4 người/căn):\n   ・Giá 1 đêm: Ngày thường 8.000 yên / Thứ Sáu, Thứ Bảy, Ngày trước lễ 10.000 yên\n*Ngoài giá thuê 1 đêm nêu trên, cần đóng thêm phí quản lý cơ sở vật chất: Người lớn (từ cấp 3 trở lên) 500 yên/người, Học sinh tiểu học/cấp 2: 200 yên/người (Trẻ nhỏ chưa vào tiểu học được miễn phí).\n*Bộ dụng cụ nướng BBQ và than củi được cho thuê với giá 2.000 yên/bộ (cần đặt trước qua điện thoại chậm nhất là ngày hôm trước; không nhận đăng ký trong ngày). Ngoài ra, từ sau 9 giờ tối để tránh làm phiền xung quanh, nghiêm cấm đốt pháo hoa và bật nhạc.', NULL, NULL, NULL, '[{"expression":"公園","reading":"こうえん","meaning_vi":"công viên"},{"expression":"管理","reading":"かんり","meaning_vi":"quản lý"},{"expression":"幼児","reading":"ようじ","meaning_vi":"trẻ nhỏ"}]', 416, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-005', 'N3-R-INFO', 'N3', 'READING', 5, '【日本全国へお届け・さくらりんご園の「季節のりんご箱」通信販売】\n当りんご園で朝とれたばかりの新鮮なりんごを、全国へ宅配便でお送りします。\n商品の種類（税込）：\n・A箱（家庭用・3キロ・約10玉）：2,500円 ※皮に少し傷がありますが、味は贈答用と同じく甘いです。\n・B箱（贈答用・3キロ・約10玉）：3,800円 ※形と色がきれいで、お祝いなどの贈り物に最適です。\n・C箱（大家族用・5キロ・約18玉）：4,200円\n送料（1箱につき）：\n・本州・四国：600円 ／ 北海道・九州・沖縄：1,000円\n※同じお届け先に2箱以上まとめてご注文いただく場合は、どの地域でも送料がすべて無料になります（ただし、別々の住所に1箱ずつ送る場合は、それぞれに送料がかかります）。\n※代金のお支払いは、クレジットカード（手数料無料）または商品が届いたときに現金で払う「届いたときの現金払い（手数料300円が別に必要）」から選べます。', '[Giao hàng toàn Nhật Bản - Bán hàng qua mạng "Thùng táo theo mùa" của Vườn táo Sakura]\nChúng tôi gửi chuyển phát nhanh trên toàn quốc những trái táo tươi ngon vừa hái buổi sáng tại vườn.\nCác loại sản phẩm (đã gồm thuế):\n・Thùng A (Dùng cho gia đình - 3kg - khoảng 10 quả): 2.500 yên *Ngoài vỏ có chút vết xước nhưng vị ngọt giống hệt loại biếu tặng.\n・Thùng B (Dùng làm quà biếu - 3kg - khoảng 10 quả): 3.800 yên *Hình dáng và màu sắc đẹp, rất hợp làm quà mừng.\n・Thùng C (Dùng cho gia đình đông người - 5kg - khoảng 18 quả): 4.200 yên\nPhí vận chuyển (mỗi thùng):\n・Honshu, Shikoku: 600 yên / Hokkaido, Kyushu, Okinawa: 1.000 yên\n*Trường hợp đặt gộp từ 2 thùng trở lên giao đến cùng một địa chỉ nhận, phí vận chuyển sẽ được miễn phí hoàn toàn ở bất kỳ vùng nào (tuy nhiên, nếu gửi mỗi thùng đến một địa chỉ khác nhau thì vẫn tính phí vận chuyển cho từng thùng).\n*Thanh toán: có thể chọn Thẻ tín dụng (miễn phí dịch vụ) hoặc "Trả tiền mặt khi nhận hàng COD (cần thêm 300 yên phí dịch vụ)".', NULL, NULL, NULL, '[{"expression":"新鮮","reading":"しんせん","meaning_vi":"tươi mới"},{"expression":"地域","reading":"ちいき","meaning_vi":"khu vực; vùng"},{"expression":"現金","reading":"げんきん","meaning_vi":"tiền mặt"}]', 398, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-006', 'N3-R-INFO', 'N3', 'READING', 6, '【ひかり語学スクール・春のビジネス英語講座のご案内】\n仕事で英語を使う方のために、4月から始まる3か月間（全12回）の講座を開きます。\n1. 会話・会議コース（毎週火曜日 19:30〜21:00）：授業料 36,000円 ／ テキスト代 3,000円\n   外国の取引先との会議や電話での応対を中心に練習します。\n2. メール・書類コース（毎週木曜日 19:30〜21:00）：授業料 32,000円 ／ テキスト代 2,500円\n   正確で丁寧なビジネスメールや報告書の書き方を学びます。\n3. 土曜集中コース（毎週土曜日 13:00〜16:00）：授業料 60,000円 ／ テキスト代 5,000円\n   会話とメールの両方を1日でまとめて学ぶコースです。\n※初めて当スクールに申し込む方は、入学金として10,000円が必要です。ただし、3月15日までに申し込む「早期申込」の方は入学金が無料になり、さらに授業料から3,000円割引になります（テキスト代は割引になりません）。\n※欠席した日の授業は、同じ週の別の曜日のクラスへ変更するか、インターネットで録画を見ることができます。', '[Trường Ngoại ngữ Hikari - Hướng dẫn Khóa học Tiếng Anh thương mại mùa xuân]\nDành cho những người sử dụng tiếng Anh trong công việc, trường khai giảng khóa học 3 tháng (tổng 12 buổi) bắt đầu từ tháng 4.\n1. Khóa Hội thoại & Họp hành (Thứ Ba hằng tuần 19:30~21:00): Học phí 36.000 yên / Tiền giáo trình 3.000 yên\n   Luyện tập trọng tâm vào họp hành và nghe điện thoại với đối tác nước ngoài.\n2. Khóa Email & Tài liệu (Thứ Năm hằng tuần 19:30~21:00): Học phí 32.000 yên / Tiền giáo trình 2.500 yên\n   Học cách viết email thương mại và báo cáo chính xác, lịch sự.\n3. Khóa Tập trung Thứ Bảy (Thứ Bảy hằng tuần 13:00~16:00): Học phí 60.000 yên / Tiền giáo trình 5.000 yên\n   Khóa học gộp cả hội thoại lẫn viết email trong cùng 1 ngày.\n*Người đăng ký tại trường lần đầu cần đóng 10.000 yên phí nhập học. Tuy nhiên, người "Đăng ký sớm" trước ngày 15/03 sẽ được miễn phí nhập học, đồng thời được giảm thêm 3.000 yên vào học phí (tiền giáo trình không được giảm).\n*Buổi học bị vắng mặt có thể đổi sang lớp ngày khác trong cùng tuần hoặc xem lại video ghi hình qua internet.', NULL, NULL, NULL, '[{"expression":"中心","reading":"ちゅうしん","meaning_vi":"trung tâm"},{"expression":"学ぶ","reading":"まなぶ","meaning_vi":"học hỏi"},{"expression":"火曜","reading":"かよう","meaning_vi":"thứ Ba"}]', 458, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-007', 'N3-R-INFO', 'N3', 'READING', 7, '【グリーンホテル駅前・駐車場ご利用の案内】\n当ホテルの地下駐車場（高さ2メートルまでのふつうの車のみ・大型バスやトラックは駐車不可）は、以下の料金でご利用いただけます。\n1. ご宿泊のお客様：一晩（チェックイン当日の14:00から翌日の11:00まで）1台 1,200円\n   ※上記の時間より前に入る場合、または11:00を過ぎて出る場合は、30分につき200円の追加料金がかかります。\n2. レストラン・喫茶店をご利用のお客様：最初の1時間は300円、その後は30分につき200円\n   ※ただし、ホテル内のレストランで合計3,000円以上お食事をされた方は2時間まで無料、5,000円以上お食事をされた方は3時間まで無料になります（会計のときに駐車券をレジでお見せください）。\n※地下駐車場が満車の場合は、ホテルの裏にある「1番パーキング（約束のある駐車場）」をご案内します。約束のある駐車場にとめた場合も、ホテルのフロントに駐車券をお持ちいただければ上記と同じ割引が受けられます。', '[Khách sạn Green trước ga - Hướng dẫn sử dụng Bãi đỗ xe]\nBãi đỗ xe ngầm của khách sạn (chỉ dành cho xe ô tô thường cao tối đa 2m; không đỗ được xe buýt lớn hay xe tải) áp dụng mức phí dưới đây:\n1. Khách nghỉ qua đêm tại khách sạn: 1 đêm (từ 14:00 ngày nhận phòng đến 11:00 sáng hôm sau) 1.200 yên/xe\n   *Trường hợp vào sớm hơn giờ trên hoặc ra muộn sau 11:00 sẽ tính thêm phí 200 yên cho mỗi 30 phút.\n2. Khách sử dụng Nhà hàng / Quán nước: 1 tiếng đầu tiên 300 yên, sau đó 200 yên cho mỗi 30 phút\n   *Tuy nhiên, khách dùng bữa tại nhà hàng trong khách sạn với tổng hóa đơn từ 3.000 yên trở lên được miễn phí tối đa 2 tiếng, từ 5.000 yên trở lên được miễn phí tối đa 3 tiếng (vui lòng xuất trình vé xe tại quầy thu ngân khi thanh toán).\n*Trường hợp bãi đỗ xe ngầm hết chỗ, chúng tôi sẽ hướng dẫn sang "Bãi đỗ xe số 1 (bãi xe liên kết)" ở phía sau khách sạn. Khi đỗ tại bãi xe liên kết, nếu mang vé xe tới quầy lễ tân khách sạn thì vẫn được hưởng ưu đãi giảm giá giống hệt như trên.', NULL, NULL, NULL, '[{"expression":"翌日","reading":"よくじつ","meaning_vi":"ngày hôm sau"},{"expression":"場合","reading":"ばあい","meaning_vi":"trường hợp"},{"expression":"大型","reading":"おおがた","meaning_vi":"cỡ to"}]', 429, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-008', 'N3-R-INFO', 'N3', 'READING', 8, '【みどり市・春のフリーマーケット（不用品販売会）出店者募集】\n家庭で使わなくなった服や本、食器などを販売するフリーマーケットを、5月18日（日）午前10時〜午後3時にみどり公園の広場で開きます（雨天の場合は次の週の5月25日に延期します）。\n出店スペースと参加費：\n・A区画（手持ち出店・2メートル×2メートル）：1区画 1,000円（歩いて荷物を運び入れる区画です）\n・B区画（車出店・3メートル×5メートル）：1区画 2,500円（自分の車を区画の横に直接とめて販売できます）\n※出店できるのは、みどり市内に住んでいる18歳以上の方（高校生は不可）で、家庭の不用品を売る個人に限ります（プロの業者や、自分で作った食べ物・飲み物の販売は固くお断りします）。\n※申し込みは1世帯につき1区画までです。4月30日（必着）までに往復はがきで申し込んでください。応募が多い場合はくじ引きを行い、5月7日までに全員に結果を郵送します。参加費は当日、会場の受付でお支払いください。', '[Thành phố Midori - Tuyển người đăng ký gian hàng Chợ trời mùa xuân (Hội chợ bán đồ cũ)]\nChợ trời bán quần áo, sách vở, bát đĩa... không còn dùng trong gia đình sẽ được tổ chức vào Chủ nhật ngày 18/05 từ 10:00 sáng ~ 3:00 chiều tại quảng trường công viên Midori (trường hợp trời mưa sẽ hoãn sang ngày 25/05 tuần kế tiếp).\nLoại gian hàng và phí tham gia:\n・Ô khu A (Gian hàng xách tay - 2m × 2m): 1.000 yên/ô (khu vực tự đi bộ mang đồ vào)\n・Ô khu B (Gian hàng có xe ô tô - 3m × 5m): 2.500 yên/ô (được đỗ xe ô tô ngay cạnh gian hàng để bán)\n*Đối tượng được mở gian hàng: chỉ giới hạn cho cá nhân từ 18 tuổi trở lên sống trong thành phố Midori (không nhận học sinh cấp 3) và bán đồ không dùng đến của gia đình (nghiêm cấm người buôn bán chuyên nghiệp hoặc bán đồ ăn, thức uống tự làm).\n*Mỗi hộ gia đình chỉ được đăng ký tối đa 1 ô. Vui lòng đăng ký bằng bưu thiếp khứ hồi trước ngày 30/04 (tính theo ngày bưu thiếp đến nơi). Nếu số lượng đăng ký nhiều sẽ bốc thăm và gửi kết quả qua bưu điện cho tất cả mọi người trước ngày 07/05. Phí tham gia thanh toán trực tiếp tại quầy lễ tân hội trường vào ngày diễn ra.', NULL, NULL, NULL, '[{"expression":"個人","reading":"こじん","meaning_vi":"cá nhân"},{"expression":"場合","reading":"ばあい","meaning_vi":"trường hợp"},{"expression":"当日","reading":"とうじつ","meaning_vi":"đúng ngày hôm đó"}]', 427, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-009', 'N3-R-INFO', 'N3', 'READING', 9, '【さくら美術館・「近代日本の風景の絵の会」前売り券と割引のご案内】\n期間：6月1日（日）〜7月20日（日） 午前9:30〜午後5:00 ※休みの日：毎週月曜日（月曜日が祝日の場合は開き、次の日の火曜日が休みになります）\n入場料金：\n・一般（大人）：当日券 1,400円 ／ 前売り券 1,100円\n・大学生・高校生：当日券 900円 ／ 前売り券 700円\n・中学生以下：無料（窓口で生徒手帳または年齢がわかるものをお見せください）\n※前売り券は、5月31日（土）まで美術館の窓口および市内の主な書店で販売しています（6月1日以降は前売り券を買うことはできません）。\n※当日の割引制度（前売り券と一緒に使うことはできません）：\n  ①65歳以上の方は、年齢が確認できる証明書を窓口で見せると、当日券が半額（700円）になります。\n  ②午後5時以降に入場する「夕方割引（金曜日・土曜日のみ開く時間を午後8時まで延長）」を利用すると、一般・学生ともに当日券から300円引きになります。', '[Bảo tàng Mỹ thuật Sakura - Hướng dẫn Vé đặt trước và Giảm giá cho "Triển lãm Tranh phong cảnh Nhật Bản cận đại"]\nThời gian mở: 01/06 (Chủ nhật) ~ 20/07 (Chủ nhật) 9:30 sáng ~ 5:00 chiều *Ngày nghỉ: Thứ Hai hằng tuần (nếu Thứ Hai là ngày lễ thì vẫn mở cửa và nghỉ vào Thứ Ba hôm sau)\nGiá vé vào cửa:\n・Khách thường (Người lớn): Vé mua trong ngày 1.400 yên / Vé đặt trước 1.100 yên\n・Sinh viên đại học, học sinh cấp 3: Vé mua trong ngày 900 yên / Vé đặt trước 700 yên\n・Học sinh cấp 2 trở xuống: Miễn phí (vui lòng xuất trình sổ học sinh hoặc giấy tờ xác nhận độ tuổi tại quầy)\n*Vé đặt trước được bán đến hết Thứ Bảy ngày 31/05 tại quầy vé bảo tàng và các hiệu sách chính trong thành phố (từ ngày 01/06 trở đi không thể mua vé đặt trước).\n*Chế độ giảm giá trong ngày (không áp dụng đồng thời với vé đặt trước):\n  ① Người từ 65 tuổi trở lên khi xuất trình giấy tờ xác nhận độ tuổi tại quầy sẽ được giảm một nửa giá vé mua trong ngày (còn 700 yên).\n  ② Nếu sử dụng "Giảm giá buổi chiều tối" vào cửa từ sau 5 giờ chiều (chỉ Thứ Sáu và Thứ Bảy kéo dài giờ mở cửa đến 8 giờ tối), cả khách thường lẫn học sinh/sinh viên đều được giảm 300 yên so với giá vé mua trong ngày.', NULL, NULL, NULL, '[{"expression":"一般","reading":"いっぱん","meaning_vi":"thông thường; đại chúng"},{"expression":"年齢","reading":"ねんれい","meaning_vi":"tuổi tác"},{"expression":"以降","reading":"いこう","meaning_vi":"từ đó về sau"}]', 418, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-010', 'N3-R-INFO', 'N3', 'READING', 10, '【スマイル歯科医院・定期の歯の検査とクリーニングのご案内】\n歯の健康を守るため、半年に一度の定期の歯の検査をおすすめしています（当院は完全予約制です）。\n1. 基本の検査コース（約30分）：虫歯と歯ぐきの検査、簡単な歯石取り\n   ・健康保険証をお持ちの方：約1,500円 ／ 保険証がない方：5,000円\n2. 徹底クリーニングコース（約60分）：専用の機械でコーヒーやタバコの着色汚れを落とし、歯の表面をツルツルに磨きます（保険は使えません・自分でお金を払う診察）。\n   ・料金：6,000円（ただし、基本の検査コースと同じ日に続けて受ける場合は、クリーニング代が1,000円引きの5,000円になります）\n3. 子ども予防コース（小学生以下・約30分）：虫歯の検査と、虫歯を防ぐ薬を塗ります。\n   ・料金：市内の子ども医療証をお持ちの方は無料（市外の方は1,000円）\n※予約の変更や取り消しは、前日の午後5時までに電話でご連絡ください。連絡なしで休まれた場合は、次回の予約が取りにくくなることがあります。', '[Phòng khám Nha khoa Smile - Hướng dẫn Khám định kỳ và Làm sạch răng]\nĐể bảo vệ sức khỏe răng miệng, chúng tôi khuyến khích khám định kỳ 6 tháng một lần (phòng khám áp dụng chế độ đặt hẹn hoàn toàn).\n1. Gói khám cơ bản (khoảng 30 phút): Kiểm tra sâu răng và nướu, lấy cao răng đơn giản\n   ・Người có thẻ bảo hiểm y tế: khoảng 1.500 yên / Người không có thẻ bảo hiểm: 5.000 yên\n2. Gói làm sạch chuyên sâu (khoảng 60 phút): Dùng máy chuyên dụng làm sạch vết ố màu do cà phê hay thuốc lá, đánh bóng bề mặt răng (không áp dụng bảo hiểm - khám tự túc).\n   ・Giá: 6.000 yên (tuy nhiên, nếu làm liên tiếp trong cùng một ngày với Gói khám cơ bản thì phí làm sạch được giảm 1.000 yên còn 5.000 yên)\n3. Gói dự phòng trẻ em (Học sinh tiểu học trở xuống - khoảng 30 phút): Kiểm tra sâu răng và bôi thuốc ngừa sâu răng.\n   ・Giá: Miễn phí đối với trẻ có thẻ y tế trẻ em của thành phố (trẻ ngoài thành phố: 1.000 yên)\n*Thay đổi hoặc hủy lịch hẹn vui lòng gọi điện báo trước 5 giờ chiều ngày hôm trước. Trường hợp nghỉ không báo trước có thể sẽ khó đặt lịch cho lần tiếp theo.', NULL, NULL, NULL, '[{"expression":"前日","reading":"ぜんじつ","meaning_vi":"ngày trước"},{"expression":"汚れ","reading":"よごれ","meaning_vi":"vết bẩn"},{"expression":"歯科医","reading":"しかい","meaning_vi":"nha sĩ"}]', 436, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-011', 'N3-R-INFO', 'N3', 'READING', 11, '【さくら市コミュニティバス・1日乗車券と回数券のご案内】\n市内を走るすべてのコミュニティバス（赤ルート・青ルート・緑ルート）は、1回乗るごとに大人200円、小学生100円（小学生未満は大人1人につき2人まで無料）の運賃がかかります。よくバスをご利用になる方には、以下の割引乗車券が便利です。\n1. 1日乗り放題パス（買ったその日だけ、3つのルートすべてに何回でも乗れます）：\n   ・大人：500円 ／ 小学生：250円（バスの運転手から直接買えます）\n2. 回数券（200円券が11枚つづり・有効期限は買った日から3か月間）：\n   ・販売価格：2,000円（1回分お得です。市役所の窓口またはバス営業所で販売・車内では買えません）\n3. 高齢者さわやかパス（市内に住む70歳以上の方が対象）：\n   ・1か月 1,000円で全ルート乗り放題（市役所で住所と年齢がわかる証明書を出して買ってください）\n※別のルートのバスへ乗り換える場合、最初のバスを降りるときに運転手から「乗り換え券」をもらえば、30分以内に乗る2台目のバスの運賃が半額（大人100円、小学生50円）になります。', '[Xe buýt cộng đồng thành phố Sakura - Hướng dẫn Vé đi 1 ngày và Vé tập]\nTất cả các tuyến xe buýt cộng đồng chạy trong thành phố (Tuyến Đỏ, Tuyến Xanh dương, Tuyến Xanh lá) đều có giá vé mỗi lượt là Người lớn 200 yên, Học sinh tiểu học 100 yên (trẻ chưa vào tiểu học được miễn phí tối đa 2 bé đi kèm 1 người lớn). Với những khách thường xuyên đi xe buýt, các loại vé giảm giá dưới đây rất tiện lợi:\n1. Vé đi không giới hạn 1 ngày (chỉ trong ngày mua, được đi không giới hạn số lần cả 3 tuyến):\n   ・Người lớn: 500 yên / Tiểu học: 250 yên (có thể mua trực tiếp từ tài xế trên xe buýt)\n2. Vé tập (xấp 11 vé mệnh giá 200 yên - thời hạn sử dụng 3 tháng kể từ ngày mua):\n   ・Giá bán: 2.000 yên (lời được 1 lượt. Bán tại quầy Ủy ban thành phố hoặc văn phòng xe buýt - không bán trên xe)\n3. Vé ưu đãi người cao tuổi (dành cho người từ 70 tuổi trở lên sống trong thành phố):\n   ・1.000 yên/tháng đi không giới hạn mọi tuyến (mua tại Ủy ban thành phố, xuất trình giấy tờ xác nhận địa chỉ và độ tuổi)\n*Trường hợp chuyển sang tuyến xe buýt khác, nếu xin "Phiếu chuyển tuyến" từ tài xế khi xuống xe đầu tiên, thì giá vé của chuyến xe thứ hai lên trong vòng 30 phút sẽ được giảm một nửa (Người lớn 100 yên, Tiểu học 50 yên).', NULL, NULL, NULL, '[{"expression":"運賃","reading":"うんちん","meaning_vi":"giá vé tàu xe"},{"expression":"割引","reading":"わりびき","meaning_vi":"giảm giá"},{"expression":"年齢","reading":"ねんれい","meaning_vi":"tuổi tác"}]', 468, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-012', 'N3-R-INFO', 'N3', 'READING', 12, '【東山ホテル・会議と食事会プランのご案内】\n会社の会議や歓迎会や送別会、同窓会などに、当ホテルの広い会場と料理をぜひご利用ください（10名様以上の団体から予約を受け付けます）。\n1. 会議のみプラン（2時間・お茶とコーヒー付き）：お一人様 1,500円\n   ※プロジェクターとスクリーンのセットは、1会場につき3,000円で貸し出します。\n2. 昼食弁当付き会議プラン（3時間・季節の幕の内弁当とお茶付き）：お一人様 3,500円\n   ※このプランをご利用の団体には、プロジェクターとスクリーンを無料でお貸しします。\n3. 夜の食事会プラン（2時間・和洋コース料理）：お一人様 5,000円\n   ※飲み放題（ビール・ジュース・お茶）をつける場合は、お一人様プラス1,500円（全員分のお申し込みが必要です）になります。\n※人数の変更は前日の正午まで無料で受け付けますが、それ以降に人数が減った場合は、減った人数分の料理代（プラン1は1,500円、プラン2は2,000円、プラン3は3,500円）をキャンセル料としていただきます。', '[Khách sạn Higashiyama - Hướng dẫn các gói Họp và Tiệc]\nXin mời quý khách sử dụng hội trường rộng rãi và ẩm thực của khách sạn cho các buổi họp công ty, tiệc chào đón/chia tay, họp lớp... (nhận đặt cho đoàn từ 10 người trở lên).\n1. Gói chỉ họp (2 tiếng - kèm trà và cà phê): 1.500 yên/người\n   *Bộ máy chiếu và màn chiếu cho thuê với giá 3.000 yên/phòng họp.\n2. Gói họp kèm cơm hộp trưa (3 tiếng - kèm cơm hộp Makunouchi theo mùa và trà): 3.500 yên/người\n   *Đoàn sử dụng gói này được cho mượn miễn phí máy chiếu và màn chiếu.\n3. Gói tiệc tối (2 tiếng - món ăn theo thực đơn Âu - Nhật): 5.000 yên/người\n   *Trường hợp thêm gói uống thỏa thích (bia, nước ngọt, trà) sẽ cộng thêm 1.500 yên/người (cần đăng ký cho toàn bộ thành viên trong đoàn).\n*Thay đổi số lượng người được tiếp nhận miễn phí đến trước 12 giờ trưa ngày hôm trước; nếu giảm số người sau thời điểm đó sẽ thu phí hủy bằng tiền thức ăn của số người giảm (Gói 1: 1.500 yên, Gói 2: 2.000 yên, Gói 3: 3.500 yên).', NULL, NULL, NULL, '[{"expression":"団体","reading":"だんたい","meaning_vi":"đoàn thể; nhóm"},{"expression":"無料","reading":"むりょう","meaning_vi":"miễn phí"},{"expression":"前日","reading":"ぜんじつ","meaning_vi":"ngày trước"}]', 444, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-013', 'N3-R-INFO', 'N3', 'READING', 13, '【クリーン洗濯店・春の布団（ふとん）丸洗いキャンペーン】\n冬の間使った羽毛布団や毛布を、しまう前に専用の大きな洗濯機で水洗いしませんか。4月1日から5月15日までの特別価格です。\n1. 羽毛布団（1枚につき）：通常 4,500円 → キャンペーン価格 3,500円\n2. 綿の敷き布団（1枚につき）：通常 4,000円 → キャンペーン価格 3,200円\n3. 毛布（厚手・薄手どちらも1枚につき）：通常 1,500円 → キャンペーン価格 1,000円\n※3枚以上まとめてお出しいただくと、上記のキャンペーン価格からさらに合計金額の1割（10%）を割引いたします（組み合わせは自由です）。\n※大きな布団をお店まで運ぶのが大変な方のために、ご自宅まで取りに伺い、洗ったあとにお届けする「集配サービス」を行っています。集配料は1回（往復）につき800円ですが、割引後の洗濯代が合計6,000円以上の場合は集配料が無料になります。\n※出来上がりまでには約1週間かかります。また、そのまま今年の秋まで当店の温度管理された専用の部屋でお預かりする「預かりサービス（1枚につきプラス1,000円）」もございます。', '[Tiệm giặt Clean - Chiến dịch giặt trọn gói chăn đệm mùa xuân]\nTrước khi cất chăn lông vũ hay chăn len đã dùng suốt mùa đông, bạn có muốn giặt nước bằng máy giặt cỡ lớn chuyên dụng không? Đây là giá đặc biệt từ 01/04 đến 15/05.\n1. Chăn lông vũ (mỗi chiếc): Thông thường 4.500 yên -> Giá chiến dịch 3.500 yên\n2. Đệm bông trải sàn (mỗi chiếc): Thông thường 4.000 yên -> Giá chiến dịch 3.200 yên\n3. Chăn len/chăn lông (cả loại dày và mỏng, mỗi chiếc): Thông thường 1.500 yên -> Giá chiến dịch 1.000 yên\n*Nếu mang giặt gộp từ 3 chiếc trở lên, quý khách sẽ được giảm thêm 10% trên tổng số tiền tính theo giá chiến dịch nêu trên (tự do kết hợp các loại).\n*Dành cho những khách gặp khó khăn khi mang chăn đệm lớn ra tiệm, chúng tôi có "Dịch vụ giao nhận tận nhà" đến lấy và giao trả sau khi giặt. Phí giao nhận là 800 yên/lần (khứ hồi), nhưng nếu tổng tiền giặt sau khi giảm giá từ 6.000 yên trở lên thì được miễn phí giao nhận.\n*Thời gian giặt xong mất khoảng 1 tuần. Ngoài ra còn có "Dịch vụ giữ đồ (cộng thêm 1.000 yên/chiếc)" giữ chăn tại phòng chuyên dụng kiểm soát nhiệt độ của tiệm cho đến mùa thu năm nay.', NULL, NULL, NULL, '[{"expression":"洗濯","reading":"せんたく","meaning_vi":"giặt giũ"},{"expression":"価格","reading":"かかく","meaning_vi":"giá cả"},{"expression":"管理","reading":"かんり","meaning_vi":"quản lý"}]', 479, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-014', 'N3-R-INFO', 'N3', 'READING', 14, '【みどり市国際交流協会・外国人住民のための無料相談会】\nみどり市に暮らす外国人の方が安心して生活できるよう、専門家が無料で相談に応じる窓口を毎月3番目の土曜日に開いています。\n日時：毎月3番目の土曜日 午前10:00〜午後4:00（1人につき相談時間は45分まで）\n場所：みどり市民プラザ 3階 相談室\n相談できる分野と対応言語：\n・A：在留資格（ビザ）や法律に関する相談 …… 英語・中国語・ベトナム語・やさしい日本語\n・B：税金・年金・健康保険などの手続き相談 …… 英語・ベトナム語・やさしい日本語\n・C：子どもの学校・進学・教育に関する相談 …… 中国語・ベトナム語・やさしい日本語\n※「A：在留資格や法律の相談」だけは、弁護士や専門の担当者の人数が限られているため、相談日の3日前（水曜日）までに電話またはホームページでの事前予約が必要です（BとCの相談は予約なしで当日直接お越しいただけますが、午後3時30分までに受付を済ませてください）。', '[Hiệp hội Giao lưu Quốc tế thành phố Midori - Buổi tư vấn miễn phí dành cho cư dân người nước ngoài]\nĐể người nước ngoài sinh sống tại thành phố Midori có thể an tâm cuộc sống, chúng tôi mở quầy tư vấn miễn phí cùng chuyên gia vào Thứ Bảy tuần thứ 3 hằng tháng.\nThời gian: Thứ Bảy tuần thứ 3 hằng tháng, 10:00 sáng ~ 4:00 chiều (thời gian tư vấn tối đa 45 phút/người)\nĐịa điểm: Phòng tư vấn tầng 3, Midori Shimin Plaza\nCác lĩnh vực tư vấn và ngôn ngữ hỗ trợ:\n・A: Tư vấn về tư cách lưu trú (visa) và pháp luật ...... Tiếng Anh, Tiếng Trung, Tiếng Việt, Tiếng Nhật đơn giản\n・B: Tư vấn thủ tục thuế, lương hưu, bảo hiểm y tế ...... Tiếng Anh, Tiếng Việt, Tiếng Nhật đơn giản\n・C: Tư vấn về trường học, học lên cao, giáo dục của con cái ...... Tiếng Trung, Tiếng Việt, Tiếng Nhật đơn giản\n*Riêng mục "A: Tư vấn về tư cách lưu trú và pháp luật", do số lượng luật sư và người phụ trách chuyên môn có hạn nên cần đặt lịch hẹn trước qua điện thoại hoặc trang chủ chậm nhất là 3 ngày trước buổi tư vấn (tức Thứ Tư). (Mục B và C không cần đặt hẹn trước mà có thể đến trực tiếp trong ngày, nhưng vui lòng làm thủ tục tiếp nhận trước 3:30 chiều).', NULL, NULL, NULL, '[{"expression":"住民","reading":"じゅうみん","meaning_vi":"cư dân"},{"expression":"法律","reading":"ほうりつ","meaning_vi":"pháp luật"},{"expression":"資格","reading":"しかく","meaning_vi":"chứng chỉ"}]', 409, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-015', 'N3-R-INFO', 'N3', 'READING', 15, '【青空スポーツクラブ・夏の子ども短期水泳教室のご案内】\n夏休みの期間中、泳ぎが苦手なお子さんからもっと速く泳ぎたいお子さんまでを対象に、4日間の短期水泳教室を開きます。\n期間（どちらも火曜日〜金曜日の4日間・毎日午前9:30〜10:45）：\n・1回目の期間：7月22日〜7月25日 ／ 2回目の期間：8月5日〜8月8日\nクラスと対象：\n・メダカ組（4歳〜小学2年生）：水に顔をつける練習や、ビート板を使って浮く練習をします。\n・イルカ組（小学1年生〜小学6年生）：クロールや平泳ぎで25メートル泳げるように練習します。\n参加費（4日間）：1回につき 6,000円（ただし、1回目の期間と2回目の期間の両方を同時に申し込む場合は、2回分の合計から1,500円割引になり10,500円になります）\n※水着は自由ですが、安全のため当クラブ指定のぼうし（1枚800円）を必ずかぶっていただきます（すでにお持ちの方は新しく買う必要はありません）。\n※教室のあと、当クラブの通常コースへ8月中にご入会いただくと、入会金（5,000円）が無料になり、指定のバッグをプレゼントします。', '[Câu lạc bộ Thể thao Aozora - Hướng dẫn Lớp học bơi ngắn hạn mùa hè cho trẻ em]\nTrong kỳ nghỉ hè, chúng tôi mở lớp học bơi ngắn hạn 4 ngày dành cho các bé từ còn sợ nước cho đến các bé muốn bơi nhanh hơn.\nThời gian (cả 2 đợt đều học 4 ngày Thứ Ba ~ Thứ Sáu, mỗi ngày 9:30~10:45 sáng):\n・Đợt 1: 22/07 ~ 25/07 / Đợt 2: 05/08 ~ 08/08\nLớp học và đối tượng:\n・Lớp Cá Medaka (4 tuổi ~ Lớp 2 tiểu học): Tập úp mặt xuống nước và tập nổi bằng phao tấm.\n・Lớp Cá heo (Lớp 1 ~ Lớp 6 tiểu học): Tập bơi sải và bơi ếch để bơi được 25 mét.\nHọc phí (4 ngày): 6.000 yên/đợt (tuy nhiên, nếu đăng ký cùng lúc cả Đợt 1 và Đợt 2 sẽ được giảm 1.500 yên trên tổng 2 đợt, còn 10.500 yên)\n*Áo bơi tự do, nhưng để đảm bảo an toàn các bé bắt buộc phải đội mũ bơi chỉ định của câu lạc bộ (800 yên/chiếc; bé nào đã có sẵn thì không cần mua mới).\n*Sau lớp học ngắn hạn, nếu đăng ký vào khóa học thường xuyên của câu lạc bộ trong tháng 8 sẽ được miễn phí nhập hội (5.000 yên) và tặng cặp sách chỉ định.', NULL, NULL, NULL, '[{"expression":"期間","reading":"きかん","meaning_vi":"thời gian; kỳ hạn"},{"expression":"対象","reading":"たいしょう","meaning_vi":"đối tượng"},{"expression":"苦手な","reading":"にがてな","meaning_vi":"kém"}]', 472, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-016', 'N3-R-INFO', 'N3', 'READING', 16, '【みどり市文化会館・「秋のクラシック音楽祭」チケット販売のお知らせ】\n日時：10月26日（日） 午後2:00開演（午後1:15開場）\n座席の種類と料金（全席指定）：\n・S席（1階の前列〜中央）：5,000円\n・A席（1階の後列・2階席）：3,500円\n・学生席（2階の後ろの列・高校生から大学生まで対象）：1,500円（入場時に学生証を見せることが必要）\n※小学生未満のお子様は入場できません。小学生・中学生は、S席・A席ともに上記の半額になります（学生席は高校生以上のみ）。\n※同じ日の午前11:00から11:45まで、0歳のお子様から一緒に入れる「親子のためのミニコンサート（全席自由・大人1,000円、中学生以下500円、3歳未満で保護者のひざの上に座る場合は無料）」も開かれます。\n※チケットを4枚以上まとめて買う場合は、合計金額から1割（10%）引きになります（ただし、学生席および午前中のミニコンサートは割引の対象外です）。', '[Nhà văn hóa thành phố Midori - Thông báo bán vé "Lễ hội Âm nhạc Cổ điển mùa thu"]\nThời gian: Chủ nhật ngày 26/10, bắt đầu biểu diễn lúc 2:00 chiều (mở cửa đón khách lúc 1:15 chiều)\nCác hạng ghế và giá vé (tất cả đều có số ghế cố định):\n・Ghế hạng S (Hàng đầu ~ giữa tầng 1): 5.000 yên\n・Ghế hạng A (Hàng sau tầng 1 & tầng 2): 3.500 yên\n・Ghế học sinh/sinh viên (Hàng cuối tầng 2 - dành cho học sinh cấp 3 đến sinh viên đại học): 1.500 yên (cần xuất trình thẻ học sinh/sinh viên khi vào cửa)\n*Trẻ em chưa vào tiểu học không được vào cửa buổi chiều. Học sinh tiểu học và cấp 2 được giảm một nửa giá nêu trên cho cả ghế S và ghế A (ghế học sinh/sinh viên chỉ dành cho cấp 3 trở lên).\n*Từ 11:00 đến 11:45 sáng cùng ngày có tổ chức thêm "Buổi hòa nhạc nhỏ dành cho cha mẹ và con cái" mà trẻ từ 0 tuổi có thể vào cùng (ngồi tự do - Người lớn 1.000 yên, Cấp 2 trở xuống 500 yên, Trẻ dưới 3 tuổi ngồi trên đùi phụ huynh được miễn phí).\n*Trường hợp mua gộp từ 4 vé trở lên sẽ được giảm 10% tổng số tiền (tuy nhiên, Ghế học sinh/sinh viên và Buổi hòa nhạc nhỏ buổi sáng không thuộc diện được giảm giá).', NULL, NULL, NULL, '[{"expression":"座席","reading":"ざせき","meaning_vi":"chỗ ngồi; ghế ngồi"},{"expression":"中央","reading":"ちゅうおう","meaning_vi":"trung tâm; chính giữa"},{"expression":"対象","reading":"たいしょう","meaning_vi":"đối tượng"}]', 409, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-017', 'N3-R-INFO', 'N3', 'READING', 17, '【山川宅配便・「ゴルフ・スキー荷物往復サービス」のご案内】\n重いゴルフバッグやスキー板を、ご自宅からホテルやゴルフ場・スキー場まで直接お届けします。手ぶらで楽に旅行ができます。\n1. 片道料金（1つにつき）：関東・中部エリア 1,800円 ／ 関西・東北エリア 2,200円\n2. 往復割引パック（行きと帰りを同時に申し込む場合）：\n   ・往復の合計料金から400円引きになります（例：関東エリアなら往復3,200円）。\n※集荷の締め切り：ご利用になる日（プレー日）の「2日前の午後5時まで」にお近くの営業所へ持ち込むか、ご自宅への集荷を予約してください（北海道・沖縄へ送る場合は3日前まで）。\n※ご自分で営業所へ荷物を直接持ち込まれた場合は、1つにつき100円引きになります（往復パックの場合は、行きの分として100円引きになります）。\n※1つの袋に2人分の道具を入れて送ることは、壊れることの原因になるためお断りしています。', '[Chuyển phát nhanh Yamakawa - Hướng dẫn "Dịch vụ gửi hành lý Golf / Trượt tuyết khứ hồi"]\nChúng tôi giao trực tiếp túi gậy golf hay ván trượt tuyết nặng nhọc từ nhà quý khách tới khách sạn, sân golf hoặc khu trượt tuyết. Quý khách có thể đi du lịch thảnh thơi không phải mang vác.\n1. Giá một chiều (mỗi kiện): Khu vực Kanto, Chubu 1.800 yên / Khu vực Kansai, Tohoku 2.200 yên\n2. Gói giảm giá khứ hồi (trường hợp đăng ký cùng lúc cả chiều đi và chiều về):\n   ・Được giảm 400 yên trên tổng cước phí khứ hồi (Ví dụ: khu vực Kanto khứ hồi là 3.200 yên).\n*Thời hạn nhận hàng: Vui lòng mang ra bưu cục gần nhất hoặc đặt lịch lấy hàng tại nhà chậm nhất là "trước 5 giờ chiều của 2 ngày trước ngày sử dụng" (trường hợp gửi đi Hokkaido hoặc Okinawa là trước 3 ngày).\n*Trường hợp quý khách tự mang hành lý trực tiếp ra bưu cục sẽ được giảm 100 yên/kiện (với gói khứ hồi sẽ được giảm 100 yên cho chiều đi).\n*Chúng tôi từ chối nhận gửi dụng cụ của 2 người nhét chung vào 1 túi vì dễ gây hư hỏng.', NULL, NULL, NULL, '[{"expression":"直接","reading":"ちょくせつ","meaning_vi":"trực tiếp"},{"expression":"原因","reading":"げんいん","meaning_vi":"nguyên nhân"},{"expression":"片道","reading":"かたみち","meaning_vi":"một chiều"}]', 399, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-018', 'N3-R-INFO', 'N3', 'READING', 18, '【シェアオフィス「ワーク・プラス」・利用プランのご案内】\n駅のすぐ隣にある静かな仕事・勉強スペースです。高速インターネット、電源、プリンターを完備しています（営業時間：毎日 午前7:00〜午後11:00）。\n1. 1日利用（ドロップイン・会員登録は不要）：\n   ・1時間につき 400円 ／ 1日最大料金（何時間いても）：1,800円\n2. 月額会員プラン（毎月決まった料金で何度でも利用できます）：\n   ・A：夜＆休日プラン（平日の18:00〜23:00、および土日祝日の全時間）：月額 7,000円\n   ・B：平日昼プラン（月〜金の7:00〜18:00のみ）：月額 8,000円\n   ・C：フルタイムプラン（すべての曜日・すべての時間）：月額 13,000円\n※すべての利用者に、コーヒーとお茶の無料サービスがあります。白黒コピーは1日10枚まで無料（11枚目からは1枚10円）、カラーコピーは1枚目から1枚40円です。\n※月額会員に初めて申し込むときは、カード発行料として2,000円が必要です（1日利用の方は不要）。また、会議室（6人用）を借りたい場合は、月額会員に限り1時間1,000円で予約できます。', '[Văn phòng chia sẻ "Work Plus" - Hướng dẫn các gói sử dụng]\nKhông gian làm việc và học tập yên tĩnh nằm ngay sát nhà ga. Trang bị đầy đủ internet tốc độ cao, ổ cắm điện và máy in (Giờ mở cửa: Mỗi ngày 7:00 sáng ~ 11:00 đêm).\n1. Sử dụng theo ngày (Drop-in - không cần đăng ký hội viên):\n   ・400 yên/tiếng / Giá tối đa 1 ngày (dù ngồi bao nhiêu tiếng): 1.800 yên\n2. Gói hội viên tháng (đóng mức phí cố định hằng tháng và sử dụng không giới hạn số lần):\n   ・A: Gói Tối & Ngày nghỉ (18:00~23:00 ngày thường, và toàn bộ thời gian Thứ Bảy, Chủ nhật, Ngày lễ): 7.000 yên/tháng\n   ・B: Gói Ban ngày ngày thường (chỉ 7:00~18:00 từ Thứ Hai ~ Thứ Sáu): 8.000 yên/tháng\n   ・C: Gói Toàn thời gian (tất cả các ngày, mọi khung giờ): 13.000 yên/tháng\n*Tất cả người sử dụng đều được phục vụ miễn phí cà phê và trà. Photocopy đen trắng miễn phí tối đa 10 tờ/ngày (từ tờ thứ 11 là 10 yên/tờ), photocopy màu tính 40 yên/tờ ngay từ tờ đầu tiên.\n*Khi đăng ký hội viên tháng lần đầu cần đóng 2.000 yên phí làm thẻ (khách dùng lẻ theo ngày không cần). Ngoài ra, trường hợp muốn thuê phòng họp (6 chỗ), chỉ hội viên tháng mới được đặt với giá 1.000 yên/tiếng.', NULL, NULL, NULL, '[{"expression":"電源","reading":"でんげん","meaning_vi":"nguồn điện; ổ điện"},{"expression":"祝日","reading":"しゅくじつ","meaning_vi":"ngày lễ quốc gia"},{"expression":"場合","reading":"ばあい","meaning_vi":"trường hợp"}]', 480, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-019', 'N3-R-INFO', 'N3', 'READING', 19, '【さくら市・家庭用省エネ家電の買い替え助けのお金のお知らせ】\n市では、家庭での電気の使用量を減らすため、古いエアコンや冷蔵庫を省エネ性能の高い新しい製品に買い替える市民の方に、助けのお金を出しています。\n対象となる製品と助けのお金の額：\n・エアコン（省エネラベル4つ星以上）：買った価格（税金を入れる前）の2割（上限 30,000円）\n・電気冷蔵庫（省エネラベル3つ星以上）：買った価格（税金を入れる前）の2割（上限 40,000円）\n申し込みの条件（すべてを満たす必要があります）：\n①さくら市内に住んでいる証明の紙があり、現在住んでいる自宅に置くこと。\n②さくら市内の店（本店・支店を問わず市内に店がある電気店）で買った新品であること（インターネットでの買い物や市外の店で買ったものは対象外です）。\n③今年4月1日から12月20日までの間に買い・置き、置いた後30日以内に市役所環境課へ領収書と保証書のコピーをつけて申請すること（ただし、予算の上限に達した場合は、12月20日より前でも受付を終了します）。', '[Thành phố Sakura - Thông báo Tiền trợ cấp đổi mới đồ điện gia dụng tiết kiệm điện]\nĐể giảm lượng điện tiêu thụ trong gia đình, thành phố hỗ trợ tiền trợ cấp cho những công dân đổi máy điều hòa hoặc tủ lạnh cũ sang sản phẩm mới có hiệu suất tiết kiệm điện cao.\nSản phẩm thuộc diện hỗ trợ và mức tiền trợ cấp:\n・Máy điều hòa (Nhãn tiết kiệm điện từ 4 sao trở lên): 20% giá mua chưa thuế (Tối đa 30.000 yên)\n・Tủ lạnh điện (Nhãn tiết kiệm điện từ 3 sao trở lên): 20% giá mua chưa thuế (Tối đa 40.000 yên)\nĐiều kiện đăng ký (cần đáp ứng tất cả các mục):\n① Có giấy chứng nhận cư trú tại thành phố Sakura và lắp đặt tại nhà riêng đang ở hiện tại.\n② Là hàng mới mua tại cửa hàng nằm trong thành phố Sakura (không phân biệt trụ sở chính hay chi nhánh, miễn là cửa hàng điện máy nằm trong thành phố; hàng mua qua mạng internet hoặc mua ở cửa hàng ngoài thành phố không được hỗ trợ).\n③ Mua và lắp đặt trong khoảng từ 01/04 đến 20/12 năm nay, nộp đơn kèm bản sao hóa đơn và phiếu bảo hành tại Phòng Môi trường Ủy ban thành phố trong vòng 30 ngày sau khi lắp đặt (tuy nhiên, nếu hết ngân sách sẽ kết thúc tiếp nhận trước cả ngày 20/12).', NULL, NULL, NULL, '[{"expression":"製品","reading":"せいひん","meaning_vi":"sản phẩm"},{"expression":"価格","reading":"かかく","meaning_vi":"giá cả"},{"expression":"条件","reading":"じょうけん","meaning_vi":"điều kiện"}]', 445, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-020', 'N3-R-INFO', 'N3', 'READING', 20, '【みどり市立博物館・ボランティアガイド募集のお知らせ】\n当館を訪れる小学生や観光客の方に、地域の歴史や古い道具について説明していただくボランティアガイドを募集しています。\n活動期間：来年の4月から1年間（月に2回以上、1回3時間程度活動できる方）\n活動時間帯：①午前の部（9:30〜12:30） ／ ②午後の部（13:30〜16:30）\n応募資格：\n・18歳以上の方（歴史の専門知識がなくても、人と話すのが好きな方ならどなたでも応募できます）。\n・活動を開始する前に、3月に行われる「基礎研修（全3回・毎週土曜日10:00〜12:00・参加費無料）」に3回すべて出席できる方に限ります。\nお礼と条件：\n・ボランティアのため給料はありませんが、活動1回につき交通費として同じ金額で1,000円をお渡しします。\n・午前の部と午後の部を同じ日に続けて活動される方には、博物館1階の食堂で使える昼食券（800円分）も差し上げます。\n申し込み方法：2月20日までに、応募の理由を書いた申込書を窓口へお持ちいただくか郵送してください。', '[Bảo tàng thành phố Midori - Thông báo tuyển Hướng dẫn viên tình nguyện]\nChúng tôi đang tuyển hướng dẫn viên tình nguyện thuyết minh về lịch sử địa phương và các nông cụ, đồ dùng cổ cho học sinh tiểu học và khách tham quan đến thăm bảo tàng.\nThời gian hoạt động: 1 năm kể từ tháng 4 năm sau (dành cho người có thể tham gia từ 2 lần/tháng trở lên, mỗi lần khoảng 3 tiếng)\nKhung giờ hoạt động: ① Ca sáng (9:30~12:30) / ② Ca chiều (13:30~16:30)\nĐiều kiện ứng tuyển:\n・Người từ 18 tuổi trở lên (dù không có kiến thức chuyên môn về lịch sử, chỉ cần thích trò chuyện với mọi người thì ai cũng có thể ứng tuyển).\n・Chỉ giới hạn cho những người có thể tham dự đầy đủ cả 3 buổi "Đào tạo cơ bản (tổng 3 buổi - Thứ Bảy hằng tuần trong tháng 3, từ 10:00~12:00 - miễn phí tham gia)" trước khi bắt đầu hoạt động.\nChế độ đãi ngộ:\n・Vì là tình nguyện nên không có lương, nhưng mỗi lần hoạt động sẽ được hỗ trợ đồng mức 1.000 yên tiền đi lại.\n・Những người tham gia liên tiếp cả Ca sáng và Ca chiều trong cùng một ngày sẽ được tặng thêm phiếu ăn trưa (trị giá 800 yên) dùng tại nhà ăn tầng 1 của bảo tàng.\nCách thức đăng ký: Nộp đơn đăng ký có ghi lý do ứng tuyển tại quầy hoặc gửi qua bưu điện trước ngày 20/02.', NULL, NULL, NULL, '[{"expression":"歴史","reading":"れきし","meaning_vi":"lịch sử"},{"expression":"知識","reading":"ちしき","meaning_vi":"kiến thức"},{"expression":"昼食","reading":"ちゅうしょく","meaning_vi":"bữa trưa"}]', 449, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-001', 'N3-L-TASK', 'N3', 'LISTENING', 1, NULL, NULL, '[{"speaker":"N","ja":"男の人は作品を見せる会の準備でこの後まず何をしますか。"},{"speaker":"M","ja":"明日の作品を見せる会ですが、作品を壁に掛ける前に、会場の机を動かしておきましょうか。入口が少しせまくなっていますし。"},{"speaker":"F","ja":"机は夕方、会場の係の人が動かしてくれるそれより、作品の説明を書いたカードに間違いが見つかったんです。"},{"speaker":"M","ja":"昨日印刷した分ですね。全部印刷し直すなら、先に紙を買ってきます。事務所には白い紙がほとんど残っていませんでした。"},{"speaker":"F","ja":"印刷は私が別の事務所に頼みます。あなたは、送る前に作家の名前を名簿とくらべてください。値段の間違いは私が直しました。"},{"speaker":"M","ja":"名前だけ確認して、違っている所に印を付ければいいんですね。確認が終わるまで、作品は箱に入れたままにします。"},{"speaker":"F","ja":"カードを直して印刷に出した後で、二人で作品を掛けましょう。入口の案内はもう係の人に渡してあります。"},{"speaker":"N","ja":"男の人は作品を見せる会の準備でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây để chuẩn bị triển lãm?\nNam: Về triển lãm ngày mai, trước khi treo tác phẩm lên tường, tôi chuyển bàn trong hội trường nhé? Lối vào hơi hẹp.\nNữ: Người phụ trách hội trường nói sẽ chuyển bàn chiều nay. Quan trọng hơn, tôi tìm thấy lỗi trên thẻ ghi giới thiệu tác phẩm.\nNam: Số in hôm qua nhỉ. Nếu in lại hết thì tôi đi mua giấy trước. Văn phòng gần hết giấy trắng rồi.\nNữ: Tôi sẽ nhờ văn phòng khác in. Trước khi gửi, anh đối chiếu tên tác giả với danh sách giúp tôi. Tôi đã sửa lỗi giá rồi.\nNam: Tôi hiểu. Chỉ kiểm tra tên và đánh dấu chỗ sai nhỉ. Kiểm tra xong trước đã, tôi cứ để tác phẩm trong hộp.\nNữ: Nhờ anh nhé. Sửa thẻ và gửi đi in xong thì hai người cùng treo tác phẩm. Tôi đã đưa bảng hướng dẫn lối vào cho người phụ trách.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây để chuẩn bị triển lãm?', NULL, '[{"expression":"作品","reading":"さくひん","meaning_vi":"tác phẩm"},{"expression":"名簿","reading":"めいぼ","meaning_vi":"danh sách tên"}]', 378, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-002', 'N3-L-TASK', 'N3', 'LISTENING', 2, NULL, NULL, '[{"speaker":"N","ja":"女の人は登山の出発前にこの後まず何をしますか。"},{"speaker":"F","ja":"週末の登山ですが、天気が変わりそうなので、山の上の小屋にとまれるか、電話して確認しようと思っています。"},{"speaker":"M","ja":"その前に参加者の人数を確かめてくれませんか。昨日、一人から足を痛めたという連絡があり、もう一人も迷っているようです。"},{"speaker":"F","ja":"二人とも今回は来ないと考えて、八人で予約してしまってもいいですか。小屋の空きが少ないと聞いたので、急いだほうが。"},{"speaker":"M","ja":"足を痛めた人は欠席が決まっていますが、もう一人は医者に相談してから返事をするその人だけに今、聞いてください。"},{"speaker":"F","ja":"では、その人に連絡してから人数を決めます。帰りのバスの時間も変えたほうがいいでしょうか。雨なら早く下りたいですよね。"},{"speaker":"M","ja":"バスは私が調べます。雨の予報を見て山へ行くか決めるのは今夜なので、小屋には人数を確認した後で、予約の条件だけ聞きましょう。"},{"speaker":"N","ja":"女の人は登山の出発前にこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây trước khi xuất phát leo núi?\nNữ: Về chuyến leo núi cuối tuần, thời tiết có vẻ thay đổi nên tôi định gọi hỏi có ngủ được ở nhà nghỉ trên núi không.\nNam: Trước đó chị xác nhận số người tham gia giúp tôi được không? Hôm qua một người báo đau chân, một người nữa có vẻ còn phân vân.\nNữ: Coi như cả hai không đi lần này và đặt cho tám người luôn được không? Tôi nghe nói nhà nghỉ còn ít chỗ nên nên nhanh lên.\nNam: Người đau chân đã xác định nghỉ, nhưng người kia nói hỏi bác sĩ rồi mới trả lời. Bây giờ chị chỉ hỏi người đó thôi.\nNữ: Vậy tôi liên lạc người ấy rồi chốt số người. Có nên đổi cả giờ xe buýt về không? Nếu mưa thì muốn xuống sớm nhỉ.\nNam: Tôi sẽ tra xe buýt. Tối nay mới xem dự báo rồi quyết định có lên núi không, nên xác nhận số người xong thì chỉ hỏi điều kiện đặt nhà nghỉ thôi.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây trước khi xuất phát leo núi?', NULL, '[{"expression":"登山","reading":"とざん","meaning_vi":"leo núi"},{"expression":"条件","reading":"じょうけん","meaning_vi":"điều kiện; điều khoản; điều kiện／tiền đề"}]', 384, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-003', 'N3-L-TASK', 'N3', 'LISTENING', 3, NULL, NULL, '[{"speaker":"N","ja":"男の人はパン屋でこの後まず何をしますか。"},{"speaker":"M","ja":"注文されたパンは全部やけました。箱につめて車に積もうと思いますが、三十こずつ二つの箱に分ければいいですよね。"},{"speaker":"F","ja":"数はそれで合っていますが、配達先が変わりました。最初に予定していた学校ではなく、駅のそばの集会所に届ける"},{"speaker":"M","ja":"では、運転する人に新しい住所を知らせます。その後で箱につめますが、袋は一こずつ分けたほうがよかったんでしたね。"},{"speaker":"F","ja":"住所は私がもう伝えました。袋に入れる前に、パンの種類を注文の紙とくらべてください。チーズ入りを頼んだのは半分だけなので。"},{"speaker":"M","ja":"三十こがチーズ入りで、残りは何も入っていないパンですね。表面が似ているから、切れ目の形を見ながら数を確かめます。"},{"speaker":"F","ja":"箱には私が届け先を書いておきます。数を確かめて袋に入れ終わるころに、車の人が取りに来るはずです。"},{"speaker":"N","ja":"男の人はパン屋でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây tại tiệm bánh?\nNam: Bánh được đặt đã nướng xong hết. Tôi định xếp vào hộp rồi đưa lên xe, chia hai hộp mỗi hộp ba mươi cái là được nhỉ?\nNữ: Số lượng đúng, nhưng địa chỉ giao đã đổi. Không phải trường như dự định ban đầu mà giao tới nhà sinh hoạt gần ga.\nNam: Vậy tôi báo địa chỉ mới cho người lái xe. Sau đó xếp hộp, nhưng phải cho từng chiếc vào túi riêng nhỉ?\nNữ: Tôi đã báo địa chỉ rồi. Trước khi cho vào túi, anh đối chiếu loại bánh với giấy đặt hàng. Chỉ một nửa được đặt loại có phô mai.\nNam: Ba mươi chiếc có phô mai, còn lại không nhân nhỉ. Bề ngoài giống nhau nên tôi sẽ nhìn hình vết rạch để đếm.\nNữ: Anh làm thế nhé. Tôi sẽ ghi nơi giao lên hộp. Khi anh kiểm đếm và cho vào túi xong thì chắc người lái xe tới lấy.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây tại tiệm bánh?', NULL, '[{"expression":"注文","reading":"ちゅうもん","meaning_vi":"đặt hàng; đơn đặt hàng"},{"expression":"配達","reading":"はいたつ","meaning_vi":"giao hàng"}]', 365, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-004', 'N3-L-TASK', 'N3', 'LISTENING', 4, NULL, NULL, '[{"speaker":"N","ja":"女の人は修理を頼むためにこの後まず何をしますか。"},{"speaker":"F","ja":"部屋のエアコンから水が落ちてきたので、修理の会社に直接電話したいんですが、大家さんの許可が必要でしょうか。"},{"speaker":"M","ja":"費用はこちらで払いますから、私が会社に連絡します。いつから水が出ているのか、くわしく教えていただけますか。"},{"speaker":"F","ja":"昨夜気づきました。床がぬれていたのでふきましたが、今朝また同じ場所に水がありました。今は電源を切っています。"},{"speaker":"M","ja":"切ったままにしておいてください。修理の人に様子を説明するため、まず水の跡とエアコン全体の写真を送ってもらえますか。"},{"speaker":"F","ja":"では、床をもう一度ふく前に撮って送ります。今日は午後から仕事ですが、修理の人が来るまで家にいたほうがいいですか。"},{"speaker":"M","ja":"訪問の日は会社と相談してから決めましょう。今すぐ待っていただく必要はありません。私は写真を受け取ったら、修理を依頼します。"},{"speaker":"N","ja":"女の人は修理を頼むためにこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để yêu cầu sửa chữa?\nNữ: Điều hòa phòng tôi chảy nước nên tôi muốn gọi thẳng công ty sửa chữa. Có cần xin phép chủ nhà không?\nNam: Chúng tôi trả chi phí nên tôi sẽ liên hệ công ty. Chị nói kỹ giúp tôi nước bắt đầu chảy từ khi nào nhé.\nNữ: Tôi nhận ra tối qua. Sàn ướt nên đã lau, nhưng sáng nay lại có nước chỗ đó. Giờ tôi đã tắt nguồn.\nNam: Chị cứ để tắt. Để mô tả cho thợ, trước tiên chị gửi ảnh vết nước và toàn bộ điều hòa giúp tôi được không?\nNữ: Vậy tôi chụp và gửi trước khi lau sàn lại. Chiều nay tôi đi làm, có nên ở nhà đến khi thợ tới không?\nNam: Ngày tới sẽ quyết định sau khi trao đổi với công ty. Chị không cần đợi ngay bây giờ. Nhận được ảnh, tôi sẽ yêu cầu sửa.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để yêu cầu sửa chữa?', NULL, '[{"expression":"修理","reading":"しゅうり","meaning_vi":"sửa chữa (máy móc hoặc đồ vật)"},{"expression":"電源","reading":"でんげん","meaning_vi":"nguồn điện; nguồn"}]', 382, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-005', 'N3-L-TASK', 'N3', 'LISTENING', 5, NULL, NULL, '[{"speaker":"N","ja":"男の人は学校の祭りでこの後まず何をしますか。"},{"speaker":"M","ja":"劇が始まるまで一時間ですね。いすを並べ終わったので、入口でお客さんを案内する係に入ろうと思っています。"},{"speaker":"F","ja":"入口は一年生が担当してくれることになりました。あなたには音楽を流してほしいんですが、その前に一つ頼めますか。"},{"speaker":"M","ja":"音の大きさを調整するんですか。昨日は後ろの席で聞こえにくかったので、もう少し大きくする必要がありますよね。"},{"speaker":"F","ja":"音は先生がさっき調整しました。舞台の右側に置いた箱が通り道をふさいでいるので、奥の部屋へうつしてほしいんです。"},{"speaker":"M","ja":"赤い布が掛かっている箱ですね。中に道具が入っているなら、先に出してから運んだほうがかるくなりそうですが。"},{"speaker":"F","ja":"中身は次の劇で使う物なので、そのまま運んでください。重ければ私も手伝います。箱をうつしたら、音楽の順番を一緒に確認しましょう。"},{"speaker":"N","ja":"男の人は学校の祭りでこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây tại lễ hội trường?\nNam: Còn một tiếng nữa kịch bắt đầu nhỉ. Xếp ghế xong rồi, tôi định vào phụ hướng dẫn khách ở cửa.\nNữ: Học sinh năm nhất đã nhận phụ trách cửa. Tôi muốn nhờ anh phát nhạc, nhưng trước đó nhờ một việc được không?\nNam: Chỉnh âm lượng à? Hôm qua ngồi phía sau khó nghe nên cần tăng thêm chút nhỉ.\nNữ: Thầy vừa chỉnh âm thanh rồi. Hộp ở bên phải sân khấu đang chắn lối đi nên tôi muốn anh chuyển vào phòng bên trong.\nNam: Hộp phủ vải đỏ nhỉ. Nếu trong có đạo cụ, lấy ra trước rồi khiêng chắc sẽ nhẹ hơn.\nNữ: Đồ bên trong dùng cho vở sau nên hãy chuyển nguyên hộp. Nặng thì tôi phụ. Chuyển xong mình cùng kiểm tra thứ tự nhạc.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây tại lễ hội trường?', NULL, '[{"expression":"舞台","reading":"ぶたい","meaning_vi":"sân khấu"},{"expression":"担当","reading":"たんとう","meaning_vi":"người phụ trách; phụ trách; đảm nhiệm"}]', 372, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-006', 'N3-L-TASK', 'N3', 'LISTENING', 6, NULL, NULL, '[{"speaker":"N","ja":"女の人はインタビューの準備でこの後まず何をしますか。"},{"speaker":"F","ja":"町の新聞にのせる店のインタビューですが、質問を十こ考えました。これを印刷してから、カメラを借りに行ってもいいですか。"},{"speaker":"M","ja":"店のご主人から連絡があって、話せる時間が三十分から十五分になりました。質問はそのままでは全部聞けないでしょう。"},{"speaker":"F","ja":"では、料理の値段や営業時間は調べればわかるので外します。店を始めた理由については、くわしく聞きたいと思っています。"},{"speaker":"M","ja":"その話は大事ですね。まず質問を四つにしぼって私に見せてください。写真は店の人が送ってくれるので、カメラは要りません。"},{"speaker":"F","ja":"四つなら時間に間に合い残した質問の順番も、答えやすいものからになるように考え直してみます。"},{"speaker":"M","ja":"質問を確認したら、二人分印刷しましょう。お店への道は私が調べておくので、そちらに時間を使わなくていいですよ。"},{"speaker":"N","ja":"女の人はインタビューの準備でこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để chuẩn bị phỏng vấn?\nNữ: Về phỏng vấn cửa hàng đăng báo thị trấn, tôi nghĩ mười câu hỏi rồi. In xong tôi đi mượn máy ảnh được không?\nNam: Chủ quán báo thời gian nói chuyện giảm từ ba mươi xuống mười lăm phút. Giữ nguyên thì chắc không hỏi hết.\nNữ: Vậy tôi bỏ giá món ăn và giờ mở cửa vì tự tra được. Tôi muốn hỏi kỹ lý do mở quán.\nNam: Chuyện đó quan trọng. Trước hết chị rút còn bốn câu rồi cho tôi xem. Người của quán sẽ gửi ảnh nên không cần máy ảnh.\nNữ: Bốn câu thì có vẻ kịp. Tôi sẽ nghĩ lại cả thứ tự, bắt đầu từ những câu dễ trả lời.\nNam: Nhờ chị nhé. Kiểm tra câu hỏi xong thì in cho hai người. Tôi tra đường tới quán, chị không cần mất thời gian việc đó.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để chuẩn bị phỏng vấn?', NULL, '[{"expression":"インタビュー","reading":"いんたびゅー","meaning_vi":"cuộc phỏng vấn; phỏng vấn"},{"expression":"質問","reading":"しつもん","meaning_vi":"câu hỏi; hỏi (thầy; người khác)"}]', 379, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-007', 'N3-L-TASK', 'N3', 'LISTENING', 7, NULL, NULL, '[{"speaker":"N","ja":"男の人は予約した店へ行く前にこの後まず何をしますか。"},{"speaker":"M","ja":"今夜の食事会ですが、一人増えて七人になりました。店に電話して席を一つ増やしてもらえば、料理はそのままでいいですよね。"},{"speaker":"F","ja":"増えたのは山田さんですよね。魚が食べられないと聞いたことがあるので、料理の内容も変えなければならないかもしれません。"},{"speaker":"M","ja":"では、店に魚を全部肉にかえてもらえるか聞きます。昨日もらったメニューには、魚の料理が二つ入っていましたから。"},{"speaker":"F","ja":"全員の分をかえる必要はないと思います。ただ、食べられないのが魚全部なのか、ある種類なのか、本人に確かめてください。"},{"speaker":"M","ja":"先に山田さんへ電話します。店への人数の変更は、食べられない物がわかってから一緒に伝えればいいですね。"},{"speaker":"F","ja":"私は集合場所の地図を皆に送ります。返事がすぐ来なければ、人数だけ先に店へ知らせておいてください。"},{"speaker":"N","ja":"男の人は予約した店へ行く前にこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây trước khi tới quán đã đặt?\nNam: Bữa liên hoan tối nay thêm một người thành bảy. Tôi gọi quán thêm một chỗ, món ăn giữ nguyên được nhỉ?\nNữ: Người thêm là anh Yamada nhỉ. Tôi từng nghe anh ấy không ăn được cá nên có thể phải đổi cả món.\nNam: Vậy tôi hỏi quán có đổi hết cá thành thịt được không. Thực đơn nhận hôm qua có hai món cá.\nNữ: Tôi nghĩ không cần đổi phần của mọi người. Nhưng anh hãy hỏi trực tiếp xem anh ấy không ăn được mọi loại cá hay chỉ loại cụ thể.\nNam: Tôi gọi anh Yamada trước. Biết món không ăn được rồi báo cùng việc đổi số người cho quán là được nhỉ.\nNữ: Đúng vậy. Tôi gửi bản đồ điểm tập trung cho mọi người. Nếu chưa nhận trả lời ngay thì anh cứ báo số người cho quán trước.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây trước khi tới quán đã đặt?', NULL, '[{"expression":"変更","reading":"へんこう","meaning_vi":"thay đổi"},{"expression":"料理","reading":"りょうり","meaning_vi":"món ăn; việc nấu ăn"}]', 377, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-008', 'N3-L-TASK', 'N3', 'LISTENING', 8, NULL, NULL, '[{"speaker":"N","ja":"女の人は録音を始める前にこの後まず何をしますか。"},{"speaker":"F","ja":"本を読む声の録音ですが、文章の読み方は全部調べました。静かなうちに始めたいので、窓を閉めて機械の電源を入れますね。"},{"speaker":"M","ja":"窓はもう閉めてあります。ただ、文章の最後のページに一文追加されたので、古い文章のまま録音しないようにしてください。"},{"speaker":"F","ja":"では、新しい文章を印刷します。全部で八ページありましたが、最初から印刷し直したほうが間違えなくていいでしょうか。"},{"speaker":"M","ja":"最後の一枚だけで大丈夫です。私が印刷して持ってきますから、その間に、携帯電話の音が出ないようにせっていしてください。"},{"speaker":"F","ja":"電話はかばんの中ですが、前の録音でも途中で鳴ってしまいましたね。先に音を切って、画面もふせておきます。"},{"speaker":"M","ja":"機械の準備は私がします。文章がそろったら、追加の文を一度声に出して練習してから、録音を始めましょう。"},{"speaker":"N","ja":"女の人は録音を始める前にこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây trước khi bắt đầu thu âm?\nNữ: Về thu âm đọc truyện, tôi đã tra hết cách đọc trong bản thảo. Tranh thủ yên tĩnh, tôi đóng cửa sổ rồi bật máy nhé.\nNam: Cửa sổ đóng rồi. Nhưng trang cuối được thêm một câu nên đừng thu theo bản cũ.\nNữ: Vậy tôi in bản mới. Tất cả tám trang, có nên in lại từ đầu để đỡ nhầm không?\nNam: Chỉ tờ cuối là được. Tôi in và mang lại, trong lúc đó chị chỉnh điện thoại để không phát tiếng nhé.\nNữ: Điện thoại trong cặp nhưng lần thu trước cũng reo giữa chừng nhỉ. Tôi tắt âm trước rồi úp màn hình xuống.\nNam: Nhờ chị. Tôi chuẩn bị máy. Có đủ bản thảo rồi mình đọc luyện câu thêm một lần thành tiếng trước khi thu.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây trước khi bắt đầu thu âm?', NULL, '[{"expression":"録音","reading":"ろくおん","meaning_vi":"ghi âm"},{"expression":"文章","reading":"ぶんしょう","meaning_vi":"bài viết; bài văn; đoạn văn"}]', 377, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-009', 'N3-L-TASK', 'N3', 'LISTENING', 9, NULL, NULL, '[{"speaker":"N","ja":"男の人は公民館の教室でこの後まず何をしますか。"},{"speaker":"M","ja":"料理教室の材料が届きました。野菜を洗ってから、参加者の人数に合わせて四つの机に分けて置いておきましょうか。"},{"speaker":"F","ja":"今日は初めての人が多いので、材料を切る前に説明します。野菜は係の人が洗いますから、あなたには道具の準備を"},{"speaker":"M","ja":"包丁とまな板ですね。棚の下に四組入っていたので、それぞれの机に一組ずつ出せば足りると思います。"},{"speaker":"F","ja":"参加者が増えて机を一つ追加したんです。まず隣の部屋で、もう一組借りてきてください。今ある道具は私が並べておきます。"},{"speaker":"M","ja":"五つの机を使うんですね。隣の部屋の先生には、料理教室で使うと言えばわかりますか。返す時間も聞いておきましょうか。"},{"speaker":"F","ja":"ええ、終わるのは十二時ですが、洗ってかわかしてから返すので、少し遅くなります。材料を分けるのは道具がそろってからです。"},{"speaker":"N","ja":"男の人は公民館の教室でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây ở lớp tại nhà văn hóa?\nNam: Nguyên liệu lớp nấu ăn tới rồi. Tôi rửa rau rồi chia ra bốn bàn theo số người tham gia nhé?\nNữ: Hôm nay nhiều người mới nên sẽ giải thích trước khi cắt nguyên liệu. Người phụ trách rửa rau, anh chuẩn bị dụng cụ giúp tôi.\nNam: Dao và thớt nhỉ. Trong ngăn dưới tủ có bốn bộ, mỗi bàn một bộ chắc đủ.\nNữ: Thêm người nên đã kê thêm một bàn. Trước hết anh mượn thêm một bộ ở phòng bên cạnh. Tôi xếp dụng cụ hiện có.\nNam: Dùng năm bàn nhỉ. Tôi nói với thầy phòng bên là dùng cho lớp nấu ăn thì thầy hiểu chứ? Tôi hỏi cả giờ trả nhé?\nNữ: Vâng, nhờ anh. Kết thúc lúc mười hai giờ nhưng phải rửa và để khô rồi mới trả nên sẽ muộn hơn chút. Đủ dụng cụ rồi mới chia nguyên liệu.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây ở lớp tại nhà văn hóa?', NULL, '[{"expression":"材料","reading":"ざいりょう","meaning_vi":"nguyên liệu (nấu ăn); vật liệu"},{"expression":"道具","reading":"どうぐ","meaning_vi":"dụng cụ; đạo cụ"}]', 370, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-010', 'N3-L-TASK', 'N3', 'LISTENING', 10, NULL, NULL, '[{"speaker":"N","ja":"女の人は水族館への遠足についてこの後まず何をしますか。"},{"speaker":"F","ja":"遠足の案内を親に送る前に確認を集合は学校の門で八時、帰りは四時という予定で書きました。"},{"speaker":"M","ja":"集合時間は八時のままですが、場所は体育館に変わりました。雨が降っても子供たちがぬれずに待てるようにするためです。"},{"speaker":"F","ja":"では、場所を直します。帰りの時間はバス会社に聞いたほうがいいですか。道路が混むと遅くなる可能性もありますよね。"},{"speaker":"M","ja":"帰りは私が確認します。あなたはまず案内の集合場所を直して、それを学年の先生に見せてください。まだ親には送らないで。"},{"speaker":"F","ja":"修正した案内を先生に確認してもらうんですね。お弁当を持ってくるという注意も、目立つように大きい字にしておきます。"},{"speaker":"M","ja":"それは水族館の料金については学校でまとめて払うので、当日お金を持たせる必要はないと、今の説明のままにしてください。"},{"speaker":"N","ja":"女の人は水族館への遠足についてこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây về chuyến tham quan thủy cung?\nNữ: Trước khi gửi hướng dẫn chuyến tham quan cho phụ huynh, nhờ thầy kiểm tra. Tôi ghi tập trung tám giờ ở cổng trường, về lúc bốn giờ.\nNam: Giờ vẫn tám giờ nhưng địa điểm đổi sang nhà thể chất, để trời mưa trẻ vẫn đợi mà không ướt.\nNữ: Vậy tôi sửa địa điểm. Có nên hỏi công ty xe buýt về giờ về không? Tắc đường cũng có thể muộn nhỉ.\nNam: Tôi kiểm tra giờ về. Trước hết cô sửa địa điểm tập trung rồi đưa các giáo viên khối xem. Chưa gửi phụ huynh nhé.\nNữ: Tôi nhờ giáo viên kiểm tra bản đã sửa nhỉ. Tôi cũng phóng to lưu ý mang cơm hộp cho dễ thấy.\nNam: Thế tốt quá. Phí thủy cung trường trả gộp nên phần giải thích không cần cho trẻ mang tiền hôm đó cứ giữ như hiện tại.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây về chuyến tham quan thủy cung?', NULL, '[{"expression":"親","reading":"おや","meaning_vi":"cha mẹ; bố mẹ"},{"expression":"修正","reading":"しゅうせい","meaning_vi":"chỉnh sửa; chỉnh lý; sửa đổi"}]', 378, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-011', 'N3-L-TASK', 'N3', 'LISTENING', 11, NULL, NULL, '[{"speaker":"N","ja":"男の人は忘れ物を受け取るためにこの後まず何をしますか。"},{"speaker":"M","ja":"昨日電車に置き忘れたかばんが見つかったと聞きました。夕方、駅へ取りに行けばいいですか。中に会社のカードが入っているので急いでいます。"},{"speaker":"F","ja":"かばんは駅ではなく、忘れ物を扱う事務所に届いています。今日は六時までですが、お名前の確認ができる物を持ってきてください。"},{"speaker":"M","ja":"会社のカード以外は家にあるので、一度帰らないといけませんね。弟に代わりに受け取ってもらうこともできますか。"},{"speaker":"F","ja":"代理の方には別の書類が必要です。ご本人なら運転免許証で大丈夫ですから、そちらを用意していただくほうが簡単だと思います。"},{"speaker":"M","ja":"免許証は家の机に置いてあります。では、会社から直接そちらへ行かず、家で取ってから伺います。事務所の場所はわかります。"},{"speaker":"F","ja":"受付ではこの番号を伝えてください。番号は携帯電話に送りますので、紙に書き写さなくても画面を見せれば結構です。"},{"speaker":"N","ja":"男の人は忘れ物を受け取るためにこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây để nhận lại đồ bỏ quên?\nNam: Tôi nghe đã tìm thấy cặp bỏ quên trên tàu hôm qua. Chiều tôi tới ga lấy được không? Trong có thẻ nhân viên nên tôi đang vội.\nNữ: Cặp ở văn phòng xử lý đồ thất lạc, không phải ở ga. Hôm nay mở tới sáu giờ, anh mang giấy xác nhận tên nhé.\nNam: Ngoài thẻ nhân viên thì giấy tờ ở nhà, tôi phải về một lần nhỉ. Có thể nhờ em trai nhận thay không?\nNữ: Người nhận thay cần giấy tờ khác. Chính anh thì bằng lái được nên tôi nghĩ chuẩn bị bằng lái sẽ đơn giản hơn.\nNam: Bằng lái để trên bàn ở nhà. Vậy tôi không đi thẳng từ công ty tới đó mà về lấy rồi đến. Tôi biết địa chỉ văn phòng.\nNữ: Vâng. Anh cung cấp mã này tại quầy. Tôi sẽ gửi vào điện thoại, không cần chép ra giấy, chỉ đưa màn hình là được.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây để nhận lại đồ bỏ quên?', NULL, '[{"expression":"会社","reading":"かいしゃ","meaning_vi":"công ty"},{"expression":"代理","reading":"だいり","meaning_vi":"đại diện; thay mặt"}]', 404, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-012', 'N3-L-TASK', 'N3', 'LISTENING', 12, NULL, NULL, '[{"speaker":"N","ja":"女の人は音楽会の受付でこの後まず何をしますか。"},{"speaker":"F","ja":"受付の名簿を印刷しました。予約した方には、名前を確認してからこの青い券を渡せばいいんですね。現金はここで受け取りますか。"},{"speaker":"M","ja":"予約の方は全員支払い済みなので、お金は受け取りません。ただ、名簿の順番が申込順になっていて、名前を探しにくいですね。"},{"speaker":"F","ja":"では、五十音順に並べ直して印刷します。券の枚数も足りないようですが、先に隣の事務室でもらってきましょうか。"},{"speaker":"M","ja":"券は私が取りに行きます。あなたは名簿を並べ直す前に、今朝届いた三人分の予約を追加してください。メールを転送しておきました。"},{"speaker":"F","ja":"新しい三人を加えてから、全員を名前の順にするんですね。二部印刷して、一部は入口の係に渡してもよろしいですか。"},{"speaker":"M","ja":"はい、入口の係にも支払いは済んでいると私から伝えます。変更前の名簿は混ざらないよう、最後に片づけておきましょう。"},{"speaker":"N","ja":"女の人は音楽会の受付でこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây ở quầy đón khách buổi hòa nhạc?\nNữ: Tôi in danh sách quầy đón khách rồi. Khách đặt trước thì xác nhận tên rồi đưa vé xanh này nhỉ. Có nhận tiền mặt ở đây không?\nNam: Khách đặt trước đều trả tiền rồi nên không thu. Nhưng danh sách theo thứ tự đăng ký, khó tìm tên.\nNữ: Vậy tôi sắp lại theo thứ tự âm rồi in. Vé có vẻ cũng thiếu, tôi qua văn phòng bên cạnh lấy trước nhé?\nNam: Tôi đi lấy vé. Trước khi sắp danh sách, cô thêm ba lượt đặt sáng nay nhé. Tôi đã chuyển tiếp thư cho cô.\nNữ: Thêm ba người mới rồi sắp toàn bộ theo tên nhỉ. Tôi in hai bản, đưa một bản cho người ở lối vào được không?\nNam: Vâng, làm thế nhé. Tôi cũng báo người ở lối vào là đã thanh toán rồi. Danh sách cũ cuối cùng hãy dọn đi để không lẫn.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây ở quầy đón khách buổi hòa nhạc?', NULL, '[{"expression":"名簿","reading":"めいぼ","meaning_vi":"danh sách tên"},{"expression":"追加","reading":"ついか","meaning_vi":"bổ sung; thêm; thêm vào"}]', 388, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-013', 'N3-L-TASK', 'N3', 'LISTENING', 13, NULL, NULL, '[{"speaker":"N","ja":"男の人は畑の作業でこの後まず何をしますか。"},{"speaker":"M","ja":"午後から雨だそうなので、午前中に畑の野菜を取ってしまいましょうか。店へ出す箱も車から下ろしてあります。"},{"speaker":"F","ja":"トマトはまだ赤くなっていない物が多いから、今日は取りません。先に、風で倒れかけている豆の棒を直しておきたいですね。"},{"speaker":"M","ja":"では、ひもを持ってきて棒を結び直します。そうこにあった細いひもで足りますか。太いのは昨日使い切ったと思いますが。"},{"speaker":"F","ja":"太いひもは今朝買っておきました。ただ、土がかわいて硬いので、棒を押し込む前に、その周りだけ水をかけてください。"},{"speaker":"M","ja":"畑全体ではなく、倒れそうな棒の根元だけですね。水を運ぶ間に、使うひもの長さをはかって切っておいてもらえますか。"},{"speaker":"F","ja":"棒を直した後で、店に持っていく野菜の種類を決めましょう。箱は雨でぬれないように、私が車へ戻しておきます。"},{"speaker":"N","ja":"男の人は畑の作業でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây khi làm việc ở ruộng?\nNam: Nghe nói chiều mưa nên mình hái rau trong buổi sáng nhé? Tôi đã dỡ thùng mang hàng ra tiệm xuống xe rồi.\nNữ: Còn nhiều cà chua chưa đỏ nên hôm nay chưa hái. Tôi muốn sửa các cọc đậu bị gió làm nghiêng trước.\nNam: Vậy tôi lấy dây buộc lại cọc. Dây nhỏ trong kho có đủ không? Tôi nghĩ hôm qua dùng hết dây to rồi.\nNữ: Sáng nay tôi mua dây to rồi. Nhưng đất khô cứng, trước khi ấn cọc xuống anh tưới nước chỉ quanh cọc nhé.\nNam: Không tưới cả ruộng, chỉ gốc cọc sắp đổ nhỉ. Trong lúc tôi mang nước, chị đo cắt dây giúp được không?\nNữ: Tất nhiên. Sửa cọc xong mình quyết định loại rau mang ra tiệm. Tôi cất thùng lại lên xe để khỏi ướt mưa.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây khi làm việc ở ruộng?', NULL, '[{"expression":"畑","reading":"はたけ","meaning_vi":"ruộng cạn; vườn; cánh đồng"},{"expression":"豆","reading":"まめ","meaning_vi":"hạt đậu; đậu; đỗ"}]', 368, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-014', 'N3-L-TASK', 'N3', 'LISTENING', 14, NULL, NULL, '[{"speaker":"N","ja":"女の人はアルバイトの変更についてこの後まず何をしますか。"},{"speaker":"F","ja":"来週の金曜日に大学の試験が入ったので、夕方のアルバイトを休ませていただけませんか。土曜日なら一日働けます。"},{"speaker":"M","ja":"金曜日はお客さんが多いので、代わりの人が見つかれば変更できます。土曜日は人数が足りているため、出なくても大丈夫ですよ。"},{"speaker":"F","ja":"では、いつも金曜日に休んでいる田中さんに頼んでみます。先に勤務表の私の名前を消して、田中さんと書いてもいいですか。"},{"speaker":"M","ja":"まだ書きかえないでください。田中さんは来週旅行だ水曜日が休みの山田さんなら、金曜日に入れるかもしれません。"},{"speaker":"F","ja":"山田さんに予定を聞いて、代わってもらえるか相談するんですね。返事をもらったら、そのまま勤務表を直しておきますか。"},{"speaker":"M","ja":"変更は私がしますので、結果だけ知らせてください。もし難しければ別の方法を考えます。試験の時間がわかる紙も、後で見せてくださいね。"},{"speaker":"N","ja":"女の人はアルバイトの変更についてこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây về việc đổi ca làm thêm?\nNữ: Thứ sáu tuần sau trường xếp lịch thi, cho em nghỉ ca chiều được không? Nếu thứ bảy thì em làm cả ngày được.\nNam: Thứ sáu đông khách nên tìm được người thay thì đổi được. Thứ bảy đủ người, em không cần vào.\nNữ: Vậy em thử nhờ chị Tanaka thường nghỉ thứ sáu. Em xóa tên mình trên lịch rồi ghi chị Tanaka trước được không?\nNam: Chưa sửa nhé. Nghe nói tuần sau Tanaka đi du lịch. Yamada nghỉ thứ tư thì có thể vào thứ sáu.\nNữ: Em hỏi lịch chị Yamada và bàn chuyện đổi ca nhỉ. Nhận trả lời xong em sửa lịch luôn ạ?\nNam: Tôi sẽ sửa, em chỉ báo kết quả. Nếu khó thì mình nghĩ cách khác. Sau đó cho tôi xem giấy ghi giờ thi nữa nhé.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây về việc đổi ca làm thêm?', NULL, '[{"expression":"勤務","reading":"きんむ","meaning_vi":"làm việc; công tác"},{"expression":"試験","reading":"しけん","meaning_vi":"kỳ thi; thi; bài kiểm tra"}]', 398, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-015', 'N3-L-TASK', 'N3', 'LISTENING', 15, NULL, NULL, '[{"speaker":"N","ja":"男の人は地域の訓練でこの後まず何をしますか。"},{"speaker":"M","ja":"訓練に来た人の数を数えました。まだ集まっていない家が三軒あるので、今から一軒ずつ電話して確認しようと思います。"},{"speaker":"F","ja":"そのうち二軒は今日は参加しないと連絡がありました。残りの一軒には私が電話しますから、あなたは受付の片づけを"},{"speaker":"M","ja":"机をそうこへ戻して、参加者の名簿を事務所へ持っていきます。ペンや紙も一緒に箱へ入れておけばいいですね。"},{"speaker":"F","ja":"机はこの後、飲み物を配るのに使います。動かさずに、机の上の名簿だけ先に私のかばんへ入れてください。名前が見えないようにしたいので。"},{"speaker":"M","ja":"名簿はこの青いかばんに入れるんですね。ペンなどは箱にまとめますが、その作業は名簿をしまった後にします。"},{"speaker":"F","ja":"飲み物は別の係が運んできます。受付の看板を外すのは、まだ来ていない人の確認が終わってからにしましょう。"},{"speaker":"N","ja":"男の人は地域の訓練でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây trong buổi diễn tập phòng chống thiên tai?\nNam: Tôi đếm người tới diễn tập rồi. Còn ba hộ chưa tập trung, tôi định gọi từng hộ xác nhận.\nNữ: Trong đó hai hộ đã báo hôm nay không tham gia. Tôi gọi hộ còn lại, anh dọn quầy tiếp nhận giúp nhé.\nNam: Vâng. Tôi trả bàn vào kho rồi mang danh sách về văn phòng. Bút giấy cũng cho chung vào hộp nhỉ.\nNữ: Sau đây còn dùng bàn để phát đồ uống. Đừng di chuyển, trước hết chỉ cho danh sách trên bàn vào cặp tôi. Tôi muốn không để lộ tên.\nNam: Cho danh sách vào cặp xanh này nhỉ. Tôi gom bút vào hộp nhưng sẽ làm sau khi cất danh sách.\nNữ: Cảm ơn anh. Người phụ trách khác mang đồ uống tới. Biển tiếp nhận thì chờ xác nhận người chưa đến xong rồi mới tháo nhé.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây trong buổi diễn tập phòng chống thiên tai?', NULL, '[{"expression":"訓練","reading":"くんれん","meaning_vi":"huấn luyện; tập huấn"},{"expression":"名簿","reading":"めいぼ","meaning_vi":"danh sách tên"}]', 370, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-016', 'N3-L-TASK', 'N3', 'LISTENING', 16, NULL, NULL, '[{"speaker":"N","ja":"女の人は借りた会議室を使うためにこの後まず何をしますか。"},{"speaker":"F","ja":"予約した三階の会議室ですが、前の団体がまだ使っています。開始まで十分しかないので、先に資料を廊下に並べてもいいでしょうか。"},{"speaker":"M","ja":"廊下に物を置くのは禁止されています。前の団体には私から声をかけますから、資料はかばんに入れたままにしておいてください。"},{"speaker":"F","ja":"では、参加者に少し遅れると連絡します。全員の電話番号は持っていますが、もう建物に着いている人もいると思います。"},{"speaker":"M","ja":"まだ遅れるとは決まっていません。二階の空いている部屋が使えるかもしれないので、まず受付で変更できるか聞いてきてもらえますか。"},{"speaker":"F","ja":"空いている部屋へ勝手に入らず、受付に確認するんですね。広さが違う場合は、いすが十二こ入るかも聞いておきます。"},{"speaker":"M","ja":"部屋が決まったら、私が参加者を案内します。資料を配るのは全員が座ってからで十分ですので、今は持っていてください。"},{"speaker":"N","ja":"女の人は借りた会議室を使うためにこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để sử dụng phòng họp đã thuê?\nNữ: Phòng họp tầng ba đã đặt, nhóm trước vẫn dùng. Chỉ còn mười phút nữa bắt đầu, tôi xếp tài liệu ngoài hành lang trước được không?\nNam: Cấm để đồ ngoài hành lang. Tôi sẽ nói với nhóm trước, chị cứ để tài liệu trong cặp.\nNữ: Vậy tôi báo người tham gia là sẽ muộn chút. Tôi có số điện thoại tất cả, nhưng chắc có người tới tòa nhà rồi.\nNam: Chưa chắc sẽ muộn. Có thể dùng phòng trống tầng hai, trước tiên chị hỏi quầy tiếp nhận đổi được không nhé.\nNữ: Không tự vào phòng trống mà phải hỏi quầy nhỉ. Nếu khác diện tích, tôi hỏi cả có xếp được mười hai ghế không.\nNam: Nhờ chị. Chốt phòng rồi tôi hướng dẫn mọi người. Tài liệu đợi tất cả ngồi rồi phát vẫn kịp, giờ chị cứ giữ.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để sử dụng phòng họp đã thuê?', NULL, '[{"expression":"団体","reading":"だんたい","meaning_vi":"đoàn thể; nhóm"},{"expression":"禁止","reading":"きんし","meaning_vi":"cấm"}]', 403, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-017', 'N3-L-TASK', 'N3', 'LISTENING', 17, NULL, NULL, '[{"speaker":"N","ja":"男の人は水泳大会の係としてこの後まず何をしますか。"},{"speaker":"M","ja":"選手に配る番号の紙を用意しました。名前と番号を読み上げて渡す予定ですが、先に全員をプールの入口へ集めていいですか。"},{"speaker":"F","ja":"入口は子供の選手が着かえに行くので混みます。大人の選手には廊下の奥で待ってもらいましょう。案内は私がします。"},{"speaker":"M","ja":"では、私は番号を順番に並べます。欠席する選手の分は抜いておいたほうが、渡すときに間違えにくいですよね。"},{"speaker":"F","ja":"そうですね。ただ、番号の紙に古い名簿の名前が残っているようです。まず今日の名簿とくらべて、出場する人の名前を確かめてください。"},{"speaker":"M","ja":"今日の名簿は青い表紙のほうですね。名前を確認してから、欠席の分を別の袋に入れます。番号自体は変えないんですよね。"},{"speaker":"F","ja":"ええ、番号はそのままです。並べ終わったら私に知らせてください。紙を渡す前に、選手には競技の順番を説明する時間を取ってあります。"},{"speaker":"N","ja":"男の人は水泳大会の係としてこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây với vai trò phụ trách giải bơi?\nNam: Tôi chuẩn bị giấy số phát cho vận động viên rồi. Định đọc tên và số để phát, tôi tập trung mọi người trước lối vào bể bơi nhé?\nNữ: Lối vào đông vì trẻ đi thay đồ. Vận động viên người lớn chờ cuối hành lang nhé. Tôi sẽ hướng dẫn.\nNam: Vậy tôi xếp số theo thứ tự. Rút phần người vắng ra trước thì lúc phát đỡ nhầm nhỉ.\nNữ: Đúng. Nhưng có vẻ trên giấy số còn tên theo danh sách cũ. Trước hết anh đối chiếu danh sách hôm nay, xác nhận tên người thi.\nNam: Danh sách hôm nay bìa xanh nhỉ. Kiểm tra tên xong tôi cho phần người vắng vào túi riêng. Bản thân số thì không đổi nhỉ.\nNữ: Vâng, giữ nguyên số. Xếp xong báo tôi. Trước khi phát giấy, đã dành thời gian giải thích thứ tự thi cho vận động viên.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây với vai trò phụ trách giải bơi?', NULL, '[{"expression":"選手","reading":"せんしゅ","meaning_vi":"vận động viên"},{"expression":"競技","reading":"きょうぎ","meaning_vi":"thi đấu; tranh tài"}]', 394, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-018', 'N3-L-TASK', 'N3', 'LISTENING', 18, NULL, NULL, '[{"speaker":"N","ja":"女の人は研究発表の準備でこの後まず何をしますか。"},{"speaker":"F","ja":"発表で使うグラフを直しました。数字を大きくしたので、後ろの席からも見えると思います。これを印刷して配ってもいいですか。"},{"speaker":"M","ja":"印刷する前に、調査に答えた人数を確認しましょう。説明には百人と書いてありますが、グラフは九十八人分しかないようです。"},{"speaker":"F","ja":"二人は答えが空白だったので、計算から外しました。では、グラフに合わせて説明の人数を九十八人に変えておけばいいですね。"},{"speaker":"M","ja":"百人に聞いたこと自体は正しいので、そこは変えないでください。まず、二人の回答を使わなかった理由を説明の下に一行加えましょう。"},{"speaker":"F","ja":"人数だけ変えると、最初から九十八人に聞いたように見えてしまいますね。使った回答の数と、空白だった理由を書き足します。"},{"speaker":"M","ja":"発表の時間は私がはかります。修正が終わったら一度通して読んで、長すぎなければ、そのものを配る資料にしましょう。"},{"speaker":"N","ja":"女の人は研究発表の準備でこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để chuẩn bị thuyết trình nghiên cứu?\nNữ: Tôi sửa biểu đồ dùng khi trình bày rồi. Số lớn hơn nên chắc người phía sau nhìn được. Tôi in phát được không?\nNam: Trước khi in, kiểm tra số người trả lời khảo sát nhé. Giải thích ghi một trăm người nhưng biểu đồ hình như chỉ có chín mươi tám.\nNữ: Hai người để trống nên tôi loại khỏi tính toán. Vậy đổi số trong giải thích thành chín mươi tám cho khớp biểu đồ nhỉ.\nNam: Đã hỏi một trăm người là đúng nên đừng đổi chỗ đó. Trước hết thêm một dòng dưới giải thích nêu lý do không dùng hai câu trả lời.\nNữ: Chỉ đổi số thì trông như ngay từ đầu hỏi chín mươi tám người. Tôi sẽ ghi thêm số câu trả lời được dùng và lý do để trống.\nNam: Chị làm thế nhé. Tôi đo thời gian trình bày. Sửa xong đọc một lượt, không quá dài thì dùng bản đó làm tài liệu phát.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để chuẩn bị thuyết trình nghiên cứu?', NULL, '[{"expression":"調査","reading":"ちょうさ","meaning_vi":"điều tra; khảo sát"},{"expression":"回答","reading":"かいとう","meaning_vi":"câu trả lời"}]', 398, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-019', 'N3-L-TASK', 'N3', 'LISTENING', 19, NULL, NULL, '[{"speaker":"N","ja":"男の人は落ち葉を集める作業でこの後まず何をしますか。"},{"speaker":"M","ja":"校庭の落ち葉を全部集めました。燃えるごみの袋に入れて、門の横のごみ置き場へ運ぼうと思っています。袋は十枚あります。"},{"speaker":"F","ja":"その落ち葉は学校の畑で使うことになったので、ごみに出さないでください。ただ、枝や空き缶が少し混ざっているようですね。"},{"speaker":"M","ja":"では、枝と缶を取り除いてから、畑へ運びます。袋に入れるより、大きな箱にまとめたほうが運びやすいでしょうか。"},{"speaker":"F","ja":"箱は底がぬれているので使えません。袋に入れる前に、まず落ち葉に混ざった缶をひろってください。枝は私が集めます。"},{"speaker":"M","ja":"缶だけ分けるんですね。割れた物があると危ないので、手袋を使います。袋に入れた後は、私一人で畑へ運んでも大丈夫ですか。"},{"speaker":"F","ja":"袋が重くなると思うので、台車を借りてきます。それまで袋は校庭の隅に置いておいてください。畑の先生にも私から連絡しておきます。"},{"speaker":"N","ja":"男の人は落ち葉を集める作業でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây khi thu gom lá rụng?\nNam: Tôi gom hết lá rụng sân trường rồi. Tôi định cho vào túi rác cháy được rồi mang đến chỗ rác cạnh cổng. Có mười túi.\nNữ: Lá sẽ dùng ở ruộng trường nên đừng bỏ rác. Nhưng hình như có lẫn cành cây và lon rỗng.\nNam: Vậy tôi loại cành và lon rồi mang ra ruộng. Gom vào hộp lớn có dễ chuyển hơn túi không?\nNữ: Đáy hộp ướt nên không dùng được. Trước khi cho vào túi, anh nhặt lon lẫn trong lá trước nhé. Tôi sẽ gom cành.\nNam: Chỉ tách lon nhỉ. Có vật vỡ thì nguy hiểm nên tôi dùng găng. Cho vào túi xong tôi tự mang ra ruộng được không?\nNữ: Túi chắc nặng nên tôi đi mượn xe đẩy. Trong lúc đó cứ để túi ở góc sân. Tôi cũng liên lạc giáo viên phụ trách ruộng.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây khi thu gom lá rụng?', NULL, '[{"expression":"落ち葉","reading":"おちば","meaning_vi":"lá rụng"},{"expression":"枝","reading":"えだ","meaning_vi":"cành; cành cây; nhánh"}]', 395, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-020', 'N3-L-TASK', 'N3', 'LISTENING', 20, NULL, NULL, '[{"speaker":"N","ja":"女の人は新商品の紹介についてこの後まず何をしますか。"},{"speaker":"F","ja":"新しいお茶の紹介文を書きました。香りが強いことと、冷たい水でも作れることを中心に説明しています。店のページにのせてもいいですか。"},{"speaker":"M","ja":"内容はよいと思いますが、写真では袋の文字が小さくて読めません。写真を撮り直す必要がありますが、それは私が担当します。"},{"speaker":"F","ja":"では、写真が届くまで文章の漢字を確認しておきます。外国のお客さんも読むので、難しい言葉には説明を付けたいと思います。"},{"speaker":"M","ja":"その前に、紹介文の値段を直してください。来月からの値段になっていますが、今月中に注文する人には現在の値段で販売するので。"},{"speaker":"F","ja":"今の値段に変えて、来月値段が変わることも下に書きます。注文した日で値段が決まるとわかるようにすればいいですね。"},{"speaker":"M","ja":"ええ、説明を足すのはその後で大丈夫です。写真と文章がそろったら二人で確認してから公開しましょう。まだのせないでください。"},{"speaker":"N","ja":"女の人は新商品の紹介についてこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây về việc giới thiệu sản phẩm mới?\nNữ: Tôi viết giới thiệu trà mới rồi, tập trung vào hương thơm đậm và pha được bằng nước lạnh. Tôi đăng lên trang cửa hàng được không?\nNam: Nội dung tốt nhưng ảnh không đọc được chữ nhỏ trên túi. Cần chụp lại, phần đó tôi phụ trách.\nNữ: Vậy trong lúc chờ ảnh tôi kiểm tra chữ Hán. Khách nước ngoài cũng đọc nên muốn giải thích từ khó.\nNam: Trước đó sửa giá trong giới thiệu nhé. Đang ghi giá từ tháng sau, nhưng người đặt trong tháng này vẫn mua theo giá hiện tại.\nNữ: Tôi đổi thành giá hiện tại và ghi dưới là tháng sau đổi giá. Viết rõ giá xác định theo ngày đặt là được nhỉ.\nNam: Vâng, nhờ chị. Giải thích từ thêm sau cũng được. Đủ ảnh và bài mình cùng kiểm rồi công bố. Chưa đăng nhé.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây về việc giới thiệu sản phẩm mới?', NULL, '[{"expression":"紹介","reading":"しょうかい","meaning_vi":"giới thiệu"},{"expression":"販売","reading":"はんばい","meaning_vi":"bán hàng; tiêu thụ"}]', 407, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-021', 'N3-L-TASK', 'N3', 'LISTENING', 21, NULL, NULL, '[{"speaker":"N","ja":"男の人はホテルの研修でこの後まず何をしますか。"},{"speaker":"M","ja":"客室の掃除の練習ですが、ベッドから始めればいいですか。昨日教わったように、シーツを外して新しい物にかえようと思います。"},{"speaker":"F","ja":"今日はお客さんが忘れた物を見つけたときの練習を先にします。机の引き出しに時計が入っているので、見てください。"},{"speaker":"M","ja":"時計があったら、すぐ受付に届けるんでしたね。持ち主がまだホテルにいるかもしれないので、早く連絡したほうがよさ"},{"speaker":"F","ja":"受付へ運ぶ前に、見つけた部屋の番号と場所を記録してください。今回は練習用の時計ですから、実際にお客さんへ連絡する必要はありません。"},{"speaker":"M","ja":"部屋番号だけではなく、机の引き出しの中にあったことも書くんですね。時計にはふれず、先に記録の紙を用意します。"},{"speaker":"F","ja":"記録ができたら袋に入れる手順を説明します。シーツをかえる練習はその後にしますから、新しい物はまだ出さなくて結構です。"},{"speaker":"N","ja":"男の人はホテルの研修でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây trong buổi đào tạo tại khách sạn?\nNam: Về luyện dọn phòng, tôi bắt đầu từ giường được không? Tôi định tháo ga và thay ga mới như học hôm qua.\nNữ: Hôm nay luyện cách xử lý đồ khách bỏ quên trước. Có đồng hồ trong ngăn kéo bàn, anh xem nhé.\nNam: Có đồng hồ thì mang ngay tới quầy tiếp tân nhỉ. Chủ có thể còn ở khách sạn nên chắc liên lạc sớm sẽ hơn.\nNữ: Trước khi mang tới quầy, hãy ghi số phòng và chỗ tìm thấy. Lần này là đồng hồ dùng tập nên không cần thật sự liên lạc khách.\nNam: Không chỉ số phòng mà còn ghi tìm thấy trong ngăn kéo bàn nhỉ. Tôi chưa chạm vào đồng hồ, chuẩn bị giấy ghi trước.\nNữ: Đúng. Ghi xong tôi giải thích quy trình bỏ vào túi. Luyện thay ga làm sau nên chưa cần lấy ga mới ra.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây trong buổi đào tạo tại khách sạn?', NULL, '[{"expression":"研修","reading":"けんしゅう","meaning_vi":"tập huấn; đào tạo; thực tập"},{"expression":"記録","reading":"きろく","meaning_vi":"ghi chép; bản ghi"}]', 390, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-022', 'N3-L-TASK', 'N3', 'LISTENING', 22, NULL, NULL, '[{"speaker":"N","ja":"女の人は犬をかってくれる人を探す活動でこの後まず何をしますか。"},{"speaker":"F","ja":"犬の写真を撮ったので、かってくれる人を探す案内を作ります。名前と年齢を書けば十分でしょうか。早く知らせたいと思っています。"},{"speaker":"M","ja":"性格や必要な世話についても書いたほうがいいですね。この犬は静かですが、毎日薬を飲ませる必要があると聞きました。"},{"speaker":"F","ja":"では、薬の名前と飲む回数もくわしく書いておきます。前にもらった紙には一日二回とあったので、その通りに入れればいいですね。"},{"speaker":"M","ja":"最近薬が変わったそうですから、古い紙は使わないでください。まず世話をしている係の人に、今必要な世話の内容を確認しましょう。"},{"speaker":"F","ja":"係の人に電話して、薬のことと散歩の長さを聞いてみます。案内に写真を入れるのは、その後でも間に合いますよね。"},{"speaker":"M","ja":"写真の大きさは私が直しておきます。内容が確かになるまで案内は配らず、係の人にも一度読んでもらってからにしましょう。"},{"speaker":"N","ja":"女の人は犬をかってくれる人を探す活動でこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây trong hoạt động tìm người nhận nuôi chó?\nNữ: Tôi chụp ảnh chó rồi nên sẽ làm thông báo tìm người nuôi. Chỉ ghi tên và tuổi đủ không? Tôi muốn thông báo sớm.\nNam: Nên ghi cả tính cách và cách chăm sóc cần thiết. Tôi nghe con này yên tĩnh nhưng cần uống thuốc hàng ngày.\nNữ: Vậy tôi ghi kỹ tên thuốc và số lần uống. Giấy trước ghi ngày hai lần, tôi ghi theo thế được nhỉ.\nNam: Nghe nói gần đây đổi thuốc rồi nên đừng dùng giấy cũ. Trước hết hãy xác nhận cách chăm sóc hiện tại với người đang phụ trách.\nNữ: Tôi gọi hỏi người phụ trách về thuốc và thời gian đi dạo. Thêm ảnh vào thông báo sau vẫn kịp nhỉ?\nNam: Tất nhiên. Tôi chỉnh cỡ ảnh. Chưa chắc nội dung thì không phát thông báo; cần để người phụ trách đọc một lần rồi hãy phát.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây trong hoạt động tìm người nhận nuôi chó?', NULL, '[{"expression":"性格","reading":"せいかく","meaning_vi":"tính cách"},{"expression":"世話","reading":"せわ","meaning_vi":"sự chăm sóc; sự giúp đỡ"}]', 409, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-023', 'N3-L-TASK', 'N3', 'LISTENING', 23, NULL, NULL, '[{"speaker":"N","ja":"男の人はキャンプ場でこの後まず何をしますか。"},{"speaker":"M","ja":"テントを張る場所はこの川の近くでいいでしょうか。水を運びやすいですし、木の下なら日差しも強くありません。"},{"speaker":"F","ja":"午後に上流で雨が降る予報なので、川からはなれた所にしましょう。あの少し高い場所なら、土も平らで安全"},{"speaker":"M","ja":"では、荷物を全部あそこへ運びます。テントの袋は重いので、先に小さい物を運んでから、二人で持っていきましょうか。"},{"speaker":"F","ja":"運ぶ前に、管理の人にその場所を使ってよいか聞いてきてください。予約した場所と違うので、勝手に変えることはできません。"},{"speaker":"M","ja":"管理の建物は入口の右側でしたね。場所を説明しやすいように、地図を持っていきます。火を使えるかも一緒に聞きます。"},{"speaker":"F","ja":"私は荷物が雨でぬれないように車の中を整理します。許可が出てから移動して、その後でテントを張り始めましょう。"},{"speaker":"N","ja":"男の人はキャンプ場でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây tại khu cắm trại?\nNam: Dựng lều gần sông chỗ này được không? Dễ mang nước, dưới cây thì nắng cũng không gắt.\nNữ: Dự báo chiều có mưa thượng nguồn nên chọn chỗ xa sông đi. Chỗ hơi cao kia đất phẳng, có vẻ an toàn.\nNam: Vậy tôi mang hết đồ ra đó. Túi lều nặng, tôi chuyển đồ nhỏ trước rồi hai người khiêng lều nhé?\nNữ: Trước khi chuyển, anh hỏi người quản lý có được dùng chỗ đó không. Khác khu đã đặt nên không tự ý đổi.\nNam: Nhà quản lý ở bên phải lối vào nhỉ. Tôi mang bản đồ để dễ chỉ vị trí, hỏi luôn có được dùng lửa không.\nNữ: Nhờ anh. Tôi xếp lại trong xe để đồ không ướt mưa. Có phép rồi mới chuyển, sau đó bắt đầu dựng lều.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây tại khu cắm trại?', NULL, '[{"expression":"管理","reading":"かんり","meaning_vi":"quản lý"},{"expression":"許可","reading":"きょか","meaning_vi":"cho phép; sự cho phép"}]', 366, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-024', 'N3-L-TASK', 'N3', 'LISTENING', 24, NULL, NULL, '[{"speaker":"N","ja":"女の人はオンライン講座の前にこの後まず何をしますか。"},{"speaker":"F","ja":"今夜の講座で使う資料を参加者に送ろうと思います。画面にも映しますが、紙で見たい人がいるかもしれないので、早めに送りたいです。"},{"speaker":"M","ja":"送る資料は昨日確認したものですよね。最後の練習問題に答えが入っていたと思いますが、そのままだと授業で考えてもらえません。"},{"speaker":"F","ja":"では、答えのページだけ消します。練習問題の下にも説明が少しあるので、それも全部消したほうがよさそうですね。"},{"speaker":"M","ja":"問題を解くための説明は残してください。まず講師用と参加者用を別のファイルにして、参加者用から答えだけを取り除きましょう。"},{"speaker":"F","ja":"元のファイルを残したまま、もう一つ作るんですね。ファイル名に参加者用と入れれば、送るときにも間違えずに済みますね。"},{"speaker":"M","ja":"送信先の確認は私がします。参加者用ができたら私に見せてください。音声のテストは送った後で二人で行えば間に合います。"},{"speaker":"N","ja":"女の人はオンライン講座の前にこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây trước khóa học trực tuyến?\nNữ: Tôi định gửi tài liệu dùng trong buổi học tối nay cho người tham gia. Dù cũng chiếu trên màn hình nhưng có người muốn xem giấy nên tôi muốn gửi sớm.\nNam: Tài liệu gửi là bản kiểm tra hôm qua nhỉ. Tôi nghĩ bài luyện cuối có đáp án, để vậy thì học viên không suy nghĩ trong giờ được.\nNữ: Vậy tôi xóa riêng trang đáp án. Dưới bài luyện cũng có giải thích một chút, có lẽ xóa hết luôn sẽ tốt.\nNam: Giữ giải thích cần để giải bài. Trước hết tách tệp cho giảng viên và người tham gia, chỉ bỏ đáp án khỏi bản người tham gia.\nNữ: Giữ nguyên tệp gốc và tạo thêm một bản nhỉ. Ghi dành cho người tham gia trong tên tệp thì lúc gửi cũng đỡ nhầm.\nNam: Đúng. Tôi kiểm tra người nhận. Làm xong bản học viên thì cho tôi xem. Kiểm tra âm thanh sau khi gửi, hai người cùng làm vẫn kịp.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây trước khóa học trực tuyến?', NULL, '[{"expression":"講座","reading":"こうざ","meaning_vi":"khóa học"},{"expression":"講師","reading":"こうし","meaning_vi":"giảng viên; giáo viên; diễn giả"}]', 401, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-025', 'N3-L-TASK', 'N3', 'LISTENING', 25, NULL, NULL, '[{"speaker":"N","ja":"男の人は古本市の準備でこの後まず何をしますか。"},{"speaker":"M","ja":"寄付された本を種類ごとに分けました。値段のシールを貼ってから、明日の会場へ運ぶために箱へ戻しておこうと思います。"},{"speaker":"F","ja":"値段は一冊百円で同じにしますが、書き込みがある本は売らないことになりました。中を確認する作業はもう終わりましたか。"},{"speaker":"M","ja":"表紙の汚れだけ見たので、中はまだです。では、値段を貼る前に全部開いてみます。名前があるだけでも売れないんでしょうか。"},{"speaker":"F","ja":"名前だけなら消して売れますが、問題の答えが書いてある本は外します。まずその本を別にしてください。名前を消す作業は私がします。"},{"speaker":"M","ja":"答えが書かれた本を探して分けるんですね。分けた本は、すぐ紙の回収に出してもいいですか。机の上がいっぱいになりそうですが。"},{"speaker":"F","ja":"必要だという人に無料で渡す予定なので、すてずに別の箱へ入れてください。値段を貼るのも会場へ運ぶのも、確認が済んでからです。"},{"speaker":"N","ja":"男の人は古本市の準備でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây để chuẩn bị chợ sách cũ?\nNam: Tôi phân loại sách được quyên góp rồi. Tôi định dán giá rồi bỏ lại hộp để ngày mai chuyển tới hội trường.\nNữ: Giá thống nhất một trăm yên một cuốn, nhưng sách có viết vào thì không bán. Đã kiểm tra bên trong chưa?\nNam: Tôi mới nhìn bìa bẩn thôi, chưa xem trong. Vậy trước khi dán giá tôi mở hết ra xem. Chỉ có tên thôi cũng không bán được à?\nNữ: Chỉ tên thì xóa rồi bán được, nhưng sách có viết đáp án thì loại. Trước hết anh tách những cuốn đó. Tôi xóa tên.\nNam: Tìm và tách sách đã viết đáp án nhỉ. Sách tách ra mang thu gom giấy ngay được không? Trên bàn có vẻ sắp đầy.\nNữ: Dự định tặng miễn phí người cần nên đừng vứt, hãy cho vào hộp khác. Dán giá và chuyển tới hội trường đều sau khi kiểm tra xong.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây để chuẩn bị chợ sách cũ?', NULL, '[{"expression":"寄付","reading":"きふ","meaning_vi":"quyên góp"},{"expression":"値段","reading":"ねだん","meaning_vi":"giá cả; giá tiền"}]', 400, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-026', 'N3-L-TASK', 'N3', 'LISTENING', 26, NULL, NULL, '[{"speaker":"N","ja":"女の人は電話で受けた注文についてこの後まず何をしますか。"},{"speaker":"F","ja":"電話で花の注文を受けました。赤い花を中心に、明日の午前中に届けてほしい先に花を選んで包み始めてもいいですか。"},{"speaker":"M","ja":"届け先はどこですか。明日は午前中の配達が多いので、場所によっては希望の時間に間に合わないかもしれません。"},{"speaker":"F","ja":"住所は聞きましたが、住所の番号がはっきり聞こえませんでした。前にも注文した方なので、前の記録を見ればわかると思います。"},{"speaker":"M","ja":"以前と同じ住所とは限らないので、まずお客さんに電話して確認してください。花を選ぶのは私がやります。時間の約束はまだしないで。"},{"speaker":"F","ja":"住所の番号だけではなく、建物の名前も聞いておきます。配達できる時間は、住所を確認してから相談すると伝えればいいですね。"},{"speaker":"M","ja":"配達の予定は運転手と私が調整します。赤い花が足りなければ別の色を使えるかという確認は、私から後で連絡します。"},{"speaker":"N","ja":"女の人は電話で受けた注文についてこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây với đơn hàng nhận qua điện thoại?\nNữ: Tôi nhận đơn hoa qua điện thoại. Khách muốn chủ yếu hoa đỏ, giao sáng mai. Tôi chọn hoa rồi bắt đầu gói trước được không?\nNam: Địa chỉ giao ở đâu? Sáng mai nhiều đơn nên tùy nơi có thể không kịp giờ mong muốn.\nNữ: Tôi hỏi địa chỉ rồi nhưng số nhà nghe không rõ. Khách từng đặt nên xem hồ sơ cũ chắc biết.\nNam: Không chắc địa chỉ giống trước, nên trước hết chị gọi khách xác nhận. Tôi sẽ chọn hoa. Chưa hứa giờ giao nhé.\nNữ: Tôi hỏi cả tên tòa nhà chứ không chỉ số. Tôi nói giờ giao sẽ trao đổi sau khi xác nhận địa chỉ là được nhỉ.\nNam: Đúng. Tôi và tài xế điều chỉnh lịch giao. Nếu thiếu hoa đỏ thì tôi sẽ gọi hỏi sau có dùng màu khác được không.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây với đơn hàng nhận qua điện thoại?', NULL, '[{"expression":"住所","reading":"じゅうしょ","meaning_vi":"địa chỉ"},{"expression":"配達","reading":"はいたつ","meaning_vi":"giao hàng"}]', 396, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-027', 'N3-L-TASK', 'N3', 'LISTENING', 27, NULL, NULL, '[{"speaker":"N","ja":"男の人は博物館の案内係としてこの後まず何をしますか。"},{"speaker":"M","ja":"午後の団体は外国の方が多いそうなので、英語の案内を二十枚用意しました。入口で配ってから、作品の部屋へ案内しようと思います。"},{"speaker":"F","ja":"人数は二十人で合っていますが、半分は日本語の説明を希望しています。英語の紙だけ渡すと、わかりにくい人もいるでしょう。"},{"speaker":"M","ja":"では、日本語を十枚追加して持っていきます。集合場所が入口ではなく庭に変わったと聞いたので、そちらへ向かえばいいですね。"},{"speaker":"F","ja":"庭は雨で使えなくなりました。まず玄関の案内板を直して、団体の集合場所が一階の休憩室だとわかるようにしてください。"},{"speaker":"M","ja":"案内板にはまだ庭と書いてありますね。部屋の場所も矢印で示しておきます。日本語の紙を取りに行くのは、その後にします。"},{"speaker":"F","ja":"紙は私が用意しますから、案内板ができたら休憩室で待っていてください。作品の部屋へ移動する前に、希望する言語を一人ずつ確認しましょう。"},{"speaker":"N","ja":"男の人は博物館の案内係としてこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây với vai trò hướng dẫn ở bảo tàng?\nNam: Nghe nói đoàn chiều nhiều người nước ngoài nên tôi chuẩn bị hai mươi tờ hướng dẫn tiếng Anh. Tôi định phát ở lối vào rồi dẫn tới phòng trưng bày.\nNữ: Đúng hai mươi người nhưng nửa số muốn giải thích tiếng Nhật. Chỉ phát giấy tiếng Anh thì có người khó hiểu.\nNam: Vậy tôi lấy thêm mười tờ tiếng Nhật. Tôi nghe điểm tập trung đổi từ lối vào sang vườn, vậy tôi ra đó nhỉ.\nNữ: Vườn không dùng được vì mưa. Trước hết anh sửa bảng hướng dẫn ở tiền sảnh để mọi người biết tập trung ở phòng nghỉ tầng một.\nNam: Trên bảng vẫn ghi vườn nhỉ. Tôi thêm mũi tên chỉ phòng. Lấy giấy tiếng Nhật tôi để sau.\nNữ: Tôi chuẩn bị giấy, anh làm bảng xong thì chờ ở phòng nghỉ. Trước khi sang khu trưng bày, mình xác nhận ngôn ngữ mong muốn từng người.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây với vai trò hướng dẫn ở bảo tàng?', NULL, '[{"expression":"団体","reading":"だんたい","meaning_vi":"đoàn thể; nhóm"},{"expression":"説明","reading":"せつめい","meaning_vi":"giải thích; lời hướng dẫn"}]', 409, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-028', 'N3-L-TASK', 'N3', 'LISTENING', 28, NULL, NULL, '[{"speaker":"N","ja":"女の人は会員へのお知らせについてこの後まず何をしますか。"},{"speaker":"F","ja":"来月からの運動教室の時間を会員に知らせたいので、メールを作りました。月曜日のクラスは六時から七時に変更すると書いています。"},{"speaker":"M","ja":"月曜日はそれで正しいですが、木曜日のクラスも先生の都合で三十分遅くなります。その変更も入れておいてください。"},{"speaker":"F","ja":"では、木曜日も加えて全員に送ります。退会した人のアドレスが残っているかもしれないので、先に送信先を整理しますね。"},{"speaker":"M","ja":"アドレスは私が昨日確認しました。まず木曜日の新しい開始時刻を先生からのメールで確かめて、案内に書き加えてください。"},{"speaker":"F","ja":"記憶だけで書かず、先生の連絡を見直すんですね。終了時刻も一緒に変わるのか確認します。追加したらすぐ送ってもいいですか。"},{"speaker":"M","ja":"受付でも同じ案内を出すので、送る前に私に見せてください。紙のお知らせは私が印刷します。会員への送信は確認が終わってからにしましょう。"},{"speaker":"N","ja":"女の人は会員へのお知らせについてこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây với thông báo gửi hội viên?\nNữ: Tôi soạn thư báo giờ lớp thể dục từ tháng sau cho hội viên rồi. Tôi ghi lớp thứ hai đổi từ sáu giờ sang bảy giờ.\nNam: Thứ hai đúng, nhưng lớp thứ năm cũng muộn ba mươi phút do lịch giáo viên. Thêm thay đổi đó nữa nhé.\nNữ: Vậy tôi thêm thứ năm rồi gửi tất cả. Có thể còn địa chỉ người đã nghỉ nên tôi dọn danh sách gửi trước.\nNam: Tôi kiểm tra địa chỉ hôm qua rồi. Trước hết chị xem thư của giáo viên để xác nhận giờ bắt đầu mới thứ năm rồi thêm vào thông báo.\nNữ: Không ghi theo trí nhớ mà xem lại liên lạc của giáo viên nhỉ. Tôi kiểm tra cả giờ kết thúc có đổi không. Thêm xong gửi luôn được không?\nNam: Quầy cũng ra thông báo giống vậy nên trước khi gửi hãy cho tôi xem. Tôi in bản giấy. Xác nhận xong rồi mới gửi hội viên.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây với thông báo gửi hội viên?', NULL, '[{"expression":"会員","reading":"かいいん","meaning_vi":"hội viên; thành viên"},{"expression":"開始","reading":"かいし","meaning_vi":"sự bắt đầu; khởi đầu; bắt đầu"}]', 409, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-029', 'N3-L-TASK', 'N3', 'LISTENING', 29, NULL, NULL, '[{"speaker":"N","ja":"男の人は公園のベンチを直す作業でこの後まず何をしますか。"},{"speaker":"M","ja":"ベンチの板が一枚割れていますね。新しい板を買ってきたので、古い板を外してすぐ取りかえようと思います。道具も持ってきました。"},{"speaker":"F","ja":"作業を始める前に、子供が近づかないように周りをかこみましょう。今日は隣の広場で遊ぶ子が多いので、特に気をつけたいです。"},{"speaker":"M","ja":"そうこからロープを借りてきます。長さが足りなければ、いすを並べて入れないようにすればいいでしょうか。"},{"speaker":"F","ja":"ロープはこの袋にあります。ただ、周りをかこむ前にベンチに置いてあるかばんを受付へ届けてください。誰かが忘れた物のようです。"},{"speaker":"M","ja":"この黒いかばんですね。中を開けずに、ベンチにあったと受付の人に伝えます。かこむ作業は戻ってから二人でやりましょう。"},{"speaker":"F","ja":"私はその間に板の長さを確かめておきます。受付へ行くとき、修理中の看板も借りてきてください。道具を使うのは周りをかこんでからです。"},{"speaker":"N","ja":"男の人は公園のベンチを直す作業でこの後まず何をしますか。"}]', 'Người dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây để sửa ghế công viên?\nNam: Một tấm ván ghế bị vỡ nhỉ. Tôi mua ván mới rồi nên định tháo ván cũ thay ngay. Tôi mang cả dụng cụ.\nNữ: Trước khi làm hãy quây quanh để trẻ không tới gần. Hôm nay nhiều trẻ chơi ở quảng trường bên nên đặc biệt cẩn thận.\nNam: Tôi mượn dây ở kho. Nếu không đủ dài thì xếp ghế ngăn vào được không?\nNữ: Dây có trong túi này. Nhưng trước khi quây, anh mang cặp trên ghế tới quầy tiếp nhận. Có vẻ ai đó bỏ quên.\nNam: Cặp đen này nhỉ. Tôi không mở, sẽ báo nhân viên là tìm trên ghế. Tôi về rồi hai người cùng quây.\nNữ: Trong lúc đó tôi kiểm tra chiều dài ván. Khi tới quầy anh mượn cả biển đang sửa chữa nhé. Quây xong mới dùng dụng cụ.\nNgười dẫn: Người đàn ông sẽ làm gì đầu tiên sau đây để sửa ghế công viên?', NULL, '[{"expression":"修理","reading":"しゅうり","meaning_vi":"sửa chữa (máy móc hoặc đồ vật)"},{"expression":"道具","reading":"どうぐ","meaning_vi":"dụng cụ; đạo cụ"}]', 408, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-030', 'N3-L-TASK', 'N3', 'LISTENING', 30, NULL, NULL, '[{"speaker":"N","ja":"女の人は旅行の写真集を作るためにこの後まず何をしますか。"},{"speaker":"F","ja":"旅行の写真を日付順に並べました。このまま写真集を注文したいんですが、同じ場所の写真が多いので、少し減らしたほうがいいですか。"},{"speaker":"M","ja":"枚数を減らす前に、写っている人にのせてよいか確かめましょう。特に宿で一緒になった方の写真は、まだ許可をもらっていませんよね。"},{"speaker":"F","ja":"連絡先はありますから、その方にメールを送ります。家族に見せるだけの写真集ですが、それでも確認したほうが安心ですね。"},{"speaker":"M","ja":"ええ、どの写真か伝わるように、のせたい一枚をメールに付けてください。他の人が写った写真を全部送る必要はありません。"},{"speaker":"F","ja":"では、その方が写った写真を一枚選んで、使ってもよいか聞きます。返事を待っている間に、風景の写真を選べばいいですね。"},{"speaker":"M","ja":"私は写真集の大きさと値段を調べます。返事が来るまでは注文せず、許可が出なければ、その一枚を外して作りましょう。"},{"speaker":"N","ja":"女の人は旅行の写真集を作るためにこの後まず何をしますか。"}]', 'Người dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để làm tập ảnh chuyến đi?\nNữ: Tôi xếp ảnh chuyến đi theo ngày rồi. Muốn đặt làm tập ảnh luôn nhưng nhiều ảnh cùng nơi, có nên giảm chút không?\nNam: Trước khi giảm số ảnh, mình hỏi người có mặt trong ảnh cho đăng không. Đặc biệt ảnh người gặp ở chỗ trọ vẫn chưa xin phép nhỉ.\nNữ: Có thông tin liên lạc nên tôi gửi thư cho người đó. Tập ảnh chỉ cho gia đình xem, nhưng xác nhận vẫn an tâm hơn nhỉ.\nNam: Vâng, hãy đính kèm một ảnh muốn dùng để họ biết ảnh nào. Không cần gửi hết ảnh có người khác.\nNữ: Vậy tôi chọn một ảnh có người đó, hỏi có dùng được không. Trong lúc đợi trả lời thì chọn ảnh phong cảnh nhỉ.\nNam: Đúng vậy. Tôi tra kích cỡ và giá tập ảnh. Chưa có trả lời thì chưa đặt; nếu không được phép thì bỏ ảnh đó rồi làm.\nNgười dẫn: Người phụ nữ sẽ làm gì đầu tiên sau đây để làm tập ảnh chuyến đi?', NULL, '[{"expression":"風景","reading":"ふうけい","meaning_vi":"phong cảnh"},{"expression":"許可","reading":"きょか","meaning_vi":"cho phép; sự cho phép"}]', 406, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-001', 'N3-L-POINT', 'N3', 'LISTENING', 1, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして説明の方法を変えようとしていますか。"},{"speaker":"M","ja":"来週の町の掃除では、最初に全員へ説明するんですよね。去年の資料を人数分コピーしておけば、準備は早く終わりそうですが。"},{"speaker":"F","ja":"資料は使いますが、説明は小さいグループに分かれて行うつもりです。去年は分からないことがあっても、みんなの前では聞きにくかったそうなんです。"},{"speaker":"M","ja":"確かに百人もいると、手を上げるのに勇気がいりますね。ただ、何度も同じ説明をすると、掃除を始める時間が遅くなりませんか。"},{"speaker":"F","ja":"係の人を増やして、同じ時刻に説明します。大事なのは、参加する人が疑問を残したまま仕事を始めないことだと思っています。"},{"speaker":"M","ja":"去年は道具の場所を間違える人もいましたね。グループごとに違う場所を担当すれば、道具も少なくて済むのでしょうか。"},{"speaker":"F","ja":"道具の数や担当する場所は変えません。近くの係に気軽に確認できれば、初めて来た人も安心して動けるはずです。"},{"speaker":"N","ja":"女の人はどうして説明の方法を変えようとしていますか。"}]', 'Người dẫn: Vì sao người phụ nữ muốn đổi cách hướng dẫn?\nNam: Buổi dọn vệ sinh thị trấn tuần sau sẽ hướng dẫn chung trước nhỉ. Sao chép tài liệu năm ngoái theo số người thì chuẩn bị sẽ nhanh.\nNữ: Vẫn dùng tài liệu, nhưng tôi định chia nhóm nhỏ để hướng dẫn. Năm ngoái nghe nói có thắc mắc mà ngại hỏi trước mọi người.\nNam: Một trăm người thì giơ tay cũng cần can đảm. Nhưng giải thích lặp lại nhiều lần có làm giờ bắt đầu dọn muộn không?\nNữ: Tôi tăng người phụ trách và hướng dẫn cùng giờ. Tôi nghĩ quan trọng là người tham gia không bắt đầu việc khi còn thắc mắc.\nNam: Năm ngoái cũng có người nhầm chỗ dụng cụ. Nếu từng nhóm phụ trách địa điểm khác nhau thì cần ít dụng cụ hơn sao?\nNữ: Số dụng cụ và địa điểm phụ trách không đổi. Nếu dễ xác nhận với người phụ trách gần mình, người đến lần đầu cũng yên tâm làm việc.\nNgười dẫn: Vì sao người phụ nữ muốn đổi cách hướng dẫn?', NULL, '[{"expression":"時刻","reading":"じこく","meaning_vi":"thời khắc; giờ giấc"},{"expression":"疑問","reading":"ぎもん","meaning_vi":"điều nghi vấn; nghi vấn; hoài nghi"}]', 403, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-002', 'N3-L-POINT', 'N3', 'LISTENING', 2, NULL, NULL, '[{"speaker":"N","ja":"女の人が店の順番の決め方で最も大切にしていることは何ですか。"},{"speaker":"M","ja":"新しい番号の機械を置くんですね。お客さんが入口で番号を取れば、店の前に長い列を作らなくてもよくなりますね。"},{"speaker":"F","ja":"並ばなくていいのも便利ですが、私が一番気にしているのは、来た順番が誰にでも分かることです。前は順番について不満がありましたから。"},{"speaker":"M","ja":"小さい買い物の人を先にすると、待つ人の数は減りそうです。修理の相談は時間がかかるので、別にした方がよくありませんか。"},{"speaker":"F","ja":"相談の内容で順番を変えると、後から来た人が先になった理由を説明しなければなりません。今回は全員、番号の順に呼びます。"},{"speaker":"M","ja":"画面に番号を出すだけなら、店員が名前を呼ぶ必要もなくなりますね。少ない人数で仕事をすることもできそうです。"},{"speaker":"F","ja":"番号が見えにくい人には声もかけます。仕事を減らすためではなく、誰もが同じ決まりで案内されていると感じられることが大事なんです。"},{"speaker":"N","ja":"女の人が店の順番の決め方で最も大切にしていることは何ですか。"}]', 'Người dẫn: Người phụ nữ coi trọng nhất điều gì khi quyết định thứ tự phục vụ?\nNam: Cửa hàng sẽ đặt máy số thứ tự mới nhỉ. Khách lấy số ở cửa thì không cần xếp hàng dài trước tiệm.\nNữ: Không phải xếp hàng cũng tiện, nhưng tôi quan tâm nhất là ai cũng biết thứ tự đến. Trước đây có phàn nàn về lượt phục vụ.\nNam: Cho người mua ít lên trước thì số người chờ có vẻ giảm. Tư vấn sửa chữa mất thời gian, tách riêng có tốt hơn không?\nNữ: Đổi thứ tự theo nội dung tư vấn thì phải giải thích vì sao người đến sau lên trước. Lần này tất cả được gọi theo số.\nNam: Chỉ hiện số trên màn hình thì nhân viên không cần gọi tên. Có lẽ ít nhân viên cũng làm được.\nNữ: Chúng tôi vẫn gọi người khó nhìn số. Không nhằm giảm việc, mà quan trọng là ai cũng cảm thấy được phục vụ theo cùng quy tắc.\nNgười dẫn: Người phụ nữ coi trọng nhất điều gì khi quyết định thứ tự phục vụ?', NULL, '[{"expression":"順番","reading":"じゅんばん","meaning_vi":"thứ tự; lần lượt"},{"expression":"画面","reading":"がめん","meaning_vi":"màn hình; màn ảnh"}]', 409, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-003', 'N3-L-POINT', 'N3', 'LISTENING', 3, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうしてアンケートに名前を書くところをなくしましたか。"},{"speaker":"M","ja":"職場についてのアンケート、前は名前と働いている部を書いてもらっていましたね。今回は名前がないと、後で内容を確かめにくくありませんか。"},{"speaker":"F","ja":"その点は不便ですが、言いにくいことも書いてもらいたいんです。名前が残ると困ると思って、問題がないと答える人もいるでしょう。"},{"speaker":"M","ja":"結果をまとめる時に、名前を入力する手間が省けますね。答える項目も少なくなれば、短い時間で書いてもらえそうです。"},{"speaker":"F","ja":"質問の数は同じですし、作業を減らすことが目的ではありません。本当は困っているのに、その声が見えなくなる方が問題です。"},{"speaker":"M","ja":"同じ人が二回出しても分からないのではないですか。紙を自由に取れる場所に置くと、数が合わなくなるかもしれません。"},{"speaker":"F","ja":"一人に一枚ずつ渡します。書いた後は箱に入れてもらい、誰の回答か調べません。まず正直な意見を集めることを優先したいです。"},{"speaker":"N","ja":"女の人はどうしてアンケートに名前を書くところをなくしましたか。"}]', 'Người dẫn: Vì sao người phụ nữ bỏ ô ghi tên khỏi khảo sát?\nNam: Khảo sát về nơi làm việc trước đây ghi tên và bộ phận nhỉ. Lần này không tên thì khó hỏi lại nội dung về sau không?\nNữ: Điểm đó bất tiện, nhưng tôi muốn mọi người viết cả điều khó nói. Có người nghĩ để lại tên sẽ phiền nên trả lời không có vấn đề.\nNam: Tổng hợp sẽ đỡ công nhập tên nhỉ. Giảm mục trả lời thì cũng viết nhanh hơn.\nNữ: Số câu hỏi như cũ, mục đích không phải giảm thao tác. Điều đáng ngại hơn là người đang khó khăn mà tiếng nói không được biết đến.\nNam: Có phải sẽ không biết một người nộp hai lần? Nếu để giấy tự lấy có thể số lượng không khớp.\nNữ: Chúng tôi phát mỗi người một tờ. Viết xong bỏ vào hộp, không tìm ai trả lời. Trước tiên tôi muốn ưu tiên thu ý kiến thành thật.\nNgười dẫn: Vì sao người phụ nữ bỏ ô ghi tên khỏi khảo sát?', NULL, '[{"expression":"意見","reading":"いけん","meaning_vi":"ý kiến"},{"expression":"目的","reading":"もくてき","meaning_vi":"mục đích; mục tiêu cần đạt"}]', 416, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-004', 'N3-L-POINT', 'N3', 'LISTENING', 4, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして庭の当番を二人ずつにしましたか。"},{"speaker":"M","ja":"みんなで使う庭の当番表が変わりましたね。今までは一人ずつ水をやっていましたが、草が増えて作業が大変になったんですか。"},{"speaker":"F","ja":"作業の量は同じです。急に来られなくなった人が、一人で代わりを探すのに困っていたので、二人で相談できるようにしました。"},{"speaker":"M","ja":"二人とも来れば、半分の時間で終わりそうですね。毎朝八時という決まりもなくして、好きな時刻に来ていいのでしょうか。"},{"speaker":"F","ja":"水をやるのは今まで通り朝です。ただ、二人が毎回一緒に来る必要はありません。前日に連絡して、どちらが来るか決めればいいんです。"},{"speaker":"M","ja":"それなら、仕事の予定が変わりやすい人も続けられそうです。でも、片方の人ばかり来ることにならないか、少し心配ですね。"},{"speaker":"F","ja":"一週間ごとに二人で回数を確認してもらいます。早く終わらせることより、無理がある日は頼れる相手がいることを大切にしたいんです。"},{"speaker":"N","ja":"女の人はどうして庭の当番を二人ずつにしましたか。"}]', 'Người dẫn: Vì sao người phụ nữ phân công chăm vườn theo cặp?\nNam: Lịch trực khu vườn dùng chung đổi rồi nhỉ. Trước mỗi lần một người tưới, cỏ tăng nên việc vất vả hơn à?\nNữ: Lượng việc như cũ. Người đột ngột không đến được gặp khó khi tự tìm người thay, nên tôi muốn hai người bàn bạc được.\nNam: Cả hai cùng đến chắc xong trong nửa thời gian. Có bỏ quy định tám giờ sáng, cho đến lúc tùy thích không?\nNữ: Vẫn tưới buổi sáng như trước. Nhưng không cần cả hai đến mỗi lần. Liên lạc hôm trước rồi quyết định ai đến là được.\nNam: Vậy người hay đổi lịch làm cũng tiếp tục được. Nhưng tôi hơi lo chỉ một người thường xuyên phải đến.\nNữ: Mỗi tuần hai người kiểm tra số lần với nhau. Tôi coi trọng có người nhờ khi khó sắp xếp hơn là làm xong nhanh.\nNgười dẫn: Vì sao người phụ nữ phân công chăm vườn theo cặp?', NULL, '[{"expression":"当番","reading":"とうばん","meaning_vi":"ca trực; phiên trực; lượt"},{"expression":"片方","reading":"かたほう","meaning_vi":"một bên; một phía; một chiếc"}]', 401, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-005', 'N3-L-POINT', 'N3', 'LISTENING', 5, NULL, NULL, '[{"speaker":"N","ja":"女の人は研修でどのような話をしてほしいと言っていますか。"},{"speaker":"M","ja":"新入社員の研修で、先輩から話をするんですよね。大きな契約が取れた時の経験を話せば、やる気を出してもらえるでしょうか。"},{"speaker":"F","ja":"成功した話もいいですが、今回は困った時に誰へ相談したかを中心に話してほしいです。一人で解決しようとして遅れる人が多いので。"},{"speaker":"M","ja":"仕事の間違いを話すと、新しい人が不安になりませんか。会社のよい所を知ってもらうことも必要だと思います。"},{"speaker":"F","ja":"失敗を並べて怖がらせたいのではありません。助けを求めたことで状況が変わった例なら、困った時の行動が分かるはずです。"},{"speaker":"M","ja":"詳しい仕事の方法は、来週の研修で教えるんでしたね。それなら、今回も使う資料や道具の紹介は省いていいですか。"},{"speaker":"F","ja":"資料については来週で大丈夫です。今は、分からないことを隠すより早く人に聞く方がよいと、実際の経験から伝えてください。"},{"speaker":"N","ja":"女の人は研修でどのような話をしてほしいと言っていますか。"}]', 'Người dẫn: Người phụ nữ muốn nghe chuyện như thế nào trong buổi đào tạo?\nNam: Đào tạo nhân viên mới có tiền bối chia sẻ nhỉ. Kể lúc ký được hợp đồng lớn sẽ giúp họ có động lực chứ?\nNữ: Thành công cũng hay, nhưng lần này tôi muốn tập trung kể đã hỏi ai khi gặp khó. Nhiều người cố tự giải quyết nên chậm.\nNam: Kể sai sót có khiến người mới lo không? Tôi nghĩ cũng cần giúp họ biết điểm tốt của công ty.\nNữ: Tôi không muốn liệt kê thất bại để dọa. Ví dụ tình hình thay đổi sau khi nhờ giúp sẽ cho họ biết cách hành động khi khó.\nNam: Cách làm chi tiết sẽ dạy ở buổi tuần sau nhỉ. Vậy lần này cũng bỏ giới thiệu tài liệu và dụng cụ được không?\nNữ: Tài liệu để tuần sau được. Giờ hãy dùng trải nghiệm thật để truyền đạt rằng hỏi sớm tốt hơn giấu điều chưa biết.\nNgười dẫn: Người phụ nữ muốn nghe chuyện như thế nào trong buổi đào tạo?', NULL, '[{"expression":"状況","reading":"じょうきょう","meaning_vi":"tình hình; tình huống; trạng thái"},{"expression":"やる気","reading":"やるき","meaning_vi":"có hứng thú; động lực; ý muốn làm"}]', 394, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-006', 'N3-L-POINT', 'N3', 'LISTENING', 6, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして演奏会の席を変えましたか。"},{"speaker":"M","ja":"来月の演奏会、一番前の席が取れたと喜んでいましたよね。新しいチケットを見ると、後ろの中央になっていますが、なぜ変えたんですか。"},{"speaker":"F","ja":"前なら演奏する人の顔はよく見えますが、私は楽器全体の音を聞きたいんです。中央の方が、いろいろな音が一緒に聞こえるそうなので。"},{"speaker":"M","ja":"後ろの席は料金も安くなりますね。演奏会の後に友達と食事をすると言っていたので、その分のお金を残したかったんですか。"},{"speaker":"F","ja":"今回の席は同じ料金です。食事の予定も変わっていません。舞台に近いことより、自分の好きな曲をどんな音で聞けるかを考えました。"},{"speaker":"M","ja":"中央だと通路から遠くなりますよね。終わったら早く出たい人には、出口に近い席の方が便利だと思いますが。"},{"speaker":"F","ja":"帰りは急がないので問題ありません。手の動きを見るのも面白そうですが、今回は目を閉じても楽しめるような聞き方をしたいんです。"},{"speaker":"N","ja":"女の人はどうして演奏会の席を変えましたか。"}]', 'Người dẫn: Vì sao người phụ nữ đổi chỗ ngồi buổi hòa nhạc?\nNam: Anh chị đã vui vì lấy được hàng đầu hòa nhạc tháng sau nhỉ. Vé mới lại là giữa phía sau, sao đổi vậy?\nNữ: Hàng đầu nhìn rõ mặt người biểu diễn, nhưng tôi muốn nghe âm của cả dàn nhạc. Nghe nói ngồi giữa các âm hòa cùng nhau tốt hơn.\nNam: Ghế sau cũng rẻ hơn nhỉ. Bạn nói ăn với bạn sau hòa nhạc nên muốn để tiền cho bữa đó à?\nNữ: Chỗ lần này cùng giá. Kế hoạch ăn cũng không đổi. Tôi cân nhắc nghe bản nhạc thích với âm thanh ra sao hơn là gần sân khấu.\nNam: Giữa thì xa lối đi nhỉ. Ai muốn ra nhanh sau buổi diễn ngồi gần cửa sẽ tiện hơn.\nNữ: Tôi không vội về nên không sao. Xem động tác tay cũng thú vị, nhưng lần này tôi muốn nghe theo cách nhắm mắt vẫn thưởng thức được.\nNgười dẫn: Vì sao người phụ nữ đổi chỗ ngồi buổi hòa nhạc?', NULL, '[{"expression":"楽器","reading":"がっき","meaning_vi":"nhạc cụ"},{"expression":"中央","reading":"ちゅうおう","meaning_vi":"trung ương; trung tâm; giữa"}]', 396, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-007', 'N3-L-POINT', 'N3', 'LISTENING', 7, NULL, NULL, '[{"speaker":"N","ja":"女の人はバスの調査で何を特に知りたいですか。"},{"speaker":"M","ja":"町のバスについて調べるんですね。今乗っている人に、何時の便を増やしてほしいか聞けば、便利な時間が分かりそうです。"},{"speaker":"F","ja":"利用している人にも聞きますが、今回は乗っていない人の理由を知りたいんです。今の時刻だと間に合わない人は、車内では会えませんから。"},{"speaker":"M","ja":"乗客が少ない午後の便を減らすための調査ではなかったんですか。費用を考えると、空いている便を見直す必要もありますね。"},{"speaker":"F","ja":"費用も大切ですが、乗らないから必要ないとは限りません。買い物へ行けても帰りの便がないという人もいるかもしれないでしょう。"},{"speaker":"M","ja":"それなら、家を訪ねて一人ずつ聞くのですか。町には住んでいる人が多いので、かなり時間がかかりそうです。"},{"speaker":"F","ja":"まず町の広場で話を聞く予定です。使う人の数だけでは分からない不便を見つけてから、時刻や道順を考え直したいんです。"},{"speaker":"N","ja":"女の人はバスの調査で何を特に知りたいですか。"}]', 'Người dẫn: Trong khảo sát xe buýt, người phụ nữ đặc biệt muốn biết điều gì?\nNam: Bạn khảo sát xe buýt thị trấn nhỉ. Hỏi người đang đi muốn tăng chuyến giờ nào sẽ biết giờ tiện.\nNữ: Tôi cũng hỏi người dùng, nhưng lần này muốn biết vì sao có người không đi. Người không kịp giờ hiện tại thì không gặp được trên xe.\nNam: Không phải khảo sát để giảm chuyến chiều ít khách sao? Xét chi phí cũng cần xem lại chuyến vắng.\nNữ: Chi phí quan trọng nhưng không đi không đồng nghĩa không cần. Có thể có người đi mua sắm được nhưng không có chuyến về.\nNam: Vậy sẽ thăm từng nhà hỏi à? Thị trấn đông dân, chắc mất khá nhiều thời gian.\nNữ: Trước tiên tôi định hỏi ở quảng trường. Tôi muốn tìm bất tiện không thể biết chỉ qua số người dùng rồi xem lại giờ và tuyến.\nNgười dẫn: Trong khảo sát xe buýt, người phụ nữ đặc biệt muốn biết điều gì?', NULL, '[{"expression":"乗客","reading":"じょうきゃく","meaning_vi":"hành khách; hành khách trên phương tiện"},{"expression":"費用","reading":"ひよう","meaning_vi":"chi phí; chi phí nói chung; khoản chi phục vụ công việc"}]', 387, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-008', 'N3-L-POINT', 'N3', 'LISTENING', 8, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして祖父の話を録音することにしましたか。"},{"speaker":"M","ja":"おじいさんの昔の話を、町の本にまとめるそうですね。メモを取るだけでは、聞いたことを全部覚えておけないから録音するんですか。"},{"speaker":"F","ja":"内容だけならメモでも残せます。でも、言葉を探す間や笑い方にも、その人らしさがあるでしょう。文字にすると消えてしまう部分を残したいんです。"},{"speaker":"M","ja":"録音しておけば、後で文章を書く時も便利ですね。何度も質問せずに済むので、おじいさんを疲れさせないためにもよさそうです。"},{"speaker":"F","ja":"一度に長く話してもらうつもりはありません。短い話を少しずつ聞きます。早く本を作るより、声で伝わる感じを大切にしたいので。"},{"speaker":"M","ja":"その声は本を買った人なら誰でも聞けるようにするんですか。自分だけの話もあるから、おじいさんに確かめた方がいいですね。"},{"speaker":"F","ja":"公開する物は、必ず本人と一緒に選びます。話の内容だけでなく、どんな人が話しているのかも伝えられる記録にしたいんです。"},{"speaker":"N","ja":"女の人はどうして祖父の話を録音することにしましたか。"}]', 'Người dẫn: Vì sao người phụ nữ quyết định thu âm lời kể của ông?\nNam: Bạn sẽ gom chuyện ngày xưa của ông thành sách thị trấn nhỉ. Thu âm vì chỉ ghi chú thì không nhớ hết sao?\nNữ: Chỉ nội dung thì ghi chú cũng lưu được. Nhưng khoảng dừng tìm từ hay cách cười cũng có nét riêng. Tôi muốn giữ phần biến mất khi thành chữ.\nNam: Thu âm tiện lúc viết lại nhỉ. Không cần hỏi lặp, cũng giúp ông đỡ mệt.\nNữ: Tôi không định nhờ ông nói lâu một lần. Tôi nghe từng chuyện ngắn. Tôi muốn coi trọng cảm giác truyền qua giọng hơn làm sách nhanh.\nNam: Ai mua sách cũng được nghe giọng đó sao? Có chuyện riêng nên cần hỏi ông nhỉ.\nNữ: Phần công khai nhất định chọn cùng ông. Tôi muốn làm tư liệu truyền được không chỉ nội dung mà cả con người đang kể.\nNgười dẫn: Vì sao người phụ nữ quyết định thu âm lời kể của ông?', NULL, '[{"expression":"録音","reading":"ろくおん","meaning_vi":"ghi âm"},{"expression":"記録","reading":"きろく","meaning_vi":"ghi chép; kỷ lục; kỉ lục"}]', 416, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-009', 'N3-L-POINT', 'N3', 'LISTENING', 9, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして子供の大会で順位をつけないことにしましたか。"},{"speaker":"M","ja":"今年の工作大会は、一位から三位まで賞を出さないんですね。参加する子供が多くて、選ぶのに時間がかかるからですか。"},{"speaker":"F","ja":"選ぶ時間より、子供たちが同じような物ばかり作るようになったことが気になったんです。去年の一位に似せればいいと思っているようで。"},{"speaker":"M","ja":"賞品を用意するお金も必要ですし、なくせば準備が楽になりますね。作品を飾るだけにすれば、係の人も減らせそうです。"},{"speaker":"F","ja":"賞品の代わりに全員へ材料を渡すので、お金は同じくらいかかります。それぞれが面白いと思った工夫を、自由に試してほしいんです。"},{"speaker":"M","ja":"上手な子は目標がなくなって、つまらないと感じないでしょうか。誰かに認めてもらえる機会もあった方がよさそうですが。"},{"speaker":"F","ja":"最後に一人ずつ工夫した点を話してもらいます。ほかの作品より上か下かではなく、その子が考えたことに目を向けたいんです。"},{"speaker":"N","ja":"女の人はどうして子供の大会で順位をつけないことにしましたか。"}]', 'Người dẫn: Vì sao người phụ nữ quyết định không xếp hạng cuộc thi trẻ em?\nNam: Cuộc thi thủ công năm nay không trao nhất nhì ba nhỉ. Vì nhiều trẻ nên chọn mất thời gian sao?\nNữ: Tôi quan tâm hơn việc trẻ bắt đầu chỉ làm đồ giống nhau. Có vẻ các em nghĩ bắt chước giải nhất năm trước là được.\nNam: Cần tiền mua giải nữa, bỏ thì chuẩn bị nhẹ hơn. Chỉ trưng bày tác phẩm có thể giảm người phụ trách.\nNữ: Thay quà giải, chúng tôi phát vật liệu cho mọi em nên tiền gần như cũ. Tôi muốn các em tự do thử sáng kiến thấy thú vị.\nNam: Trẻ giỏi có thấy mất mục tiêu và chán không? Có cơ hội được công nhận cũng tốt.\nNữ: Cuối buổi từng em kể điểm sáng tạo. Tôi muốn nhìn điều em nghĩ ra thay vì hơn hay kém tác phẩm khác.\nNgười dẫn: Vì sao người phụ nữ quyết định không xếp hạng cuộc thi trẻ em?', NULL, '[{"expression":"作品","reading":"さくひん","meaning_vi":"tác phẩm; bà ～"},{"expression":"目標","reading":"もくひょう","meaning_vi":"mục tiêu; mục đích; đích cụ thể cần đạt"}]', 408, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-010', 'N3-L-POINT', 'N3', 'LISTENING', 10, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして山歩きのグループを二つに分けましたか。"},{"speaker":"M","ja":"来月の山歩きは、早く歩く人とゆっくり歩く人に分けるんですね。人数が増えて、一緒に乗るバスが足りなくなったのですか。"},{"speaker":"F","ja":"バスは一台で全員乗れます。前回、遅れないように急いだ人が、景色を見る余裕もなく疲れてしまったと聞いたんです。"},{"speaker":"M","ja":"一緒に歩けば、慣れている人が初めての人を助けられますね。分けると、ゆっくりのグループが道に迷う心配はありませんか。"},{"speaker":"F","ja":"両方に道を知っている係が付きます。上手かどうかで分けるのではなく、どんな速さなら楽しめるか、自分で選んでもらいます。"},{"speaker":"M","ja":"早いグループは山の上まで行って、ゆっくりのグループは途中で戻るのですか。見る場所が違うと、迷う人もいそうです。"},{"speaker":"F","ja":"行く場所も距離も同じです。出発時刻をずらして、帰りのバスでは一緒になります。誰かの速さに合わせるために無理をしてほしくないんです。"},{"speaker":"N","ja":"女の人はどうして山歩きのグループを二つに分けましたか。"}]', 'Người dẫn: Vì sao người phụ nữ chia đoàn đi bộ trên núi thành hai nhóm?\nNam: Chuyến đi núi tháng sau chia người đi nhanh và chậm nhỉ. Đông lên nên một xe buýt không đủ à?\nNữ: Một xe đủ tất cả. Lần trước có người cố đi nhanh để không tụt lại, mệt đến mức không thong thả ngắm cảnh được.\nNam: Đi cùng thì người quen giúp người mới được. Chia ra có lo nhóm chậm lạc đường không?\nNữ: Cả hai đều có người biết đường đi kèm. Không chia theo giỏi dở mà để mọi người tự chọn tốc độ mình thấy vui.\nNam: Nhóm nhanh lên đỉnh, nhóm chậm quay lại giữa đường à? Điểm xem khác thì có người phân vân.\nNữ: Điểm đến và quãng đường giống nhau. Giờ xuất phát lệch để cùng lên xe về. Tôi không muốn ai gắng quá chỉ để theo tốc độ người khác.\nNgười dẫn: Vì sao người phụ nữ chia đoàn đi bộ trên núi thành hai nhóm?', NULL, '[{"expression":"景色","reading":"けしき","meaning_vi":"phong cảnh; cảnh sắc"},{"expression":"距離","reading":"きょり","meaning_vi":"khoảng cách; cự li; cự ly"}]', 400, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-011', 'N3-L-POINT', 'N3', 'LISTENING', 11, NULL, NULL, '[{"speaker":"N","ja":"女の人は町の新聞のどこを変えるつもりですか。"},{"speaker":"M","ja":"町の新聞、新しい案では文字が大きくなっていますね。読む人から、写真をもっと大きくしてほしいという意見もありましたよね。"},{"speaker":"F","ja":"写真の大きさはそのままです。今回は一つの記事を短くして、文字を大きくします。必要な情報を見つける前に読むのをやめる人がいたので。"},{"speaker":"M","ja":"記事が短いと、町であった出来事を詳しく伝えられなくなりませんか。ページを増やせば、内容を減らさずに済みそうですが。"},{"speaker":"F","ja":"全部を紙に載せる必要はないと思います。日時や場所は分かりやすく紙に書き、詳しい話は希望する人がホームページで読めるようにします。"},{"speaker":"M","ja":"インターネットを使わない人もいますね。その人たちは、イベントの内容をもっと知りたくても、調べられなくなるのではありませんか。"},{"speaker":"F","ja":"電話で聞ける番号も載せます。入口になる紙面は読みやすくして、その先の詳しい情報へは、いくつかの方法で進めるようにしたいんです。"},{"speaker":"N","ja":"女の人は町の新聞のどこを変えるつもりですか。"}]', 'Người dẫn: Người phụ nữ định thay đổi điểm nào của báo thị trấn?\nNam: Bản mới của báo thị trấn chữ lớn hơn nhỉ. Cũng có ý kiến muốn ảnh lớn hơn đúng không?\nNữ: Cỡ ảnh giữ nguyên. Lần này rút bài và tăng cỡ chữ. Có người bỏ đọc trước khi tìm thấy thông tin cần.\nNam: Bài ngắn thì không kể chi tiết sự kiện được sao? Tăng trang thì khỏi giảm nội dung.\nNữ: Tôi nghĩ không cần đưa mọi thứ lên giấy. Ngày giờ và địa điểm ghi rõ trên giấy, ai muốn đọc chi tiết thì xem trang web.\nNam: Có người không dùng mạng. Họ muốn biết thêm về sự kiện thì có bị không tra được không?\nNữ: Tôi cũng in số gọi hỏi. Tôi muốn trang giấy mở đầu dễ đọc và có nhiều cách đi tiếp đến thông tin chi tiết.\nNgười dẫn: Người phụ nữ định thay đổi điểm nào của báo thị trấn?', NULL, '[{"expression":"記事","reading":"きじ","meaning_vi":"bài báo; bài viết; phóng sự"},{"expression":"情報","reading":"じょうほう","meaning_vi":"thông tin; tin tức"}]', 413, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-012', 'N3-L-POINT', 'N3', 'LISTENING', 12, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして事務所を駅前へ移さなかったのですか。"},{"speaker":"M","ja":"駅前の建物は契約しなかったんですね。今の事務所より家賃が安くて、通勤にも便利だと話していたので、意外でした。"},{"speaker":"F","ja":"社員には便利ですが、長く来てくださっているお客さんは、この近所に住んでいる方が多いんです。歩いて立ち寄れることを大事にしたくて。"},{"speaker":"M","ja":"駅前なら、新しいお客さんが増える可能性もありますね。今の建物は古いので、設備を直すお金も必要になるでしょう。"},{"speaker":"F","ja":"その費用は考えています。ただ、用事がなくても顔を見せてくれる人との関係は、お金だけでは比べられないと思うんです。"},{"speaker":"M","ja":"今の場所にいると、社員の通勤時間は長いままですね。駅から遠いことについて、不満は出ていませんか。"},{"speaker":"F","ja":"みんなには理由を説明しました。出勤の時間を相談できるようにもします。便利な場所へ行くより、今あるつながりを続けることを選びました。"},{"speaker":"N","ja":"女の人はどうして事務所を駅前へ移さなかったのですか。"}]', 'Người dẫn: Vì sao người phụ nữ không chuyển văn phòng ra trước ga?\nNam: Bạn không ký hợp đồng tòa nhà trước ga nhỉ. Trước nói thuê rẻ hơn, đi làm tiện nên tôi bất ngờ.\nNữ: Tiện cho nhân viên, nhưng nhiều khách lâu năm sống quanh đây. Tôi muốn coi trọng việc họ đi bộ ghé được.\nNam: Trước ga có thể thêm khách mới. Tòa hiện tại cũ, cũng cần tiền sửa thiết bị nhỉ.\nNữ: Tôi có tính chi phí đó. Nhưng quan hệ với người không có việc vẫn ghé chào không thể chỉ so bằng tiền.\nNam: Ở đây thì nhân viên vẫn đi làm xa. Có phàn nàn vì xa ga không?\nNữ: Tôi đã giải thích lý do, cũng cho trao đổi giờ đến làm. Tôi chọn giữ kết nối đang có hơn chuyển tới nơi tiện.\nNgười dẫn: Vì sao người phụ nữ không chuyển văn phòng ra trước ga?', NULL, '[{"expression":"関係","reading":"かんけい","meaning_vi":"quan hệ; mối quan hệ; sự liên quan"},{"expression":"家賃","reading":"やちん","meaning_vi":"tiền thuê nhà; tiền thuê"}]', 393, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-013', 'N3-L-POINT', 'N3', 'LISTENING', 13, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして道具を貸す前に一緒に使ってみる時間を作りましたか。"},{"speaker":"M","ja":"町で道具を貸すサービスを始めるんですね。借りる人に説明書を渡せば、自宅で読んでから使ってもらえるのではありませんか。"},{"speaker":"F","ja":"説明書も渡しますが、ここで一度使ってもらいます。知っているつもりで間違った使い方をすると、道具が壊れることもあるので。"},{"speaker":"M","ja":"返す時に傷を調べて、壊した人に払ってもらえばいいと思います。貸す前の説明が長いと、利用する人が減りませんか。"},{"speaker":"F","ja":"お金を払ってもらっても、使う途中で困ったことはなくなりません。最初に手を動かして、注意する所を自分で確かめる方が大切です。"},{"speaker":"M","ja":"道具の使い方を教える教室も開くのでしょうか。毎週決まった時間に集まるなら、参加できない人もいそうですね。"},{"speaker":"F","ja":"教室ではなく、借りる時の五分くらいです。面倒に感じる人もいると思いますが、家に帰ってから安心して使えるようにしておきたいんです。"},{"speaker":"N","ja":"女の人はどうして道具を貸す前に一緒に使ってみる時間を作りましたか。"}]', 'Người dẫn: Vì sao người phụ nữ thêm thời gian cùng dùng thử trước khi cho mượn dụng cụ?\nNam: Bạn mở dịch vụ cho mượn dụng cụ trong thị trấn nhỉ. Phát hướng dẫn thì người mượn có thể về đọc rồi dùng chứ?\nNữ: Vẫn phát nhưng tôi cho dùng một lần ở đây. Tưởng đã biết mà dùng sai thì có thể làm hỏng dụng cụ.\nNam: Lúc trả kiểm tra vết xước, ai làm hỏng thì trả tiền được mà. Hướng dẫn trước quá lâu có giảm người dùng không?\nNữ: Được trả tiền cũng không xóa được rắc rối lúc sử dụng. Ban đầu tự thao tác để kiểm tra điểm cần chú ý quan trọng hơn.\nNam: Có mở lớp hướng dẫn dụng cụ không? Nếu họp giờ cố định mỗi tuần thì có người không dự được.\nNữ: Không phải lớp, chỉ khoảng năm phút lúc mượn. Có người thấy phiền nhưng tôi muốn họ về nhà có thể yên tâm dùng.\nNgười dẫn: Vì sao người phụ nữ thêm thời gian cùng dùng thử trước khi cho mượn dụng cụ?', NULL, '[{"expression":"道具","reading":"どうぐ","meaning_vi":"dụng cụ; đạo cụ"},{"expression":"教室","reading":"きょうしつ","meaning_vi":"phòng học; lớp học"}]', 414, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-014', 'N3-L-POINT', 'N3', 'LISTENING', 14, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして見学の後に自由時間を入れましたか。"},{"speaker":"M","ja":"工場見学の予定に、最後の自由時間が増えていますね。案内する方の都合で、説明を短くすることになったんですか。"},{"speaker":"F","ja":"説明の時間は変わりません。全員で回った後、自分が気になった場所へ戻れるようにしました。一度聞いただけでは、質問が思いつかないこともありますから。"},{"speaker":"M","ja":"お土産の店が新しくできたそうですね。買い物の時間が足りないという意見が出たので、自由時間を作ったのかと思いました。"},{"speaker":"F","ja":"店にも行けますが、それが目的ではありません。説明を聞いて少し考えてから、自分の疑問を確かめる時間が必要だと思ったんです。"},{"speaker":"M","ja":"自由に歩くと、帰りのバスに遅れる人が出ませんか。工場は広いので、どこに戻ればいいか分からなくなりそうです。"},{"speaker":"F","ja":"行ける範囲と集合場所は紙で知らせます。案内通りに一度回って終わるより、一人ひとりが関心を持ったことを深められる見学にしたいです。"},{"speaker":"N","ja":"女の人はどうして見学の後に自由時間を入れましたか。"}]', 'Người dẫn: Vì sao người phụ nữ thêm thời gian tự do sau buổi tham quan?\nNam: Lịch tham quan nhà máy thêm thời gian tự do cuối buổi nhỉ. Người hướng dẫn có việc nên rút thời gian giải thích à?\nNữ: Thời gian giải thích không đổi. Sau khi đi cùng đoàn, mọi người được quay lại chỗ quan tâm. Nghe một lần có khi chưa nghĩ ra câu hỏi.\nNam: Nghe mới có quầy lưu niệm. Tôi tưởng vì có ý kiến thiếu giờ mua sắm nên thêm giờ tự do.\nNữ: Có thể đi quầy nhưng đó không phải mục đích. Tôi nghĩ cần thời gian nghe, suy nghĩ rồi xác nhận thắc mắc của mình.\nNam: Tự đi có ai trễ xe về không? Nhà máy rộng, có thể không biết quay lại đâu.\nNữ: Tôi thông báo phạm vi được đi và chỗ tập trung bằng giấy. Tôi muốn chuyến tham quan giúp từng người tìm hiểu điều mình quan tâm hơn chỉ theo hướng dẫn một vòng rồi xong.\nNgười dẫn: Vì sao người phụ nữ thêm thời gian tự do sau buổi tham quan?', NULL, '[{"expression":"見学","reading":"けんがく","meaning_vi":"tham quan (để học hỏi)"},{"expression":"関心","reading":"かんしん","meaning_vi":"sự quan tâm; quan tâm; đam mê"}]', 409, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-015', 'N3-L-POINT', 'N3', 'LISTENING', 15, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして商品の箱を同じ大きさにしなかったのですか。"},{"speaker":"M","ja":"商品の箱を一種類にすれば、注文する時に楽ですね。大きい箱なら、小さい物もまとめて入れられるので、便利だと思いますが。"},{"speaker":"F","ja":"作業は楽になりますが、中が空きすぎると紙をたくさん詰める必要があります。受け取る人が捨てる物を、できるだけ減らしたいんです。"},{"speaker":"M","ja":"箱を何種類も用意すると、置き場所が必要になりますね。送料も大きさで変わるので、安く送るために分けるのでしょうか。"},{"speaker":"F","ja":"送料が安くなる場合もありますが、一番の理由ではありません。前にお客さんから、商品より箱が大きくて片付けが大変だと言われました。"},{"speaker":"M","ja":"箱を全く使わず、袋だけにする方法もありますね。割れやすい商品以外は、その方が用意する物も少なくなりそうです。"},{"speaker":"F","ja":"袋で大丈夫な物はそうします。ただ、壊れないことは守りたいので、商品に合わせて選びます。こちらの便利さだけで決めないようにしたいんです。"},{"speaker":"N","ja":"女の人はどうして商品の箱を同じ大きさにしなかったのですか。"}]', 'Người dẫn: Vì sao người phụ nữ không dùng hộp cùng kích thước cho hàng hóa?\nNam: Chỉ một loại hộp thì đặt mua dễ nhỉ. Hộp lớn cho được nhiều món nhỏ, tôi nghĩ tiện.\nNữ: Thao tác dễ nhưng quá trống thì cần nhét nhiều giấy. Tôi muốn giảm tối đa đồ người nhận phải vứt.\nNam: Chuẩn bị nhiều cỡ cần chỗ chứa. Phí vận chuyển theo cỡ, vậy phân loại để gửi rẻ à?\nNữ: Có trường hợp phí giảm nhưng không phải lý do chính. Trước khách nói hộp lớn hơn hàng, dọn rất vất vả.\nNam: Có thể không dùng hộp, chỉ dùng túi. Ngoài hàng dễ vỡ thì như vậy ít thứ phải chuẩn bị hơn.\nNữ: Món dùng túi được sẽ dùng. Nhưng vẫn phải giữ hàng không vỡ nên chọn theo sản phẩm. Tôi không muốn chỉ quyết theo tiện lợi bên mình.\nNgười dẫn: Vì sao người phụ nữ không dùng hộp cùng kích thước cho hàng hóa?', NULL, '[{"expression":"商品","reading":"しょうひん","meaning_vi":"hàng hóa; sản phẩm"},{"expression":"送料","reading":"そうりょう","meaning_vi":"phí vận chuyển; phí gửi; cước phí"}]', 418, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-016', 'N3-L-POINT', 'N3', 'LISTENING', 16, NULL, NULL, '[{"speaker":"N","ja":"女の人は翻訳のチームで何を先に決めたいですか。"},{"speaker":"M","ja":"旅行案内を三人で訳すんですね。ページを同じ数ずつ分けて、一人ずつ好きな所から始めれば、早く終わるのではありませんか。"},{"speaker":"F","ja":"分担する前に、同じ場所や乗り物を何と呼ぶか決めたいんです。前回は人によって言葉が違って、別の物のように見えてしまいました。"},{"speaker":"M","ja":"最後に一人が全部読んで直せば、言い方をそろえられますね。最初から話し合うと、作業を始めるのが遅くなりませんか。"},{"speaker":"F","ja":"後で直すと、地図や表の中まで探さなければなりません。よく出る言葉だけでも先に決めておく方が、読む人の混乱も防げます。"},{"speaker":"M","ja":"文章の長さや、丁寧な言い方も全部同じにするんですか。担当する内容によっては、少し変えた方が自然な気がします。"},{"speaker":"F","ja":"細かい表現は内容に合わせていいです。まず、同じ物には同じ名前を使うという約束をしてから、それぞれのページを担当してもらいます。"},{"speaker":"N","ja":"女の人は翻訳のチームで何を先に決めたいですか。"}]', 'Người dẫn: Người phụ nữ muốn nhóm dịch thống nhất điều gì trước?\nNam: Ba người dịch hướng dẫn du lịch nhỉ. Chia đều trang rồi mỗi người bắt đầu chỗ thích thì xong nhanh chứ?\nNữ: Trước khi chia, tôi muốn quyết định cách gọi cùng một địa điểm hay phương tiện. Lần trước mỗi người dùng từ khác, trông như những thứ khác nhau.\nNam: Cuối cùng một người đọc sửa hết thì thống nhất được. Bàn từ đầu có làm bắt đầu chậm không?\nNữ: Sửa sau phải tìm cả trong bản đồ, bảng. Chốt trước ít nhất từ hay xuất hiện sẽ tránh độc giả bối rối.\nNam: Độ dài câu và mức lịch sự cũng phải giống hết à? Tùy nội dung phụ trách, thay chút có vẻ tự nhiên hơn.\nNữ: Cách diễn đạt chi tiết tùy nội dung được. Trước tiên thống nhất cùng thứ dùng cùng tên rồi mỗi người nhận trang.\nNgười dẫn: Người phụ nữ muốn nhóm dịch thống nhất điều gì trước?', NULL, '[{"expression":"内容","reading":"ないよう","meaning_vi":"nội dung; nội dung thông tin; thứ chứa bên trong"},{"expression":"訳す","reading":"やくす","meaning_vi":"dịch; dịch (phiên dịch; thông dịch)"}]', 395, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-017', 'N3-L-POINT', 'N3', 'LISTENING', 17, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして忘れ物の写真を全部公開しないのですか。"},{"speaker":"M","ja":"駅の忘れ物をホームページに載せるんですね。中身まで写真に撮れば、持ち主がすぐ自分の物だと分かって、便利だと思います。"},{"speaker":"F","ja":"見つけやすさは大事ですが、全部見せると、本当の持ち主かどうか確かめにくくなります。本人しか知らない特徴を残しておきたいんです。"},{"speaker":"M","ja":"財布の中には名前や住所も入っていますから、個人の情報を見せないようにする必要もありますね。外側だけなら大丈夫ですか。"},{"speaker":"F","ja":"外側でも、特徴を全部は載せません。問い合わせが来た時に、色以外の印や中身を聞いて、間違った人に渡さないようにします。"},{"speaker":"M","ja":"写真を少なくすれば、ページを作る時間も短くなりますね。駅員の仕事を減らすための方法なのかと思っていました。"},{"speaker":"F","ja":"確認する仕事はむしろ残ります。それでも、早く数を減らすより、正しい相手に返すことを優先したいので、情報の出し方を考えているんです。"},{"speaker":"N","ja":"女の人はどうして忘れ物の写真を全部公開しないのですか。"}]', 'Người dẫn: Vì sao người phụ nữ không công khai toàn bộ ảnh đồ thất lạc?\nNam: Nhà ga sẽ đăng đồ thất lạc lên web nhỉ. Chụp cả bên trong thì chủ nhận ngay được đồ mình, tiện hơn.\nNữ: Dễ tìm quan trọng nhưng hiện hết thì khó xác nhận ai thật là chủ. Tôi muốn giữ lại đặc điểm chỉ người đó biết.\nNam: Trong ví có tên địa chỉ nên cũng phải tránh lộ thông tin riêng. Chỉ ngoài thì được à?\nNữ: Ngay ngoài cũng không đăng hết đặc điểm. Khi có liên hệ sẽ hỏi dấu ngoài màu sắc hoặc đồ bên trong để không trả nhầm.\nNam: Ít ảnh thì làm trang cũng nhanh. Tôi tưởng đây là cách giảm việc cho nhân viên ga.\nNữ: Việc xác nhận vẫn còn. Dù vậy tôi ưu tiên trả đúng người hơn giảm nhanh số đồ nên cân nhắc cách đưa thông tin.\nNgười dẫn: Vì sao người phụ nữ không công khai toàn bộ ảnh đồ thất lạc?', NULL, '[{"expression":"特徴","reading":"とくちょう","meaning_vi":"đặc trưng; đặc tính; đặc điểm"},{"expression":"確認","reading":"かくにん","meaning_vi":"việc kiểm lại; xác nhận; xác minh"}]', 409, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-018', 'N3-L-POINT', 'N3', 'LISTENING', 18, NULL, NULL, '[{"speaker":"N","ja":"女の人はどうして会場で食べ物を配る方法を変えましたか。"},{"speaker":"M","ja":"町の交流会では、料理を一人分ずつ箱に入れて渡す予定でしたよね。机に並べて自分で取る形にすると、準備が大変ではありませんか。"},{"speaker":"F","ja":"少し手間は増えますが、食べられる物を自分で選べるようにしたいんです。前は苦手な物が多くて、ほとんど食べられない人がいました。"},{"speaker":"M","ja":"料理を多く取る人と少なく取る人が出ると、足りなくなるかもしれませんね。量を同じにしておく方が公平ではないでしょうか。"},{"speaker":"F","ja":"一人分の目安は示します。でも、同じ物を同じ量で渡すことだけが公平だとは思いません。材料も書いて、選ぶ時に確認できるようにします。"},{"speaker":"M","ja":"料理の種類を増やすために、参加費も上げるのですか。前と同じ料金なら、用意できる物に限りがありますね。"},{"speaker":"F","ja":"料金も料理の数も変えません。受け取り方を変えるだけです。用意した分を無理に食べるのではなく、自分に合う組み合わせで楽しんでほしいんです。"},{"speaker":"N","ja":"女の人はどうして会場で食べ物を配る方法を変えましたか。"}]', 'Người dẫn: Vì sao người phụ nữ thay đổi cách phát đồ ăn ở địa điểm tổ chức?\nNam: Buổi giao lưu thị trấn định chia mỗi người một hộp món ăn nhỉ. Bày bàn cho tự lấy thì chuẩn bị vất vả không?\nNữ: Tốn công hơn chút nhưng tôi muốn mọi người tự chọn món ăn được. Trước có người nhiều món không thích nên gần như không ăn được.\nNam: Có người lấy nhiều ít khác nhau, có thể thiếu nhỉ. Chia cùng lượng có công bằng hơn không?\nNữ: Tôi sẽ ghi lượng tham khảo mỗi người. Nhưng tôi không nghĩ chỉ phát cùng món cùng lượng mới là công bằng. Tôi cũng ghi nguyên liệu để kiểm tra khi chọn.\nNam: Tăng loại món thì tăng phí tham gia sao? Cùng phí cũ thì giới hạn thứ chuẩn bị được.\nNữ: Phí và số món không đổi, chỉ đổi cách nhận. Tôi muốn mọi người thưởng thức tổ hợp hợp mình thay vì cố ăn phần đã chia.\nNgười dẫn: Vì sao người phụ nữ thay đổi cách phát đồ ăn ở địa điểm tổ chức?', NULL, '[{"expression":"材料","reading":"ざいりょう","meaning_vi":"nguyên liệu (nấu ăn); vật liệu"},{"expression":"料金","reading":"りょうきん","meaning_vi":"cước phí; phí"}]', 417, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-019', 'N3-L-POINT', 'N3', 'LISTENING', 19, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして練習の動画を短く分けましたか。"},{"speaker":"F","ja":"バスケットボールの練習を撮った動画、全部で三十分ありますね。短く分けるのは、携帯で送る時に時間がかかるからですか。"},{"speaker":"M","ja":"送ることは問題ありません。ただ、長い動画を一度見るだけだと、どこを直すか分からなくなる人が多いんです。一つの動きだけを見てほしくて。"},{"speaker":"F","ja":"試合で点が入った場面だけ集めれば、見ていて楽しいですね。失敗した所はあまり見たくない人もいるでしょう。"},{"speaker":"M","ja":"成功だけを残すつもりはありません。同じ動きのよかった時と、うまくいかなかった時を並べて、自分で違いに気づけるようにします。"},{"speaker":"F","ja":"先生が全部説明するより、自分で考えるんですね。見る時間が短い分、実際に練習する時間を増やすこともできそうです。"},{"speaker":"M","ja":"練習の長さは変えません。動画を止めて考える時間も必要なので。一度にたくさん直そうとせず、次に意識する点を一つ決めてもらいたいんです。"},{"speaker":"N","ja":"男の人はどうして練習の動画を短く分けましたか。"}]', 'Người dẫn: Vì sao người đàn ông chia video luyện tập thành đoạn ngắn?\nNữ: Video tập bóng rổ dài tổng ba mươi phút nhỉ. Chia ngắn vì gửi điện thoại mất thời gian à?\nNam: Gửi không có vấn đề. Nhưng chỉ xem video dài một lần, nhiều người không biết cần sửa chỗ nào. Tôi muốn họ xem chỉ một động tác.\nNữ: Gom cảnh ghi điểm thì xem vui. Có người chắc không muốn xem chỗ thất bại.\nNam: Tôi không định giữ mỗi thành công. Tôi đặt cạnh lần tốt và lần chưa tốt của cùng động tác để họ tự nhận ra khác biệt.\nNữ: Vậy tự nghĩ thay vì giáo viên giải thích hết. Xem ngắn thì tăng thời gian luyện thực tế được nhỉ.\nNam: Thời gian tập không đổi. Cũng cần dừng video suy nghĩ. Tôi muốn họ chọn một điểm chú ý lần sau thay vì sửa nhiều thứ cùng lúc.\nNgười dẫn: Vì sao người đàn ông chia video luyện tập thành đoạn ngắn?', NULL, '[{"expression":"場面","reading":"ばめん","meaning_vi":"cảnh; phân cảnh; tình huống"},{"expression":"意識","reading":"いしき","meaning_vi":"ý thức; tri giác"}]', 402, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-020', 'N3-L-POINT', 'N3', 'LISTENING', 20, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうしてオンライン授業でカメラを必ずつけなくてもよいことにしましたか。"},{"speaker":"F","ja":"新しいオンライン授業では、顔を見せなくても参加できるんですね。学生の様子が分からないと、理解しているか確かめにくくありませんか。"},{"speaker":"M","ja":"反応は声や文字でも確認できます。家の中を見られたくないために、授業そのものを休んでしまう学生がいると知ったんです。"},{"speaker":"F","ja":"通信が遅い人には、映像を送らない方が便利ですね。パソコンが古くても使えるようにすることが、一番の理由ですか。"},{"speaker":"M","ja":"通信の問題もありますが、それだけではありません。学ぶことと関係のない心配で、参加する機会を失ってほしくないんです。"},{"speaker":"F","ja":"顔を出さない学生が、授業中に別のことをしていても分からなくなりませんか。自由にすると心配な点もありますね。"},{"speaker":"M","ja":"途中で質問に答えたり、二人で話したりする時間は作ります。参加しているかは活動で確かめて、顔を映すことだけで判断しないつもりです。"},{"speaker":"N","ja":"男の人はどうしてオンライン授業でカメラを必ずつけなくてもよいことにしましたか。"}]', 'Người dẫn: Vì sao người đàn ông cho phép không bật camera trong lớp trực tuyến?\nNữ: Lớp trực tuyến mới không lộ mặt vẫn tham gia được nhỉ. Không nhìn trạng thái học viên thì khó biết có hiểu không?\nNam: Tôi xác nhận phản ứng qua tiếng hoặc chữ được. Tôi biết có học viên nghỉ hẳn vì không muốn người khác nhìn trong nhà.\nNữ: Người mạng chậm không gửi hình sẽ tiện. Lý do chính là dùng được máy cũ à?\nNam: Cũng có vấn đề đường truyền, nhưng không chỉ thế. Tôi không muốn họ mất cơ hội tham gia vì nỗi lo không liên quan học tập.\nNữ: Nếu không lộ mặt mà làm việc khác trong giờ thì không biết sao? Tự do vậy có điểm đáng lo.\nNam: Tôi vẫn có thời gian trả lời câu hỏi và nói theo cặp. Tôi kiểm tra tham gia qua hoạt động, không chỉ đánh giá bằng việc hiện mặt.\nNgười dẫn: Vì sao người đàn ông cho phép không bật camera trong lớp trực tuyến?', NULL, '[{"expression":"機会","reading":"きかい","meaning_vi":"cơ hội; dịp; máy móc"},{"expression":"通信","reading":"つうしん","meaning_vi":"liên lạc; truyền thông; truyền dữ liệu"}]', 427, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-021', 'N3-L-POINT', 'N3', 'LISTENING', 21, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして店を開く前に一か月だけ試してもらうのですか。"},{"speaker":"F","ja":"空いている店を若い人に貸す計画ですが、最初の一か月は試しに使えるんですね。家賃を安くすれば、そのまま契約する人も増えそうですが。"},{"speaker":"M","ja":"安さだけで始めても、町のお客さんに合うか分からないでしょう。実際に売ってみて、自分が続けたい店と求められる物の違いを知ってほしいんです。"},{"speaker":"F","ja":"試す間に看板や棚を全部そろえるのは大変ですね。準備にお金がかかると、結局やめられなくなるのではありませんか。"},{"speaker":"M","ja":"使える棚は町で貸しますし、大きな工事はしません。始める前に細かく計画を書くだけでは、分からないことを確かめる期間にしたいんです。"},{"speaker":"F","ja":"一か月で売り上げが一番多かった人だけに、店を貸すのでしょうか。それなら、安売りをする人が有利になりそうですね。"},{"speaker":"M","ja":"競争で選ぶためではありません。続けるか、商品を変えるか、本人が考える材料にしてもらいます。長く借りる前に試せることが大切なんです。"},{"speaker":"N","ja":"男の人はどうして店を開く前に一か月だけ試してもらうのですか。"}]', 'Người dẫn: Vì sao người đàn ông cho thử một tháng trước khi mở cửa hàng?\nNữ: Kế hoạch cho người trẻ thuê tiệm trống có tháng dùng thử nhỉ. Hạ giá thuê thì người ký ngay cũng tăng chứ?\nNam: Bắt đầu chỉ vì rẻ thì chưa biết hợp khách thị trấn không. Tôi muốn họ bán thật để biết khác biệt giữa cửa hàng mình muốn duy trì và thứ được cần.\nNữ: Thử mà phải sắm biển và kệ đầy đủ rất vất vả. Tốn tiền chuẩn bị rồi có phải cuối cùng không bỏ được?\nNam: Thị trấn cho mượn kệ dùng được, không sửa lớn. Tôi muốn đây là thời gian kiểm tra điều không biết chỉ bằng viết kế hoạch chi tiết.\nNữ: Chỉ cho người doanh thu cao nhất tháng đó thuê à? Vậy người giảm giá sẽ lợi.\nNam: Không nhằm chọn bằng cạnh tranh. Tôi muốn họ dùng làm cơ sở tự nghĩ có tiếp tục hay đổi hàng. Quan trọng là thử được trước khi thuê dài.\nNgười dẫn: Vì sao người đàn ông cho thử một tháng trước khi mở cửa hàng?', NULL, '[{"expression":"期間","reading":"きかん","meaning_vi":"khoảng thời gian; kỳ; thời kỳ"},{"expression":"売り上げ","reading":"うりあげ","meaning_vi":"doanh thu; doanh thu bán ra; bán đắt"}]', 430, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-022', 'N3-L-POINT', 'N3', 'LISTENING', 22, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして商品の作り方を店で紹介していますか。"},{"speaker":"F","ja":"手作りのかばんの横に、作業の写真を置いたんですね。自分でも作ってみたいというお客さんから、教室を開いてほしいと言われたんですか。"},{"speaker":"M","ja":"教室の予定はありません。値段だけを見て高いと思う人にも、一つ作るまでの手間を知ってもらいたいんです。材料だけの値段ではないので。"},{"speaker":"F","ja":"職人さんの顔が見えると、親しみも感じますね。有名な人が作った商品だと分かれば、たくさん売れるかもしれません。"},{"speaker":"M","ja":"有名かどうかを伝えたいのではありません。細かい所を何度も直して仕上げる仕事が、長く使える理由につながっていると分かってほしいんです。"},{"speaker":"F","ja":"作るのに何日かかるかも書いてありますね。注文した人に、商品が届くまで待ってもらうための説明にもなりそうです。"},{"speaker":"M","ja":"注文の時期は別に案内します。今あるかばんを選ぶ時に、見た目と金額だけでなく、その値段になった理由も考えてもらえればうれしいです。"},{"speaker":"N","ja":"男の人はどうして商品の作り方を店で紹介していますか。"}]', 'Người dẫn: Vì sao người đàn ông giới thiệu cách làm sản phẩm tại cửa hàng?\nNữ: Anh đặt ảnh thao tác cạnh túi thủ công nhỉ. Có khách muốn tự làm nên yêu cầu mở lớp à?\nNam: Không có kế hoạch lớp. Tôi muốn người thấy giá cao cũng biết công sức để làm một chiếc. Giá không chỉ là nguyên liệu.\nNữ: Thấy mặt thợ tạo thân thiện nhỉ. Nếu biết người nổi tiếng làm thì có thể bán nhiều.\nNam: Tôi không muốn nói nổi tiếng hay không. Tôi muốn họ hiểu việc sửa kỹ chi tiết nhiều lần để hoàn thiện liên quan lý do dùng bền.\nNữ: Có ghi số ngày làm nữa. Cũng giải thích để người đặt chờ hàng nhỉ.\nNam: Thời gian đặt sẽ hướng dẫn riêng. Khi chọn túi có sẵn, tôi vui nếu họ nghĩ cả lý do giá đó, không chỉ hình thức và số tiền.\nNgười dẫn: Vì sao người đàn ông giới thiệu cách làm sản phẩm tại cửa hàng?', NULL, '[{"expression":"手間","reading":"てま","meaning_vi":"công sức; thời gian bỏ ra; thời gian"},{"expression":"金額","reading":"きんがく","meaning_vi":"số tiền; kim ngạch"}]', 418, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-023', 'N3-L-POINT', 'N3', 'LISTENING', 23, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして古い写真に正確な年を書かないのですか。"},{"speaker":"F","ja":"町の昔の写真を見せるんですね。この一枚だけ年代が広く書いてありますが、調べる時間が足りなかったんですか。"},{"speaker":"M","ja":"調べましたが、人によって覚えている年が違うんです。一番多かった答えをそのまま書くと、確かな事実のように伝わってしまいます。"},{"speaker":"F","ja":"建物が完成した年を調べれば、写真を撮った時期も分かるのではありませんか。昔の新聞に記事が残っていそうです。"},{"speaker":"M","ja":"建物より後だとは分かりました。でも、それだけでは何年か決められません。分かっている範囲と、まだ分からないことを分けて示したいんです。"},{"speaker":"F","ja":"細かい説明が多いと、見る人が疲れそうですね。写真だけ飾って、年について何も書かない方法もありますよ。"},{"speaker":"M","ja":"時期の目安がある方が町の変化を想像しやすいので、全部は省きません。新しい資料が見つかったら直せるように、今の確かさも伝えておきます。"},{"speaker":"N","ja":"男の人はどうして古い写真に正確な年を書かないのですか。"}]', 'Người dẫn: Vì sao người đàn ông không ghi năm chính xác cho ảnh cũ?\nNữ: Anh trưng bày ảnh xưa thị trấn nhỉ. Chỉ tấm này ghi khoảng năm rộng, vì thiếu thời gian tra sao?\nNam: Tôi tra rồi nhưng mỗi người nhớ năm khác. Ghi ngay câu trả lời nhiều nhất sẽ khiến nó được hiểu như sự thật chắc chắn.\nNữ: Tra năm xây xong tòa nhà thì biết lúc chụp chứ? Có thể còn bài báo cũ.\nNam: Tôi biết ảnh sau khi xây nhưng chỉ vậy chưa quyết được năm. Tôi muốn tách phạm vi biết với điều chưa biết.\nNữ: Nhiều giải thích chi tiết thì người xem mệt. Chỉ treo ảnh, không ghi gì về năm cũng được.\nNam: Có mốc gần đúng dễ hình dung thay đổi của thị trấn nên tôi không bỏ hết. Tôi sẽ truyền cả mức chắc chắn hiện giờ để có thể sửa khi tìm được tài liệu mới.\nNgười dẫn: Vì sao người đàn ông không ghi năm chính xác cho ảnh cũ?', NULL, '[{"expression":"事実","reading":"じじつ","meaning_vi":"sự thật; tình hình thực tế"},{"expression":"範囲","reading":"はんい","meaning_vi":"phạm vi; phạm vi trừu tượng hoặc kích thước"}]', 402, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-024', 'N3-L-POINT', 'N3', 'LISTENING', 24, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして服を受け取る人に自分で選んでもらいますか。"},{"speaker":"F","ja":"集まった服を必要な人に渡す活動ですが、家族の人数と体の大きさを聞いて、こちらで袋に入れておけば早いのではありませんか。"},{"speaker":"M","ja":"早くはできますが、着たい色や形は人によって違います。必要としている人だから何でもいい、とこちらで決めたくないんです。"},{"speaker":"F","ja":"自由に選ぶと、人気の色だけ先になくなりそうですね。全員に同じ数を渡すことも難しくなるのではありませんか。"},{"speaker":"M","ja":"一人が選べる数は決めますし、服は何回かに分けて並べます。その中で、自分で決める機会は残しておきたいんです。"},{"speaker":"F","ja":"試着する場所まで用意するのですか。選ぶ時間が長くなれば、手伝う人も増やす必要がありそうですね。"},{"speaker":"M","ja":"鏡と、着てみられる小さい場所を作ります。手間はかかりますが、もらう人がただ渡されるだけにならず、普段の買い物のように選べることが大事です。"},{"speaker":"N","ja":"男の人はどうして服を受け取る人に自分で選んでもらいますか。"}]', 'Người dẫn: Vì sao người đàn ông để người nhận quần áo tự chọn?\nNữ: Hoạt động trao quần áo quyên góp cho người cần, nếu hỏi số người gia đình và cỡ rồi mình chia túi sẵn sẽ nhanh hơn chứ?\nNam: Nhanh hơn nhưng màu và kiểu muốn mặc khác nhau. Tôi không muốn bên mình quyết rằng vì họ cần nên gì cũng được.\nNữ: Tự chọn thì màu được thích hết trước. Có khó phát cùng số lượng cho mọi người không?\nNam: Tôi giới hạn số mỗi người chọn và bày đồ thành nhiều đợt. Trong phạm vi đó tôi muốn giữ cơ hội tự quyết.\nNữ: Chuẩn bị cả chỗ thử à? Chọn lâu thì cần thêm người hỗ trợ nhỉ.\nNam: Tôi tạo chỗ nhỏ thử với gương. Tốn công nhưng quan trọng là người nhận được chọn như mua sắm thường ngày, không chỉ được đưa cho.\nNgười dẫn: Vì sao người đàn ông để người nhận quần áo tự chọn?', NULL, '[{"expression":"手間","reading":"てま","meaning_vi":"công sức; thời gian bỏ ra; thời gian"},{"expression":"普段","reading":"ふだん","meaning_vi":"thường ngày; thường xuyên; đều đặn"}]', 396, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-025', 'N3-L-POINT', 'N3', 'LISTENING', 25, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして仕事の予定を時間ではなく作業ごとに書くことにしましたか。"},{"speaker":"F","ja":"今週の予定表は、何時から何時までというところがないんですね。働く時間を自由にすれば、急な用事にも対応しやすくなりますね。"},{"speaker":"M","ja":"自由にする部分もありますが、一番の目的は、何を終えれば次の人が進めるか分かるようにすることです。時間だけでは仕事のつながりが見えなくて。"},{"speaker":"F","ja":"同じ作業でも人によってかかる時間が違うので、遅い人が誰かは分からなくなりませんか。評価する時に困りそうです。"},{"speaker":"M","ja":"速さを比べるための表ではありません。自分の仕事が終わっても、必要な資料を渡し忘れたら、ほかの人は待ったままになります。"},{"speaker":"F","ja":"では、終わった作業に印をつけるだけでいいのですね。何時までに終わらせるかという約束も、なくなるのでしょうか。"},{"speaker":"M","ja":"締め切りは書きますし、次に渡す相手も書きます。長く働いたことより、チームの仕事を前へ進める結果が分かる表にしたいんです。"},{"speaker":"N","ja":"男の人はどうして仕事の予定を時間ではなく作業ごとに書くことにしましたか。"}]', 'Người dẫn: Vì sao người đàn ông quyết định ghi kế hoạch theo nhiệm vụ thay vì theo giờ?\nNữ: Bảng tuần này không có ô từ mấy giờ đến mấy giờ nhỉ. Linh hoạt giờ làm thì dễ xử lý việc đột xuất.\nNam: Có phần linh hoạt nhưng mục tiêu lớn nhất là biết phải xong gì để người sau tiếp tục. Chỉ giờ thì không thấy liên kết công việc.\nNữ: Cùng nhiệm vụ mỗi người mất thời gian khác, có khó biết ai chậm không? Đánh giá sẽ khó.\nNam: Bảng này không để so tốc độ. Dù xong việc mình mà quên chuyển tài liệu cần thì người khác vẫn phải đợi.\nNữ: Vậy chỉ đánh dấu việc xong là được. Cam kết xong trước mấy giờ cũng bỏ sao?\nNam: Vẫn ghi hạn và người nhận tiếp. Tôi muốn bảng cho thấy kết quả giúp việc nhóm tiến lên hơn là đã làm lâu bao nhiêu.\nNgười dẫn: Vì sao người đàn ông quyết định ghi kế hoạch theo nhiệm vụ thay vì theo giờ?', NULL, '[{"expression":"結果","reading":"けっか","meaning_vi":"kết quả; thành quả"},{"expression":"資料","reading":"しりょう","meaning_vi":"tài liệu; tư liệu"}]', 427, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-026', 'N3-L-POINT', 'N3', 'LISTENING', 26, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして音についての案内を書き直しましたか。"},{"speaker":"F","ja":"アパートの案内、前は大きく静かにしてくださいと書いてありましたね。今度は夜の時間と、音の例が細かく書かれています。"},{"speaker":"M","ja":"静かにという言葉だけでは、どのくらいか人によって考えが違うんです。椅子を引く音でも下の部屋に聞こえることがあると、具体的に伝えたくて。"},{"speaker":"F","ja":"最近、苦情が増えたんですか。規則を厳しくして、守らない人には出ていってもらうという意味なのでしょうか。"},{"speaker":"M","ja":"新しい罰を作るつもりはありません。自分では小さい音だと思っていても、別の部屋では違って聞こえることを知ってほしいんです。"},{"speaker":"F","ja":"昼間なら何をしてもいいと受け取る人もいそうですね。夜の時間だけ書けば、昼の問題が残ってしまいませんか。"},{"speaker":"M","ja":"昼も周りに気をつけることは書きます。その上で、夜は特に控えてほしい例を示します。注意の言葉を強くするより、行動を選びやすくしたいんです。"},{"speaker":"N","ja":"男の人はどうして音についての案内を書き直しましたか。"}]', 'Người dẫn: Vì sao người đàn ông viết lại thông báo về tiếng ồn?\nNữ: Thông báo căn hộ trước ghi lớn hãy yên lặng nhỉ. Lần này ghi kỹ giờ đêm và ví dụ tiếng động.\nNam: Chỉ nói yên lặng thì mỗi người hiểu mức độ khác. Tôi muốn truyền cụ thể như kéo ghế cũng có thể vọng xuống phòng dưới.\nNữ: Gần đây nhiều phàn nàn à? Có nghĩa siết quy định, ai không theo thì phải chuyển đi sao?\nNam: Tôi không định tạo phạt mới. Tôi muốn họ biết âm tưởng nhỏ với mình có thể nghe khác ở phòng khác.\nNữ: Có người hiểu ban ngày làm gì cũng được. Chỉ ghi giờ đêm thì vấn đề ban ngày còn lại chứ?\nNam: Tôi vẫn ghi ban ngày lưu ý xung quanh, rồi nêu ví dụ đêm đặc biệt nên hạn chế. Tôi muốn họ dễ chọn hành vi hơn là dùng lời cảnh cáo mạnh.\nNgười dẫn: Vì sao người đàn ông viết lại thông báo về tiếng ồn?', NULL, '[{"expression":"具体的","reading":"ぐたいてき","meaning_vi":"cụ thể; chi tiết; một cách cụ thể"},{"expression":"苦情","reading":"くじょう","meaning_vi":"lời khiếu nại; phàn nàn; khiếu nại"}]', 406, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-027', 'N3-L-POINT', 'N3', 'LISTENING', 27, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして作品に触れる触ってもよい見本を用意しましたか。"},{"speaker":"F","ja":"博物館に、触ってもよい触ってもよい見本を置くんですね。本物を近くで見られるなら、わざわざ同じ形の物を作らなくてもよさそうですが。"},{"speaker":"M","ja":"目で見るだけでは形をつかみにくい人もいます。大きさや曲がっている部分を手で確かめれば、説明の言葉がもっと分かりやすくなると思うんです。"},{"speaker":"F","ja":"子供たちは触れる物があると喜びそうですね。遊ぶ場所を作って、その間に大人がゆっくり見られるようにするのですか。"},{"speaker":"M","ja":"子供だけのためではありませんし、遊び場とも違います。同じ作品を、見る以外の方法でも理解できるようにしたいんです。"},{"speaker":"F","ja":"本物を触らせないための注意も必要ですね。触ってもよい見本と同じ色にすると、間違えて本物へ手を伸ばす人がいませんか。"},{"speaker":"M","ja":"触ってもよい見本は色を変えて、触れる印もつけます。本物を守りながら、説明を聞くだけでは届かない情報を、自分の手で確かめてもらうつもりです。"},{"speaker":"N","ja":"男の人はどうして作品に触れる触ってもよい見本を用意しましたか。"}]', 'Người dẫn: Vì sao người đàn ông chuẩn bị mô hình có thể sờ của vật trưng bày?\nNữ: Bảo tàng đặt mô hình được sờ nhỉ. Đã nhìn gần đồ thật thì không nhất thiết làm vật cùng hình chứ?\nNam: Có người khó nắm hình chỉ bằng mắt. Dùng tay xác nhận kích thước và chỗ cong thì tôi nghĩ lời giải thích dễ hiểu hơn.\nNữ: Trẻ chắc thích đồ được sờ. Tạo chỗ chơi để người lớn thong thả xem sao?\nNam: Không chỉ cho trẻ và cũng khác khu chơi. Tôi muốn cùng vật trưng bày được hiểu bằng cách ngoài nhìn.\nNữ: Cũng cần nhắc không sờ đồ thật. Mô hình cùng màu thì có người nhầm đưa tay tới đồ thật không?\nNam: Tôi đổi màu mô hình và đánh dấu được chạm. Vừa bảo vệ vật thật vừa để họ dùng tay xác nhận thông tin nghe giải thích thôi chưa truyền được.\nNgười dẫn: Vì sao người đàn ông chuẩn bị mô hình có thể sờ của vật trưng bày?', NULL, '[{"expression":"博物館","reading":"はくぶつかん","meaning_vi":"viện bảo tàng; bảo tàng"},{"expression":"部分","reading":"ぶぶん","meaning_vi":"một phần; bộ phận; bộ phận hoặc vị trí cụ thể"}]', 430, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-028', 'N3-L-POINT', 'N3', 'LISTENING', 28, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうしてイベントの感想を一週間後にも聞くのですか。"},{"speaker":"F","ja":"防災のイベントが終わった日にアンケートを取りましたよね。一週間後にも送るのは、当日答えられなかった人のためですか。"},{"speaker":"M","ja":"その人にも答えてほしいですが、参加した後で家の準備を変えたか知りたいんです。楽しかったという感想だけでは、役に立ったか分からないので。"},{"speaker":"F","ja":"一週間経つと、話の内容を忘れてしまう人もいそうですね。どの説明を覚えているか、簡単なテストをするのでしょうか。"},{"speaker":"M","ja":"知識の点数をつけるのではありません。水を置く場所を家族と相談したなど、小さくても行動につながったことがあったか聞きます。"},{"speaker":"F","ja":"何もしなかった人は答えにくいかもしれませんね。よかったという回答ばかり集まると、結果を正しく見られなくなりませんか。"},{"speaker":"M","ja":"まだ何もしていない理由も選べるようにします。次の説明を改善するために、イベントの中だけでなく、その後の生活に何が残ったかを確かめたいんです。"},{"speaker":"N","ja":"男の人はどうしてイベントの感想を一週間後にも聞くのですか。"}]', 'Người dẫn: Vì sao người đàn ông hỏi cảm nhận sự kiện thêm một lần sau một tuần?\nNữ: Ngày kết thúc sự kiện phòng chống thiên tai đã khảo sát rồi nhỉ. Gửi sau một tuần vì người chưa trả lời hôm đó à?\nNam: Cũng muốn họ trả lời, nhưng tôi muốn biết sau tham gia có đổi chuẩn bị ở nhà không. Chỉ cảm tưởng vui thì chưa biết hữu ích không.\nNữ: Một tuần có người quên nội dung. Có kiểm tra đơn giản nhớ lời giải thích nào không?\nNam: Không chấm điểm kiến thức. Tôi hỏi có dẫn tới hành động dù nhỏ như bàn với gia đình chỗ để nước không.\nNữ: Người chưa làm gì có thể khó trả lời. Chỉ gom đáp tốt thì không nhìn kết quả đúng được.\nNam: Tôi cho chọn cả lý do chưa làm gì. Để cải thiện giải thích lần sau, tôi muốn biết điều còn lại trong cuộc sống sau sự kiện, không chỉ trong buổi đó.\nNgười dẫn: Vì sao người đàn ông hỏi cảm nhận sự kiện thêm một lần sau một tuần?', NULL, '[{"expression":"防災","reading":"ぼうさい","meaning_vi":"phòng chống thiên tai; phòng chóng thiên tai"},{"expression":"知識","reading":"ちしき","meaning_vi":"kiến thức; tri thức"}]', 425, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-029', 'N3-L-POINT', 'N3', 'LISTENING', 29, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして話し合いの前に意見を書いてもらいますか。"},{"speaker":"F","ja":"次の会議では、最初に五分間、紙に意見を書くんですね。会議の後で記録を作る手間を省くためなら、話しながら入力してもよさそうですが。"},{"speaker":"M","ja":"記録のためだけではありません。すぐ話せる人の意見が先に出ると、考えるのに時間が必要な人は、自分の考えを出しにくくなるんです。"},{"speaker":"F","ja":"紙を先に集めれば、部長の意見がどれか分からなくなりますね。名前を書かず、誰が書いたか最後まで知らせないのでしょうか。"},{"speaker":"M","ja":"名前は書きますし、後で本人に説明してもらいます。まずほかの人の話を聞く前に、自分ならどう考えるか整理する時間を取りたいんです。"},{"speaker":"F","ja":"それなら、書いた意見は会議中に変えない方がいいのですか。人の話を聞いて、もっとよい案が浮かぶこともありますよね。"},{"speaker":"M","ja":"途中で変えても大丈夫です。最初から同じ意見に合わせるのではなく、それぞれの考えを出発点にして、話し合いを進めたいんです。"},{"speaker":"N","ja":"男の人はどうして話し合いの前に意見を書いてもらいますか。"}]', 'Người dẫn: Vì sao người đàn ông yêu cầu viết ý kiến trước khi thảo luận?\nNữ: Họp tới đầu buổi có năm phút viết ý kiến nhỉ. Nếu để đỡ công làm biên bản thì vừa nói vừa nhập cũng được.\nNam: Không chỉ vì biên bản. Nếu ý người nói nhanh ra trước, người cần thời gian nghĩ sẽ khó đưa ý mình.\nNữ: Gom giấy trước thì không biết đâu ý trưởng phòng nhỉ. Không ghi tên và giữ kín đến cuối sao?\nNam: Vẫn ghi tên và sau đó chính người viết giải thích. Trước khi nghe người khác, tôi muốn có thời gian tự sắp xếp cách nghĩ.\nNữ: Vậy không nên đổi ý đã viết trong cuộc họp à? Nghe người khác có thể nảy ý tốt hơn.\nNam: Được đổi giữa chừng. Tôi muốn bắt đầu thảo luận từ cách nghĩ riêng của mỗi người, thay vì ngay từ đầu theo cùng một ý.\nNgười dẫn: Vì sao người đàn ông yêu cầu viết ý kiến trước khi thảo luận?', NULL, '[{"expression":"記録","reading":"きろく","meaning_vi":"ghi chép; kỷ lục; kỉ lục"},{"expression":"考え","reading":"かんがえ","meaning_vi":"suy nghĩ; ý kiến; ý tưởng"}]', 419, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-030', 'N3-L-POINT', 'N3', 'LISTENING', 30, NULL, NULL, '[{"speaker":"N","ja":"男の人はどうして店の歴史を一人の話だけでまとめないのですか。"},{"speaker":"F","ja":"商店街の歴史をまとめるなら、一番長く住んでいる店主に聞くのが早いですね。昔のことをよく覚えていて、資料もたくさん持っているそうです。"},{"speaker":"M","ja":"その方にも聞きますが、働いていた人や買い物に来ていた人にも話してもらいます。同じ店でも、立場によって大切な出来事は違うと思うので。"},{"speaker":"F","ja":"何人にも聞くと、同じ話が重なって長くなりませんか。短い本にするなら、店主の説明に合わせて整理した方が読みやすそうです。"},{"speaker":"M","ja":"内容が重なる所はまとめます。ただ、店主には小さな変化でも、客にとっては生活が変わる出来事だったかもしれません。そういう違いを残したいんです。"},{"speaker":"F","ja":"昔の年や値段について、話が合わない場合もありそうですね。人数が多い方の話を正しいことにするのでしょうか。"},{"speaker":"M","ja":"数字は資料で確かめますが、感じ方は一つに決めません。一人の成功の話ではなく、いろいろな人がその場所とどう関わったかを伝えたいんです。"},{"speaker":"N","ja":"男の人はどうして店の歴史を一人の話だけでまとめないのですか。"}]', 'Người dẫn: Vì sao người đàn ông không tổng hợp lịch sử cửa hàng chỉ từ lời kể một người?\nNữ: Ghi lịch sử phố mua sắm thì hỏi chủ tiệm sống lâu nhất nhanh nhỉ. Nghe ông nhớ chuyện xưa và có nhiều tư liệu.\nNam: Tôi cũng hỏi ông, nhưng cả người từng làm và từng mua. Cùng một tiệm, điều quan trọng khác theo vị trí mỗi người.\nNữ: Hỏi nhiều người có lặp và dài không? Sách ngắn thì theo lời chủ sắp lại dễ đọc hơn.\nNam: Tôi gộp phần trùng. Nhưng thay đổi nhỏ với chủ có thể đổi cuộc sống khách. Tôi muốn giữ khác biệt đó.\nNữ: Năm và giá xưa có thể không khớp. Chọn lời bên đông người là đúng sao?\nNam: Số liệu xác nhận bằng tư liệu, cảm nhận không ép thành một. Tôi muốn kể nhiều người liên quan nơi ấy thế nào, không chỉ chuyện thành công của một người.\nNgười dẫn: Vì sao người đàn ông không tổng hợp lịch sử cửa hàng chỉ từ lời kể một người?', NULL, '[{"expression":"立場","reading":"たちば","meaning_vi":"lập trường"},{"expression":"資料","reading":"しりょう","meaning_vi":"tài liệu; tư liệu"}]', 438, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-001', 'N3-L-SUMMARY', 'N3', 'LISTENING', 1, NULL, NULL, '[{"speaker":"N","ja":"以前、休みの日には一週間分の日本語をまとめて勉強していました。一日中机に向かうので、その日は頑張った気がしましたが、次の週には言葉をほとんど忘れていました。それで、朝の電車で十分、夜寝る前に十分だけ勉強することにしました。最初は、それだけで十分なのか心配でした。ところが、毎日同じ言葉に会うので、前より自然に覚えられるようになったんです。忙しい日は五分で終わっても、次の日にまた開きます。短い時間なら、勉強を始めるまでの始めるときの心配も減ります。今では、長く勉強できない日があっても、やめようとは思いません。大切なのは、一日にどれだけ頑張ったかより、少しでも毎日続けることだと感じています。"},{"speaker":"N","ja":"日本語の勉強について、この人が最も伝えたいことは何ですか。"},{"speaker":"N","ja":"短い時間でも毎日学ぶことが役に立つ。"},{"speaker":"N","ja":"電車の時間を使って言葉を覚える工夫。"},{"speaker":"N","ja":"朝と夜で勉強する内容を分ける工夫。"},{"speaker":"N","ja":"週末に机に向かって頑張った経験。"}]', 'Người dẫn: Trước đây, vào ngày nghỉ tôi học dồn tiếng Nhật của cả tuần. Ngồi bàn cả ngày khiến tôi cảm thấy đã cố gắng, nhưng tuần sau hầu như quên hết từ. Vì vậy tôi chuyển sang học mười phút trên tàu buổi sáng và mười phút trước khi ngủ. Ban đầu tôi lo chừng ấy có đủ không. Nhưng gặp cùng những từ mỗi ngày giúp tôi nhớ tự nhiên hơn. Hôm bận chỉ học năm phút thì hôm sau lại mở sách. Học ngắn cũng làm nhẹ gánh tâm lý trước khi bắt đầu. Giờ đây có hôm không học lâu được tôi cũng không nghĩ đến bỏ học. Tôi thấy điều quan trọng là duy trì mỗi ngày, dù ít, hơn là cố gắng bao lâu trong một ngày.\nNgười dẫn: Về học tiếng Nhật, người này muốn truyền đạt nhất điều gì?\nNgười dẫn: Học mỗi ngày dù ngắn vẫn có ích.\nNgười dẫn: Cách tận dụng thời gian trên tàu để nhớ từ.\nNgười dẫn: Cách chia nội dung học giữa sáng và tối.\nNgười dẫn: Trải nghiệm cố gắng ngồi học cuối tuần.', NULL, '[{"expression":"日本語","reading":"にほんご","meaning_vi":"tiếng Nhật"},{"expression":"言葉","reading":"ことば","meaning_vi":"từ; từ ngữ; lời nói"}]', 394, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-002', 'N3-L-SUMMARY', 'N3', 'LISTENING', 2, NULL, NULL, '[{"speaker":"N","ja":"新しい町に引っ越したとき、近所の店を全く知りませんでした。買い物は便利な大きいスーパーだけで済ませていたんです。ある日、雨を避けようと小さなパン屋に入ったら、店の人が町のお祭りの話をしてくれました。それから時々その店に通い、おいしい食堂や静かな公園も教えてもらいました。店の前で会う人とあいさつをするようになり、道を歩くのも楽しくなりました。値段だけならスーパーのほうが安い物もあります。店で覚えてもらえると、この町に自分の居場所ができたように感じます。それでも、町で暮らす楽しさは、物を買うことだけではないと気づきました。身近な店で少し話すことが、新しい町とつながるきっかけになったのです。"},{"speaker":"N","ja":"引っ越した町について、この人は主に何を話していますか。"},{"speaker":"N","ja":"パン屋で教えてもらった町のお祭り。"},{"speaker":"N","ja":"近所の店での交流が町になじむ助けになったこと。"},{"speaker":"N","ja":"スーパーと小さな店の値段の違い。"},{"speaker":"N","ja":"雨を避けるために入った店の様子。"}]', 'Người dẫn: Khi mới chuyển đến, tôi hoàn toàn không biết cửa hàng quanh nhà. Tôi chỉ mua sắm ở siêu thị lớn tiện lợi. Một hôm vào tiệm bánh nhỏ tránh mưa, chủ tiệm kể tôi nghe về lễ hội của khu phố. Từ đó thỉnh thoảng tôi ghé và được giới thiệu quán ăn ngon, công viên yên tĩnh. Tôi bắt đầu chào những người gặp trước tiệm, đi bộ cũng thấy vui hơn. Nếu chỉ xét giá thì một số món ở siêu thị rẻ hơn. Được cửa hàng nhớ mặt khiến tôi cảm thấy có chỗ thuộc về mình ở khu phố. Dù vậy tôi nhận ra niềm vui sống ở khu phố không chỉ là mua đồ. Những cuộc trò chuyện nhỏ ở cửa hàng gần nhà đã giúp tôi gắn bó với nơi mới.\nNgười dẫn: Người này chủ yếu nói điều gì về khu phố mình chuyển đến?\nNgười dẫn: Lễ hội khu phố được tiệm bánh giới thiệu.\nNgười dẫn: Giao lưu ở cửa hàng gần nhà giúp hòa nhập khu phố.\nNgười dẫn: Khác biệt giá giữa siêu thị và cửa hàng nhỏ.\nNgười dẫn: Quang cảnh tiệm vào tránh mưa.', NULL, '[{"expression":"町","reading":"まち","meaning_vi":"thị trấn; phố; khu phố"},{"expression":"買い物","reading":"かいもの＜する＞","meaning_vi":"mua sắm; việc mua sắm; việc đi chợ"}]', 395, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-003', 'N3-L-SUMMARY', 'N3', 'LISTENING', 3, NULL, NULL, '[{"speaker":"N","ja":"料理教室で、初めて魚を使った料理を作りました。先生と同じように作ったつもりなのに、私の魚は少し硬くなりました。失敗したと思って黙っていたら、隣の人が理由を先生に聞いてみようと言いました。先生は火が強すぎたかもしれないと説明し、次はどうすればよいか教えてくれました。すると、ほかの人も自分が困ったところを話し始めたんです。教室では、上手にできた料理だけを見せればいいと思っていました。一人で悩んでいた時間が、みんなで考える時間に変わったのです。でも、うまくいかなかったことを話すと、自分だけでなく周りの人も新しいことを学べます。失敗を隠さずに話すことも、勉強の一つなのだと分かりました。"},{"speaker":"N","ja":"料理教室での経験から、この人は何が大切だと思いましたか。"},{"speaker":"N","ja":"魚を柔らかく作るための火の使い方。"},{"speaker":"N","ja":"隣の人から先生に質問するよう勧められたこと。"},{"speaker":"N","ja":"うまくいかなかった経験も人に話すこと。"},{"speaker":"N","ja":"先生と同じ料理を作るための準備。"}]', 'Người dẫn: Ở lớp nấu ăn, lần đầu tôi làm món cá. Tôi tưởng làm giống thầy nhưng cá hơi cứng. Tôi nghĩ đã làm hỏng nên im lặng, người bên cạnh đề nghị hỏi thầy lý do. Thầy giải thích có thể lửa quá to và chỉ cách làm lần sau. Rồi những người khác cũng bắt đầu nói về chỗ mình gặp khó khăn. Tôi từng nghĩ trong lớp chỉ cần cho mọi người xem món làm thành công. Thời gian một mình lo lắng đã biến thành thời gian cả nhóm cùng suy nghĩ. Nhưng nói về điều chưa làm tốt giúp cả mình lẫn mọi người học điều mới. Tôi hiểu rằng chia sẻ thất bại cũng là một cách học.\nNgười dẫn: Từ trải nghiệm lớp nấu ăn, người này thấy điều gì quan trọng?\nNgười dẫn: Cách dùng lửa để cá mềm.\nNgười dẫn: Được người bên cạnh khuyên hỏi thầy.\nNgười dẫn: Chia sẻ với người khác cả trải nghiệm chưa thành công.\nNgười dẫn: Chuẩn bị để làm món giống thầy.', NULL, '[{"expression":"料理","reading":"りょうり","meaning_vi":"món ăn; việc nấu ăn"},{"expression":"先生","reading":"せんせい","meaning_vi":"người dạy học; thầy (cô) giáo"}]', 394, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-004', 'N3-L-SUMMARY', 'N3', 'LISTENING', 4, NULL, NULL, '[{"speaker":"N","ja":"市の図書館では、今月から本を紹介する小さな集まりを始めます。参加する人は、好きな本を一冊持ってきて、どんなところが好きかを話します。難しい説明を準備する必要はありません。子どものころに読んだ本や、料理の本でもかまいません。自分で読むと、いつも同じ種類の本を選びがちですが、人の話を聞くと、知らなかった本に興味がわくことがあります。本を読む速さや、読んだ数を比べる会ではありません。本の内容を全部知らなくても、好きな一場面の話だけで十分です。まだ紹介したい本がない方は、話を聞くだけでも参加できます。読書が好きな方も、これから何か読みたい方も、一緒に新しい本との出会いを楽しみませんか。"},{"speaker":"N","ja":"図書館の人は、この集まりをどのような場にしたいですか。"},{"speaker":"N","ja":"子どものころに読んだ本を思い出す場。"},{"speaker":"N","ja":"料理の本の使い方を細かく説明する場。"},{"speaker":"N","ja":"上手に本を紹介する練習をする場。"},{"speaker":"N","ja":"人の話を通して読書の楽しみを広げる場。"}]', 'Người dẫn: Thư viện thành phố sẽ bắt đầu buổi gặp nhỏ giới thiệu sách từ tháng này. Người tham gia mang một quyển yêu thích và kể mình thích điểm nào. Không cần chuẩn bị bài giải thích khó; sách đọc thời nhỏ hay sách nấu ăn đều được. Khi tự đọc ta dễ chọn cùng loại sách, còn nghe người khác nói có thể khiến ta quan tâm sách chưa biết. Đây không phải buổi so tốc độ hay số lượng sách đã đọc. Không cần biết hết nội dung sách; chỉ kể một cảnh yêu thích cũng đủ. Chưa có sách muốn giới thiệu vẫn có thể đến chỉ để nghe. Người yêu đọc sách và người muốn bắt đầu đọc hãy cùng tận hưởng cơ hội gặp sách mới.\nNgười dẫn: Nhân viên thư viện muốn buổi gặp thành nơi như thế nào?\nNgười dẫn: Nơi nhớ lại sách đã đọc thời nhỏ.\nNgười dẫn: Nơi giải thích kỹ cách dùng sách nấu ăn.\nNgười dẫn: Nơi luyện giới thiệu sách hay.\nNgười dẫn: Nơi mở rộng niềm vui đọc qua câu chuyện của người khác.', NULL, '[{"expression":"図書館","reading":"としょかん","meaning_vi":"thư viện"},{"expression":"興味","reading":"きょうみ","meaning_vi":"hứng thú; sự hứng thú; quan tâm"}]', 390, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-005', 'N3-L-SUMMARY', 'N3', 'LISTENING', 5, NULL, NULL, '[{"speaker":"N","ja":"会社で会議の時間を短くするために、新しい方法を試しました。以前は、会議が始まってから初めて資料を読み、内容を理解するだけで時間がかかっていました。そこで、前の日までに資料を送り、質問も先に集めるようにしました。最初は準備が増えて大変だという声もありましたが、会議では大事な問題にすぐ入れるようになりました。話し合いを急いで終わらせたり、意見を言う人を減らしたりしたわけではありません。必要な話は十分にできています。前もって考える時間があると、普段静かな人からも意見が出ました。同じ一時間でも、準備によって使い方は変わります。短い会議にしたいなら、始まる前の仕事を見直すことが大切だと思います。"},{"speaker":"N","ja":"この人が会議について一番言いたいことは何ですか。"},{"speaker":"N","ja":"前もってする準備を工夫すると話し合いの時間を生かせる。"},{"speaker":"N","ja":"資料を前の日に送るための方法。"},{"speaker":"N","ja":"静かな人が意見を出したときの様子。"},{"speaker":"N","ja":"会議で一時間を過ごすことの大変さ。"}]', 'Người dẫn: Công ty thử cách mới để rút ngắn cuộc họp. Trước đây mọi người chỉ đọc tài liệu sau khi họp bắt đầu, mất thời gian chỉ để hiểu nội dung. Chúng tôi chuyển sang gửi tài liệu và gom câu hỏi từ hôm trước. Ban đầu có ý kiến rằng chuẩn bị nhiều hơn sẽ vất vả, nhưng trong họp đã có thể vào vấn đề chính ngay. Không phải chúng tôi ép kết thúc nhanh hay giảm người phát biểu; những nội dung cần thiết vẫn được bàn đủ. Có thời gian nghĩ trước, người thường im lặng cũng nêu ý kiến. Cùng một giờ nhưng sự chuẩn bị thay đổi cách sử dụng. Muốn họp ngắn hơn thì nên xem lại công việc trước khi bắt đầu.\nNgười dẫn: Người này muốn nói nhất điều gì về cuộc họp?\nNgười dẫn: Cải thiện chuẩn bị trước giúp tận dụng thời gian thảo luận.\nNgười dẫn: Cách gửi tài liệu từ hôm trước.\nNgười dẫn: Tình huống người thường im lặng nêu ý kiến.\nNgười dẫn: Sự vất vả khi dành một giờ họp.', NULL, '[{"expression":"資料","reading":"しりょう","meaning_vi":"tài liệu; tư liệu"},{"expression":"質問","reading":"しつもん＜する＞","meaning_vi":"câu hỏi; hỏi (thầy; người khác)"}]', 396, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-006', 'N3-L-SUMMARY', 'N3', 'LISTENING', 6, NULL, NULL, '[{"speaker":"N","ja":"週末、家族で山へ出かける計画を立てました。行きたい場所を全部入れると、朝から夕方まで予定がいっぱいになりました。ところが、当日は子どもが川のそばで石を拾い始め、なかなか動こうとしませんでした。最初は次の場所に間に合わないと困りましたが、楽しそうな顔を見て、予定を一つやめることにしました。川の近くでゆっくり昼ご飯を食べ、帰りも急がずに済みました。家に戻って子どもが一番話したのは、その川のことでした。帰ってから疲れだけが残るような旅行には、もうしたくありません。たくさんの場所を回るだけが、よい旅行ではないんですね。計画には少し余裕を残し、その場で見つけた楽しみも大切にしたいです。"},{"speaker":"N","ja":"家族旅行を終えて、この人はどんなことを感じていますか。"},{"speaker":"N","ja":"川の近くで食べる昼ご飯は楽しい。"},{"speaker":"N","ja":"予定を詰めすぎず、その場の楽しみも大事にしたい。"},{"speaker":"N","ja":"旅行の前には行きたい場所を調べたい。"},{"speaker":"N","ja":"子どもは石を拾うことが好きだ。"}]', 'Người dẫn: Cuối tuần gia đình tôi lên kế hoạch đi núi. Đưa hết nơi muốn đi vào khiến lịch kín từ sáng đến chiều. Nhưng hôm đó con bắt đầu nhặt đá bên sông và mãi không muốn đi tiếp. Ban đầu tôi lo trễ chỗ tiếp theo, nhưng thấy con vui nên bỏ một điểm trong lịch. Chúng tôi ăn trưa thong thả gần sông, lúc về cũng không phải vội. Về nhà, điều con kể nhiều nhất là con sông đó. Tôi không muốn chuyến đi mà về nhà chỉ còn lại mệt mỏi nữa. Chuyến đi tốt không chỉ là đi nhiều nơi. Tôi muốn để lịch có khoảng trống và trân trọng niềm vui tìm thấy tại chỗ.\nNgười dẫn: Sau chuyến du lịch gia đình, người này cảm nhận điều gì?\nNgười dẫn: Ăn trưa gần sông rất vui.\nNgười dẫn: Không nên nhồi lịch, cũng nên trân trọng niềm vui phát sinh.\nNgười dẫn: Muốn tìm hiểu điểm đến trước chuyến đi.\nNgười dẫn: Trẻ thích nhặt đá.', NULL, '[{"expression":"予定","reading":"よてい","meaning_vi":"dự định; lịch trình; kế hoạch"},{"expression":"計画","reading":"けいかく＜する＞","meaning_vi":"kế hoạch"}]', 391, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-007', 'N3-L-SUMMARY', 'N3', 'LISTENING', 7, NULL, NULL, '[{"speaker":"N","ja":"町の公園でごみを拾う活動に初めて参加しました。正直に言うと、朝早く起きるのが嫌で、友だちに誘われなければ行かなかったと思います。実際にやってみると、道の端や木の下など、普段見ていなかった場所にごみがあることに気づきました。終わった後は、同じ公園なのに前より気持ちよく歩けました。それ以来、自分が使った場所に何か残っていないか、少し気にするようになりました。一度の活動ですべてのごみがなくなるわけではありません。人が片づけてくれるのを待つだけだった自分にも、できることがありました。でも、自分の手を動かすと、町を見る目や毎日の行動が変わります。参加してよかったと思ったのは、その変化があったからです。"},{"speaker":"N","ja":"公園での活動について、この人が主に伝えていることは何ですか。"},{"speaker":"N","ja":"朝の活動には友だちと参加すると行きやすい。"},{"speaker":"N","ja":"公園の木の下にはごみが集まりやすい。"},{"speaker":"N","ja":"実際に参加すると身近な環境への意識が変わる。"},{"speaker":"N","ja":"活動が終わった後の散歩は気持ちがよい。"}]', 'Người dẫn: Tôi lần đầu tham gia nhặt rác ở công viên khu phố. Thành thật mà nói tôi ghét dậy sớm, nếu bạn không rủ chắc đã không đi. Làm rồi mới thấy rác ở ven đường, dưới cây, những chỗ thường không để ý. Kết thúc, vẫn công viên ấy mà đi bộ thấy dễ chịu hơn. Từ đó tôi chú ý xem mình có để lại gì ở nơi vừa dùng không. Một buổi hoạt động không làm mọi rác biến mất. Trước đây chỉ chờ người khác dọn, nhưng bản thân tôi cũng có việc làm được. Nhưng tự tay làm giúp thay đổi cách nhìn khu phố và hành động mỗi ngày. Tôi thấy đáng tham gia chính vì sự thay đổi ấy.\nNgười dẫn: Người này chủ yếu truyền đạt điều gì về hoạt động ở công viên?\nNgười dẫn: Tham gia hoạt động sáng cùng bạn sẽ dễ đi.\nNgười dẫn: Rác dễ tụ dưới cây công viên.\nNgười dẫn: Tham gia thực tế thay đổi ý thức về môi trường gần mình.\nNgười dẫn: Đi bộ sau khi hoạt động xong rất dễ chịu.', NULL, '[{"expression":"公園","reading":"こうえん","meaning_vi":"công viên"},{"expression":"活動","reading":"かつどう＜する＞","meaning_vi":"hoạt động; chuỗi việc có mục tiêu"}]', 409, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-008', 'N3-L-SUMMARY', 'N3', 'LISTENING', 8, NULL, NULL, '[{"speaker":"N","ja":"母は長い間、スマホは難しいから使いたくないと言っていました。私が便利な機能をいくつも説明しても、覚えられないと困った顔をするばかりでした。そこで、遠くに住む孫の写真を見る方法だけを一緒に練習しました。次に会ったとき、母は自分で写真を開いて、昨日はこんな服を着ていたねと話してくれました。今では、写真に短い返事を送ることもできます。母が自分から次の使い方を聞いてくれるようになったのも、うれしい変化です。最初から全部教えようとしたのが、よくなかったのでしょう。新しい道具を使うときは、機能の多さを説明するより、その人がやってみたいことから始めるほうが、自然に覚えられるのだと思いました。"},{"speaker":"N","ja":"母親にスマホを教えた経験から、この人は何を伝えたいですか。"},{"speaker":"N","ja":"家族の写真をスマホで見る楽しさ。"},{"speaker":"N","ja":"便利な機能を一度に覚える難しさ。"},{"speaker":"N","ja":"写真に短い返事を送る方法。"},{"speaker":"N","ja":"相手の関心に合うことから教えると学びやすい。"}]', 'Người dẫn: Mẹ tôi lâu nay nói điện thoại thông minh khó nên không muốn dùng. Dù tôi giải thích nhiều chức năng tiện ích, mẹ chỉ tỏ ra khổ sở vì không nhớ được. Tôi chuyển sang cùng mẹ luyện đúng cách xem ảnh cháu ở xa. Lần gặp sau mẹ tự mở ảnh, kể hôm qua cháu mặc đồ thế này. Giờ mẹ còn gửi được trả lời ngắn cho ảnh. Mẹ bắt đầu chủ động hỏi cách dùng tiếp theo cũng là thay đổi đáng mừng. Có lẽ việc muốn dạy tất cả từ đầu là không tốt. Tôi nhận ra khi dùng công cụ mới, bắt đầu từ điều người ấy muốn làm giúp họ học tự nhiên hơn việc giải thích nhiều chức năng.\nNgười dẫn: Qua dạy mẹ dùng điện thoại, người này muốn truyền đạt điều gì?\nNgười dẫn: Niềm vui xem ảnh gia đình trên điện thoại.\nNgười dẫn: Cái khó khi nhớ nhiều chức năng cùng lúc.\nNgười dẫn: Cách gửi trả lời ngắn cho ảnh.\nNgười dẫn: Dạy từ điều hợp mối quan tâm của người học sẽ dễ tiếp thu.', NULL, '[{"expression":"写真","reading":"しゃしん","meaning_vi":"tấm ảnh; ảnh chụp; ảnh"},{"expression":"機能","reading":"きのう＜する＞","meaning_vi":"chức năng; chức năng làm được gì; hoạt động"}]', 388, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-009', 'N3-L-SUMMARY', 'N3', 'LISTENING', 9, NULL, NULL, '[{"speaker":"N","ja":"駅前の食堂では、昼のメニューを三つだけにしています。初めて来たお客さんには、種類が少ないと言われることもあります。以前は十種類以上作っていましたが、料理によって出る数が大きく違い、材料が残ってしまいました。今は、季節の野菜を使って三つの料理を丁寧に作っています。買う量が分かりやすくなり、捨てる材料が減りましたし、お客さんを待たせる時間も短くなりました。選ぶ楽しさを減らしたくないので、料理の内容は週ごとに変えています。お客さんからは、昼休みの短い日にも入りやすいと言っていただきました。数を多くすることだけがお客さんのためとは限りません。私たちは、少ない種類でも安心して選べる食事を出したいと考えています。"},{"speaker":"N","ja":"食堂の人は、メニューについてどんな考えを話していますか。"},{"speaker":"N","ja":"種類を絞る工夫で質を守りながら無駄も減らしたい。"},{"speaker":"N","ja":"季節の野菜で作る料理を紹介したい。"},{"speaker":"N","ja":"昼休みに早く食べたい客を集めたい。"},{"speaker":"N","ja":"週ごとに料理を変える楽しさを話したい。"}]', 'Người dẫn: Quán ăn trước ga chỉ có ba món trưa. Khách mới đôi khi nói ít loại. Trước đây chúng tôi nấu hơn mười loại nhưng lượng bán mỗi món rất khác, nguyên liệu bị thừa. Giờ chúng tôi chăm chút ba món dùng rau theo mùa. Dễ biết lượng cần mua hơn, giảm đồ bỏ và thời gian khách chờ cũng ngắn hơn. Không muốn giảm niềm vui lựa chọn nên chúng tôi đổi nội dung món theo tuần. Khách nói những hôm nghỉ trưa ngắn cũng dễ ghé quán hơn. Nhiều lựa chọn không phải lúc nào cũng tốt cho khách. Chúng tôi muốn phục vụ bữa ăn mà khách an tâm lựa chọn dù số loại ít.\nNgười dẫn: Người ở quán ăn đang nói suy nghĩ gì về thực đơn?\nNgười dẫn: Muốn giới hạn số món để vừa giữ chất lượng vừa giảm lãng phí.\nNgười dẫn: Muốn giới thiệu món từ rau theo mùa.\nNgười dẫn: Muốn thu hút khách cần ăn nhanh giờ trưa.\nNgười dẫn: Muốn nói niềm vui đổi món mỗi tuần.', NULL, '[{"expression":"材料","reading":"ざいりょう","meaning_vi":"nguyên liệu (nấu ăn); vật liệu"},{"expression":"野菜","reading":"やさい","meaning_vi":"rau; rau củ"}]', 409, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-010', 'N3-L-SUMMARY', 'N3', 'LISTENING', 10, NULL, NULL, '[{"speaker":"N","ja":"学生のころ、発表の前には発表の文章を全部覚えようとしていました。一つ言葉を忘れると、その後が続かなくなり、とても不安でした。ある先生に相談したら、最初に、聞く人に何を伝えたいかを一つ決めるように言われました。それからは、話の順番と大事な言葉だけを紙に書いて練習しています。発表の文章と全く同じ言い方でなくても、伝えたいことが分かればよいと考えると、少し楽になりました。言葉を探して少し止まっても、落ち着いて話に戻ればよいと思っています。今も人前では緊張しますが、聞いている人の顔を見る余裕ができました。発表で大切なのは、覚えた文章を間違えずに言うことより、相手に考えを届けることなのだと思います。"},{"speaker":"N","ja":"発表の経験について、この人が一番言いたいことは何ですか。"},{"speaker":"N","ja":"発表の前に紙に順番を書く方法。"},{"speaker":"N","ja":"覚えたとおりに言うことより、伝える内容と相手を大事にする。"},{"speaker":"N","ja":"人前で緊張したときの体の様子。"},{"speaker":"N","ja":"先生に相談するきっかけになった失敗。"}]', 'Người dẫn: Hồi đi học, trước khi thuyết trình tôi cố thuộc cả bản thảo. Quên một từ là không nói tiếp được, rất lo. Một thầy khuyên trước hết hãy chọn một điều muốn truyền đạt cho người nghe. Từ đó tôi chỉ viết trình tự và từ quan trọng ra giấy để luyện. Nghĩ rằng không cần nói y hệt bản thảo miễn truyền đạt được ý khiến tôi thoải mái hơn. Tôi nghĩ dù dừng chút để tìm từ, bình tĩnh quay lại câu chuyện là được. Giờ tôi vẫn căng thẳng trước đám đông nhưng có thể nhìn mặt người nghe. Tôi thấy điều quan trọng khi trình bày là truyền ý đến người khác hơn là đọc không sai câu đã thuộc.\nNgười dẫn: Qua trải nghiệm thuyết trình, người này muốn nói nhất điều gì?\nNgười dẫn: Cách ghi trình tự ra giấy trước thuyết trình.\nNgười dẫn: Nên coi trọng nội dung và người nghe hơn đọc lại nguyên bản.\nNgười dẫn: Trạng thái cơ thể khi căng thẳng trước đám đông.\nNgười dẫn: Thất bại khiến mình hỏi ý kiến thầy.', NULL, '[{"expression":"発表","reading":"はっぴょう＜する＞","meaning_vi":"buổi trình bày; phát biểu; thông báo"},{"expression":"言葉","reading":"ことば","meaning_vi":"từ; từ ngữ; lời nói"}]', 403, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-011', 'N3-L-SUMMARY', 'N3', 'LISTENING', 11, NULL, NULL, '[{"speaker":"N","ja":"健康のために走り始めたとき、私は毎日五キロ走ると決めました。最初の三日は頑張れましたが、足が痛くなり、その後は外に出るのも嫌になりました。友だちに話すと、まず十分歩くことから始めてはどうかと言われました。そんな短い運動では意味がないと思いましたが、試してみると気分がよく、次の日も続けられました。今は体の調子に合わせて、歩いたり少し走ったりしています。ほかの人と距離を比べることもやめました。できた日を一つずつ増やしていくほうが、失敗したと感じずに済みます。長く続けたいことほど、最初から大きな目標を持ちすぎないほうがよいのかもしれません。自分に合う小さな一歩を見つけたことが、私には一番役立ちました。"},{"speaker":"N","ja":"運動を続けることについて、この人の考えはどれですか。"},{"speaker":"N","ja":"友だちと運動の話をすることが楽しい。"},{"speaker":"N","ja":"足が痛い日は外へ出るのが難しい。"},{"speaker":"N","ja":"自分に合う無理のない始め方が続ける力になる。"},{"speaker":"N","ja":"歩くことと走ることでは距離が違う。"}]', 'Người dẫn: Khi bắt đầu chạy để khỏe, tôi đặt mục tiêu mỗi ngày năm cây số. Ba ngày đầu cố được nhưng rồi đau chân đến mức không muốn ra ngoài. Bạn gợi ý bắt đầu bằng đi bộ mười phút. Tôi tưởng vận động ngắn vậy vô ích, nhưng thử thấy dễ chịu và hôm sau tiếp tục được. Giờ tùy sức khỏe mà tôi đi bộ hoặc chạy chút ít, không so khoảng cách với người khác nữa. Tăng dần từng ngày làm được giúp tôi tránh cảm giác thất bại. Việc muốn duy trì lâu có lẽ càng không nên đặt mục tiêu quá lớn từ đầu. Tìm bước nhỏ hợp mình là điều giúp tôi nhiều nhất.\nNgười dẫn: Người này nghĩ thế nào về việc duy trì vận động?\nNgười dẫn: Nói chuyện vận động với bạn rất vui.\nNgười dẫn: Ngày đau chân khó ra ngoài.\nNgười dẫn: Bắt đầu vừa sức, hợp mình giúp duy trì.\nNgười dẫn: Đi bộ và chạy có cự ly khác nhau.', NULL, '[{"expression":"健康","reading":"けんこう＜な＞","meaning_vi":"sức khỏe; khỏe mạnh"},{"expression":"運動","reading":"うんどう＜する＞","meaning_vi":"vận động; tập thể dục"}]', 400, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-012', 'N3-L-SUMMARY', 'N3', 'LISTENING', 12, NULL, NULL, '[{"speaker":"N","ja":"大学の授業で、四人で一つの作品を作ることになりました。初めは全員が同じ作業をすれば公平だと考えて、毎回みんなで絵を描いていました。でも、絵が苦手な人は時間がかかり、得意な人は待つばかりでした。そこで、それぞれ何ができるか話してみました。一人は文章を書くのが上手で、別の人は材料を集めるのが得意でした。仕事を分けると、作業が早く進んだだけでなく、全員が自分の役目を楽しめるようになりました。途中で困った人がいれば、役目が違ってもお互いに声をかけました。同じことを同じ量だけするのが、いつも公平とは限りません。それぞれの力を生かして一つのものを作ることが、協力する意味なのだと感じました。"},{"speaker":"N","ja":"作品作りを通して、この人は協力について何を学びましたか。"},{"speaker":"N","ja":"作品に使う材料を集める方法。"},{"speaker":"N","ja":"絵が苦手な人が作業で感じた困りごと。"},{"speaker":"N","ja":"四人で絵を描いたときにかかった時間。"},{"speaker":"N","ja":"得意なことを生かして役割を分けるとよい。"}]', 'Người dẫn: Trong lớp đại học, bốn người chúng tôi cùng làm một tác phẩm. Ban đầu nghĩ mọi người làm cùng việc mới công bằng nên lần nào cũng cùng vẽ. Nhưng người vẽ kém mất thời gian, người giỏi chỉ chờ. Chúng tôi bàn mỗi người làm được gì: có người viết hay, người khác giỏi tìm vật liệu. Chia việc xong không chỉ nhanh hơn mà ai cũng vui với vai trò của mình. Giữa chừng ai gặp khó, dù vai trò khác nhau chúng tôi vẫn hỏi han nhau. Làm cùng việc với cùng lượng không phải lúc nào cũng công bằng. Tôi cảm nhận hợp tác là phát huy khả năng từng người để tạo một sản phẩm chung.\nNgười dẫn: Qua làm tác phẩm, người này học gì về hợp tác?\nNgười dẫn: Cách gom vật liệu cho tác phẩm.\nNgười dẫn: Khó khăn người vẽ kém cảm thấy khi làm.\nNgười dẫn: Thời gian bốn người cùng vẽ.\nNgười dẫn: Nên chia vai trò theo sở trường từng người.', NULL, '[{"expression":"作品","reading":"さくひん","meaning_vi":"tác phẩm; bà ～"},{"expression":"材料","reading":"ざいりょう","meaning_vi":"nguyên liệu (nấu ăn); vật liệu"}]', 390, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-013', 'N3-L-SUMMARY', 'N3', 'LISTENING', 13, NULL, NULL, '[{"speaker":"N","ja":"最近、写真を撮るために遠くへ出かけることをやめ、家の周りを歩いています。最初は見慣れた道に撮りたいものはないと思っていました。ところが、朝と夕方では建物の色が違って見えますし、雨の後には道に空が映ります。同じ木にも、毎週小さな変化がありました。遠くの有名な場所では、雑誌で見た写真と同じものを撮ろうとしていた気がします。今は、自分が気づいたものをゆっくり探すのが楽しいです。通り過ぎていた角でカメラを向けると、自分の町が少し好きになりました。特別な景色に会うために、必ず遠くへ行く必要はありません。いつもの場所でも、少し立ち止まって見方を変えると、今まで知らなかった面白さが見つかるのです。"},{"speaker":"N","ja":"写真の話を通して、この人が伝えたいことは何ですか。"},{"speaker":"N","ja":"見方を変えれば身近な場所にも発見がある。"},{"speaker":"N","ja":"朝と夕方では建物の色が違って見える。"},{"speaker":"N","ja":"雨の後の道は空を映すことがある。"},{"speaker":"N","ja":"有名な場所には写真を撮る人が集まる。"}]', 'Người dẫn: Gần đây tôi thôi đi xa để chụp ảnh, chuyển sang đi bộ quanh nhà. Ban đầu tôi nghĩ đường quen chẳng có gì muốn chụp. Nhưng màu tòa nhà khác nhau vào sáng và chiều, sau mưa mặt đường phản chiếu bầu trời. Cùng một cây cũng thay đổi nhỏ mỗi tuần. Ở nơi nổi tiếng xa xôi, hình như tôi chỉ muốn chụp giống ảnh đã thấy trong tạp chí. Giờ tôi thích thong thả tìm điều chính mình nhận ra. Giơ máy ở góc phố từng đi ngang khiến tôi yêu khu mình hơn chút. Không nhất thiết đi xa để gặp cảnh đặc biệt. Ở nơi quen, dừng lại đổi cách nhìn cũng thấy thú vị chưa từng biết.\nNgười dẫn: Qua chuyện chụp ảnh, người này muốn truyền đạt điều gì?\nNgười dẫn: Đổi cách nhìn sẽ có phát hiện ngay ở nơi gần gũi.\nNgười dẫn: Màu nhà nhìn khác vào sáng và chiều.\nNgười dẫn: Đường sau mưa có khi phản chiếu trời.\nNgười dẫn: Nơi nổi tiếng tập trung người chụp ảnh.', NULL, '[{"expression":"写真","reading":"しゃしん","meaning_vi":"tấm ảnh; ảnh chụp; ảnh"},{"expression":"景色","reading":"けしき","meaning_vi":"phong cảnh; cảnh sắc"}]', 392, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-014', 'N3-L-SUMMARY', 'N3', 'LISTENING', 14, NULL, NULL, '[{"speaker":"N","ja":"会社では、分からないことがあると、すぐ先輩に質問していました。先輩はいつも答えてくれましたが、同じことを何度も聞いてしまうのが気になりました。そこで、質問する前に、何を調べてどこまで分かったかを短く書くことにしました。書いている間に、自分で答えを見つけることもあります。まだ分からないときも、困っている部分をはっきり伝えられるので、説明がよく理解できるようになりました。聞いた後は自分の言葉でもう一度説明して、理解が合っているか確かめます。質問しないで一人で困り続けるのがよいわけではありません。ただ、相手に全部任せる前に、自分の考えを少し整理すると、教えてもらう時間をもっと役立てられるのだと思います。"},{"speaker":"N","ja":"仕事で質問するとき、この人は何を大切にしていますか。"},{"speaker":"N","ja":"同じ質問を何度もしてしまった経験。"},{"speaker":"N","ja":"分かった点と疑問を整理してから助けを求める。"},{"speaker":"N","ja":"先輩が質問にいつも答えてくれること。"},{"speaker":"N","ja":"説明を短く書くための紙の使い方。"}]', 'Người dẫn: Ở công ty, cứ không hiểu là tôi hỏi tiền bối ngay. Anh chị luôn trả lời nhưng tôi bận tâm vì hỏi lại nhiều lần. Tôi chuyển sang viết ngắn trước khi hỏi: đã tra gì, hiểu đến đâu. Đang viết có khi tự tìm được đáp án. Nếu vẫn chưa hiểu, tôi cũng nói rõ chỗ vướng nên hiểu lời giải thích hơn. Sau khi hỏi tôi giải thích lại bằng lời mình để xác nhận hiểu đúng. Không phải cứ không hỏi rồi tự mắc kẹt là tốt. Nhưng trước khi giao hết cho người khác, sắp xếp suy nghĩ một chút sẽ giúp tận dụng thời gian được chỉ dẫn hơn.\nNgười dẫn: Khi hỏi về công việc, người này coi trọng điều gì?\nNgười dẫn: Trải nghiệm lặp cùng câu hỏi nhiều lần.\nNgười dẫn: Sắp xếp điều đã hiểu và thắc mắc rồi nhờ giúp.\nNgười dẫn: Tiền bối luôn trả lời câu hỏi.\nNgười dẫn: Cách dùng giấy để viết giải thích ngắn.', NULL, '[{"expression":"質問","reading":"しつもん＜する＞","meaning_vi":"câu hỏi; hỏi (thầy; người khác)"},{"expression":"先輩","reading":"せんぱい","meaning_vi":"người khoá trên; tiền bối; người đi trước"}]', 401, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-015', 'N3-L-SUMMARY', 'N3', 'LISTENING', 15, NULL, NULL, '[{"speaker":"N","ja":"町のスポーツセンターからお知らせです。来月、運動が得意でない方も参加できる体験の日を開きます。速く走ることや試合に勝つことを目指す日ではありません。音楽に合わせて体を動かしたり、柔らかいボールを使って遊んだりします。疲れたら、途中で休んでも大丈夫です。これまで運動の教室は自分には難しそうだと思っていた方に、体を動かす楽しさを知っていただきたいと考えています。道具はこちらで用意しますので、動きやすい服でお越しください。周りの人と比べず、体が気持ちよく動く感覚を楽しんでいただけます。年齢や経験に関係なく、自分の速さで楽しめる時間にしたいと思います。どうぞ安心して参加してください。"},{"speaker":"N","ja":"スポーツセンターは、体験の日について何を強調していますか。"},{"speaker":"N","ja":"音楽に合わせて体を動かす時間がある。"},{"speaker":"N","ja":"会場では柔らかいボールを用意する。"},{"speaker":"N","ja":"運動に自信がない人も無理なく楽しめる。"},{"speaker":"N","ja":"参加するときは動きやすい服を着る。"}]', 'Người dẫn: Trung tâm thể thao khu phố thông báo: tháng sau có ngày trải nghiệm dành cả cho người không giỏi vận động. Mục tiêu không phải chạy nhanh hay thắng thi đấu. Mọi người vận động theo nhạc, chơi bằng bóng mềm. Mệt có thể nghỉ giữa chừng. Chúng tôi muốn người từng nghĩ lớp thể dục quá khó biết niềm vui vận động. Trung tâm chuẩn bị dụng cụ, xin mặc đồ dễ cử động. Mọi người có thể tận hưởng cảm giác vận động dễ chịu mà không so với ai. Chúng tôi muốn thời gian ai cũng vui theo nhịp của mình, bất kể tuổi tác và kinh nghiệm. Hãy thoải mái tham gia.\nNgười dẫn: Trung tâm thể thao nhấn mạnh điều gì về ngày trải nghiệm?\nNgười dẫn: Có thời gian vận động theo nhạc.\nNgười dẫn: Địa điểm có chuẩn bị bóng mềm.\nNgười dẫn: Người thiếu tự tin về vận động vẫn vui vừa sức.\nNgười dẫn: Nên mặc đồ dễ vận động khi tham gia.', NULL, '[{"expression":"運動","reading":"うんどう＜する＞","meaning_vi":"vận động; tập thể dục"},{"expression":"経験","reading":"けいけん＜する＞","meaning_vi":"kinh nghiệm; trải qua"}]', 391, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-016', 'N3-L-SUMMARY', 'N3', 'LISTENING', 16, NULL, NULL, '[{"speaker":"N","ja":"仕事から帰ると、疲れていて、つい何も考えずにテレビをつけていました。気づくと寝る時間になり、好きな絵を描く時間がなかったと後悔する毎日でした。そこで、帰宅後すぐにテレビをつけず、机に紙と鉛筆を置くことにしました。たくさん描こうとは決めず、まず五分だけ座ります。すると、少し描くだけでも気分が変わり、そのまま続ける日も増えました。テレビを見るのを完全にやめたわけではありません。始める前は大変そうでも、手を動かすと案外すぐに楽しめるものですね。自分が本当にしたいことを、先に少し始めるようにしただけです。自由な時間が増えるのを待つより、今ある時間の最初の使い方を変えるほうが、私には合っていました。"},{"speaker":"N","ja":"帰宅後の過ごし方について、この人が伝えたいことは何ですか。"},{"speaker":"N","ja":"机に紙と鉛筆を用意しておく便利さ。"},{"speaker":"N","ja":"夜遅くまでテレビを見ていた経験。"},{"speaker":"N","ja":"疲れたときに絵を描くと気分が変わること。"},{"speaker":"N","ja":"したいことを先に少し始めると時間を生かせる。"}]', 'Người dẫn: Đi làm về mệt, tôi thường bật tivi mà không suy nghĩ. Chợt đã tới giờ ngủ, ngày nào cũng tiếc không có thời gian vẽ điều mình thích. Tôi quyết định không bật tivi ngay khi về mà đặt giấy bút trên bàn. Không ép vẽ nhiều, trước hết chỉ ngồi năm phút. Vẽ một chút đã đổi tâm trạng, ngày tiếp tục vẽ cũng nhiều hơn. Trước khi bắt đầu tưởng vất vả, nhưng động tay lại vui nhanh hơn ngờ. Tôi không bỏ hẳn tivi; chỉ bắt đầu một chút việc thật sự muốn làm trước. Với tôi, đổi cách dùng phần đầu thời gian đang có phù hợp hơn chờ rảnh nhiều hơn.\nNgười dẫn: Về thời gian sau khi về nhà, người này muốn truyền đạt điều gì?\nNgười dẫn: Sự tiện lợi khi để sẵn giấy bút trên bàn.\nNgười dẫn: Trải nghiệm xem tivi đến khuya.\nNgười dẫn: Vẽ lúc mệt giúp đổi tâm trạng.\nNgười dẫn: Bắt đầu chút ít việc muốn làm trước giúp tận dụng thời gian.', NULL, '[{"expression":"時間","reading":"じかん","meaning_vi":"thời gian"},{"expression":"鉛筆","reading":"えんぴつ","meaning_vi":"bút chì"}]', 402, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-017', 'N3-L-SUMMARY', 'N3', 'LISTENING', 17, NULL, NULL, '[{"speaker":"N","ja":"友だちに誕生日のプレゼントを選ぶとき、前は値段の高いものほど喜ばれると思っていました。去年は何を買えばよいか決まらず、一緒に過ごした日の写真を小さな本にして渡しました。写真の横には、その日の短い思い出を書きました。友だちは何度もページを開き、こんなこともあったねと笑ってくれました。買ったものではないので、がっかりされないか心配していたのですが、今年もその本を大事に持っていると聞きました。写真を選びながら、私自身も友だちとの時間を思い出して楽しくなりました。相手のことを考えながら使った時間も、ちゃんと伝わるのですね。贈り物を選ぶときは、値段より、その人と自分の間にあるものを考えたいと思うようになりました。"},{"speaker":"N","ja":"贈り物について、この人の考えはどう変わりましたか。"},{"speaker":"N","ja":"値段より相手とのつながりを表すことを大事にしたい。"},{"speaker":"N","ja":"写真を小さな本にまとめる方法を知った。"},{"speaker":"N","ja":"去年の友だちの誕生日を思い出した。"},{"speaker":"N","ja":"写真の横に短い文を書く楽しさを知った。"}]', 'Người dẫn: Trước đây chọn quà sinh nhật cho bạn, tôi nghĩ càng đắt càng được thích. Năm ngoái không quyết được mua gì, tôi làm sách ảnh nhỏ từ những ngày cùng nhau, bên ảnh viết kỷ niệm ngắn. Bạn mở đi mở lại, cười nhớ rằng đã có chuyện thế này. Tôi lo bạn thất vọng vì không phải đồ mua, nhưng năm nay nghe bạn vẫn giữ sách rất quý. Lúc chọn ảnh, bản thân tôi cũng vui khi nhớ thời gian bên bạn. Thời gian dành ra khi nghĩ về người ấy cũng được cảm nhận. Tôi bắt đầu muốn chọn quà dựa vào điều gắn giữa hai người hơn là giá.\nNgười dẫn: Suy nghĩ của người này về quà tặng đã thay đổi thế nào?\nNgười dẫn: Muốn coi trọng biểu đạt gắn bó với người nhận hơn giá.\nNgười dẫn: Biết cách gom ảnh thành sách nhỏ.\nNgười dẫn: Nhớ sinh nhật bạn năm ngoái.\nNgười dẫn: Biết niềm vui viết câu ngắn cạnh ảnh.', NULL, '[{"expression":"写真","reading":"しゃしん","meaning_vi":"tấm ảnh; ảnh chụp; ảnh"},{"expression":"誕生日","reading":"たんじょうび","meaning_vi":"sinh nhật"}]', 410, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-018', 'N3-L-SUMMARY', 'N3', 'LISTENING', 18, NULL, NULL, '[{"speaker":"N","ja":"学校の食堂で、食べ残しを減らすための取り組みが始まりました。前は全員に同じ量のご飯を出していたので、少ししか食べない人には多すぎ、運動の後の人には足りないことがありました。今は、注文するときに、ご飯の量を三つから選べます。大きな量を選ぶことを恥ずかしがる必要も、小さな量にして遠慮する必要もありません。自分が食べられる量を考えることが大切です。毎日同じ量を選ぶ必要はなく、その日の体調に合わせて変えられます。まだ始めて一か月ですが、残るご飯は少なくなりました。残さず食べなさいと言うだけでなく、最初から無理なく食べきれる方法を考えると、一人一人が行動しやすくなるのだと感じています。"},{"speaker":"N","ja":"食堂の取り組みについて、この人が一番伝えたいことは何ですか。"},{"speaker":"N","ja":"運動した後はご飯を多く食べたくなる。"},{"speaker":"N","ja":"一人一人が量を選べると食べ残しを減らしやすい。"},{"speaker":"N","ja":"食堂では三つの量から注文できる。"},{"speaker":"N","ja":"体調によって食べられる量が変わる。"}]', 'Người dẫn: Nhà ăn trường bắt đầu hoạt động giảm đồ ăn thừa. Trước đây ai cũng nhận cùng lượng cơm nên người ăn ít thấy quá nhiều, người vừa vận động lại thiếu. Giờ khi gọi món có thể chọn ba lượng cơm. Không cần ngại chọn nhiều hay miễn cưỡng chọn ít. Quan trọng là nghĩ lượng mình ăn được. Không cần ngày nào cũng chọn cùng lượng; có thể đổi theo thể trạng hôm đó. Mới một tháng nhưng cơm thừa đã giảm. Tôi cảm thấy thay vì chỉ bảo ăn hết, tạo cơ chế ngay từ đầu để mỗi người ăn vừa sức sẽ giúp từng người dễ hành động hơn.\nNgười dẫn: Người này muốn truyền đạt nhất điều gì về hoạt động của nhà ăn?\nNgười dẫn: Sau vận động sẽ muốn ăn cơm nhiều.\nNgười dẫn: Có lựa chọn hợp từng người sẽ dễ giảm đồ ăn thừa.\nNgười dẫn: Nhà ăn cho chọn ba lượng cơm.\nNgười dẫn: Lượng ăn được đổi theo thể trạng.', NULL, '[{"expression":"食堂","reading":"しょくどう","meaning_vi":"nhà ăn; căn tin"},{"expression":"量","reading":"りょう","meaning_vi":"lượng (nhiều hay ít)"}]', 395, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-019', 'N3-L-SUMMARY', 'N3', 'LISTENING', 19, NULL, NULL, '[{"speaker":"N","ja":"先月、友だちと小さな演奏会を開きました。私は準備の係で、会場や時間を知らせる紙を作りました。必要な情報は全部書いたつもりでしたが、駅からどう行くのか分からないという電話が何件もありました。私たちはいつも使う会場なので、道の説明が必要だと思わなかったのです。次の会には、初めて来る人に案内を見てもらい、分かりにくい点を教えてもらいました。駅の出口と曲がる角を加えるだけで、ずっと分かりやすくなりました。読み手に一度確かめてもらう手間が、当日の困りごとを減らしてくれました。自分が知っていることは、相手も知っているとは限りません。知らせるときは、初めて見る人の立場で確かめることが必要だと学びました。"},{"speaker":"N","ja":"演奏会の案内作りから、この人は何を学びましたか。"},{"speaker":"N","ja":"駅の出口と曲がる角を紙に加えたこと。"},{"speaker":"N","ja":"案内を作るときに会場を確認したこと。"},{"speaker":"N","ja":"受け取る人の知識に合わせて情報を確かめること。"},{"speaker":"N","ja":"演奏会の前に問い合わせが来たこと。"}]', 'Người dẫn: Tháng trước tôi cùng bạn tổ chức buổi biểu diễn nhỏ. Phụ trách chuẩn bị, tôi làm giấy thông báo địa điểm giờ giấc. Tưởng đã đủ thông tin nhưng nhiều người gọi không biết đi từ ga thế nào. Chúng tôi dùng hội trường quen nên không nghĩ cần chỉ đường. Lần sau tôi nhờ người mới xem hướng dẫn và chỉ chỗ khó hiểu. Thêm cửa ra ga và góc rẽ đã dễ hiểu hơn nhiều. Công nhờ người đọc kiểm một lượt đã giảm rắc rối trong ngày tổ chức. Điều mình biết không có nghĩa người khác cũng biết. Tôi học rằng khi thông báo cần kiểm tra từ góc nhìn người lần đầu xem.\nNgười dẫn: Từ việc làm hướng dẫn buổi biểu diễn, người này học được gì?\nNgười dẫn: Đã thêm cửa ra ga và góc rẽ vào giấy.\nNgười dẫn: Đã xác nhận hội trường khi làm hướng dẫn.\nNgười dẫn: Kiểm tra thông tin theo kiến thức của người nhận.\nNgười dẫn: Có người hỏi trước buổi biểu diễn.', NULL, '[{"expression":"会場","reading":"かいじょう","meaning_vi":"địa điểm tổ chức (sự kiện); hội trường"},{"expression":"情報","reading":"じょうほう","meaning_vi":"thông tin; tin tức"}]', 398, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-020', 'N3-L-SUMMARY', 'N3', 'LISTENING', 20, NULL, NULL, '[{"speaker":"N","ja":"私は新しい服が欲しくなると、すぐ店へ行っていました。あるとき部屋を片づけると、買ったままほとんど着ていない服が何枚も出てきました。色は好きでも、持っている服と合わせにくかったのです。それから、何か買う前に、持っている服を写真で確認するようにしました。店で気に入っても、何と一緒に着るか思いつかなければ、その日は買わずに帰ります。買い物の回数は減りましたが、毎朝着るものを選ぶのは楽になりました。服の写真を見て、忘れていた一枚をまた着るようになったこともあります。物を増やす前に、今ある物をよく知ることが大切なのですね。買わないことを我慢するより、使える物を選ぶ楽しさを感じています。"},{"speaker":"N","ja":"服の買い方について、この人は主に何を話していますか。"},{"speaker":"N","ja":"部屋を片づけると忘れた服が出てくること。"},{"speaker":"N","ja":"店で好きな色の服を見つける楽しさ。"},{"speaker":"N","ja":"毎朝着る服を早く選べるようになったこと。"},{"speaker":"N","ja":"持っている物をよく知ると役立つ買い物ができる。"}]', 'Người dẫn: Cứ muốn quần áo mới là trước đây tôi ra cửa hàng ngay. Một lần dọn phòng, tôi tìm thấy nhiều món mua mà hầu như chưa mặc. Màu đẹp nhưng khó phối với đồ có sẵn. Từ đó trước khi mua tôi xem ảnh đồ đang có. Dù thích ở cửa hàng, nếu chưa nghĩ được phối với gì thì hôm ấy về không mua. Số lần mua sắm giảm nhưng sáng chọn đồ dễ hơn. Xem ảnh quần áo còn khiến tôi mặc lại món từng quên. Trước khi thêm đồ, cần biết rõ đồ đang có. Tôi cảm thấy vui vì chọn đồ dùng được, hơn là phải nhịn không mua.\nNgười dẫn: Người này chủ yếu nói gì về cách mua quần áo?\nNgười dẫn: Dọn phòng sẽ tìm ra quần áo đã quên.\nNgười dẫn: Niềm vui tìm màu đồ thích ở cửa hàng.\nNgười dẫn: Đã có thể chọn đồ mặc buổi sáng nhanh hơn.\nNgười dẫn: Nắm đồ mình có giúp mua sắm hữu ích.', NULL, '[{"expression":"服","reading":"ふく","meaning_vi":"quần áo"},{"expression":"買い物","reading":"かいもの＜する＞","meaning_vi":"mua sắm; việc mua sắm; việc đi chợ"}]', 397, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-021', 'N3-L-SUMMARY', 'N3', 'LISTENING', 21, NULL, NULL, '[{"speaker":"N","ja":"町の歴史を紹介する写真と説明を見に行きました。古い建物の写真が並んでいましたが、最初は今と違うなと思うだけでした。ところが、その町で育った人の短い話が写真の横にあると、急に景色が身近に感じられました。雨の日に友だちを待った店や、初めて一人で買い物をした道など、普通の生活の話です。有名な出来事だけでは分からなかった、町の人の気持ちが伝わってきました。帰ってから祖父に昔の話を聞くと、いつもの駅にも家族の思い出があることを知りました。一枚の写真も、そこにいた人の声と一緒に見ると違って感じられます。歴史は遠い昔の特別な人だけのものではありません。身近な人の経験を聞くことも、町を知る大切な方法なのですね。"},{"speaker":"N","ja":"町の写真と説明を見て、この人が気づいたことは何ですか。"},{"speaker":"N","ja":"普通の人の思い出からも地域の歴史を理解できる。"},{"speaker":"N","ja":"昔と今で建物の形が違うこと。"},{"speaker":"N","ja":"祖父に家族の思い出を聞く楽しさ。"},{"speaker":"N","ja":"古い写真の横に短い話が書いてあったこと。"}]', 'Người dẫn: Tôi đi xem ảnh và lời giải thích giới thiệu lịch sử khu phố. Ban đầu nhìn ảnh nhà cũ chỉ thấy khác bây giờ. Nhưng khi bên ảnh có lời kể ngắn của người lớn lên ở đó, cảnh vật bỗng gần gũi. Đó là chuyện bình thường: quán chờ bạn ngày mưa, con đường lần đầu đi mua đồ một mình. Cảm xúc cư dân mà các sự kiện nổi tiếng không thể hiện đã truyền đến tôi. Về hỏi ông chuyện xưa, tôi biết ga quen cũng có ký ức gia đình. Cùng một tấm ảnh, xem cùng lời kể người từng ở đó sẽ cảm nhận khác. Lịch sử không chỉ thuộc người đặc biệt ở quá khứ xa. Nghe trải nghiệm của người gần mình cũng là cách quan trọng để hiểu khu phố.\nNgười dẫn: Xem ảnh và lời giải thích về khu phố, người này nhận ra điều gì?\nNgười dẫn: Ký ức người bình thường cũng giúp hiểu lịch sử địa phương.\nNgười dẫn: Hình dáng nhà khác nhau giữa xưa và nay.\nNgười dẫn: Niềm vui hỏi ông ký ức gia đình.\nNgười dẫn: Bên ảnh cũ có viết lời kể ngắn.', NULL, '[{"expression":"歴史","reading":"れきし","meaning_vi":"lịch sử; môn sử"},{"expression":"写真","reading":"しゃしん","meaning_vi":"tấm ảnh; ảnh chụp; ảnh"}]', 401, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-022', 'N3-L-SUMMARY', 'N3', 'LISTENING', 22, NULL, NULL, '[{"speaker":"N","ja":"外国語を勉強している友だちと、週に一度、お互いの言葉で話しています。初めは、間違えたらすぐ直してほしいと頼みました。でも、言うたびに止めてもらうと、話したかった内容を忘れてしまいました。相談して、話している間は意味が伝わらないときだけ聞き返し、終わってから大事な間違いを二つ教えてもらうことにしました。それからは、前より長く自分の考えを話せるようになりました。正しい言葉を覚えることはもちろん必要です。終わった後には、次に使ってみたい表現を短いメモに残しています。ただ、全部の間違いをその場で直すのが、いつもよい練習になるとは限りません。話す楽しさと、後で確かめる時間の両方を大事にしたいです。"},{"speaker":"N","ja":"会話の練習について、この人の考えに合うものはどれですか。"},{"speaker":"N","ja":"週に一度友だちと外国語を話している。"},{"speaker":"N","ja":"話を続けることと後で直すことを組み合わせたい。"},{"speaker":"N","ja":"練習の後に短いメモを残している。"},{"speaker":"N","ja":"話を止められると内容を忘れることがある。"}]', 'Người dẫn: Tôi cùng người bạn học ngoại ngữ trò chuyện bằng ngôn ngữ của nhau mỗi tuần. Ban đầu tôi nhờ sửa ngay khi sai. Nhưng bị dừng mỗi lần nói khiến tôi quên điều muốn kể. Chúng tôi thống nhất trong lúc nói chỉ hỏi lại khi không hiểu ý, kết thúc mới chỉ hai lỗi quan trọng. Từ đó tôi nói suy nghĩ dài hơn. Sau buổi nói tôi ghi ngắn biểu đạt muốn dùng lần sau. Học lời đúng tất nhiên cần thiết, nhưng sửa mọi lỗi tại chỗ không phải lúc nào cũng là luyện tập tốt. Tôi muốn coi trọng cả niềm vui nói và thời gian kiểm tra sau đó.\nNgười dẫn: Ý nào hợp suy nghĩ của người này về luyện hội thoại?\nNgười dẫn: Nói ngoại ngữ với bạn mỗi tuần.\nNgười dẫn: Muốn kết hợp giữ mạch nói và sửa sau đó.\nNgười dẫn: Ghi ngắn sau khi luyện.\nNgười dẫn: Có khi quên nội dung khi bị ngắt lời.', NULL, '[{"expression":"練習","reading":"れんしゅう＜する＞","meaning_vi":"luyện tập"},{"expression":"言葉","reading":"ことば","meaning_vi":"từ; từ ngữ; lời nói"}]', 402, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-023', 'N3-L-SUMMARY', 'N3', 'LISTENING', 23, NULL, NULL, '[{"speaker":"N","ja":"会社の昼休みに、いつも机でパンを食べながら仕事のメールを読んでいました。休んでいるつもりでも、午後になると頭がぼんやりして、簡単な間違いをすることがありました。ある日、同僚に誘われて、十分だけ外を歩いてみました。特別なことを話したわけではありませんが、戻ると仕事を始めやすく感じました。それからは、短くても机を離れる時間を作っています。歩けない日も、窓の近くでお茶を飲むなど、小さな休み方を選んでいます。忙しいほど休む時間を削りたくなりますが、仕事を続けながらの休みでは、気持ちが変わらないのですね。長い休みが取れなくても、仕事から一度離れる工夫が、その後の集中を助けるのだと思います。"},{"speaker":"N","ja":"昼休みについて、この人が一番伝えたいことは何ですか。"},{"speaker":"N","ja":"同僚に外を歩こうと誘われた経験。"},{"speaker":"N","ja":"昼休みにパンを食べていたこと。"},{"speaker":"N","ja":"短くても仕事から離れる休みがその後に役立つ。"},{"speaker":"N","ja":"歩けない日は窓のそばでお茶を飲むこと。"}]', 'Người dẫn: Giờ nghỉ trưa ở công ty, tôi luôn ăn bánh tại bàn vừa đọc email việc. Tưởng đang nghỉ nhưng chiều đầu óc lơ mơ, đôi khi sai việc đơn giản. Một hôm đồng nghiệp rủ đi ngoài trời mười phút. Chẳng nói gì đặc biệt mà lúc về tôi thấy dễ bắt tay vào việc hơn. Từ đó tôi tạo thời gian rời bàn dù ngắn. Hôm không đi bộ được, tôi chọn nghỉ nhỏ như uống trà gần cửa sổ. Càng bận càng muốn cắt nghỉ, nhưng nghỉ mà tiếp tục làm thì tâm trí không chuyển được. Dù không nghỉ dài, tìm cách tạm rời công việc giúp tập trung sau đó.\nNgười dẫn: Người này muốn truyền đạt nhất điều gì về giờ nghỉ trưa?\nNgười dẫn: Trải nghiệm được đồng nghiệp rủ đi bộ.\nNgười dẫn: Đã ăn bánh trong giờ nghỉ trưa.\nNgười dẫn: Nghỉ tách khỏi công việc dù ngắn vẫn có ích về sau.\nNgười dẫn: Hôm không đi bộ thì uống trà bên cửa sổ.', NULL, '[{"expression":"仕事","reading":"しごと","meaning_vi":"công việc; nghề; việc làm"},{"expression":"昼休み","reading":"ひるやすみ","meaning_vi":"giờ nghỉ trưa; nghỉ trưa"}]', 391, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-024', 'N3-L-SUMMARY', 'N3', 'LISTENING', 24, NULL, NULL, '[{"speaker":"N","ja":"子ども向けの本を作る仕事をしています。先日、動物について説明するページを見てもらったところ、子どもたちは私たちが大事だと思った文章より、小さな絵に注目しました。その絵から、どうしてこうなるのと質問がいくつも出てきたのです。最初は説明を読んでほしいと思いましたが、質問を聞くうちに、そこから学びが始まるのだと分かりました。今は、答えを全部先に書くのではなく、何だろうと考えたくなる部分を残しています。子どもの反応を見て初めて、作る側だけでは気づけない入口が見えました。正しい知識を伝えることに加えて、自分で知りたいと思う気持ちを育てたいからです。本を開いた人が次の疑問を持てるようなページを作りたいです。"},{"speaker":"N","ja":"この人は、子どもの本を作るうえで何を大切にしたいですか。"},{"speaker":"N","ja":"動物の絵を子どもに見てもらうこと。"},{"speaker":"N","ja":"子どもが出した質問を集めて読むこと。"},{"speaker":"N","ja":"大人が大事だと思う文章を選ぶこと。"},{"speaker":"N","ja":"答えを伝えるだけでなく子どもの好奇心を引き出す。"}]', 'Người dẫn: Tôi làm sách cho trẻ. Gần đây nhờ các em xem trang giải thích động vật, các em chú ý hình nhỏ hơn đoạn văn chúng tôi thấy quan trọng. Từ hình ấy xuất hiện nhiều câu hỏi tại sao như vậy. Ban đầu tôi muốn các em đọc giải thích, nhưng nghe câu hỏi mới hiểu việc học bắt đầu từ đó. Giờ tôi không viết sẵn mọi câu trả lời mà để lại phần khiến người đọc tự hỏi. Nhìn phản ứng trẻ tôi mới thấy lối vào việc học mà người làm sách không tự nhận ra. Ngoài truyền kiến thức đúng, tôi muốn nuôi ham muốn tự tìm hiểu. Tôi muốn làm trang sách khiến người mở ra nảy sinh câu hỏi tiếp theo.\nNgười dẫn: Khi làm sách trẻ em, người này muốn coi trọng điều gì?\nNgười dẫn: Cho trẻ xem tranh động vật.\nNgười dẫn: Gom và đọc câu hỏi trẻ nêu.\nNgười dẫn: Chọn đoạn văn người lớn thấy quan trọng.\nNgười dẫn: Không chỉ cho đáp án mà gợi tính tò mò của trẻ.', NULL, '[{"expression":"子ども","reading":"こども","meaning_vi":"trẻ con; con; trẻ em"},{"expression":"質問","reading":"しつもん＜する＞","meaning_vi":"câu hỏi; hỏi (thầy; người khác)"}]', 405, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-025', 'N3-L-SUMMARY', 'N3', 'LISTENING', 25, NULL, NULL, '[{"speaker":"N","ja":"雨の日に出かけると気分が暗くなるので、以前は休みの日の雨が嫌いでした。ところが、友だちに誘われて雨の公園を歩いたとき、葉の色がいつもよりきれいだと感じました。人が少なく、雨の音もゆっくり聞けました。それから、晴れた日と同じことをしようとするのではなく、雨の日に合う楽しみを探しています。家で温かいお茶を入れて本を読むのも、その一つです。もちろん、大雨の日に無理に外へ行くことはしません。一つの過ごし方にこだわらなくなると、雨の予報にも前ほどがっかりしません。天気を変えることはできませんが、一日の過ごし方は少し選べます。予定どおりにならない日も、その日にできる楽しみを見つけると、気持ちが楽になるのです。"},{"speaker":"N","ja":"雨の日の話で、この人が伝えたいことは何ですか。"},{"speaker":"N","ja":"状況に合う楽しみを探すと気持ちを変えられる。"},{"speaker":"N","ja":"雨の公園では葉の色がきれいに見える。"},{"speaker":"N","ja":"雨の日は家でお茶を飲んで本を読める。"},{"speaker":"N","ja":"天気予報を見て外出を決めている。"}]', 'Người dẫn: Trước đây tôi ghét mưa ngày nghỉ vì ra ngoài ngày mưa thấy buồn. Nhưng lần đi công viên mưa theo lời bạn rủ, tôi thấy màu lá đẹp hơn thường. Ít người, có thể thong thả nghe mưa. Từ đó thay vì cố làm giống ngày nắng, tôi tìm niềm vui hợp ngày mưa, như pha trà nóng đọc sách ở nhà. Tất nhiên mưa lớn tôi không ép ra ngoài. Không bám vào một cách dùng ngày nữa, tôi cũng bớt thất vọng khi nghe dự báo mưa. Không thể đổi thời tiết nhưng có thể chọn phần nào cách dùng ngày. Ngày không theo kế hoạch vẫn nhẹ lòng hơn nếu tìm được niềm vui có thể làm hôm ấy.\nNgười dẫn: Qua chuyện ngày mưa, người này muốn truyền đạt điều gì?\nNgười dẫn: Tìm niềm vui hợp hoàn cảnh có thể đổi tâm trạng.\nNgười dẫn: Lá ở công viên mưa trông đẹp.\nNgười dẫn: Ngày mưa có thể uống trà đọc sách tại nhà.\nNgười dẫn: Quyết định ra ngoài dựa dự báo thời tiết.', NULL, '[{"expression":"雨","reading":"あめ","meaning_vi":"mưa"},{"expression":"天気","reading":"てんき","meaning_vi":"thời tiết"}]', 399, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-026', 'N3-L-SUMMARY', 'N3', 'LISTENING', 26, NULL, NULL, '[{"speaker":"N","ja":"店で働き始めたころ、お客さんに質問されると、すぐに答えなければと思っていました。ある日、よく確かめずに商品の使い方を説明し、後で間違いに気づきました。お客さんに連絡して謝りましたが、余計な手間をかけてしまいました。先輩から、少し待っていただいても、正しいことを伝えるほうが安心してもらえると言われました。今は、自信がないときは、確認しますと伝えて調べています。待つ理由をきちんと伝えれば、お客さんも落ち着いて待ってくださいます。何でもすぐ答えられる人だけが、よい店員なのではありません。分からないことをごまかさず、確かめてから責任を持って答えることも、お客さんとの信頼を作る大切な仕事だと思います。"},{"speaker":"N","ja":"接客の経験から、この人は何が重要だと考えていますか。"},{"speaker":"N","ja":"商品の使い方を説明するときに失敗したこと。"},{"speaker":"N","ja":"速さだけでなく確かめた情報を正しく伝えること。"},{"speaker":"N","ja":"間違った説明をした後で謝ったこと。"},{"speaker":"N","ja":"待ってもらう理由をお客さんに話すこと。"}]', 'Người dẫn: Khi mới làm ở cửa hàng, khách hỏi là tôi nghĩ phải đáp ngay. Có hôm chưa kiểm kỹ đã giải thích cách dùng sản phẩm, sau mới phát hiện sai. Tôi liên lạc xin lỗi nhưng làm khách tốn công thêm. Tiền bối nói dù để khách đợi chút, thông tin đúng sẽ khiến họ yên tâm hơn. Giờ thiếu chắc chắn tôi báo sẽ xác nhận rồi tra. Giải thích rõ lý do cần đợi thì khách cũng bình tĩnh chờ. Không phải chỉ người đáp ngay mọi thứ mới là nhân viên tốt. Không che điều chưa biết, kiểm rồi trả lời có trách nhiệm cũng là việc quan trọng tạo niềm tin với khách.\nNgười dẫn: Từ trải nghiệm tiếp khách, người này thấy điều gì quan trọng?\nNgười dẫn: Đã sai khi giải thích cách dùng sản phẩm.\nNgười dẫn: Không chỉ nhanh mà cần truyền thông tin chắc chắn, trung thực.\nNgười dẫn: Đã xin lỗi sau khi giải thích sai.\nNgười dẫn: Nói với khách lý do cần chờ.', NULL, '[{"expression":"商品","reading":"しょうひん","meaning_vi":"hàng hóa; sản phẩm"},{"expression":"先輩","reading":"せんぱい","meaning_vi":"người khoá trên; tiền bối; người đi trước"}]', 405, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-027', 'N3-L-SUMMARY', 'N3', 'LISTENING', 27, NULL, NULL, '[{"speaker":"N","ja":"近所で、使わなくなった道具を持ち寄る会がありました。私は、家の棚にしまったままの大きな鍋を持っていきました。捨てるにはもったいないけれど、一人暮らしでは使う機会がなかったのです。会場で、家族の多い人がちょうど欲しかったと言って受け取ってくれました。私は、別の人が持ってきた小さな花をもらいました。お金を使わずに物が手に入るだけでなく、その物をどんなふうに使っていたかという話も聞けました。物を受け取る人の顔が見えると、手放すときにも気持ちよさがありました。自分には要らなくなった物でも、別の人の生活では役立つことがあります。すぐ捨てる前に、次に使う人を探す方法があると知って、うれしくなりました。"},{"speaker":"N","ja":"道具を持ち寄る会について、この人が伝えたいことは何ですか。"},{"speaker":"N","ja":"一人で暮らすと大きな鍋を使う機会が少ない。"},{"speaker":"N","ja":"会場でお金を使わず物を受け取れる。"},{"speaker":"N","ja":"使わない物を人につなぐと新たな役割が生まれる。"},{"speaker":"N","ja":"もらった物について前に使っていた人と話せる。"}]', 'Người dẫn: Khu tôi có buổi mang dụng cụ không dùng nữa đến trao đổi. Tôi đem nồi lớn cất mãi trên kệ; vứt thì tiếc nhưng sống một mình không có dịp dùng. Một người gia đình đông nhận, nói đúng món đang muốn. Tôi nhận cây hoa nhỏ người khác mang tới. Không chỉ có đồ không tốn tiền, tôi còn nghe chuyện họ từng dùng nó thế nào. Thấy mặt người nhận đồ khiến lúc trao đi cũng dễ chịu. Đồ mình không cần nữa có thể hữu ích với đời sống người khác. Tôi vui khi biết trước khi vứt còn có cách tìm người dùng tiếp.\nNgười dẫn: Người này muốn truyền đạt điều gì về buổi mang dụng cụ đến trao đổi?\nNgười dẫn: Sống một mình ít dịp dùng nồi lớn.\nNgười dẫn: Ở buổi trao đổi có thể nhận đồ không tốn tiền.\nNgười dẫn: Chuyển đồ không dùng cho người khác tạo vai trò mới cho đồ.\nNgười dẫn: Có thể trò chuyện về đồ nhận với chủ trước.', NULL, '[{"expression":"道具","reading":"どうぐ","meaning_vi":"dụng cụ; đạo cụ"},{"expression":"生活","reading":"せいかつ＜する＞","meaning_vi":"sinh hoạt; sinh sống; cuộc sống"}]', 410, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-028', 'N3-L-SUMMARY', 'N3', 'LISTENING', 28, NULL, NULL, '[{"speaker":"N","ja":"アルバイト先で、新しく入った人に仕事を教えることになりました。私は自分が覚えた順番で一度に説明しましたが、相手は何度もうなずくだけで、作業を始めると困ってしまいました。そこで、一つ説明したら実際にやってもらい、どこが難しいか聞くようにしました。すると、言葉の意味が分からなかったことや、道具の場所を知らなかったことが分かりました。私には当たり前でも、初めての人には小さな疑問がたくさんあるのですね。教えた後に一緒に作業を見直すと、お互いに安心して次へ進めました。説明を終えたことと、相手ができるようになったことは同じではありません。教える側も相手の様子を見ながら、進み方を変える必要があると感じました。"},{"speaker":"N","ja":"新人に教えた経験から、この人は何を学びましたか。"},{"speaker":"N","ja":"道具の場所を知らない人がいたこと。"},{"speaker":"N","ja":"相手が何度もうなずいていたこと。"},{"speaker":"N","ja":"自分が覚えた順番で仕事を説明したこと。"},{"speaker":"N","ja":"相手の理解を確かめながら教え方を調整すること。"}]', 'Người dẫn: Ở chỗ làm thêm, tôi được giao dạy người mới. Tôi giải thích một lượt theo thứ tự mình từng học, nhưng người ấy chỉ gật và lúc bắt tay làm lại lúng túng. Tôi đổi sang giải thích một việc rồi cho thực hành, hỏi chỗ khó. Nhờ vậy biết có từ họ chưa hiểu, chỗ dụng cụ chưa biết. Điều tôi thấy đương nhiên lại chứa nhiều thắc mắc nhỏ với người mới. Dạy xong cùng xem lại thao tác giúp cả hai yên tâm chuyển sang việc tiếp. Giải thích xong không đồng nghĩa người kia đã làm được. Tôi thấy người dạy cũng cần theo dõi người học và đổi nhịp tiến hành.\nNgười dẫn: Từ việc dạy người mới, người này học được gì?\nNgười dẫn: Có người chưa biết chỗ dụng cụ.\nNgười dẫn: Người kia đã gật nhiều lần.\nNgười dẫn: Đã giải thích việc theo thứ tự mình từng học.\nNgười dẫn: Kiểm tra người kia hiểu tới đâu rồi điều chỉnh cách dạy.', NULL, '[{"expression":"仕事","reading":"しごと","meaning_vi":"công việc; nghề; việc làm"},{"expression":"道具","reading":"どうぐ","meaning_vi":"dụng cụ; đạo cụ"}]', 400, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-029', 'N3-L-SUMMARY', 'N3', 'LISTENING', 29, NULL, NULL, '[{"speaker":"N","ja":"毎年、年の初めに大きな目標を立てていましたが、春になるころには何を決めたか忘れていました。今年は方法を変えて、月の終わりに、できたことを三つだけ手帳に書いています。最初は、小さすぎて書く意味がないと思うこともありました。苦手な料理を一度作ったとか、久しぶりの友だちに連絡したとか、そのくらいのことです。でも、数か月分を読み返すと、少しずつ新しいことをしているのが分かりました。後から読むと、そのときは気づかなかった自分の努力にも気づけました。できなかったことばかり考えるより、次にやってみようという気持ちが出てきます。大きな結果だけを待たず、小さな変化を自分で認めることも、前へ進む力になるのだと思います。"},{"speaker":"N","ja":"手帳に記録することについて、この人が最も伝えたいことは何ですか。"},{"speaker":"N","ja":"小さな成功を認めるとまた頑張ろうと思える。"},{"speaker":"N","ja":"月末に手帳を開く習慣を作った。"},{"speaker":"N","ja":"苦手な料理を一度作ることができた。"},{"speaker":"N","ja":"久しぶりの友だちに連絡する楽しさを知った。"}]', 'Người dẫn: Hàng năm đầu năm tôi đặt mục tiêu lớn nhưng đến xuân đã quên. Năm nay đổi cách, cuối tháng ghi đúng ba điều đã làm được vào sổ. Ban đầu có điều nhỏ đến mức tôi nghĩ viết vô nghĩa: thử món khó một lần, liên lạc bạn lâu không gặp. Nhưng đọc lại vài tháng thấy mình từng chút làm điều mới. Đọc sau này tôi còn nhận ra nỗ lực của mình mà lúc ấy không để ý. Thay vì chỉ nghĩ việc chưa làm được, tôi có thêm ý muốn thử tiếp. Tôi nghĩ không chỉ chờ kết quả lớn, tự ghi nhận thay đổi nhỏ cũng tạo sức tiến lên.\nNgười dẫn: Về ghi chép trong sổ tay, người này muốn truyền đạt nhất điều gì?\nNgười dẫn: Ghi nhận thành tựu nhỏ tạo động lực tiếp theo.\nNgười dẫn: Đã tạo thói quen mở sổ cuối tháng.\nNgười dẫn: Đã nấu được món khó một lần.\nNgười dẫn: Biết niềm vui liên lạc bạn lâu không gặp.', NULL, '[{"expression":"目標","reading":"もくひょう","meaning_vi":"mục tiêu; mục đích; đích cụ thể cần đạt"},{"expression":"手帳","reading":"てちょう","meaning_vi":"sổ tay"}]', 409, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-030', 'N3-L-SUMMARY', 'N3', 'LISTENING', 30, NULL, NULL, '[{"speaker":"N","ja":"町のバスについて意見を集める会に参加しました。私は便が少ないことだけが問題だと思っていましたが、ほかの人の話を聞くと、違う困りごとがありました。小さな子どもを連れた人は乗り場の屋根を望み、足の悪い人は停留所までの道を心配していました。学生からは、学校が終わる時間と合わないという意見も出ました。同じバスを使っていても、必要なことは人によって違うのですね。すぐに全部を変えるのは難しいでしょう。自分と違う意見を聞いても、すぐ反対するのではなく理由を尋ねたいです。それでも、一人の考えだけで決めず、いろいろな生活を知ることが、使いやすい町を作る大切な方法になると感じました。次の会でも、まず人の話をよく聞きたいです。"},{"speaker":"N","ja":"バスの意見交換会で、この人が大切だと感じたことは何ですか。"},{"speaker":"N","ja":"子ども連れの人が屋根を望んでいること。"},{"speaker":"N","ja":"いろいろな利用者の声を聞いて改善を考えること。"},{"speaker":"N","ja":"学生が学校の時間に合うバスを必要としていること。"},{"speaker":"N","ja":"足の悪い人が停留所までの道を心配していること。"}]', 'Người dẫn: Tôi dự buổi lấy ý kiến về xe buýt khu phố. Tôi tưởng vấn đề chỉ là ít chuyến, nhưng nghe người khác thấy khó khăn khác: người có con nhỏ muốn mái che chỗ đón, người chân yếu lo đường tới trạm, học sinh nói giờ xe không hợp giờ tan học. Cùng dùng xe mà nhu cầu tùy người khác nhau. Nghe ý khác mình, tôi muốn hỏi lý do thay vì phản đối ngay. Có lẽ khó đổi tất cả ngay, nhưng thay vì quyết bằng suy nghĩ một người, biết nhiều lối sống là bước đầu tạo khu phố dễ dùng. Buổi sau tôi cũng muốn trước hết nghe kỹ người khác.\nNgười dẫn: Ở buổi trao đổi ý kiến xe buýt, người này thấy điều gì quan trọng?\nNgười dẫn: Người có con nhỏ muốn mái che.\nNgười dẫn: Nghe tiếng nói nhiều nhóm người dùng để nghĩ cải thiện.\nNgười dẫn: Học sinh cần xe buýt hợp giờ học.\nNgười dẫn: Người chân yếu lo đường tới trạm.', NULL, '[{"expression":"意見","reading":"いけん","meaning_vi":"ý kiến"},{"expression":"学生","reading":"がくせい","meaning_vi":"học sinh; sinh viên"}]', 424, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-001', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 1, NULL, NULL, '[{"speaker":"N","ja":"取引先から届いた資料に、一ページ足りないことが分かりました。相手の会社の担当者に、そのページをメールで送ってもらいたいとき、何と言いますか。"},{"speaker":"N","ja":"足りないページをお送りいただけますか。"},{"speaker":"N","ja":"足りないページをお送りいたしましょうか。"},{"speaker":"N","ja":"足りないページをご覧になりました。"}]', 'Người dẫn: Tài liệu đối tác gửi thiếu một trang. Bạn muốn nhờ người phụ trách bên đối tác gửi trang đó qua email. Bạn nói gì?\nNgười dẫn (phương án 1): Anh/chị gửi giúp trang còn thiếu được không?\nNgười dẫn (phương án 2): Tôi gửi giúp trang còn thiếu nhé?\nNgười dẫn (phương án 3): Anh/chị đã xem trang còn thiếu.', 'Tài liệu đối tác gửi thiếu một trang. Bạn muốn nhờ người phụ trách bên đối tác gửi trang đó qua email. Bạn nói gì? Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"資料","reading":"しりょう","meaning_vi":"tài liệu; tư liệu"},{"expression":"相手","reading":"あいて","meaning_vi":"đối phương; đối thủ; người cùng tương tác"}]', 126, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-002', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 2, NULL, NULL, '[{"speaker":"N","ja":"受付で待っているお客様を、会議室まで自分が案内します。部屋の場所を知らないお客様に、ついて来てもらうとき何と言いますか。"},{"speaker":"N","ja":"会議室からお帰りになりますか。"},{"speaker":"N","ja":"私が会議室までご案内いたします。"},{"speaker":"N","ja":"会議室まで私をご案内ください。"}]', 'Người dẫn: Bạn đón khách đang chờ ở quầy và tự dẫn đến phòng họp. Bạn mời khách đi theo thế nào?\nNgười dẫn (phương án 1): Quý khách sẽ từ phòng họp về à?\nNgười dẫn (phương án 2): Tôi xin dẫn quý khách đến phòng họp.\nNgười dẫn (phương án 3): Xin quý khách dẫn tôi đến phòng họp.', 'Bạn đón khách đang chờ ở quầy và tự dẫn đến phòng họp. Bạn mời khách đi theo thế nào? Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"受付","reading":"うけつけ","meaning_vi":"quầy tiếp tân; quầy tiếp đón; quầy tiếp nhận"},{"expression":"会議室","reading":"かいぎしつ","meaning_vi":"phòng họp"}]', 106, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-003', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 3, NULL, NULL, '[{"speaker":"N","ja":"上司から今夜の食事に誘われましたが、家族と約束があって参加できません。誘ってくれたことに感謝しながら断るとき、何と言いますか。"},{"speaker":"N","ja":"お誘いありがとうございます、今夜は必ず伺います。"},{"speaker":"N","ja":"今夜の食事は、私から皆さんにお知らせします。"},{"speaker":"N","ja":"お誘いありがとうございます、あいにく今夜は都合がつきません。"}]', 'Người dẫn: Cấp trên mời ăn tối nhưng bạn đã hẹn gia đình. Bạn muốn cảm ơn rồi từ chối. Bạn nói gì?\nNgười dẫn (phương án 1): Cảm ơn lời mời, tối nay nhất định tôi sẽ đến.\nNgười dẫn (phương án 2): Tôi sẽ thông báo bữa tối cho mọi người.\nNgười dẫn (phương án 3): Cảm ơn lời mời, tiếc là tối nay tôi không sắp xếp được.', 'Cấp trên mời ăn tối nhưng bạn đã hẹn gia đình. Bạn muốn cảm ơn rồi từ chối. Bạn nói gì? Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"上司","reading":"じょうし","meaning_vi":"cấp trên"},{"expression":"都合","reading":"つごう","meaning_vi":"sự tiện; thu xếp được; sự thuận tiện"}]', 139, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-004', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 4, NULL, NULL, '[{"speaker":"N","ja":"会議中、自分の説明に間違いがあることに気づきました。先ほど伝えた金額を直してから説明を続けたいとき、何と言いますか。"},{"speaker":"N","ja":"申し訳ありません、先ほどの金額を直させてください。"},{"speaker":"N","ja":"先ほどの金額について、もう一度説明していただけますか。"},{"speaker":"N","ja":"先ほどの金額で間違いございません。"}]', 'Người dẫn: Trong cuộc họp bạn nhận ra đã giải thích sai số tiền. Bạn muốn sửa rồi trình bày tiếp. Bạn nói gì?\nNgười dẫn (phương án 1): Xin lỗi, cho phép tôi sửa số tiền vừa nói.\nNgười dẫn (phương án 2): Anh/chị giải thích lại số tiền vừa nói giúp được không?\nNgười dẫn (phương án 3): Số tiền vừa nói không sai.', 'Trong cuộc họp bạn nhận ra đã giải thích sai số tiền. Bạn muốn sửa rồi trình bày tiếp. Bạn nói gì? Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"金額","reading":"きんがく","meaning_vi":"số tiền; kim ngạch"},{"expression":"間違い","reading":"まちがい","meaning_vi":"sự nhầm lẫn; sai sót"}]', 127, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-005', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 5, NULL, NULL, '[{"speaker":"N","ja":"出張から戻った先輩に、お土産をもらいました。先輩が自分のために選んでくれたことにお礼を言いたいとき、何と言いますか。"},{"speaker":"N","ja":"お土産を選んでいただきましょうか。"},{"speaker":"N","ja":"わざわざ選んでくださって、ありがとうございます。"},{"speaker":"N","ja":"わざわざ選んでさしあげて、ありがとうございます。"}]', 'Người dẫn: Bạn nhận quà từ tiền bối mới đi công tác về. Bạn cảm ơn vì tiền bối đã chọn quà cho mình.\nNgười dẫn (phương án 1): Hay chúng ta nhờ chọn quà nhé?\nNgười dẫn (phương án 2): Cảm ơn anh/chị đã cất công chọn cho em.\nNgười dẫn (phương án 3): Cảm ơn vì em đã cất công chọn tặng anh/chị.', 'Bạn nhận quà từ tiền bối mới đi công tác về. Bạn cảm ơn vì tiền bối đã chọn quà cho mình. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"先輩","reading":"せんぱい","meaning_vi":"người khoá trên; tiền bối; người đi trước"},{"expression":"土産","reading":"みやげ","meaning_vi":"quà lưu niệm; quà địa phương; quà mang về"}]', 123, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-006', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 6, NULL, NULL, '[{"speaker":"N","ja":"駅のホームで、お客様から預かった荷物を自分が持ちます。重い荷物を持っているお客様に、申し出るとき何と言いますか。"},{"speaker":"N","ja":"そのお荷物、私の部屋まで運んでいただけますか。"},{"speaker":"N","ja":"そのお荷物は、こちらでお買い求めになりましたか。"},{"speaker":"N","ja":"そのお荷物、私がお持ちいたしましょうか。"}]', 'Người dẫn: Trên sân ga bạn muốn chủ động xách hành lý nặng giúp khách. Bạn nói gì?\nNgười dẫn (phương án 1): Quý khách mang hành lý đó đến phòng tôi giúp được không?\nNgười dẫn (phương án 2): Quý khách đã mua hành lý đó ở đây phải không?\nNgười dẫn (phương án 3): Tôi xách hành lý đó giúp quý khách nhé?', 'Trên sân ga bạn muốn chủ động xách hành lý nặng giúp khách. Bạn nói gì? Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"荷物","reading":"にもつ","meaning_vi":"hành lý; kiện hàng; đồ đạc"},{"expression":"ホーム","reading":"ほーむ","meaning_vi":"sân ga; nhà"}]', 123, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-007', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 7, NULL, NULL, '[{"speaker":"N","ja":"店で予約していた品物を受け取りましたが、注文した色と違っています。店員に確認を頼みたいとき、何と言いますか。"},{"speaker":"N","ja":"注文した色と違うようなので、確かめていただけますか。"},{"speaker":"N","ja":"注文した色と同じなので、確かめる必要はありません。"},{"speaker":"N","ja":"注文した色を私からお決めいたします。"}]', 'Người dẫn: Bạn nhận món đã đặt nhưng khác màu yêu cầu. Bạn nhờ nhân viên kiểm tra.\nNgười dẫn (phương án 1): Có vẻ khác màu đã đặt, anh/chị kiểm tra giúp được không?\nNgười dẫn (phương án 2): Cùng màu đã đặt nên không cần kiểm tra.\nNgười dẫn (phương án 3): Tôi xin quyết định màu đã đặt.', 'Bạn nhận món đã đặt nhưng khác màu yêu cầu. Bạn nhờ nhân viên kiểm tra. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"注文","reading":"ちゅうもん","meaning_vi":"gọi món; đặt hàng; gọi đồ"},{"expression":"品物","reading":"しなもの","meaning_vi":"món hàng; vật phẩm"}]', 123, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-008', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 8, NULL, NULL, '[{"speaker":"N","ja":"お客様との打ち合わせが長くなり、次の約束の時間が近づいています。失礼にならないように、先に帰る必要を伝えるとき何と言いますか。"},{"speaker":"N","ja":"次の約束には、お客様だけでお出かけください。"},{"speaker":"N","ja":"次の約束がございますので、そろそろ失礼させていただきます。"},{"speaker":"N","ja":"次の約束がございますので、もっと長くお話しください。"}]', 'Người dẫn: Buổi trao đổi với khách kéo dài, bạn sắp đến giờ hẹn tiếp. Bạn xin rời đi lịch sự.\nNgười dẫn (phương án 1): Xin quý khách tự đi cuộc hẹn tiếp.\nNgười dẫn (phương án 2): Tôi có cuộc hẹn tiếp nên xin phép rời đi.\nNgười dẫn (phương án 3): Tôi có cuộc hẹn tiếp nên xin quý khách nói lâu hơn.', 'Buổi trao đổi với khách kéo dài, bạn sắp đến giờ hẹn tiếp. Bạn xin rời đi lịch sự. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"約束","reading":"やくそく","meaning_vi":"cuộc hẹn; hứa; lời hứa"},{"expression":"伝える","reading":"つたえる","meaning_vi":"truyền đạt; nhắn lại; truyền lại"}]', 140, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-009', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 9, NULL, NULL, '[{"speaker":"N","ja":"上司が留守の間に、取引先から電話が来ました。上司が戻ったら自分から電話をかけ直すと伝えたいとき、何と言いますか。"},{"speaker":"N","ja":"戻り次第、もう一度お電話いただけますでしょうか。"},{"speaker":"N","ja":"担当者はただいま外出中でございます。"},{"speaker":"N","ja":"戻り次第、こちらからお電話いたします。"}]', 'Người dẫn: Đối tác gọi khi cấp trên vắng. Bạn muốn nói cấp trên về rồi bên mình sẽ gọi lại.\nNgười dẫn (phương án 1): Sau khi về, phía anh/chị gọi lại được không?\nNgười dẫn (phương án 2): Người phụ trách hiện đang ra ngoài.\nNgười dẫn (phương án 3): Ngay khi về, bên tôi sẽ gọi lại.', 'Đối tác gọi khi cấp trên vắng. Bạn muốn nói cấp trên về rồi bên mình sẽ gọi lại. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"上司","reading":"じょうし","meaning_vi":"cấp trên"},{"expression":"電話","reading":"でんわ","meaning_vi":"gọi điện thoại; điện thoại"}]', 117, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-010', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 10, NULL, NULL, '[{"speaker":"N","ja":"会社の見学に来た学生に、撮影できない場所を説明します。工場の中では写真を撮らないよう、丁寧に頼むとき何と言いますか。"},{"speaker":"N","ja":"工場内での撮影は、ご遠慮ください。"},{"speaker":"N","ja":"工場内では、自由に撮影してくださって結構です。"},{"speaker":"N","ja":"工場の写真は、受付でお受け取りください。"}]', 'Người dẫn: Bạn hướng dẫn sinh viên tham quan công ty, cần lịch sự yêu cầu không chụp trong nhà máy.\nNgười dẫn (phương án 1): Xin vui lòng không chụp trong nhà máy.\nNgười dẫn (phương án 2): Cứ tự do chụp trong nhà máy.\nNgười dẫn (phương án 3): Xin nhận ảnh nhà máy ở quầy.', 'Bạn hướng dẫn sinh viên tham quan công ty, cần lịch sự yêu cầu không chụp trong nhà máy. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"工場","reading":"こうじょう","meaning_vi":"nhà xưởng; nhà máy; công xưởng"},{"expression":"撮影","reading":"さつえい","meaning_vi":"quay phim; chụp ảnh"}]', 118, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-011', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 11, NULL, NULL, '[{"speaker":"N","ja":"後輩が作った報告書を読みました。数字の間違いを本人に直してもらいたいですが、責める言い方は避けたいです。数字を直してほしい後輩に何と言いますか。"},{"speaker":"N","ja":"この数字はそのままで、見直さなくてもいいよ。"},{"speaker":"N","ja":"この数字だけ、もう一度見直してもらえるかな。"},{"speaker":"N","ja":"この数字について、あとで私が説明しておくよ。"}]', 'Người dẫn: Bạn đọc báo cáo hậu bối, muốn nhờ sửa số liệu bằng lời nhẹ nhàng.\nNgười dẫn (phương án 1): Giữ nguyên số này, không cần xem lại.\nNgười dẫn (phương án 2): Em xem lại riêng số này một lần nữa được không?\nNgười dẫn (phương án 3): Về số này, lát tôi sẽ giải thích.', 'Bạn đọc báo cáo hậu bối, muốn nhờ sửa số liệu bằng lời nhẹ nhàng. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"後輩","reading":"こうはい","meaning_vi":"hậu bối; đàn em (vào sau mình)"},{"expression":"数字","reading":"すうじ","meaning_vi":"chữ số; con số; số"}]', 138, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-012', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 12, NULL, NULL, '[{"speaker":"N","ja":"講演会で質問したいことがありますが、司会者はまだ次の話を始めていません。話し始める前に、質問する許可を求めるとき何と言いますか。"},{"speaker":"N","ja":"何かご質問がございましたら、お知らせください。"},{"speaker":"N","ja":"質問はございませんので、次へ進んでください。"},{"speaker":"N","ja":"一点、質問させていただいてもよろしいでしょうか。"}]', 'Người dẫn: Bạn muốn hỏi ở buổi diễn thuyết trước khi người dẫn chuyển phần. Bạn xin phép thế nào?\nNgười dẫn (phương án 1): Nếu có câu hỏi gì xin cho biết.\nNgười dẫn (phương án 2): Tôi không có câu hỏi, xin sang phần tiếp.\nNgười dẫn (phương án 3): Xin cho phép tôi hỏi một điểm được không?', 'Bạn muốn hỏi ở buổi diễn thuyết trước khi người dẫn chuyển phần. Bạn xin phép thế nào? Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"講演会","reading":"こうえんかい","meaning_vi":"buổi diễn thuyết; hội thảo"},{"expression":"質問","reading":"しつもん","meaning_vi":"câu hỏi; hỏi (thầy; người khác)"}]', 133, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-013', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 13, NULL, NULL, '[{"speaker":"N","ja":"同僚が締め切りに間に合わず困っています。自分の仕事は終わったので、資料の整理を代わりにすることを申し出たいです。締め切りで困っている同僚に何と言いますか。"},{"speaker":"N","ja":"資料の整理なら、私が引き受けようか。"},{"speaker":"N","ja":"私の資料も、あなたが整理しておいて。"},{"speaker":"N","ja":"資料の整理は終わったことにしておこう。"}]', 'Người dẫn: Đồng nghiệp lo không kịp hạn, bạn đã xong việc và muốn nhận sắp xếp tài liệu giúp.\nNgười dẫn (phương án 1): Việc sắp xếp tài liệu thì để tôi nhận nhé?\nNgười dẫn (phương án 2): Cậu sắp xếp cả tài liệu của tôi nhé.\nNgười dẫn (phương án 3): Coi như đã sắp xếp xong đi.', 'Đồng nghiệp lo không kịp hạn, bạn đã xong việc và muốn nhận sắp xếp tài liệu giúp. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"締め切り","reading":"しめきり","meaning_vi":"hạn chót; hạn cuối; hạn"},{"expression":"資料","reading":"しりょう","meaning_vi":"tài liệu; tư liệu"}]', 132, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-014', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 14, NULL, NULL, '[{"speaker":"N","ja":"会場に到着した先生に、すでに来ている参加者を紹介します。参加者が先生の話を聞くために来たことを伝えるとき何と言いますか。"},{"speaker":"N","ja":"先生は皆さんのお話を伺ってくださいました。"},{"speaker":"N","ja":"皆さん、先生のお話を伺うためにいらっしゃいました。"},{"speaker":"N","ja":"皆さん、先生にお話を聞いていただくために参りました。"}]', 'Người dẫn: Bạn giới thiệu với giáo viên vừa đến rằng người tham dự tới để nghe bài nói của thầy/cô.\nNgười dẫn (phương án 1): Thầy/cô đã nghe mọi người trình bày.\nNgười dẫn (phương án 2): Mọi người đã đến để nghe thầy/cô trình bày.\nNgười dẫn (phương án 3): Mọi người đến để được thầy/cô nghe mình.', 'Bạn giới thiệu với giáo viên vừa đến rằng người tham dự tới để nghe bài nói của thầy/cô. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"会場","reading":"かいじょう","meaning_vi":"địa điểm tổ chức (sự kiện); hội trường"},{"expression":"伝える","reading":"つたえる","meaning_vi":"truyền đạt; nhắn lại; truyền lại"}]', 132, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-015', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 15, NULL, NULL, '[{"speaker":"N","ja":"ホテルで隣の部屋の声が大きく、眠れません。直接注意せず、フロントに部屋の状況を確かめてもらいたいとき何と言いますか。"},{"speaker":"N","ja":"隣の部屋の方に、もっと大きな声を出していただきたいです。"},{"speaker":"N","ja":"隣の部屋には、私がお泊まりになっています。"},{"speaker":"N","ja":"隣の部屋の声が聞こえるので、様子を見ていただけませんか。"}]', 'Người dẫn: Phòng khách sạn bên cạnh ồn khiến bạn không ngủ được. Bạn nhờ lễ tân kiểm tra.\nNgười dẫn (phương án 1): Tôi muốn người phòng bên nói to hơn.\nNgười dẫn (phương án 2): Tôi đang ở phòng bên (dùng tôn kính sai vai).\nNgười dẫn (phương án 3): Tiếng phòng bên vang quá, anh/chị kiểm tra giúp được không?', 'Phòng khách sạn bên cạnh ồn khiến bạn không ngủ được. Bạn nhờ lễ tân kiểm tra. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"ホテル","reading":"ほてる","meaning_vi":"khách sạn"},{"expression":"フロント","reading":"ふろんと","meaning_vi":"quầy lễ tân"}]', 135, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-016', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 16, NULL, NULL, '[{"speaker":"N","ja":"一緒に仕事をした相手が今日で会社を辞めます。これまで教えてもらったことに感謝を伝えるとき何と言いますか。"},{"speaker":"N","ja":"これまでいろいろ教えていただき、本当にありがとうございました。"},{"speaker":"N","ja":"これからも、この会社でよろしくお願いいたします。"},{"speaker":"N","ja":"これまで教えてさしあげたことを覚えていますか。"}]', 'Người dẫn: Đồng nghiệp nghỉ việc hôm nay. Bạn cảm ơn những điều người ấy đã chỉ dạy.\nNgười dẫn (phương án 1): Cảm ơn anh/chị đã chỉ dạy nhiều điều suốt thời gian qua.\nNgười dẫn (phương án 2): Mong tiếp tục được giúp đỡ ở công ty này.\nNgười dẫn (phương án 3): Anh/chị còn nhớ những gì tôi đã chỉ dạy cho anh/chị không?', 'Đồng nghiệp nghỉ việc hôm nay. Bạn cảm ơn những điều người ấy đã chỉ dạy. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"会社","reading":"かいしゃ","meaning_vi":"công ty"},{"expression":"感謝","reading":"かんしゃ","meaning_vi":"biết ơn; cảm tạ"}]', 130, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-017', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 17, NULL, NULL, '[{"speaker":"N","ja":"先輩が使っている道具を、自分も使ってみたいです。先輩の作業が終わってから貸してもらうよう頼むとき何と言いますか。"},{"speaker":"N","ja":"お使いになる前に、私に貸していただけますか。"},{"speaker":"N","ja":"お使いになったあとで、少し貸していただけますか。"},{"speaker":"N","ja":"今すぐ使うので、作業をやめてください。"}]', 'Người dẫn: Bạn muốn mượn dụng cụ sau khi tiền bối dùng xong. Bạn nhờ thế nào?\nNgười dẫn (phương án 1): Trước khi anh/chị dùng, cho em mượn được không?\nNgười dẫn (phương án 2): Sau khi anh/chị dùng xong, cho em mượn một chút được không?\nNgười dẫn (phương án 3): Em dùng ngay nên hãy dừng làm.', 'Bạn muốn mượn dụng cụ sau khi tiền bối dùng xong. Bạn nhờ thế nào? Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"道具","reading":"どうぐ","meaning_vi":"dụng cụ; đạo cụ"},{"expression":"先輩","reading":"せんぱい","meaning_vi":"người khoá trên; tiền bối; người đi trước"}]', 121, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-018', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 18, NULL, NULL, '[{"speaker":"N","ja":"会議の日程を変更したいという連絡を受けました。相手の希望を先に聞いてから、自分の予定を調べたいとき何と言いますか。"},{"speaker":"N","ja":"こちらで日を決めましたので、ご希望は結構です。"},{"speaker":"N","ja":"こちらの予定をご確認いただいてから、お知らせください。"},{"speaker":"N","ja":"ご希望の日を伺ってから、こちらの予定を確認いたします。"}]', 'Người dẫn: Bạn được yêu cầu đổi lịch họp, muốn hỏi ngày đối tác mong muốn trước khi xem lịch mình.\nNgười dẫn (phương án 1): Bên tôi đã chọn ngày nên không cần hỏi mong muốn.\nNgười dẫn (phương án 2): Xin kiểm tra lịch bên tôi rồi báo lại.\nNgười dẫn (phương án 3): Tôi xin hỏi ngày mong muốn rồi kiểm tra lịch bên tôi.', 'Bạn được yêu cầu đổi lịch họp, muốn hỏi ngày đối tác mong muốn trước khi xem lịch mình. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"日程","reading":"にってい","meaning_vi":"lịch trình theo ngày; lịch trình; kế hoạch"},{"expression":"予定","reading":"よてい","meaning_vi":"dự định; lịch trình; kế hoạch"}]', 134, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-019', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 19, NULL, NULL, '[{"speaker":"N","ja":"図書館の静かな部屋で、隣の人が電話を始めました。けんかにならないように、部屋の外で話してもらいたいとき何と言いますか。"},{"speaker":"N","ja":"すみませんが、お電話は外でお願いできますか。"},{"speaker":"N","ja":"よろしければ、ここでもっと長くお話しください。"},{"speaker":"N","ja":"お電話の内容を、私にも教えていただけますか。"}]', 'Người dẫn: Người bên cạnh gọi điện trong phòng yên tĩnh thư viện. Bạn lịch sự nhờ ra ngoài.\nNgười dẫn (phương án 1): Xin lỗi làm phiền, anh/chị ra ngoài nghe điện thoại được không?\nNgười dẫn (phương án 2): Nếu được cứ nói lâu hơn ở đây.\nNgười dẫn (phương án 3): Cho tôi biết cả nội dung cuộc gọi được không?', 'Người bên cạnh gọi điện trong phòng yên tĩnh thư viện. Bạn lịch sự nhờ ra ngoài. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"図書館","reading":"としょかん","meaning_vi":"thư viện"},{"expression":"内容","reading":"ないよう","meaning_vi":"nội dung; nội dung thông tin; thứ chứa bên trong"}]', 126, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-020', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 20, NULL, NULL, '[{"speaker":"N","ja":"取引先で担当者を待っていますが、急な用事で帰ることになりました。来たことだけ担当者に伝えてもらうとき、受付で何と言いますか。"},{"speaker":"N","ja":"担当の方が戻られるまで、こちらで待たせてください。"},{"speaker":"N","ja":"私が伺ったことを、お伝えいただけますでしょうか。"},{"speaker":"N","ja":"私が来たことは、担当者には伝えないでください。"}]', 'Người dẫn: Bạn đang chờ người phụ trách đối tác nhưng phải về gấp. Bạn nhờ lễ tân báo rằng mình đã ghé.\nNgười dẫn (phương án 1): Cho tôi chờ ở đây đến khi người phụ trách trở về.\nNgười dẫn (phương án 2): Anh/chị chuyển lời rằng tôi đã ghé được không?\nNgười dẫn (phương án 3): Xin đừng báo người phụ trách rằng tôi đã đến.', 'Bạn đang chờ người phụ trách đối tác nhưng phải về gấp. Bạn nhờ lễ tân báo rằng mình đã ghé. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"受付","reading":"うけつけ","meaning_vi":"quầy tiếp tân; quầy tiếp đón; quầy tiếp nhận"},{"expression":"帰る","reading":"かえる","meaning_vi":"về; trở về (nhà hoặc nước)"}]', 134, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-021', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 21, NULL, NULL, '[{"speaker":"N","ja":"お客様に出したコーヒーを、自分の不注意でこぼしてしまいました。すぐに新しい物を持ってくると伝えるとき何と言いますか。"},{"speaker":"N","ja":"申し訳ございません、新しい物を持ってきていただきます。"},{"speaker":"N","ja":"お客様がこぼされたので、そのままで結構です。"},{"speaker":"N","ja":"申し訳ございません、すぐに新しい物をお持ちいたします。"}]', 'Người dẫn: Bạn sơ ý làm đổ cà phê của khách, muốn xin lỗi và mang ly mới ngay.\nNgười dẫn (phương án 1): Xin lỗi, tôi sẽ nhờ quý khách mang ly mới.\nNgười dẫn (phương án 2): Vì quý khách làm đổ nên cứ để nguyên.\nNgười dẫn (phương án 3): Xin lỗi quý khách, tôi sẽ mang ly mới ngay.', 'Bạn sơ ý làm đổ cà phê của khách, muốn xin lỗi và mang ly mới ngay. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"コーヒー","reading":"こーひー","meaning_vi":"cà phê"},{"expression":"申し訳","reading":"もうしわけ","meaning_vi":"lời biện bạch; xin lỗi"}]', 134, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-022', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 22, NULL, NULL, '[{"speaker":"N","ja":"職場で急に休んだため、同僚が自分の仕事を代わりにしてくれました。翌日、迷惑をかけたこととお礼を伝えるとき何と言いますか。"},{"speaker":"N","ja":"急に任せてしまってごめんね、助かりました。"},{"speaker":"N","ja":"急に任せてくれてありがとう、私が助けました。"},{"speaker":"N","ja":"昨日は私が代わりにやってあげたんだよ。"}]', 'Người dẫn: Bạn nghỉ đột xuất, đồng nghiệp làm thay. Hôm sau bạn xin lỗi và cảm ơn.\nNgười dẫn (phương án 1): Xin lỗi đã giao đột ngột cho cậu, cậu giúp tôi nhiều lắm.\nNgười dẫn (phương án 2): Cảm ơn đã giao đột ngột, tôi đã giúp.\nNgười dẫn (phương án 3): Hôm qua tôi đã làm thay cho cậu đấy.', 'Bạn nghỉ đột xuất, đồng nghiệp làm thay. Hôm sau bạn xin lỗi và cảm ơn. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"翌日","reading":"よくじつ","meaning_vi":"ngày hôm sau"},{"expression":"職場","reading":"しょくば","meaning_vi":"nơi làm việc; chỗ làm"}]', 122, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-023', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 23, NULL, NULL, '[{"speaker":"N","ja":"発表を聞いてくれた先生から、感想をもらいたいです。忙しそうなので、時間があるときに短く教えてもらうよう頼むとき何と言いますか。"},{"speaker":"N","ja":"今すぐ、私の感想を最後までお聞きください。"},{"speaker":"N","ja":"お時間のあるときに、一言ご感想をいただければ幸いです。"},{"speaker":"N","ja":"先生のご感想を、ほかの学生に伝えておきましょうか。"}]', 'Người dẫn: Bạn muốn xin nhận xét của giáo viên nhưng thấy bận, nên nhờ khi rảnh cho vài ý ngắn.\nNgười dẫn (phương án 1): Xin nghe hết nhận xét của em ngay bây giờ.\nNgười dẫn (phương án 2): Khi có thời gian, em rất mong nhận được vài lời nhận xét.\nNgười dẫn (phương án 3): Em chuyển nhận xét của thầy/cô cho sinh viên khác nhé?', 'Bạn muốn xin nhận xét của giáo viên nhưng thấy bận, nên nhờ khi rảnh cho vài ý ngắn. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"発表","reading":"はっぴょう","meaning_vi":"buổi trình bày; phát biểu; thông báo"},{"expression":"感想","reading":"かんそう","meaning_vi":"cảm tưởng; cảm nghĩ; suy nghĩ"}]', 136, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-024', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 24, NULL, NULL, '[{"speaker":"N","ja":"店で品物を見ているお客様から、別の大きさがあるか聞かれました。自分が奥で調べるので、少し待ってもらいたいとき何と言いますか。"},{"speaker":"N","ja":"奥で確認いたしますので、一緒に来ていただけますか。"},{"speaker":"N","ja":"お客様が奥でお調べになってから、お戻りください。"},{"speaker":"N","ja":"奥で確認してまいりますので、少々お待ちください。"}]', 'Người dẫn: Khách hỏi có cỡ khác không. Bạn sẽ kiểm tra phía trong và xin khách chờ.\nNgười dẫn (phương án 1): Tôi kiểm tra bên trong, quý khách đi cùng được không?\nNgười dẫn (phương án 2): Quý khách tự vào trong kiểm tra rồi quay lại.\nNgười dẫn (phương án 3): Tôi sẽ vào trong kiểm tra, xin quý khách đợi một chút.', 'Khách hỏi có cỡ khác không. Bạn sẽ kiểm tra phía trong và xin khách chờ. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"品物","reading":"しなもの","meaning_vi":"món hàng; vật phẩm"},{"expression":"確認","reading":"かくにん","meaning_vi":"việc kiểm lại; xác nhận; xác minh"}]', 135, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-025', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 25, NULL, NULL, '[{"speaker":"N","ja":"後輩が自分で作った計画を見せてくれました。大きく変える必要はありませんが、一か所だけ相談して直したいとき何と言いますか。"},{"speaker":"N","ja":"全体はこのままでいいから、この部分だけ相談しよう。"},{"speaker":"N","ja":"全部やり直して、相談はしなくてもいいよ。"},{"speaker":"N","ja":"一か所も変えられないから、見せないでね。"}]', 'Người dẫn: Hậu bối đưa kế hoạch. Bạn thấy chỉ cần bàn rồi sửa một chỗ.\nNgười dẫn (phương án 1): Tổng thể giữ như vậy được, chỉ bàn phần này nhé.\nNgười dẫn (phương án 2): Làm lại hết, không cần bàn.\nNgười dẫn (phương án 3): Không đổi chỗ nào được, đừng cho tôi xem.', 'Hậu bối đưa kế hoạch. Bạn thấy chỉ cần bàn rồi sửa một chỗ. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"計画","reading":"けいかく","meaning_vi":"kế hoạch"},{"expression":"部分","reading":"ぶぶん","meaning_vi":"một phần; bộ phận; bộ phận hoặc vị trí cụ thể"}]', 125, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-026', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 26, NULL, NULL, '[{"speaker":"N","ja":"上司が来週の出張に同行することになりました。空港まで自分が車で迎えに行くと申し出るとき、何と言いますか。"},{"speaker":"N","ja":"空港まで、私をお迎えになってください。"},{"speaker":"N","ja":"空港まで、私がお迎えに参りましょうか。"},{"speaker":"N","ja":"空港までの道を、私に教えていただけますか。"}]', 'Người dẫn: Cấp trên cùng đi công tác tuần sau. Bạn đề nghị lái xe đón ở sân bay.\nNgười dẫn (phương án 1): Xin anh/chị đến sân bay đón tôi.\nNgười dẫn (phương án 2): Tôi xin đến sân bay đón anh/chị nhé?\nNgười dẫn (phương án 3): Anh/chị chỉ đường đến sân bay cho tôi được không?', 'Cấp trên cùng đi công tác tuần sau. Bạn đề nghị lái xe đón ở sân bay. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"上司","reading":"じょうし","meaning_vi":"cấp trên"},{"expression":"空港","reading":"くうこう","meaning_vi":"sân bay"}]', 111, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-027', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 27, NULL, NULL, '[{"speaker":"N","ja":"会議で相手の意見を聞きましたが、すぐには賛成できません。一度持ち帰って同僚と相談したいとき何と言いますか。"},{"speaker":"N","ja":"今ここで決まりましたので、相談は不要です。"},{"speaker":"N","ja":"ご意見には賛成ですから、検討はいたしませんでした。"},{"speaker":"N","ja":"一度持ち帰って、社内で検討させていただけますか。"}]', 'Người dẫn: Bạn nghe ý kiến đối tác nhưng chưa thể đồng ý ngay, muốn đem về bàn với đồng nghiệp.\nNgười dẫn (phương án 1): Đã quyết ngay ở đây nên không cần bàn.\nNgười dẫn (phương án 2): Tôi đồng ý nên đã không xem xét.\nNgười dẫn (phương án 3): Cho phép chúng tôi đem về xem xét nội bộ một lần được không?', 'Bạn nghe ý kiến đối tác nhưng chưa thể đồng ý ngay, muốn đem về bàn với đồng nghiệp. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"会議","reading":"かいぎ","meaning_vi":"cuộc họp; họp; tổ chức cuộc họp"},{"expression":"意見","reading":"いけん","meaning_vi":"ý kiến"}]', 123, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-028', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 28, NULL, NULL, '[{"speaker":"N","ja":"先輩に紹介してもらった人と、初めてメールで連絡を取ります。誰から紹介されたかを丁寧に伝えるとき何と言いますか。"},{"speaker":"N","ja":"山田さんからご紹介いただき、ご連絡いたしました。"},{"speaker":"N","ja":"山田さんをご紹介したく、ご連絡いたしました。"},{"speaker":"N","ja":"山田さんにご連絡いただけますでしょうか。"}]', 'Người dẫn: Bạn lần đầu email người do tiền bối giới thiệu. Bạn lịch sự nói mình được ai giới thiệu.\nNgười dẫn (phương án 1): Tôi được anh/chị Yamada giới thiệu nên xin liên hệ.\nNgười dẫn (phương án 2): Tôi liên hệ vì muốn giới thiệu Yamada với anh/chị.\nNgười dẫn (phương án 3): Anh/chị liên hệ Yamada giúp được không?', 'Bạn lần đầu email người do tiền bối giới thiệu. Bạn lịch sự nói mình được ai giới thiệu. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"先輩","reading":"せんぱい","meaning_vi":"người khoá trên; tiền bối; người đi trước"},{"expression":"メール","reading":"めーる","meaning_vi":"thư điện tử; email"}]', 121, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-029', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 29, NULL, NULL, '[{"speaker":"N","ja":"会社の見学が終わりました。案内してくれた担当者に、仕事の様子がよく分かったことを伝えてお礼を言うとき何と言いますか。"},{"speaker":"N","ja":"案内は必要ありませんでしたから、もう帰ります。"},{"speaker":"N","ja":"ご案内のおかげで、仕事の様子がよく分かりました。"},{"speaker":"N","ja":"ご案内してさしあげたので、よく分かってください。"}]', 'Người dẫn: Kết thúc tham quan công ty, bạn cảm ơn người hướng dẫn vì đã hiểu công việc rõ hơn.\nNgười dẫn (phương án 1): Không cần hướng dẫn nên tôi về đây.\nNgười dẫn (phương án 2): Nhờ anh/chị hướng dẫn, tôi đã hiểu rõ công việc.\nNgười dẫn (phương án 3): Vì tôi đã hướng dẫn cho anh/chị nên hãy hiểu rõ.', 'Kết thúc tham quan công ty, bạn cảm ơn người hướng dẫn vì đã hiểu công việc rõ hơn. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"案内","reading":"あんない","meaning_vi":"hướng dẫn; dẫn đường; thông tin chỉ dẫn"},{"expression":"様子","reading":"ようす","meaning_vi":"tình hình; dáng vẻ; bộ dạng"}]', 129, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-030', 'N3-L-UTTERANCE', 'N3', 'LISTENING', 30, NULL, NULL, '[{"speaker":"N","ja":"友人の結婚式で、受付を手伝ってほしいと頼まれました。その日は遅れて着くため、最初からは担当できないと伝えるとき何と言いますか。"},{"speaker":"N","ja":"最初から行けるから、受付は全部任せて。"},{"speaker":"N","ja":"受付の場所は、私が先に調べておくね。"},{"speaker":"N","ja":"手伝いたいんだけど、着くのが遅いから最初からは難しいんだ。"}]', 'Người dẫn: Bạn được nhờ giúp quầy đón khách đám cưới nhưng sẽ đến muộn, nên không thể làm từ đầu.\nNgười dẫn (phương án 1): Tôi đến từ đầu được nên cứ giao hết quầy cho tôi.\nNgười dẫn (phương án 2): Tôi sẽ tra trước địa điểm quầy đón khách nhé.\nNgười dẫn (phương án 3): Tôi muốn giúp nhưng đến muộn nên từ đầu thì khó.', 'Bạn được nhờ giúp quầy đón khách đám cưới nhưng sẽ đến muộn, nên không thể làm từ đầu. Tranh đặt mũi tên vào người cần nói trong tình huống.', '[{"expression":"友人","reading":"ゆうじん","meaning_vi":"bạn; người bạn; bạn thân"},{"expression":"結婚式","reading":"けっこんしき","meaning_vi":"lễ cưới; lễ kết hôn"}]', 129, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-001', 'N3-L-RESPONSE', 'N3', 'LISTENING', 1, NULL, NULL, '[{"speaker":"F","ja":"さっきの会議、来週に延びたんだって。"},{"speaker":"M","ja":"じゃあ、今日中に資料を仕上げなくてもよさそうだね。"},{"speaker":"M","ja":"会議の資料は、もう全部印刷してあるよ。"},{"speaker":"M","ja":"来週は別の会議にも出る予定だよ。"}]', 'Nữ: Nghe nói cuộc họp vừa rồi hoãn sang tuần sau.\nNam (phương án 1): Vậy có vẻ không cần hoàn tất tài liệu ngay hôm nay.\nNam (phương án 2): Hồ sơ họp đã in hết rồi.\nNam (phương án 3): Tuần sau tôi còn dự cuộc họp khác.', NULL, '[{"expression":"会議","reading":"かいぎ","meaning_vi":"cuộc họp; họp; tổ chức cuộc họp"},{"expression":"資料","reading":"しりょう","meaning_vi":"tài liệu; tư liệu"}]', 78, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-002', 'N3-L-RESPONSE', 'N3', 'LISTENING', 2, NULL, NULL, '[{"speaker":"M","ja":"この書類、部長に見てもらっといてくれる？"},{"speaker":"F","ja":"部長の書類は、あとで私にも見せてね。"},{"speaker":"F","ja":"わかった、戻っていらしたらお渡しするね。"},{"speaker":"F","ja":"この書類は、部長が作ってくれたんだよ。"}]', 'Nam: Nhờ cậu đưa giấy này cho trưởng phòng xem giúp nhé?\nNữ (phương án 1): Giấy tờ của trưởng phòng lát cho tôi xem nữa nhé.\nNữ (phương án 2): Được, trưởng phòng về thì tôi đưa nhé.\nNữ (phương án 3): Tài liệu này trưởng phòng đã làm cho đấy.', NULL, '[{"expression":"書類","reading":"しょるい","meaning_vi":"giấy tờ; tài liệu; hồ sơ"},{"expression":"部長","reading":"ぶちょう","meaning_vi":"trưởng phòng; trưởng bộ phận; trưởng ban"}]', 77, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-003', 'N3-L-RESPONSE', 'N3', 'LISTENING', 3, NULL, NULL, '[{"speaker":"F","ja":"あれ、鍵、さっきここに置いといたはずなんだけど。"},{"speaker":"M","ja":"その鍵なら、昨日新しいのを買ったよ。"},{"speaker":"M","ja":"机の上は、あとで片づけておくね。"},{"speaker":"M","ja":"机の下に落ちてるのは、それじゃない？"}]', 'Nữ: Ủa, chìa khóa tôi vừa để sẵn đây mà.\nNam (phương án 1): Chìa đó hôm qua tôi mua chiếc mới rồi.\nNam (phương án 2): Mặt bàn lát tôi dọn sẵn nhé.\nNam (phương án 3): Cái rơi dưới bàn có phải nó không?', NULL, '[{"expression":"鍵","reading":"かぎ","meaning_vi":"cái khóa; chìa để mở khóa"},{"expression":"机","reading":"つくえ","meaning_vi":"bàn học; bàn làm việc"}]', 76, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-004', 'N3-L-RESPONSE', 'N3', 'LISTENING', 4, NULL, NULL, '[{"speaker":"M","ja":"今日の発表、緊張して何も言えなくなっちゃった。"},{"speaker":"F","ja":"そんな日もあるよ、次は一緒に練習しよう。"},{"speaker":"F","ja":"発表の会場は、駅から近くて便利だったね。"},{"speaker":"F","ja":"練習なら、先週一人でやっておいたよ。"}]', 'Nam: Thuyết trình hôm nay tôi hồi hộp đến mức không nói được gì.\nNữ (phương án 1): Có những hôm như vậy mà, lần sau cùng luyện nhé.\nNữ (phương án 2): Địa điểm thuyết trình gần ga tiện nhỉ.\nNữ (phương án 3): Luyện tập thì tuần trước tôi tự làm rồi.', NULL, '[{"expression":"発表","reading":"はっぴょう","meaning_vi":"buổi trình bày; phát biểu; thông báo"},{"expression":"緊張","reading":"きんちょう","meaning_vi":"hồi hộp; run; căng người vì lo"}]', 81, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-005', 'N3-L-RESPONSE', 'N3', 'LISTENING', 5, NULL, NULL, '[{"speaker":"F","ja":"その仕事、私一人じゃとても終わりそうにないんだけど。"},{"speaker":"M","ja":"一人で全部終わったんだね、お疲れさま。"},{"speaker":"M","ja":"じゃあ、半分は私が引き受けようか。"},{"speaker":"M","ja":"その仕事は、来月から始まるそうだよ。"}]', 'Nữ: Việc đó mình tôi có vẻ không thể nào làm xong.\nNam (phương án 1): Cậu làm xong hết một mình rồi nhỉ, vất vả quá.\nNam (phương án 2): Vậy tôi nhận một nửa nhé?\nNam (phương án 3): Nghe nói việc đó tháng sau mới bắt đầu.', NULL, '[{"expression":"仕事","reading":"しごと","meaning_vi":"công việc; nghề; việc làm"},{"expression":"半分","reading":"はんぶん","meaning_vi":"một nửa"}]', 80, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-006', 'N3-L-RESPONSE', 'N3', 'LISTENING', 6, NULL, NULL, '[{"speaker":"M","ja":"この店、安いからって、何でもおいしいわけじゃないね。"},{"speaker":"F","ja":"そうだね、値段が安ければ全部おいしいね。"},{"speaker":"F","ja":"この店の場所なら、前から知っていたよ。"},{"speaker":"F","ja":"そうだね、さっきのスープは少し薄かったね。"}]', 'Nam: Quán này rẻ nhưng đâu phải món nào cũng ngon nhỉ.\nNữ (phương án 1): Ừ, cứ rẻ thì tất cả đều ngon.\nNữ (phương án 2): Địa chỉ quán này tôi biết từ trước.\nNữ (phương án 3): Ừ, súp vừa rồi hơi nhạt.', NULL, '[{"expression":"値段","reading":"ねだん","meaning_vi":"giá cả; giá tiền"},{"expression":"スープ","reading":"スープ","meaning_vi":"món canh; súp; canh"}]', 86, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-007', 'N3-L-RESPONSE', 'N3', 'LISTENING', 7, NULL, NULL, '[{"speaker":"F","ja":"田中さん、もう帰ったんじゃない？かばんがないよ。"},{"speaker":"M","ja":"いや、かばんを持って別の部屋へ行っただけだよ。"},{"speaker":"M","ja":"田中さんのかばん、私も同じのが欲しいな。"},{"speaker":"M","ja":"うん、田中さんは今日はまだ来ていないよ。"}]', 'Nữ: Tanaka chắc về rồi nhỉ? Không thấy cặp.\nNam (phương án 1): Không, chỉ mang cặp sang phòng khác thôi.\nNam (phương án 2): Cặp của Tanaka tôi cũng muốn chiếc giống vậy.\nNam (phương án 3): Ừ, hôm nay Tanaka vẫn chưa đến.', NULL, '[{"expression":"かばん","reading":"かばん","meaning_vi":"cái cặp; giỏ xách"},{"expression":"部屋","reading":"へや","meaning_vi":"phòng; căn phòng"}]', 87, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-008', 'N3-L-RESPONSE', 'N3', 'LISTENING', 8, NULL, NULL, '[{"speaker":"M","ja":"昨日頼んだパン、買ってきてくれたっけ？"},{"speaker":"F","ja":"そのパンなら、駅の店でよく買うよ。"},{"speaker":"F","ja":"うん、台所の袋に入れてあるよ。"},{"speaker":"F","ja":"昨日はパンよりご飯が食べたかったな。"}]', 'Nam: Bánh mì tôi nhờ hôm qua, cậu mua về chưa nhỉ?\nNữ (phương án 1): Bánh đó tôi hay mua ở quán ở ga.\nNữ (phương án 2): Rồi, tôi để trong túi ở bếp.\nNữ (phương án 3): Hôm qua tôi muốn cơm hơn bánh mì.', NULL, '[{"expression":"パン","reading":"ぱん","meaning_vi":"bánh mì; bánh mỳ"},{"expression":"台所","reading":"だいどころ","meaning_vi":"bếp; nhà bếp"}]', 69, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-009', 'N3-L-RESPONSE', 'N3', 'LISTENING', 9, NULL, NULL, '[{"speaker":"F","ja":"雨さえやめば、予定どおり外でできるんだけどね。"},{"speaker":"M","ja":"じゃあ、雨が強くても外でできるんだね。"},{"speaker":"M","ja":"外で使ういすは、先週買っておいたよ。"},{"speaker":"M","ja":"じゃあ、もう少し天気の様子を見ようか。"}]', 'Nữ: Chỉ cần tạnh mưa thì làm ngoài trời như dự định được.\nNam (phương án 1): Vậy dù mưa mạnh vẫn làm ngoài trời được nhỉ.\nNam (phương án 2): Ghế dùng ngoài trời tuần trước tôi mua sẵn rồi.\nNam (phương án 3): Vậy đợi xem thời tiết thêm một chút nhé?', NULL, '[{"expression":"雨","reading":"あめ","meaning_vi":"mưa"},{"expression":"予定","reading":"よてい","meaning_vi":"dự định; lịch trình; kế hoạch"}]', 79, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-010', 'N3-L-RESPONSE', 'N3', 'LISTENING', 10, NULL, NULL, '[{"speaker":"M","ja":"この写真、消しちゃってもいい？同じのが二枚あるよ。"},{"speaker":"F","ja":"一枚は残しといて、もう一枚だけ消して。"},{"speaker":"F","ja":"同じ写真なら、私も旅行で撮ったことがあるよ。"},{"speaker":"F","ja":"その写真は、友達がメールで送ってくれたんだ。"}]', 'Nam: Ảnh này tôi xóa được không? Có hai tấm giống nhau.\nNữ (phương án 1): Giữ lại một tấm, chỉ xóa tấm kia.\nNữ (phương án 2): Ảnh giống vậy tôi cũng từng chụp khi du lịch.\nNữ (phương án 3): Ảnh đó bạn đã email cho tôi.', NULL, '[{"expression":"写真","reading":"しゃしん","meaning_vi":"tấm ảnh; ảnh chụp; ảnh"},{"expression":"旅行","reading":"りょこう","meaning_vi":"du lịch; chuyến đi"}]', 88, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-011', 'N3-L-RESPONSE', 'N3', 'LISTENING', 11, NULL, NULL, '[{"speaker":"F","ja":"この案、悪くはないけど、今すぐ決めるのは難しいな。"},{"speaker":"M","ja":"では、悪い案だと決まったんですね。"},{"speaker":"M","ja":"では、明日までにもう一度検討しましょう。"},{"speaker":"M","ja":"その案を考えたのは、田中さんだそうですよ。"}]', 'Nữ: Phương án này không tệ nhưng quyết ngay thì khó.\nNam (phương án 1): Vậy đã quyết là phương án tệ nhỉ.\nNam (phương án 2): Vậy đến ngày mai ta xem xét lại một lần.\nNam (phương án 3): Nghe nói người nghĩ ra phương án đó là Tanaka.', NULL, '[{"expression":"検討","reading":"けんとう","meaning_vi":"xem xét; cân nhắc; nghiên cứu"},{"expression":"もう一度","reading":"もういちど","meaning_vi":"một lần nữa"}]', 83, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-012', 'N3-L-RESPONSE', 'N3', 'LISTENING', 12, NULL, NULL, '[{"speaker":"M","ja":"もう少しで電車に乗り遅れるところだったよ。"},{"speaker":"F","ja":"乗れなかったんだね、次を待とう。"},{"speaker":"F","ja":"その電車は、一時間に二本出ているよ。"},{"speaker":"F","ja":"間に合ってよかったね、ずいぶん急いだんだね。"}]', 'Nam: Suýt nữa tôi lỡ tàu đấy.\nNữ (phương án 1): Không lên được nhỉ, đợi chuyến sau.\nNữ (phương án 2): Tàu đó chạy mỗi giờ hai chuyến.\nNữ (phương án 3): May kịp rồi, cậu chắc vội lắm.', NULL, '[{"expression":"電車","reading":"でんしゃ","meaning_vi":"tàu điện"},{"expression":"乗り遅れる","reading":"のりおくれる","meaning_vi":"lỡ chuyến tàu; nhỡ tàu; lỡ chuyến"}]', 77, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-013', 'N3-L-RESPONSE', 'N3', 'LISTENING', 13, NULL, NULL, '[{"speaker":"F","ja":"机の上、書類だらけで、どれが新しいのか分かんない。"},{"speaker":"M","ja":"日付で分けてみたら、探しやすいんじゃない？"},{"speaker":"M","ja":"新しい机は、来週会社に届くらしいよ。"},{"speaker":"M","ja":"書類を作るのは、いつも私の仕事なんだ。"}]', 'Nữ: Bàn toàn giấy tờ, tôi không biết cái nào mới.\nNam (phương án 1): Thử phân theo ngày thì dễ tìm hơn không?\nNam (phương án 2): Bàn mới nghe nói tuần sau đến công ty.\nNam (phương án 3): Làm tài liệu luôn là việc của tôi.', NULL, '[{"expression":"書類","reading":"しょるい","meaning_vi":"giấy tờ; tài liệu; hồ sơ"},{"expression":"日付","reading":"ひづけ","meaning_vi":"ngày tháng ghi trên giấy tờ; ngày tháng; ngày"}]', 83, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-014', 'N3-L-RESPONSE', 'N3', 'LISTENING', 14, NULL, NULL, '[{"speaker":"M","ja":"あの映画、期待してたほどじゃなかったな。"},{"speaker":"F","ja":"期待したとおりで、全部よかったんだね。"},{"speaker":"F","ja":"そうなんだ、どんなところが物足りなかった？"},{"speaker":"F","ja":"映画の時間は、インターネットで調べられるよ。"}]', 'Nam: Phim đó không được như tôi kỳ vọng.\nNữ (phương án 1): Đúng như kỳ vọng, tất cả đều hay nhỉ.\nNữ (phương án 2): Vậy à, cậu thấy thiếu ở điểm nào?\nNữ (phương án 3): Có thể tra giờ phim trên mạng.', NULL, '[{"expression":"映画","reading":"えいが","meaning_vi":"bộ phim; phim ảnh"},{"expression":"期待","reading":"きたい","meaning_vi":"kỳ vọng; hi vọng; mong chờ"}]', 82, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-015', 'N3-L-RESPONSE', 'N3', 'LISTENING', 15, NULL, NULL, '[{"speaker":"F","ja":"明日の朝までに直してほしいって言われちゃって。"},{"speaker":"M","ja":"直してほしくないと言われたんだね。"},{"speaker":"M","ja":"その資料なら、私も昨日読んだよ。"},{"speaker":"M","ja":"急だね、手伝える所があれば言ってね。"}]', 'Nữ: Tôi bị yêu cầu sửa xong trước sáng mai đấy.\nNam (phương án 1): Cậu được bảo không muốn sửa nhỉ.\nNam (phương án 2): Tài liệu đó hôm qua tôi cũng đọc rồi.\nNam (phương án 3): Gấp thật, có phần nào giúp được thì nói nhé.', NULL, '[{"expression":"資料","reading":"しりょう","meaning_vi":"tài liệu; tư liệu"},{"expression":"明日","reading":"あす","meaning_vi":"ngày mai"}]', 74, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-016', 'N3-L-RESPONSE', 'N3', 'LISTENING', 16, NULL, NULL, '[{"speaker":"M","ja":"今日は風邪気味だから、飲み会は遠慮しとくよ。"},{"speaker":"F","ja":"分かった、無理しないでゆっくり休んでね。"},{"speaker":"F","ja":"分かった、必ず来るって伝えておくね。"},{"speaker":"F","ja":"飲み会の店は、駅のそばだったよね。"}]', 'Nam: Hôm nay hơi cảm nên tôi xin không đi buổi nhậu.\nNữ (phương án 1): Được, đừng cố, nghỉ ngơi nhé.\nNữ (phương án 2): Được, tôi báo cậu nhất định đến nhé.\nNữ (phương án 3): Quán buổi nhậu ở cạnh ga nhỉ.', NULL, '[{"expression":"風邪","reading":"かぜ","meaning_vi":"cảm; cảm lạnh"},{"expression":"飲み会","reading":"のみかい","meaning_vi":"tiệc nhậu"}]', 77, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-017', 'N3-L-RESPONSE', 'N3', 'LISTENING', 17, NULL, NULL, '[{"speaker":"F","ja":"駅まで行くついでに、これもポストに入れといてくれない？"},{"speaker":"M","ja":"駅までなら、今日は歩いて行くつもりだよ。"},{"speaker":"M","ja":"いいよ、途中のポストに入れてくるね。"},{"speaker":"M","ja":"その切手は、近くの店でも買えるよ。"}]', 'Nữ: Tiện ra ga, cậu bỏ cả cái này vào hòm thư giúp được không?\nNam (phương án 1): Đến ga thì hôm nay tôi định đi bộ.\nNam (phương án 2): Được, tôi bỏ vào hòm thư dọc đường.\nNam (phương án 3): Tem đó mua ở cửa hàng gần đây cũng được.', NULL, '[{"expression":"駅","reading":"えき","meaning_vi":"nhà ga; ga"},{"expression":"ポスト","reading":"ぽすと","meaning_vi":"hộp thư; thùng thư; hòm thư"}]', 82, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-018', 'N3-L-RESPONSE', 'N3', 'LISTENING', 18, NULL, NULL, '[{"speaker":"M","ja":"話を聞いた限りでは、まだ決まってないみたいだね。"},{"speaker":"F","ja":"うん、正式に決まったからもう待たなくていいね。"},{"speaker":"F","ja":"その話をした人とは、去年知り合ったんだ。"},{"speaker":"F","ja":"うん、正式な連絡が来るまでは待ったほうがいいね。"}]', 'Nam: Theo những gì nghe được thì hình như vẫn chưa quyết nhỉ.\nNữ (phương án 1): Ừ, đã quyết chính thức nên không cần đợi nữa.\nNữ (phương án 2): Tôi quen người nói chuyện đó từ năm ngoái.\nNữ (phương án 3): Ừ, nên đợi đến khi có thông báo chính thức.', NULL, '[{"expression":"正式","reading":"せいしき","meaning_vi":"chính thức"},{"expression":"連絡","reading":"れんらく","meaning_vi":"liên lạc; báo tin; sự liên lạc"}]', 91, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-019', 'N3-L-RESPONSE', 'N3', 'LISTENING', 19, NULL, NULL, '[{"speaker":"F","ja":"資料を送ったつもりだったんだけど、まだ届いてない？"},{"speaker":"M","ja":"うん、念のためメールアドレスを確かめてもらえる？"},{"speaker":"M","ja":"届いた資料は、もう全部読ませてもらったよ。"},{"speaker":"M","ja":"送る気がなかったっていうことだね。"}]', 'Nữ: Tôi tưởng đã gửi tài liệu rồi, vẫn chưa nhận được à?\nNam (phương án 1): Ừ, cậu kiểm lại người nhận cho chắc được không?\nNam (phương án 2): Tài liệu nhận được tôi đã đọc hết rồi.\nNam (phương án 3): Tức là cậu đã không định gửi nhỉ.', NULL, '[{"expression":"資料","reading":"しりょう","meaning_vi":"tài liệu; tư liệu"},{"expression":"確か","reading":"たしか","meaning_vi":"hình như là (theo trí nhớ); chắc chắn; đáng tin"}]', 87, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-020', 'N3-L-RESPONSE', 'N3', 'LISTENING', 20, NULL, NULL, '[{"speaker":"M","ja":"この靴、見た目はいいんだけど、長く歩くにはちょっとね。"},{"speaker":"F","ja":"長く歩けるなら、その靴で出かけようよ。"},{"speaker":"F","ja":"足が痛くなるなら、別のをはいたほうがいいよ。"},{"speaker":"F","ja":"その靴は、駅前の店でも見かけたよ。"}]', 'Nam: Giày này nhìn đẹp nhưng đi bộ lâu thì hơi…\nNữ (phương án 1): Nếu đi lâu được thì đi đôi đó ra ngoài thôi.\nNữ (phương án 2): Nếu đau chân thì nên đi đôi khác.\nNữ (phương án 3): Đôi giày đó tôi cũng thấy ở cửa hàng trước ga.', NULL, '[{"expression":"靴","reading":"くつ","meaning_vi":"giày; đôi giày"},{"expression":"駅前","reading":"えきまえ","meaning_vi":"trước ga"}]', 85, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-021', 'N3-L-RESPONSE', 'N3', 'LISTENING', 21, NULL, NULL, '[{"speaker":"F","ja":"私がやるより、経験のある人に任せたほうがよくない？"},{"speaker":"M","ja":"そうだね、経験がない人だけに頼もう。"},{"speaker":"M","ja":"その仕事は、説明の資料があるらしいよ。"},{"speaker":"M","ja":"そうだね、山田さんに相談してみよう。"}]', 'Nữ: Giao cho người có kinh nghiệm hơn tôi có tốt hơn không?\nNam (phương án 1): Đúng, chỉ nhờ người thiếu kinh nghiệm thôi.\nNam (phương án 2): Nghe nói việc đó có tài liệu hướng dẫn.\nNam (phương án 3): Đúng nhỉ, thử hỏi Yamada nhé.', NULL, '[{"expression":"経験","reading":"けいけん","meaning_vi":"kinh nghiệm; trải qua"},{"expression":"仕事","reading":"しごと","meaning_vi":"công việc; nghề; việc làm"}]', 80, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-022', 'N3-L-RESPONSE', 'N3', 'LISTENING', 22, NULL, NULL, '[{"speaker":"M","ja":"こんなに並ぶなら、先に予約しとけばよかった。"},{"speaker":"F","ja":"今からでも、予約できるか聞いてみようか。"},{"speaker":"F","ja":"先に予約したおかげで、並ばずに済んだね。"},{"speaker":"F","ja":"予約の電話番号は、案内に書いてあったよ。"}]', 'Nam: Nếu biết xếp hàng thế này, giá mà đặt trước.\nNữ (phương án 1): Giờ thử hỏi còn đặt được không nhé?\nNữ (phương án 2): Nhờ đặt trước nên khỏi xếp hàng nhỉ.\nNữ (phương án 3): Số điện thoại đặt trước có ghi trong hướng dẫn.', NULL, '[{"expression":"予約","reading":"よやく","meaning_vi":"đặt chỗ trước; đặt chỗ"},{"expression":"電話","reading":"でんわ","meaning_vi":"gọi điện thoại; điện thoại"}]', 82, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-023', 'N3-L-RESPONSE', 'N3', 'LISTENING', 23, NULL, NULL, '[{"speaker":"F","ja":"田中さんの説明、分かったような、分かんないような。"},{"speaker":"M","ja":"全部よく分かったなら、説明はいらないね。"},{"speaker":"M","ja":"どこがはっきりしなかったか、一緒に整理しよう。"},{"speaker":"M","ja":"田中さんは、説明するのが仕事なんだよ。"}]', 'Nữ: Giải thích của Tanaka, tôi vừa như hiểu vừa như chưa hiểu.\nNam (phương án 1): Nếu hiểu hết rồi thì không cần giải thích nhỉ.\nNam (phương án 2): Ta cùng hệ thống lại chỗ chưa rõ nhé.\nNam (phương án 3): Tanaka làm công việc giải thích đó.', NULL, '[{"expression":"説明","reading":"せつめい","meaning_vi":"lời giảng; hướng dẫn; giải thích để người khác hiểu"},{"expression":"整理","reading":"せいり","meaning_vi":"sắp xếp; thu dọn cho gọn"}]', 87, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-024', 'N3-L-RESPONSE', 'N3', 'LISTENING', 24, NULL, NULL, '[{"speaker":"M","ja":"こんな時間まで残らなくてもよかったのに。"},{"speaker":"F","ja":"うん、帰る道は電車よりバスのほうが近いよ。"},{"speaker":"F","ja":"今日は早く帰ったほうがよかったんだね。"},{"speaker":"F","ja":"気にしないで、最後まで一緒にやりたかったから。"}]', 'Nam: Đâu cần phải ở lại đến giờ này đâu.\nNữ (phương án 1): Ừ, đường về xe buýt gần hơn tàu.\nNữ (phương án 2): Hôm nay lẽ ra nên về sớm nhỉ.\nNữ (phương án 3): Đừng bận tâm, tôi muốn cùng làm đến cuối mà.', NULL, '[{"expression":"最後","reading":"さいご","meaning_vi":"cuối cùng"},{"expression":"一緒に","reading":"いっしょに","meaning_vi":"cùng nhau; cùng"}]', 83, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-025', 'N3-L-RESPONSE', 'N3', 'LISTENING', 25, NULL, NULL, '[{"speaker":"F","ja":"この仕事、慣れるまでは大変かもしれないね。"},{"speaker":"M","ja":"そうだね、少しずつ覚えていくしかないね。"},{"speaker":"M","ja":"仕事に慣れた人は、もう全員帰ったよ。"},{"speaker":"M","ja":"仕事の名前は、受付で聞いてみるといいよ。"}]', 'Nữ: Việc này có lẽ vất vả cho đến khi quen nhỉ.\nNam (phương án 1): Ừ, chỉ còn cách học dần từng chút.\nNam (phương án 2): Người quen việc đều đã về hết rồi.\nNam (phương án 3): Tên công việc thì hỏi quầy tiếp tân thử xem.', NULL, '[{"expression":"仕事","reading":"しごと","meaning_vi":"công việc; nghề; việc làm"},{"expression":"慣れる","reading":"なれる","meaning_vi":"quen với; quen"}]', 79, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-026', 'N3-L-RESPONSE', 'N3', 'LISTENING', 26, NULL, NULL, '[{"speaker":"M","ja":"その話、本人に確認してからのほうがいいんじゃない？"},{"speaker":"F","ja":"確かに、本人には聞かずに決めよう。"},{"speaker":"F","ja":"確かに、うわさだけで決めるのはよくないね。"},{"speaker":"F","ja":"本人の住所なら、ここに書いてあるよ。"}]', 'Nam: Chuyện đó, xác nhận với chính người ấy trước thì tốt hơn không?\nNữ (phương án 1): Đúng, quyết mà không hỏi chính người ấy.\nNữ (phương án 2): Đúng, quyết chỉ dựa lời đồn thì không tốt.\nNữ (phương án 3): Địa chỉ người ấy ghi ở đây.', NULL, '[{"expression":"本人","reading":"ほんにん","meaning_vi":"đương sự; chính người đó; chính chủ"},{"expression":"確認","reading":"かくにん","meaning_vi":"việc kiểm lại; xác nhận; xác minh"}]', 81, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-027', 'N3-L-RESPONSE', 'N3', 'LISTENING', 27, NULL, NULL, '[{"speaker":"F","ja":"急がなくちゃ、受付が閉まっちゃうよ。"},{"speaker":"M","ja":"急ぐ必要はないって言ってるんだね。"},{"speaker":"M","ja":"受付の仕事は、先月から友達がしているよ。"},{"speaker":"M","ja":"じゃあ、買い物はあとにして先に受付へ行こう。"}]', 'Nữ: Phải nhanh lên, quầy sắp đóng mất.\nNam (phương án 1): Tức cậu nói không cần vội nhỉ.\nNam (phương án 2): Công việc lễ tân bạn tôi làm từ tháng trước.\nNam (phương án 3): Vậy để mua sắm sau, đến quầy trước.', NULL, '[{"expression":"受付","reading":"うけつけ","meaning_vi":"quầy tiếp tân; quầy tiếp đón; quầy tiếp nhận"},{"expression":"買い物","reading":"かいもの","meaning_vi":"mua sắm; việc mua sắm; việc đi chợ"}]', 77, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-028', 'N3-L-RESPONSE', 'N3', 'LISTENING', 28, NULL, NULL, '[{"speaker":"M","ja":"せっかく作ってくれたのに、食べられなくてごめん。"},{"speaker":"F","ja":"気にしないで、無理に食べなくても大丈夫だよ。"},{"speaker":"F","ja":"私もその料理は、旅行先で食べたことがあるよ。"},{"speaker":"F","ja":"料理の作り方は、あとで送っておくね。"}]', 'Nam: Cậu cất công nấu cho mà tôi không ăn được, xin lỗi.\nNữ (phương án 1): Đừng bận tâm, không cần cố ăn đâu.\nNữ (phương án 2): Món đó tôi cũng từng ăn khi du lịch.\nNữ (phương án 3): Cách làm món đó tôi sẽ gửi sau nhé.', NULL, '[{"expression":"料理","reading":"りょうり","meaning_vi":"món ăn; việc nấu ăn"},{"expression":"大丈夫","reading":"だいじょうぶ","meaning_vi":"không sao đâu; không sao"}]', 86, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-029', 'N3-L-RESPONSE', 'N3', 'LISTENING', 29, NULL, NULL, '[{"speaker":"F","ja":"ここに名前を書くだけでいいんだっけ？"},{"speaker":"M","ja":"名前の読み方なら、先生に聞けば分かるよ。"},{"speaker":"M","ja":"名前のほかに、連絡先も書いてね。"},{"speaker":"M","ja":"名前を書いた人は、さっき帰ったよ。"}]', 'Nữ: Chỉ cần viết tên ở đây là được nhỉ?\nNam (phương án 1): Cách đọc tên thì hỏi giáo viên sẽ biết.\nNam (phương án 2): Ngoài tên, viết cả thông tin liên lạc nhé.\nNam (phương án 3): Người đã viết tên vừa về rồi.', NULL, '[{"expression":"名前","reading":"なまえ","meaning_vi":"tên"},{"expression":"読み方","reading":"よみかた","meaning_vi":"cách đọc"}]', 71, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-030', 'N3-L-RESPONSE', 'N3', 'LISTENING', 30, NULL, NULL, '[{"speaker":"M","ja":"無理して参加することないよ、まだ顔色悪いし。"},{"speaker":"F","ja":"うん、最後まで参加すると伝えておくね。"},{"speaker":"F","ja":"会場の場所は、メールで送ってあるよ。"},{"speaker":"F","ja":"ありがとう、今日は休ませてもらうね。"}]', 'Nam: Không cần cố tham gia đâu, sắc mặt cậu vẫn kém.\nNữ (phương án 1): Ừ, tôi báo là sẽ dự đến cuối nhé.\nNữ (phương án 2): Địa điểm hội trường tôi đã email rồi.\nNữ (phương án 3): Cảm ơn, hôm nay tôi xin nghỉ nhé.', NULL, '[{"expression":"参加","reading":"さんか","meaning_vi":"tham gia; góp mặt"},{"expression":"顔色","reading":"かおいろ","meaning_vi":"sắc mặt"}]', 77, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, 'bc8b069c0ce9')
INSERT INTO `jpath_skill_question` (`code`, `set_code`, `sort_order`, `question_ja`, `options_json`, `answer_index`, `explanation_vi`, `status`, `authored`, `seed_version`) VALUES
('N3-R-SHORT-001-Q1', 'N3-R-SHORT-001', 1, 'このメールで、営業部の社員が気をつけなければならないことは何ですか。', '["月曜日の午後三時に五階の大会議室へ行き、資料は正午までに自分で印刷して持っていくこと。","月曜日の午前十時に三階の1番会議室へ行き、田中部長に資料を渡すこと。","来週の営業会議は中止になったので、資料を正午までにメールで送ること。","火曜日の午後三時に本社の会議室へ行き、会場で配られる資料を受け取ること。"]', 0, 'Email thông báo đổi giờ họp sang 3 giờ chiều thứ Hai tại phòng họp lớn tầng 5, và mỗi người phải tự in tài liệu trước 12 giờ trưa hôm đó để mang theo.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-002-Q1', 'N3-R-SHORT-002', 1, '筆者がこの文章で最も言いたいことは何ですか。', '["スマートフォンの画面は目に悪いので、昼間もできるだけ使わない方がいい。","夜よく眠るためには、寝る一時間前からスマートフォンを見ないようにするとよい。","夜眠れないときは、ベッドの中でスマートフォンを使って音楽を探すとよい。","朝早く起きるためには、強い光が出る目覚まし時計を買う必要がある。"]', 1, 'Tác giả khuyên để ngủ sâu và dậy tỉnh táo vào sáng hôm sau thì trước khi ngủ 1 tiếng nên tắt nguồn hoặc để điện thoại sang phòng khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-003-Q1', 'N3-R-SHORT-003', 1, '今月二十日の午前九時から正午までの間、マンションの住民はどうなりますか。', '["エレベーターは使えるが、部屋の電気とガスが止まってしまう。","マンションの入り口が閉まるため、誰も外へ出ることができなくなる。","エレベーターも部屋の電気や水道も使えないため、外出時は階段を使う必要がある。","水道だけは普段通り使えるので、部屋で洗濯や料理をすることができる。"]', 2, 'Thông báo nêu rõ từ 9 giờ sáng đến 12 giờ trưa ngày 20, thang máy dừng hoàn toàn, điện và nước trong phòng cũng tạm ngừng, khi ra ngoài phải đi thang bộ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-004-Q1', 'N3-R-SHORT-004', 1, '時間の使い方について、筆者はどのように考えていますか。', '["仕事が忙しい人は、テレビやゲームをする時間を完全にやめるべきだ。","まとまった一時間が取れないときは、無理に勉強や読書をしない方がいい。","電車の中では何もせず、目を閉じてゆっくり休むのが一番良い。","一日の中の五分や十分といった短い時間を見直し、上手に活用する工夫が大切だ。"]', 3, 'Câu kết khẳng định: điều quan trọng không phải là than không có thời gian mà là nghĩ cách tận dụng hiệu quả những khoảng thời gian ngắn 5–10 phút trong ngày.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-005-Q1', 'N3-R-SHORT-005', 1, '来月一日から、社員証を忘れて出勤した人はどうしなければなりませんか。', '["受付から自分の課の上司に内線電話をかけ、確認してもらってから一時通行証を借りる。","一階の受付で名前と住所を書くだけで、すぐ一時通行証が借りられる。","一度自宅まで社員証を取りに戻らなければ、会社に入ることができない。","人事課へ直接行って、新しい社員証を有料で作ってもらわなければならない。"]', 0, 'Từ tháng sau, nếu quên thẻ nhân viên thì tại lễ tân phải gọi điện nội bộ cho cấp trên của bộ phận mình xác nhận nhân thân rồi mới mượn được thẻ tạm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-006-Q1', 'N3-R-SHORT-006', 1, '筆者の考えによると、人から相談を受けたときに大切なことは何ですか。', '["相手が困らないように、できるだけ早く具体的な解決方法を教えてあげること。","すぐにアドバイスをするのではなく、まず相手の気持ちを受け止めて最後まで話を聞くこと。","自分も同じような苦労をした経験があることを、詳しく話して聞かせること。","重大な問題になりそうな場合は、専門家に相談するようにすぐ勧めること。"]', 1, 'Tác giả cho rằng người tâm sự nhiều khi chỉ cần được lắng nghe, nên thay vì cắt ngang để khuyên bảo ngay thì hãy đón nhận cảm xúc và nghe hết câu chuyện trước.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-007-Q1', 'N3-R-SHORT-007', 1, 'このお知らせの内容と合っているものはどれですか。', '["今月十五日は一日中、図書館の建物に入って本を借りることができない。","ホームページの修理の前に予約した本は、もう一度予約し直さなければならない。","十五日の夜十時から次の日の朝六時まで、ホームページで本を検索することや予約ができなくなる。","修理が行われる日は、本の返却期限がいつもより一日短くなる。"]', 2, 'Thông báo ghi rõ từ 10 giờ đêm ngày 15 đến 6 giờ sáng hôm sau không thể tra cứu và đặt sách trên mạng do bảo trì trang web.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-008-Q1', 'N3-R-SHORT-008', 1, '買い物について、筆者が言いたいことは何ですか。', '["半額になっている品物を見かけたら、将来使うかもしれないので買っておくとよい。","無駄遣いを防ぐためには、スーパーやデパートへ行く回数を週に一回に減らすべきだ。","まとめ買いをすると必ず損をするので、いつも一つずつ買うようにした方がいい。","値段の安さだけに引かれず、本当に必要な物かどうかを考えてから買うべきだ。"]', 3, 'Câu cuối nêu rõ thông điệp của tác giả: không nên chọn chỉ vì giá rẻ mà hãy cân nhắc xem bản thân hiện tại có thực sự cần món đồ đó không trước khi mua.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-009-Q1', 'N3-R-SHORT-009', 1, 'このメールを送った主な目的は何ですか。', '["説明会で質問された保証や修理に関する資料を送り、注文を検討してもらうため。","来月開かれる新しい商品の説明会に、高橋さんを招待するため。","高橋さんが注文した商品の修理が完了したことを知らせるため。","初期費用の二割引きキャンペーンが先月末で終わったことを謝るため。"]', 0, 'Email cảm ơn khách đã dự buổi giới thiệu, gửi đính kèm tài liệu về thời hạn bảo hành & dịch vụ sửa chữa mà khách hỏi hôm đó, đồng thời mời khách cân nhắc đặt hàng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-010-Q1', 'N3-R-SHORT-010', 1, '新しい習慣を長く続けるために、筆者はどうすればよいと言っていますか。', '["最初から高い目標を立てて、周りの人に伝えてから始める。","無理のない小さな目標から始めて、毎日少しずつ続けていく。","毎日五キロ走るなど、体に強い負担がかかる運動から始める。","平日は何もしないで、週末にまとめて運動や勉強をする。"]', 1, 'Tác giả khuyên thay vì đặt mục tiêu quá cao ngay từ đầu, hãy bắt đầu từ những việc nhỏ dễ thực hiện với chút nỗ lực và tích lũy mỗi ngày.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-011-Q1', 'N3-R-SHORT-011', 1, '十一月十日から十三日までの間に、預けた服を受け取りたい客はどうすればよいですか。', '["工事が終わる十四日まで待ってから、駅前店へ取りに行くしかない。","前日までに電話をすれば、自宅まで無料で届けてもらえる。","駅前店から歩いて五分のところにある北口店へ行って受け取る。","駅前店の裏口から入って、店員に直接服を出してもらう。"]', 2, 'Thông báo nêu rõ trong 4 ngày nghỉ thi công (10/11–13/11), việc trả đồ đã gửi hoặc nhận giặt gấp được giải quyết bình thường tại chi nhánh cửa Bắc cách đó 5 phút đi bộ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-012-Q1', 'N3-R-SHORT-012', 1, '筆者が紙の手帳に手で書くのが良いと考えている理由は何ですか。', '["パソコンやスマートフォンよりも、速くたくさんの文字を記録できるから。","会議中にパソコンを開くと、周りの人に失礼だと思われることがあるから。","紙の手帳の方が電池切れの心配がなく、値段も安くて経済的だから。","文字を丸で囲んだり矢印でつないだりして書くことで、考えが整理されやすいから。"]', 3, 'Tác giả giải thích: khi viết tay lên sổ giấy, việc thay đổi nét, khoanh tròn từ quan trọng hay nối mũi tên giúp suy nghĩ tự nhiên được sắp xếp, hệ thống lại và dễ nhớ hơn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-013-Q1', 'N3-R-SHORT-013', 1, '午後に健康診断を受ける社員が守らなければならないことはどれですか。', '["当日の朝七時以降は食事をせず、事前に記入した質問の紙を受付に出すこと。","前日の夜九時から検査が終わるまで、水もお茶も一切飲まないこと。","当日の昼ごはんは普段通り食べて、検査の三十分前に甘いジュースを飲むこと。","質問の紙は健康診断が終わったあとに、病院へ直接郵送すること。"]', 0, 'Người khám buổi chiều không được ăn từ sau 7 giờ sáng ngày khám (chỉ được uống nước/trà không đường đến trước khám 30 phút) và phải nộp phiếu câu hỏi đã điền sẵn tại quầy tiếp nhận.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-014-Q1', 'N3-R-SHORT-014', 1, '旅行の計画について、筆者はどのように考えていますか。', '["有名な観光地をすべて回るために、出発前に分単位で細かい予定を立てるべきだ。","予定を詰め込みすぎず、自由に歩いたり立ち寄ったりできる余裕を残しておくとよい。","初めての土地では道に迷いやすいので、観光バスツアーに申し込むのが一番安全だ。","観光地には行かず、ホテルの部屋で一日中ゆっくり読書をして過ごすのがよい。"]', 1, 'Tác giả khuyên không nên nhồi nhét lịch trình kín mít mà nên chừa lại chút thời gian trống để tự do dạo bước và có những khám phá bất ngờ đáng nhớ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-015-Q1', 'N3-R-SHORT-015', 1, '来月から、汚れがついた弁当のプラスチック容器はどうやって出せばよいですか。', '["これまで通り、洗わずにそのまま「燃えるごみ」の日に出す。","熱いお湯と洗剤で完全に新品のように洗ってから、「燃えないごみ」の日に出す。","中の食べ残しをなくして少し水で洗い、「プラスチック資源」の日に出す。","市役所の環境課の窓口まで、市民が直接持っていかなければならない。"]', 2, 'Từ tháng sau, hộp nhựa đựng cơm chỉ cần đổ hết thức ăn thừa, rửa qua bằng nước là có thể bỏ vào ngày thu gom "tài nguyên nhựa" (プラスチック資源).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-016-Q1', 'N3-R-SHORT-016', 1, '子どもの育て方について、筆者が最も伝えたいことは何ですか。', '["子どもが悲しい思いをしないように、親がいつもそばにいて失敗を防ぐべきだ。","子どもが頼んできても、大人は一切手伝わず一人で解決させるべきだ。","小さいうちから難しい勉強をたくさんさせて、競争に勝てるようにするべきだ。","危険がない限り、小さな失敗を経験させて自分で考えさせることが成長につながる。"]', 3, 'Tác giả nhấn mạnh: ngoài việc bảo vệ khỏi nguy hiểm, người lớn không nên tước đi những thất bại nhỏ mà hãy để trẻ trải nghiệm và tự suy nghĩ cách khắc phục để trưởng thành.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-017-Q1', 'N3-R-SHORT-017', 1, '今月から、出張の費用を精算するときに社員がしなければならないことは何ですか。', '["出張から戻って五日以内にシステムで申請し、領収書は写真添付と原本提出の両方を行う。","毎月末にまとめて紙の申請書を書き、領収書と一緒に上司へ渡す。","領収書をスマートフォンで撮影して添付すれば、元の紙はすぐに捨ててよい。","出張へ行く一週間前に、必ず経理部の窓口で現金を受け取っておく。"]', 0, 'Quy định mới yêu cầu đăng ký trên hệ thống nội bộ trong vòng 5 ngày sau khi đi công tác về, đồng thời hóa đơn phải vừa chụp ảnh đính kèm lên hệ thống vừa nộp bản giấy gốc vào hộp của phòng Kế toán.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-018-Q1', 'N3-R-SHORT-018', 1, '料理のレシピにある「塩少々」と「塩ひとつまみ」について、正しい説明はどれですか。', '["どちらも三本の指でつまんだ量で、重さはまったく同じ約一グラムである。","「少々」は二本の指でつまむ量で、三本の指でつまむ「ひとつまみ」の半分ほどの量である。","「少々」の方が「ひとつまみ」よりも量が多く、スープを作るときにだけ使われる。","どちらもスプーンを使って量る必要があり、指でつまんで入れてはいけない。"]', 1, 'Bài viết giải thích: "ひとつまみ" kẹp bằng 3 ngón tay (~1g), còn "少々" chỉ kẹp bằng 2 ngón tay (ngón cái và ngón trỏ), lượng bằng khoảng một nửa "ひとつまみ".', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-019-Q1', 'N3-R-SHORT-019', 1, 'この焼き物体験に参加する人が知っておかなければならないことは何ですか。', '["当日は自分でねんどを買って持参し、作った器はその日のうちに持ち帰れること。","講座の日が来週の土曜日から一か月後の土曜日に延期されたこと。","当日は汚れてもよい服かエプロンを用意し、作った器は一か月後に受け取れること。","お皿や茶碗を焼くための燃料代を、一か月後に追加で払わなければならないこと。"]', 2, 'Thông báo dặn người tham gia mặc đồ không ngại bẩn hoặc mang tạp dề, và sản phẩm cần phơi khô rồi nung nên sẽ nhận sau 1 tháng chứ không mang về ngay trong ngày.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-SHORT-020-Q1', 'N3-R-SHORT-020', 1, 'メールやチャットの使い方について、筆者はどのように考えていますか。', '["どんな用件でも電話は相手の時間を奪うので、すべて短いメールで済ませるべきだ。","誤解を防ぐためには、メールの最後に必ずたくさんの絵文字や写真を入れるべきだ。","仕事での連絡にはチャットを使わず、すべて手書きの手紙を送るのが最も丁寧だ。","おわびや断りなど気持ちを伝えることが大切な場面では、文字だけでなく直接会うか電話をする方がよい。"]', 3, 'Tác giả nhấn mạnh: trong những dịp cần quan tâm đến cảm xúc đối phương như xin lỗi hay từ chối, thay vì chỉ nhắn bằng chữ dễ gây hiểu lầm thì nên gặp mặt trực tiếp hoặc gọi điện thoại.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-001-Q1', 'N3-R-MEDIUM-001', 1, '以前の筆者は、休日の過ごし方についてどのように考えていましたか。', '["映画や食事など外出の予定をたくさん入れて、特別なことをしないともったいないと思っていた。","平日の疲れを取るために、一日中ベッドで寝ているのが一番良いと思っていた。","休日に外出するとお金がかかるので、家で料理や掃除をするべきだと思っていた。","週末も会社の仕事を少しずつ進めておけば、月曜日が楽になると思っていた。"]', 0, 'Đoạn 1 nêu rõ: trước đây tác giả nghĩ ngày nghỉ mà không xếp lịch ra ngoài xem phim, ăn uống với bạn bè để làm điều gì đó đặc biệt thì thật lãng phí.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-001-Q2', 'N3-R-MEDIUM-001', 2, '筆者が日曜日に予定を入れなくなったきっかけは何ですか。', '["友人がみんな忙しくなり、週末に一緒に遊ぶ相手がいなくなったから。","週末に予定を詰め込みすぎたせいで、月曜日の朝にひどく疲れていることに気づいたから。","医者から、休日は外に出ないで静かに休むように厳しく注意されたから。","家で料理を作る楽しさに目覚め、外食をするのが嫌になったから。"]', 1, 'Đoạn 2 giải thích: có lần nhồi nhét quá nhiều lịch vào cuối tuần khiến sáng thứ Hai vô cùng mệt mỏi, tác giả mới nhận ra ngày nghỉ lại đang làm mình mệt thêm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-001-Q3', 'N3-R-MEDIUM-001', 3, '現在の筆者が考える「休日の役割」とはどのようなものですか。', '["普段できない難しい勉強や資格の試験の準備をするための日。","遠くの観光地へ旅行に行って、新しい刺激を受けるための日。","心と体を休ませて、元の元気な状態を取り戻すための日。","家族や友人のために、朝から晩まで家事を手伝うための日。"]', 2, 'Câu cuối đoạn 3 khẳng định: ngày nghỉ là ngày đưa tâm trí và cơ thể trở lại trạng thái khỏe khoắn ban đầu (心と体を元の元気な状態に戻す日).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-002-Q1', 'N3-R-MEDIUM-002', 1, '筆者が最初、近所の八百屋に入りにくいと感じたのはなぜですか。', '["スーパーに比べて野菜の値段がとても高く、種類も少なかったから。","店主のおじさんがいつも怒ったような顔をしていて怖かったから。","店の場所が暗くて狭い路地の奥にあり、見つけにくかったから。","野菜が袋に入っておらず、値段の札も少なくて買い方がわからなかったから。"]', 3, 'Đầu đoạn 2 nêu rõ: rau không đóng túi sẵn, bảng giá lại ít nên tác giả không biết mua thế nào và thấy hơi ngại vào.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-002-Q2', 'N3-R-MEDIUM-002', 2, '筆者が店主に声をかけたとき、店主はどのような対応をしましたか。', '["今朝届いた甘いトマトを勧め、おいしい食べ方まで親切に教えてくれた。","忙しいから自分で選んでほしいと言って、奥へ入ってしまった。","売れ残っていた古い野菜を、半額にするから買ってくれと頼んできた。","スーパーで買った方が安いよと冗談を言って笑った。"]', 0, 'Trong đoạn 2, bác chủ tiệm mỉm cười giới thiệu cà chua ngọt vừa về sáng nay và chỉ dẫn tận tình cả cách ăn ngon.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-002-Q3', 'N3-R-MEDIUM-002', 3, '筆者は現在、この八百屋での買い物をどのように感じていますか。', '["誰とも話さずに数分で買い物が終わるので、忙しい日にとても便利だと感じている。","店の人と会話を楽しみながら季節の野菜を選べる、温かくて楽しい時間だと感じている。","毎回食べ方の説明を聞くのに時間がかかるので、少し面倒だと感じている。","スーパーよりも必ず安く買えるので、お金の節約になると感じている。"]', 1, 'Đoạn 3 kết luận: khoảng thời gian vừa trò chuyện với người bán vừa chọn rau theo mùa mang lại sự ấm áp và niềm vui nhỏ cho cuộc sống mỗi ngày.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-003-Q1', 'N3-R-MEDIUM-003', 1, '以前の筆者は、どのように本を読んでいましたか。', '["大事なところに赤いペンで線を引きながら、声に出して読んでいた。","一度読んだ本はすぐに古本屋へ売るため、カバーをかけて読んでいた。","ページを折ったり書き込んだりせず、読み終えたあともきれいな状態で残していた。","本に直接書くかわりに、別のノートに感想を詳しくまとめていた。"]', 2, 'Đoạn 1 cho biết: trước đây tác giả tuyệt đối không gấp trang hay gạch bút, thích giữ sách sạch đẹp như lúc mới mua trên kệ sau khi đọc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-003-Q2', 'N3-R-MEDIUM-003', 2, '先輩から借りた本を見て、筆者はなぜ考えが変わったのですか。', '["本が汚れていて読みにくかったので、やはり本はきれいに扱うべきだと思ったから。","線を引いておくと、試験の勉強をするときに時間を節約できると気づいたから。","先輩から、本に書き込みをしない人は読書が足りないと言われたから。","引かれた線やページの端の書き込みから、先輩が本と真剣に向き合って読んでいたことが伝わったから。"]', 3, 'Đoạn 2 nêu rõ: nhìn những đường gạch chân và dòng ghi chú ở mép trang sách, tác giả cảm nhận sâu sắc tiền bối đã đối diện nghiêm túc và đối thoại với cuốn sách.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-003-Q3', 'N3-R-MEDIUM-003', 3, '本に書き込みをするようになって、筆者が一番良いと感じている点は何ですか。', '["あとから読み返したときに、その本を読んだ当時の自分の気持ちまで思い出せること。","本の内容を一度で全部暗記できるようになったこと。","友人に本を貸したときに、たくさん勉強していると褒められること。","難しい専門書でも、以前の半分の時間で速く読めるようになったこと。"]', 0, 'Câu cuối đoạn 3 khẳng định: sức hấp dẫn lớn nhất là khi đọc lại về sau có thể nhớ lại cả cảm xúc của chính mình vào thời điểm đọc lúc đó.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-004-Q1', 'N3-R-MEDIUM-004', 1, '筆者はスーパーなどの「セルフレジ」について、どのように評価していますか。', '["操作が複雑で時間がかかるため、どんなに慣れても不便な機械だと思っている。","最初は緊張したが、慣れると小銭を探す手間が減り、短時間で買い物ができて便利だと思っている。","お年寄りや子どもにはまったく使えないので、すぐになくすべきだと思っている。","店員と楽しくおしゃべりができるので、毎日利用したいと思っている。"]', 1, 'Đoạn 1 nêu rõ: lúc đầu hơi căng thẳng vì chưa quen thao tác, nhưng khi quen rồi thì giảm công tìm tiền lẻ và mua sắm nhanh gọn rất tiện lợi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-004-Q2', 'N3-R-MEDIUM-004', 2, 'パン屋での出来事を通して、筆者はどのようなことを感じましたか。', '["パン屋にも早くセルフレジを入れて、待ち時間を短くしてほしいと感じた。","寒い日に外へ買い物に出かけるのは、健康に良くないと感じた。","店員からの何気ない優しい一言によって、心も体も温かくなると感じた。","古いパン屋は計算を間違えることがあるので、気をつけなければならないと感じた。"]', 2, 'Đoạn 2 kể lại câu hỏi thăm ân cần của cô bán bánh mì vào ngày lạnh khiến tác giả cảm thấy ấm lòng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-004-Q3', 'N3-R-MEDIUM-004', 3, 'この文章全体で筆者が最も言いたいことは何ですか。', '["すべての店のレジを機械に変えて、人件費を減らすべきだ。","スーパーで買い物をするのをやめて、近所の小さな店だけで買い物をするべきだ。","セルフレジの使い方を教える講座を、市役所で開くべきだ。","機械の便利さを認めつつも、人との触れ合いから生まれる温かさも大切に残してほしい。"]', 3, 'Đoạn 3 tổng kết: dù trân trọng sự tiện lợi và tiết kiệm thời gian của máy móc, tác giả vẫn mong cảm giác ấm áp, an tâm khi con người giao tiếp trực tiếp không bị mất đi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-005-Q1', 'N3-R-MEDIUM-005', 1, '筆者が子どもの頃に雨の日を嫌っていたのはなぜですか。', '["外でサッカーができず、傘をさしても靴やズボンが濡れて冷たくなるから。","雨の日は母から買い物を頼まれることが多かったから。","雨の音がうるさくて、夜なかなか眠ることができなかったから。","傘を学校に忘れて帰って、親に叱られることがよくあったから。"]', 0, 'Đoạn 1 nêu lý do: không đá bóng ở sân trường được, và dù che ô đi bộ thì giày cùng ống quần vẫn bị ướt lạnh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-005-Q2', 'N3-R-MEDIUM-005', 2, '社会人になってから、筆者は雨の休日をどのように過ごしていますか。', '["雨が降っていても必ず外出して、映画館や美術館を回るようにしている。","無理に出かけず、部屋の片づけをしたりコーヒーを飲んで読書や音楽を楽しんだりしている。","実家の両親のところへ帰って、家族と一緒に食事をするようにしている。","雨の日は気分が沈むので、カーテンを閉めて夕方まで寝て過ごしている。"]', 1, 'Đoạn 2 và 3 cho biết: tác giả coi đó là ngày không cần ra ngoài, ở nhà dọn phòng, pha cà phê nóng, nghe nhạc và đọc sách.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-005-Q3', 'N3-R-MEDIUM-005', 3, 'この文章からわかる筆者の考えはどれですか。', '["子どもの頃に嫌いだったものは、大人になっても好きになることはない。","集中して勉強や読書をするためには、雨の日にしか本を読まない方がいい。","物事の見方や過ごし方を少し変えることで、嫌だった時間も心地よい時間に変えられる。","一人暮らしを始めると家事が大変なので、休日も休む暇がなくなる。"]', 2, 'Câu kết đoạn 3 khẳng định: chỉ cần thay đổi góc nhìn một chút, ngày mưa từng ghét bỏ đã trở thành khoảng thời gian nghỉ ngơi quý giá.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-006-Q1', 'N3-R-MEDIUM-006', 1, '料理を始めたばかりの頃、筆者が困っていたことは何ですか。', '["計量スプーンの使い方がわからず、いつも調味料を入れすぎてしまうこと。","野菜を切るのに時間がかかりすぎて、食べる頃には料理が冷めてしまうこと。","難しい料理ばかり作ろうとして、材料費がたくさんかかってしまうこと。","料理本の通りに調味料を量っているのに、日によって味の濃さが変わってしまうこと。"]', 3, 'Đoạn 1 nêu rõ: dù đong gia vị đúng y như sách dạy nấu ăn nhưng tùy ngày món ăn lại quá mặn hoặc quá nhạt, vị không ổn định.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-006-Q2', 'N3-R-MEDIUM-006', 2, '母によると、レシピ通りに作っても味が変わってしまう原因は何ですか。', '["野菜の季節や大きさによって、含まれている水分の量が毎回違うから。","使っている鍋やフライパンの大きさが、料理本と違っているから。","コンロの火の強さが日によって変わってしまうから。","塩や醤油などの調味料は、時間が経つと味が消えてしまうから。"]', 0, 'Đoạn 2 lời người mẹ giải thích: rau củ tùy theo mùa và kích thước mà lượng nước chứa bên trong khác nhau, nên cần phải nếm thử ở bước cuối để điều chỉnh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-006-Q3', 'N3-R-MEDIUM-006', 3, '筆者がこの経験から学んだことは何ですか。', '["おいしい料理を作るためには、料理本を見ないで最初からすべて自分の勘で作るべきだ。","基本の数字を参考にしつつも、最後は自分の感覚で確かめて調整することが大切だ。","野菜の水分量を一定にするために、同じ大きさの野菜だけを買うべきだ。","料理は母親に任せて、自分は片づけだけを手伝う方が失敗がない。"]', 1, 'Đoạn 3 đúc kết: lấy công thức làm cơ bản nhưng trước khi tắt bếp phải nếm thử và dùng cảm giác của bản thân để điều chỉnh hoàn thiện chứ không phụ thuộc mù quáng vào con số.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-007-Q1', 'N3-R-MEDIUM-007', 1, '友人と会う前、筆者はどのようなことを心配していましたか。', '["十年前に借りたままだった本について、友人から怒られるのではないかということ。","待ち合わせの場所である喫茶店が、すでになくなっているのではないかということ。","長い間に仕事や環境が変わったため、共通の話題がなくて気まずくなるのではないかということ。","友人の顔や名前をすっかり忘れてしまって、見分けられないのではないかということ。"]', 2, 'Đoạn 1 nêu rõ: tác giả lo rằng sau 10 năm công việc và môi trường sống đều thay đổi, nhỡ không có chuyện gì nói với nhau sẽ bị ngượng ngùng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-007-Q2', 'N3-R-MEDIUM-007', 2, '実際に友人と会ったとき、二人の様子はどうでしたか。', '["最初は緊張して三十分ほど二人とも黙ったままコーヒーを飲んでいた。","仕事の自慢話ばかりになってしまい、一時間ほどで別れることになった。","昔の思い出話は一切せず、将来の結婚や貯金の話だけをした。","顔を見た瞬間に不安が消え、昔の思い出から今の仕事の悩みまで楽しく語り合った。"]', 3, 'Đoạn 2 và 3 mô tả: vừa nhìn thấy mặt nhau là hết lo lắng, trò chuyện sôi nổi từ kỷ niệm thời đi học cho tới những trăn trở công việc và dự định tương lai.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-007-Q3', 'N3-R-MEDIUM-007', 3, '友人と久しぶりに会って、筆者がもう一度気づいたことは何ですか。', '["長い時間が経っても、自分の利益を考えずに正直に話せる友人との関係は変わらないということ。","大人になってからの友人よりも、小学校の頃の友人の方が仕事で役に立つということ。","昔の友人と良い関係を続けるためには、毎月必ず会わなければならないということ。","思い出の場所へ行くよりも、新しいレストランで会う方が話が盛り上がるということ。"]', 0, 'Câu kết đoạn 3 khẳng định: mối quan hệ bạn bè có thể nói chuyện thẳng thắn không tính toán lợi ích riêng thì dù thời gian dài trôi qua vẫn không hề thay đổi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-008-Q1', 'N3-R-MEDIUM-008', 1, '外国語を勉強している人がよく抱える悩みとして、筆者が文の中で出しているのはどれですか。', '["単語帳の値段が高くて、どの本を買えばよいかわからないこと。","単語をたくさん暗記したのに、実際の会話の場面になると言葉が出てこないこと。","発音の練習ばかりしてしまい、文法や漢字の勉強が追いつかないこと。","外国人の友人が多すぎて、一人で静かに勉強する時間が取れないこと。"]', 1, 'Đoạn 1 nêu rõ nỗi trăn trở phổ biến: dù đã thuộc nhiều từ qua sổ từ vựng nhưng khi hội thoại thực tế lại không nói ra được.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-008-Q2', 'N3-R-MEDIUM-008', 2, '覚えた単語を会話で使えるようにするために、筆者が勧めている練習方法は何ですか。', '["教科書の例文を一字一句間違えずに百回ずつノートに書き写すこと。","辞書を最初から最後まで順番に読んで、難しい言葉まで全部覚えること。","覚えた単語を使って、自分の実際の出来事や気持ちを表す短い文を作ってみること。","文法は気にせず、知っている単語をただ並べて大きな声で叫ぶこと。"]', 2, 'Đoạn 2 khuyên nên dùng từ vừa học để đặt câu ngắn nói về chính sự việc, trải nghiệm của bản thân (như ví dụ với từ 「残念」).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-008-Q3', 'N3-R-MEDIUM-008', 3, '自分の経験と結びつけて言葉を練習すると、どのような効果がありますか。', '["辞書を使わなくても、知らない単語の意味がすべて予想できるようになる。","一週間という短い期間で、外国語の試験に満点で合格できるようになる。","外国の歴史や文化について、専門の論文が書けるようになる。","記憶に深く残り、似た場面に出会ったときに自然と口から言葉が出てくるようになる。"]', 3, 'Đoạn 3 kết luận: từ ngữ gắn với cảm xúc và trải nghiệm cá nhân sẽ nhớ rất sâu và tự nhiên bật ra khi gặp tình huống tương tự.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-009-Q1', 'N3-R-MEDIUM-009', 1, 'この会社が水曜日の午後を「会議をしない時間帯」にした理由は何ですか。', '["会議が多すぎて昼間に自分の仕事ができず、夕方に残業をする社員が多かったから。","水曜日の午後は社員全員で会社の周りの掃除をすることになったから。","会議室の冷房が壊れてしまい、午後の暑い時間帯は使えなくなったから。","取引先の会社がすべて水曜日の午後を休みにしているから。"]', 0, 'Đoạn 1 giải thích: trước đó họp hành liên miên khiến nhân viên không có thời gian làm việc riêng trong ngày, phải tăng ca vào buổi tối để làm tài liệu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-009-Q2', 'N3-R-MEDIUM-009', 2, 'この取り組みを始めてから、社員の働き方はどう変わりましたか。', '["連絡が取れなくなって仕事が止まり、木曜日の会議が以前の二倍に増えた。","前もって連絡や確認を済ませるようになり、仕事の段取りが良くなった。","水曜日の午後は仕事がなくなってしまい、みんな早く帰るようになった。","会議の代わりに長いメールを何十通も送るようになり、かえって忙しくなった。"]', 1, 'Đoạn 2 nêu rõ: khi áp dụng thực tế, mọi người chủ động liên lạc và xác nhận trước cho chiều thứ Tư nên việc sắp xếp công việc còn hiệu quả hơn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-009-Q3', 'N3-R-MEDIUM-009', 3, '水曜日の午後にまとまった時間ができたことで、どのような良い結果が生まれましたか。', '["会社の売り上げが一か月で二倍になり、全員に特別ボーナスが出た。","他の曜日もすべて会議が禁止になり、社内の会議が完全になくなった。","新しい計画をじっくり考えたり仕事を片づけたりでき、水曜日の残業がほとんどなくなった。","社員同士がまったく話さなくなり、社内がとても静かになった。"]', 2, 'Đoạn 3 cho biết: nhờ có 3 tiếng tập trung liên tục, nhân viên suy nghĩ kỹ được kế hoạch mới, giải quyết việc tồn đọng và hầu như không còn phải tăng ca ngày thứ Tư.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-010-Q1', 'N3-R-MEDIUM-010', 1, '筆者は桜の花が咲いている時期、どのように通勤していますか。', '["花見の人で道が混雑するので、別の道を通って駅へ行くようにしている。","桜の写真を撮るために、毎朝一時間早く起きて公園へ行くようにしている。","花粉が苦手なので、桜が咲いている間はバスに乗って通勤している。","普段より十分早く家を出て、桜並木の道をゆっくり歩いて通勤している。"]', 3, 'Đoạn 1 nêu rõ: trong khoảng một tuần hoa nở, tác giả ra khỏi nhà sớm hơn 10 phút để đi bộ thong thả dưới hàng cây hoa anh đào.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-010-Q2', 'N3-R-MEDIUM-010', 2, '花が散ったあとの桜の木について、筆者はどのように感じていますか。', '["五月の輝く緑の葉や夏の涼しい木陰も、花と同じくらい強い魅力があると感じている。","花がなくなると寂しい感じがするので、来年の春まで見たくないと思っている。","秋に落ち葉がたくさん出て掃除が大変なので、枝を切った方がいいと思っている。","他の人と同じように、花が散ったあとは木を見上げることはほとんどない。"]', 0, 'Đoạn 2 khẳng định: tác giả thấy lá non xanh lấp lánh dưới nắng tháng Năm hay bóng râm mát mẻ mùa hè cũng có sức hấp dẫn không kém gì hoa.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-010-Q3', 'N3-R-MEDIUM-010', 3, '筆者がこの文章で最も伝えたいことは何ですか。', '["駅の近くの桜並木をもっと有名にして、観光客を増やすべきだ。","花の時期だけでなく、一年を通して変化する自然の姿に目を向けて季節を感じたい。","遅刻しないように、季節に関係なくいつも十分早く家を出るべきだ。","冬は寒くて木も寂しそうに見えるので、春と夏だけ散歩をするのがよい。"]', 1, 'Đoạn 3 tổng kết: một cái cây mang nhiều sắc thái suốt bốn mùa, nên thay vì chỉ nhìn xuống chân đi vội, hãy ngước nhìn để cảm nhận sự chuyển giao của các mùa.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-011-Q1', 'N3-R-MEDIUM-011', 1, '部屋の整理をしていて、筆者はどのようなことに気づきましたか。', '["大切な思い出の写真や手紙を、間違えて前に捨ててしまっていたこと。","本棚が壊れかけていて、新しい家具を買わなければならない状態だったこと。","いつか使うと思って買ったかばんや服の存在を忘れ、何年も使わずにしまい込んでいたこと。","服の数が少なすぎて、これからの季節に着る服が足りないこと。"]', 2, 'Đoạn 1 cho biết: khi dọn phòng, tác giả thấy rất nhiều túi xách và quần áo mua với suy nghĩ "có lúc sẽ dùng" nhưng lại quên bẵng và cất sâu nhiều năm không dùng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-011-Q2', 'N3-R-MEDIUM-011', 2, '筆者は一年以上使っていない物をどうしましたか。', '["すべて大きな袋に入れて、燃えるごみの日に捨てた。","新しく箱を買ってきて、もう一度クローゼットの奥にきれいにしまった。","近所に住んでいる親戚や友人に頼んで、無理やり全部もらってもらった。","リサイクルショップへ持っていき、まだ読める本は図書館に寄付した。"]', 3, 'Đoạn 2 nêu rõ: tác giả mang đồ hơn 1 năm không dùng ra tiệm đồ cũ (リサイクルショップ) và tặng sách còn đọc được cho thư viện.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-011-Q3', 'N3-R-MEDIUM-011', 3, '今回の片づけを通して、筆者はどのような考えを持つようになりましたか。', '["本当に好きで大切に使える物だけを持って暮らすことが、心地よい生活につながる。","たくさんの物に囲まれている方が安心できるので、これからも安い物を買い続けたい。","片づけには丸一日かかって疲れるので、これからは物を一切買わないようにする。","リサイクルショップで物を売ると儲かるので、新しい仕事にしたい。"]', 0, 'Đoạn 3 đúc kết: sự sung túc không nằm ở việc có nhiều đồ, mà sống giữa những món đồ mình thực sự yêu thích và trân trọng sử dụng mới tạo nên cuộc sống dễ chịu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-012-Q1', 'N3-R-MEDIUM-012', 1, '半年より前の筆者の朝の様子として、正しいものはどれですか。', '["毎朝早く起きて運動をしていたため、会社に着く頃には眠くなっていた。","出発の直前に慌てて起きて朝食も食べずに駅へ走り、午前中は仕事に集中できなかった。","朝ごはんをたくさん食べすぎてお腹が痛くなり、よく会社に遅刻していた。","電車の中で朝ごはんのパンを食べて、周りの乗客に迷惑をかけていた。"]', 1, 'Đoạn 1 mô tả: dậy sát giờ đi 20 phút, bỏ bữa sáng chạy ra ga, đến công ty đã mệt và buổi sáng không tập trung làm việc được.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-012-Q2', 'N3-R-MEDIUM-012', 2, '筆者が朝三十分早く起きるようになったきっかけは何ですか。', '["会社の上司から、毎朝一番早く出社して掃除をするように命じられたから。","引っ越しをして、自宅から駅までの距離が三十分遠くなったから。","医師から、朝食を食べないと体も脳も目を覚まさないと注意されたから。","朝早く開いている近所のパン屋で、焼きたてのパンを買いたかったから。"]', 2, 'Đoạn 2 nêu rõ: do bác sĩ nhắc nhở rằng bỏ bữa sáng thì cơ thể và não bộ đều không tỉnh táo được, nên tác giả quyết định dậy sớm hơn 30 phút.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-012-Q3', 'N3-R-MEDIUM-012', 3, '早起きと朝食の習慣をつけてから、筆者にどのような変化がありましたか。', '["夜の八時には眠くなってしまい、テレビや映画が見られなくなった。","料理が楽しくなり、毎朝一時間かけて豪華な昼の弁当まで作るようになった。","体重が急に増えてしまい、新しいスーツを買い直さなければならなくなった。","気持ちに余裕が生まれ、午前中から頭がすっきり働いて仕事が速く進むようになった。"]', 3, 'Đoạn 3 cho biết: sau khi thong thả ăn sáng rồi mới đi làm, tác giả không còn sốt ruột khi tàu trễ và đầu óc minh mẫn ngay từ sáng giúp công việc trôi chảy.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-013-Q1', 'N3-R-MEDIUM-013', 1, '美術館に入ったばかりの頃、筆者はどのように絵を見ていましたか。', '["絵の横に貼られた画家の歴史や方法などの説明書きばかりを熱心に読んでいた。","遠くから絵の色だけを眺めて、一分もたたないうちに次の部屋へ移動していた。","スマートフォンで絵の写真を撮りながら、友人と大きな声で話していた。","どの絵が一番高い値段かを予想しながら見て回っていた。"]', 0, 'Đoạn 1 nêu rõ: lúc đầu tác giả chỉ chăm chú đọc bảng thuyết minh dán cạnh bức tranh và tưởng rằng đọc thông tin chữ viết là đã hiểu bức tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-013-Q2', 'N3-R-MEDIUM-013', 2, '筆者が「私ははっとした」とあるのはなぜですか。', '["小学生の男の子が、有名な画家の名前や歴史を大人より詳しく知っていたから。","説明を読まずに自分の目で絵を感じて楽しんでいる男の子の姿に気づかされたから。","男の子が海の絵に手で触れようとして、係員に注意されているのを見たから。","自分が読んでいた説明書きが、隣の別の絵のものだと気づいたから。"]', 1, 'Đoạn 2 và 3 giải thích: nhìn cậu bé không đọc bảng thuyết minh mà trực tiếp ngắm bức tranh biển và hào hứng cảm nhận ngọn sóng sống động, tác giả nhận ra cách thưởng thức nghệ thuật thực sự.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-013-Q3', 'N3-R-MEDIUM-013', 3, 'この出来事のあと、筆者の絵の見方はどのように変わりましたか。', '["美術館へ行く前に、必ず図書館で画家の伝記を全部読んでから行くようになった。","説明書きは邪魔になるので、美術館からすべてなくしてほしいと頼んだ。","説明書きを読む前に、まず自分の目で絵の色や形を直接味わうようになった。","大人の展覧会には行かず、子どもの描いた絵だけを見に行くようになった。"]', 2, 'Câu cuối đoạn 3 cho biết: từ đó trước khi đọc thuyết minh, tác giả luôn đứng trước tranh để tự cảm nhận vẻ đẹp của màu sắc và hình khối bằng đôi mắt mình trước.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-014-Q1', 'N3-R-MEDIUM-014', 1, '以前の筆者が、忙しいときでも頼まれた仕事を引き受けていたのはなぜですか。', '["たくさんの仕事を引き受ければ、給料がすぐに上がると思っていたから。","他の人に仕事を任せるよりも、自分でやった方が速くて正確だったから。","会社の規則で、頼まれた仕事は絶対に断ってはいけないと決まっていたから。","断ることで相手に嫌われたり、冷たい人だと思われたりするのが怖かったから。"]', 3, 'Đoạn 1 nêu rõ: tác giả sợ nếu từ chối sẽ bị đối phương ghét hoặc bị đánh giá là người lạnh lùng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-014-Q2', 'N3-R-MEDIUM-014', 2, '先月、筆者が仕事を抱え込みすぎた結果、どうなりましたか。', '["疲れ果てて大切な書類にミスをし、かえって周りに大きな迷惑をかけてしまった。","すべての仕事を予定より早く終わらせて、社長から褒められた。","高熱を出して一か月間入院することになり、会社を辞めなければならなくなった。","頼んできた同僚とけんかになり、口をきかなくなってしまった。"]', 0, 'Đoạn 2 kể lại: do ôm đồm nhiều việc cùng lúc, tác giả kiệt sức và làm sai tài liệu quan trọng, gây phiền phức lớn cho mọi người.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-014-Q3', 'N3-R-MEDIUM-014', 3, '現在の筆者は、忙しいときに仕事を頼まれたらどうしていますか。', '["理由は一切言わずに、どんな仕事でもすべて断るようにしている。","自分の仕事の状況やいつなら手伝えるかを具体的に説明して、無理なときは断っている。","自分の仕事を後回しにしてでも、頼まれた仕事を最優先でやっている。","代わりにやってくれそうな別の社員を探して、その人に押しつけている。"]', 1, 'Đoạn 3 cho biết: tác giả kiểm tra khối lượng và thời hạn việc đang làm, nếu không xuể sẽ giải thích rõ lý do và báo cụ thể thời điểm có thể hỗ trợ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-015-Q1', 'N3-R-MEDIUM-015', 1, '駅前の図書館に新しく作られたスペースは、どのような場所ですか。', '["一切の音を出してはいけない、これまで以上に規則が厳しい自習室。","古い本や雑誌を安い値段で市民に販売するための専門店。","一階にあり、コーヒーを飲んだり会話をしたりしながら気軽に本に親しめる場所。","図書館の本を借りずに、インターネットのゲームだけをするための部屋。"]', 2, 'Đoạn 1 và 2 mô tả: không gian mới ở tầng 1 cho phép vừa uống cà phê, nghe nhạc nhẹ, vừa đọc sách hoặc trò chuyện trao đổi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-015-Q2', 'N3-R-MEDIUM-015', 2, '静かに集中して勉強や調べ物をしたい利用者は、どうすればよいですか。', '["一階の新しいスペースで耳をふさいで本を読むしかない。","隣町の別の図書館まで電車に乗って行かなければならない。","朝八時から九時までの間だけ図書館を利用することができる。","これまで通り私語や飲食が禁止されている二階と三階の読書室を利用する。"]', 3, 'Đoạn 2 nêu rõ: tầng 2 và tầng 3 vẫn giữ nguyên quy định cấm nói chuyện riêng và cấm ăn uống dành cho người muốn yên tĩnh tập trung.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-015-Q3', 'N3-R-MEDIUM-015', 3, 'この図書館の新しい取り組みについて、筆者はどう考えていますか。', '["時代に合わせて場所の使い方を工夫することで、これまで来なかった人も本に親しめるようになり喜ばしい。","本がコーヒーで汚れる危険があるので、すぐに元の規則に戻すべきだ。","二階や三階もすべて飲食店にして、静かな部屋はなくした方がよい。","若い人や家族連れが増えると騒がしくなるので、入場料を取るべきだ。"]', 0, 'Câu cuối đoạn 3 khẳng định: việc thay đổi cách sử dụng không gian theo thời đại giúp tăng số người đến gần với sách là điều rất đáng mừng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-016-Q1', 'N3-R-MEDIUM-016', 1, '育て始めた頃、ミニトマトの元気がなくなってしまった原因は何ですか。', '["忙しくて一週間以上も水をやるのを忘れてしまったから。","乾燥に強い植物なのに、毎日たっぷり水をやりすぎて根が弱ってしまったから。","ベランダの風が強すぎて、枝が途中で折れてしまったから。","虫がたくさんついて、葉を全部食べられてしまったから。"]', 1, 'Đoạn 1 và 2 giải thích: cà chua vốn ưa khô ráo, việc ngày nào cũng tưới quá nhiều nước làm rễ bị úng và lá ngả vàng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-016-Q2', 'N3-R-MEDIUM-016', 2, '園芸の本を読んだあと、筆者はどのように世話を変えましたか。', '["毎日朝と夜の二回、氷を入れた冷たい水をあげるようにした。","太陽の光が当たらない暗い部屋の中に箱を入れるようにした。","土の表面が乾いてから水をやるようにし、日当たりの良い場所へ箱を移した。","水は一切あげずに、毎日高い栄養の薬だけをたくさん与えるようにした。"]', 2, 'Đoạn 2 nêu rõ: đợi mặt đất khô hẳn mới tưới nước và chuyển hộp cây ra vị trí có ánh nắng tốt.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-016-Q3', 'N3-R-MEDIUM-016', 3, 'ミニトマトを育てた経験から、筆者が気づいたことは何ですか。', '["野菜を自分で育てるよりも、スーパーで買った方が安くておいしいということ。","どんな植物でも、水をたくさんあげれば必ず大きく育つということ。","マンションのベランダでは、野菜を育てることは絶対に不可能だということ。","相手の性質をよく理解せずにただ世話をしても、かえって負担になることがあるということ。"]', 3, 'Câu cuối đoạn 3 đúc kết bài học: nếu không hiểu rõ đặc tính của đối phương mà cứ chăm sóc theo ý mình thì trái lại có khi gây thêm gánh nặng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-017-Q1', 'N3-R-MEDIUM-017', 1, '以前の筆者が買った服や靴をあまり使わなくなってしまったのはなぜですか。', '["見た目だけで選んだため、履くと足が痛くなったり洗濯で形が崩れたりしたから。","流行が終わるのが速くて、すぐにデザインが古くなってしまったから。","サイズが合わないものを、確かめずにインターネットで買っていたから。","高い物ばかり買っていたため、汚れるのが怖くて使えなかったから。"]', 0, 'Đoạn 1 nêu rõ: vì chỉ chọn theo kiểu dáng và màu sắc nên giày đi lâu bị đau chân, quần áo giặt nhanh mất dáng nên rốt cuộc ít dùng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-017-Q2', 'N3-R-MEDIUM-017', 2, '筆者の父がかばんを十年以上も長く使えている理由は何ですか。', '["かばんが傷まないように、一年に一回しか外へ持っていかないから。","買う前に縫い目の丈夫さや重さをよく確かめ、納得した良い物だけを買っているから。","壊れるたびに自分で針と糸を使って修理しているから。","有名な外国のブランドの最も高価なかばんだけを買っているから。"]', 1, 'Đoạn 2 lời người bố giải thích: trước khi mua ông luôn kiểm tra kỹ đường may có chắc chắn không, cầm có nặng quá không, chỉ mua món đồ thực sự ưng ý.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-017-Q3', 'N3-R-MEDIUM-017', 3, '現在の筆者は、物の買い方についてどのように考えていますか。', '["安い物をたくさん買って、古くなったらすぐに新しい物へ買い替える方がよい。","自分で買うと失敗するので、服やかばんはすべて父親に選んでもらうのがよい。","少し値段が高くても、丈夫さや使いやすさを確かめて良い物を長く使う方が満足感が高い。","デザインや色はまったく気にせず、一番重くて固い物を選ぶべきだ。"]', 2, 'Đoạn 3 kết luận: kiểm tra độ bền và sự tiện dụng trước khi mua; dù hơi đắt một chút nhưng dùng đồ tốt lâu dài vừa tiết kiệm vừa hài lòng hơn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-018-Q1', 'N3-R-MEDIUM-018', 1, '指導教授からアドバイスを受ける前、筆者は発表の準備をどのようにしていましたか。', '["緊張しないように、前日まで何も準備をせずに当日を迎えるようにしていた。","聞き手が退屈しないように、冗談や面白い話ばかりを集めていた。","自分の代わりに友人に発表してもらえるよう、毎回頼み込んでいた。","恥ずかしい思いをしないよう、難しい言葉を並べて完全な発表のメモを作ろうとしていた。"]', 3, 'Cuối đoạn 2 cho biết: trước đó vì sợ xấu hổ nên tác giả chỉ nghĩ đến việc dùng nhiều từ khó để viết bản ghi chú thuyết trình thật hoàn chỉnh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-018-Q2', 'N3-R-MEDIUM-018', 2, '指導教授が筆者に与えたアドバイスはどのようなものでしたか。', '["うまく話そうとせず、聞き手に一番伝えたいことを一つに絞って準備しなさい。","プロのアナウンサーの話し方を真似して、毎日発声練習をしなさい。","聞き手の顔を見ると緊張するので、ずっと下を向いて紙を読みなさい。","人前で話すのが苦手なら、発表のない別の授業に変えなさい。"]', 0, 'Đầu đoạn 2 giáo sư khuyên: không cần cố nói thật hay, hãy chọn lọc đúng một điều quan trọng nhất muốn truyền đạt cho người nghe để chuẩn bị.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-018-Q3', 'N3-R-MEDIUM-018', 3, '次の発表でやり方を変えた結果、筆者はどうなりましたか。', '["途中で話す内容を忘れてしまい、以前よりもひどく失敗してしまった。","聞き手がうなずきながら聞いてくれるのが見え、初めて話す楽しさを感じられた。","図が小さすぎて後ろの席の人から見えず、教授に叱られてしまった。","緊張しなくなったので、準備を一切しなくても発表できるようになった。"]', 1, 'Đoạn 3 nêu rõ: khi bỏ học vẹt mà dùng biểu đồ giải thích như nói với bạn, tác giả thấy người nghe gật đầu hưởng ứng và lần đầu cảm nhận được niềm vui khi thuyết trình.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-019-Q1', 'N3-R-MEDIUM-019', 1, '一人暮らしを始めたばかりの頃、筆者はどのような失敗をよくしていましたか。', '["鍋の火を強くしすぎて、せっかくの料理を焦がしてしまうこと。","毎日外食ばかりして、一か月の食費が給料を超えてしまうこと。","買った野菜を使い切れずに、冷蔵庫の中で傷ませて無駄にしてしまうこと。","同じ味の料理ばかり作って、三日で飽きて食べられなくなること。"]', 2, 'Đoạn 2 nêu rõ: hồi mới ở một mình, tác giả mua một túi rau về thường không ăn hết kịp mà để hỏng trong tủ lạnh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-019-Q2', 'N3-R-MEDIUM-019', 2, '筆者が考える鍋料理の良さとして、文章に書かれていないものはどれですか。', '["準備が簡単で、多くの種類の野菜や肉を温かく食べられること。","冷蔵庫に残っている材料を何でも入れて使えるので、無駄が出ないこと。","だしの種類や味付けを変えれば、同じ材料でも飽きずに楽しめること。","冷やして食べると夏バテの予防になり、一年中いつでも作れること。"]', 3, 'Các ý 1 (đoạn 1), 2 (đoạn 2), 3 (đoạn 3) đều có trong bài; chỉ có ý 4 (ăn lạnh phòng say nắng mùa hè) hoàn toàn không có trong bài.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-019-Q3', 'N3-R-MEDIUM-019', 3, '筆者にとって、冬の鍋料理はどのような存在ですか。', '["寒い季節を健康でお金を節約しながら過ごすために欠かせない大切な料理。","友人を家に呼んでパーティーをするときにだけ作る特別な料理。","作るのに手間と時間がかかるが、味が良いので我慢して作る料理。","実家の母親から作り方を習ったものの、まだ上手に作れない料理。"]', 0, 'Câu kết đoạn 3 khẳng định: để vượt qua mùa lạnh một cách khỏe mạnh và tiết kiệm, món lẩu là người bạn đồng hành không thể thiếu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-020-Q1', 'N3-R-MEDIUM-020', 1, '電車の中で周りが気持ちよく過ごせる工夫として、筆者が最初の段落で出している例は何ですか。', '["電車の中では最初から最後まで一度も座らず、ずっと立っていること。","荷物をひざの上に置いたり足を組まずに座ったりして、他の人が座れる場所を作ること。","隣の席の人にあめやお菓子を配って、楽しく会話をすること。","雨の日は電車に乗るのをやめて、必ずタクシーで移動すること。"]', 1, 'Đoạn 1 nêu ví dụ: đặt hành lý lên đùi hoặc ngồi không bắt chéo chân để tạo chỗ trống cho người bên cạnh ngồi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-020-Q2', 'N3-R-MEDIUM-020', 2, '雨の日の満員電車で、若い女性が見せた「さりげない気配り」とは何ですか。', '["傘を持っていない見知らぬ人に、自分の傘を無料で譲ってあげたこと。","床に落ちた雨水を、自分のハンカチで熱心に拭いていたこと。","濡れた傘が周りの人の服に触れないよう、たたんで自分の体の前にまっすぐ持っていたこと。","傘をさしたまま乗車しようとした人を、大きな声で注意したこと。"]', 2, 'Đoạn 2 mô tả: cô gái gấp gọn chiếc ô ướt và giữ thẳng trước người mình để không làm ướt quần áo của những người xung quanh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-MEDIUM-020-Q3', 'N3-R-MEDIUM-020', 3, 'この出来事を通して、筆者はどのようなことを感じましたか。', '["マナーの悪い人をなくすためには、車内の放送でもっと厳しく注意するべきだ。","満員電車に傘を持ち込むとトラブルになるので、レインコートを着るべきだ。","若い人よりもお年寄りの方が、電車のマナーをよく守っている。","強い言葉で注意するよりも、一人の思いやりある行動が周りを動かして良い空気を作る。"]', 3, 'Đoạn 3 kết luận: hơn là dùng lời lẽ gay gắt nhắc nhở, chính hành động chu đáo của một cá nhân sẽ lay động mọi người xung quanh và lan tỏa bầu không khí tốt đẹp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-001-Q1', 'N3-R-LONG-001', 1, 'インターネットの「おすすめ」機能について、筆者は最初の段落でどのように述べていますか。', '["過去の記録から好みに合うものを自動で選んでくれるため、迷う時間が減って便利だ。","自分の好みに合わない商品ばかり表示されるため、買い物に時間がかかって不便だ。","値段の高い商品ばかりを無理に買わせようとするので、利用しない方がよい。","本や映画を探すときには使えるが、日用品や服を買うときにはまったく役に立たない。"]', 0, 'Đoạn 1 nêu rõ: dựa vào lịch sử mua hàng, máy tự động chọn thứ hợp sở thích nên giảm thời gian phân vân và rất tiện lợi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-001-Q2', 'N3-R-LONG-001', 2, '自分の本棚を眺めたとき、筆者が「少し怖くなった」のはなぜですか。', '["買ったまま一度も読んでいない本が二十冊以上も積まれていることに気づいたから。","「おすすめ」ばかり選んでいたせいで、似たテーマや同じ意見の本ばかりになり狭い世界に閉じこもっていたから。","本棚が本の重さにもたなくなり、今にも壊れそうになっているのを見つけたから。","昔読んだ本の内容を、自分がまったく覚えていないことに気づいたから。"]', 1, 'Đoạn 2 giải thích: hơn 20 cuốn sách trên kệ đều có chủ đề và quan điểm giống nhau do chỉ chọn theo gợi ý, khiến tác giả vô tình tự nhốt mình trong thế giới hẹp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-001-Q3', 'N3-R-LONG-001', 3, '筆者が考える「町の大きな書店へ足を運ぶ良さ」とは何ですか。', '["インターネットで買うよりも、すべての本を安い値段で買うことができること。","店員に頼めば、自分の好みにぴったりの本を機械より速く選んでくれること。","普段なら調べないような分野の本と偶然出会い、自分の考え方を広げられること。","友人と待ち合わせをするのに便利で、雨の日でも濡れずに過ごせること。"]', 2, 'Đoạn 3 nêu rõ: đi dạo giữa các kệ sách giúp bắt gặp tình cờ những cuốn sách thuộc lĩnh vực ngày thường không tìm kiếm, từ đó mở rộng suy nghĩ của bản thân.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-001-Q4', 'N3-R-LONG-001', 4, 'この文章全体で筆者が最も言いたいことは何ですか。', '["インターネットで本を買うのはすぐにやめて、これからは町の書店だけで買うべきだ。","本棚には同じ分野の本を並べた方が、専門の知識が身につくので良い。","ビジネスの本を読むよりも、歴史の小説や科学の絵本を読む方が仕事に役立つ。","便利なネットの機能も活用しつつ、時には機械の提案から離れて偶然の出会いを楽しむことも大切だ。"]', 3, 'Đoạn 4 tổng kết: tận dụng internet để thu thập thông tin hiệu quả là khôn ngoan, nhưng đôi khi nên rời khỏi gợi ý của máy móc để tận hưởng những cuộc gặp gỡ tình cờ giúp tâm hồn phong phú hơn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-002-Q1', 'N3-R-LONG-002', 1, '筆者が東京の会社を辞めて故郷へ戻ることにしたのはなぜですか。', '["東京での仕事が難しすぎて、職場の人間関係にも疲れてしまったから。","故郷で暮らす祖父が足を悪くしたと聞き、家族と相談して地元で働くことに決めたから。","自分でジャムの会社を新しく作って社長になりたいという夢があったから。","東京の家賃や物価が高すぎて、生活していくことができなくなったから。"]', 1, 'Đoạn 1 nêu rõ: khi nhận tin ông nội ở quê bị đau chân, sau khi bàn bạc với gia đình, tác giả quyết định về quê làm việc tại một nhà máy nhỏ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-002-Q2', 'N3-R-LONG-002', 2, '故郷へ戻ったばかりの頃、筆者はどのような気持ちでしたか。', '["空気がきれいで静かなので、東京よりもずっと暮らしやすいと喜んでいた。","地元の工場の給料が東京より高かったので、とても満足していた。","交通や買い物の不便さにとまどい、東京の生活が恋しくて後悔することもあった。","友達がすぐにたくさんできて、毎晩遅くまで食事に出かけていた。"]', 2, 'Đoạn 2 mô tả: tàu 1 tiếng mới có 1 chuyến, quá 8 giờ tối phố xá đã đóng cửa tối om khiến tác giả nhớ Tokyo và có những đêm hối hận vì về quê sớm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-002-Q3', 'N3-R-LONG-002', 3, '地元の工場で働き始めて半年ほど経った頃、筆者の気持ちが変わったきっかけは何ですか。', '["工場で作ったジャムが東京のデパートで一番の人気商品になったこと。","駅前に大きなスーパーが新しくできて、夜遅くまで買い物ができるようになったこと。","工場長から仕事ぶりを認められて、来月から給料が上がると言われたこと。","果物を育てた農家から「孫がジャムを喜んで食べていた」と聞き、仕事が人の笑顔につながっていると実感したこと。"]', 3, 'Đoạn 3 kể lại: bác nông dân trồng trái cây khen cháu nội bác rất thích ăn mứt do nhà máy làm, giúp tác giả cảm nhận rõ công việc của mình gắn trực tiếp với nụ cười của người khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-002-Q4', 'N3-R-LONG-002', 4, '現在の筆者は、働く場所や生き方についてどのように考えていますか。', '["都会にも地方にもそれぞれの良さがあり、仕事への向き合い方次第でどこでも幸せな人生を作れる。","若い人は一度は必ず都会を離れて、地方の工場で働くべきだ。","自然の豊かな地方で働く方が、都会で働くよりも必ず幸せになれる。","祖父の足が治ったら、もう一度東京の大きな食品会社へ戻りたい。"]', 0, 'Đoạn 4 kết luận: thành thị và địa phương đều có nét hay riêng; dù ở đâu, tùy vào thái độ đối diện với công việc mỗi ngày mà ta đều có thể xây dựng cuộc sống hạnh phúc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-003-Q1', 'N3-R-LONG-003', 1, '筆者の母がスーパーで棚の奥にある品物を取っていたのはなぜですか。', '["手前にある品物は、他の客が触っていて汚れているかもしれないから。","奥にある品物の方が、手前のものより値段が安く決まっているから。","奥にある品物の方が新しく並べられたもので、賞味期限が長いから。","スーパーの店員から、奥の品物を先に買うように頼まれていたから。"]', 2, 'Đoạn 1 nêu rõ lời người mẹ: đồ ở phía trong là đồ mới bày lên kệ nên có hạn sử dụng dài hơn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-003-Q2', 'N3-R-LONG-003', 2, 'スーパーの店長をしている友人は、どのようなことに困っていると語りましたか。', '["客が棚の奥に手を入れるときに、手前の商品を床に落として壊してしまうこと。","商品の種類が多すぎて、毎朝棚に並べる作業に時間がかかりすぎること。","賞味期限が切れた商品を間違えて売ってしまい、客から叱られること。","客が奥の商品ばかり取るため、手前の期限が近い商品が売れ残って毎日捨てなければならないこと。"]', 3, 'Đoạn 2 người bạn làm quản lý siêu thị chia sẻ: khách ai cũng lấy hàng phía trong nên hàng có hạn gần hơn ở phía ngoài bị tồn lại và phải vứt bỏ mỗi ngày.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-003-Q3', 'N3-R-LONG-003', 3, '友人の話を聞いて、筆者が「恥ずかしい気持ちになった」のはなぜですか。', '["すぐに食べる物まで奥から取るという自分の行動が、食品の無駄につながっていたと気づいたから。","自分がスーパーの店員に対して、いつも態度が悪かったことを思い出したから。","賞味期限の意味をこれまで間違って理解していたことに気づいたから。","友人がそんなに大変な仕事をしているとは知らず、のんびり暮らしていたから。"]', 0, 'Đoạn 3 giải thích: tác giả nhận ra hành động lấy đồ phía trong dù ăn ngay trong ngày của mình đã góp phần làm lãng phí thực phẩm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-003-Q4', 'N3-R-LONG-003', 4, '現在、筆者が買い物のときに心がけていることは何ですか。', '["賞味期限に関わらず、どんな食品でも必ず一番奥にあるものを買うこと。","すぐに使う予定の食品を買うときは、棚の一番手前にあるものを選ぶこと。","スーパーで買い物をするのをやめて、必要な分だけ毎日市場で買うこと。","賞味期限が切れた食品でも、捨てずに最後まで全部食べるようにすること。"]', 1, 'Đoạn 4 nêu rõ: khi mua thực phẩm dự định dùng ngay, tác giả luôn chọn lấy sản phẩm nằm ở phía ngoài cùng của kệ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-004-Q1', 'N3-R-LONG-004', 1, '昨年、会社で「午後七時に電気を消すルール」が決まったとき、社員はどう思いましたか。', '["給料が減ってしまうのではないかと、全員が強く反対した。","七時では遅すぎるので、五時に消すべきだと不満を持った。","暗い中で仕事をしなければならなくなると思い、小さい電気を用意した。","自分の自由な時間が増えると思い、誰もが喜んだ。"]', 3, 'Cuối đoạn 1 nêu rõ: ban đầu nhân viên ai cũng vui mừng vì nghĩ rằng thời gian tự do của mình sẽ tăng lên.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-004-Q2', 'N3-R-LONG-004', 2, 'ルールが始まって三か月ほど経った頃、どのような問題が起きましたか。', '["仕事の量は変わらないまま時間だけ制限されたため、昼休みを削ったり家に仕事を持ち帰ったりする人が出た。","社員が早く帰りすぎてしまい、夕方に電話をかけてくる客の対応ができなくなった。","電気を消す係の社員だけが毎日遅くまで残らなければならなくなった。","自由な時間が増えたことで、夜遅くまで遊んで次の日の朝に遅刻する社員が増えた。"]', 0, 'Đoạn 2 giải thích: lượng việc không đổi mà giờ về bị giới hạn nên có người phải bớt giờ nghỉ trưa hoặc mang việc về nhà làm đến khuya.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-004-Q3', 'N3-R-LONG-004', 3, '筆者の課で話し合った結果、無駄だとわかった作業は何ですか。', '["毎朝五分間、社員同士で仕事の進み具合を共有すること。","誰も読まない長い報告書を毎週作ることや、メールで済む確認のために三十分の会議を開くこと。","取引先の会社へ行って、新しい商品の説明を直接行うこと。","パソコンを使って書類を作り、社内のシステムに保存すること。"]', 1, 'Đoạn 3 chỉ rõ 2 việc lãng phí: hàng tuần viết báo cáo dài không ai đọc và họp 30 phút cho những việc xác nhận đơn giản có thể gửi qua email.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-004-Q4', 'N3-R-LONG-004', 4, '働く人の健康と時間を守るために、筆者が最も大切だと考えていることは何ですか。', '["どんなに仕事が残っていても、午後五時になったら無理やりパソコンの電源を切ること。","一人一人が自分の仕事だけに集中し、他の人の仕事には一切関わらないこと。","早く帰るという形だけでなく、無駄を減らして仕事のやり方そのものを見直すこと。","社員の数を今の二倍に増やして、一人あたりの仕事を半分にすること。"]', 2, 'Câu kết đoạn 4 khẳng định: không chỉ đặt quy định về sớm trên hình thức, mà phải xem xét, cải tiến lại chính cách thức làm việc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-005-Q1', 'N3-R-LONG-005', 1, '子どもの頃、筆者が「もう自転車なんて一生乗れなくてもいい」と泣いたのはなぜですか。', '["練習するたびに何度も転んでひざをすりむき、痛くて悔しかったから。","友達から自転車の色や形が古いとからかわれたから。","父親が厳しく叱りながら、毎日遅くまで無理やり練習させたから。","欲しかった新しい自転車を、両親が買ってくれなかったから。"]', 0, 'Đoạn 1 nêu rõ: mỗi lần tập ở công viên đều bị ngã nhiều lần trầy xước đầu gối, vừa đau vừa tức nên khóc và định bỏ cuộc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-005-Q2', 'N3-R-LONG-005', 2, '泣いている筆者に対して、父親はどのような言葉をかけましたか。', '["「自転車に乗れないと将来困るから、乗れるまで家に帰らないぞ」と厳しく言った。","「昨日より長く進めたし、転んだのは前に進もうとペダルを踏んだしるしだ」と元気づけた。","「そんなに痛いなら、もう一生自転車には乗らなくていいよ」と優しく言った。","「友達はみんな乗れているのに、どうして君だけ乗れないんだ」とため息をついた。"]', 1, 'Đoạn 2 dẫn lời người bố: khen hôm nay đã đi xa hơn hôm qua 3 mét và nói việc bị ngã chính là dấu hiệu cho thấy con đã cố đạp mạnh để tiến về phía trước.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-005-Q3', 'N3-R-LONG-005', 3, '公園の端から端まで一人で走れた経験は、その後の筆者にどのような影響を与えましたか。', '["プロの自転車選手になって、世界中の大会に出たいと思うようになった。","二度と転びたくないので、それ以来一度も自転車に乗らなくなった。","自分の力でできたという喜びが、その後の強い自信になった。","父親に手伝ってもらわなくても、最初から一人で何でもできると思うようになった。"]', 2, 'Cuối đoạn 3 nêu rõ: niềm vui khi tự mình làm được đã trở thành sự tự tin lớn lao cho tác giả trong suốt những năm tháng sau đó.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-005-Q4', 'N3-R-LONG-005', 4, '大人になった現在、筆者は仕事での失敗をどのように考えていますか。', '["失敗は周りの人に迷惑をかける恥ずかしいことなので、新しい挑戦は避けるべきだ。","失敗したときはすぐに仕事を辞めて、別の新しい会社を探すべきだ。","大人の仕事での失敗は、子どもの頃の練習とは違って取り返しがつかないものだ。","失敗は前に進もうと努力しているしるしであり、もう一度挑戦する勇気を与えてくれるものだ。"]', 3, 'Đoạn 4 kết luận: thất bại không phải điều đáng xấu hổ mà là dấu hiệu cho thấy mình đang nỗ lực tiến về phía trước, giúp tiếp thêm dũng khí để thử lại.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-006-Q1', 'N3-R-LONG-006', 1, '以前の筆者は、野菜の皮やブロッコリーの太い部分をどのように扱っていましたか。', '["栄養がたくさんあると知っていたので、毎回ジュースにして飲んでいた。","食べられないごみだと思い込み、何の疑問も持たずに捨てていた。","冷凍庫に集めておいて、週末にまとめてスープを作っていた。","庭の土に埋めて、花や野菜を育てるための栄養にしていた。"]', 1, 'Đoạn 1 nêu rõ: trước đây tác giả mặc định vỏ rau củ hay phần lõi súp lơ là rác không ăn được nên vứt đi mà không hề nghi ngờ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-006-Q2', 'N3-R-LONG-006', 2, '祖母が作った「大根の皮の炒め物」を食べて、筆者はどう感じましたか。', '["皮が硬すぎて噛み切れず、やはり皮は捨てるべきだと感じた。","ごま油と醤油の味が強すぎて、大根の香りが消えてしまっていると感じた。","歯ごたえがよくて実の部分より味が濃く、ご飯によく合っておいしいと感じた。","作るのに手間がかかりすぎるので、自分には真似できないと感じた。"]', 2, 'Đoạn 2 mô tả: món vỏ củ cải xào giòn sần sật, vị đậm đà hơn cả phần ruột trắng và rất đưa cơm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-006-Q3', 'N3-R-LONG-006', 3, '祖母によると、野菜の皮の近くにはどのような特徴がありますか。', '["虫や薬がついていることが多いので、厚くむいて捨てなければならない。","水分が多すぎて傷みやすいため、買ったその日にすぐ食べなければならない。","苦い味がするため、子どもや老人にはあまり向いていない。","皮のすぐ下に、栄養や香りが一番たくさん詰まっている。"]', 3, 'Cuối đoạn 2 bà ngoại giải thích: ngay dưới lớp vỏ là nơi tập trung nhiều dinh dưỡng và hương thơm nhất.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-006-Q4', 'N3-R-LONG-006', 4, '祖母の手伝いをしたあと、筆者の行動はどう変わりましたか。', '["野菜を切るときに捨てる部分を減らす工夫をし、食費やごみを減らす知恵を活かしている。","自分で料理をするのをやめて、毎日祖母の家へ夕食を食べに行くようになった。","皮をむく手間を省くため、カット野菜や冷凍野菜だけを買うようになった。","野菜の実の部分は食べずに、皮と太い部分だけで毎日料理を作るようになった。"]', 0, 'Đoạn 4 cho biết: tác giả luôn cân nhắc trước khi vứt bỏ phần thừa của rau củ, học theo bí quyết của bà để vừa tiết kiệm tiền ăn vừa giảm rác bảo vệ môi trường.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-007-Q1', 'N3-R-LONG-007', 1, '郊外の町でお寺へ向かっていたとき、筆者がおばあさんに道を尋ねたのはなぜですか。', '["スマートフォンの地図アプリの使い方が最初からわからなかったから。","おばあさんの庭に咲いている珍しい花の名前を知りたかったから。","途中でスマートフォンの電池が切れてしまい、道がわからなくなって困ったから。","お寺が閉まっている時間かどうかを確かめたかったから。"]', 2, 'Đoạn 2 nêu rõ: điện thoại chẳng may bị hết pin, xung quanh lại không có cửa hàng tiện lợi nên tác giả đành hỏi đường cụ bà đang tưới hoa.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-007-Q2', 'N3-R-LONG-007', 2, 'おばあさんが教えてくれた道は、どのような道でしたか。', '["バスやタクシーがたくさん通っていて、お寺まで一番速く着ける大通り。","急な階段がたくさんあるが、町全体が上から見渡せる山の道。","お土産屋や食堂が並んでいる、にぎやかな駅前の商店街の道。","川の横を通る静かな小道で、ちょうど白い花が満開になっている気持ちのよい道。"]', 3, 'Đoạn 2 và 3 mô tả: đó là con đường nhỏ yên tĩnh ven sông, có hoa trắng đang nở rộ, cầu đá cổ và guồng nước rất đẹp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-007-Q3', 'N3-R-LONG-007', 3, '「もしスマートフォンの地図通りに大通りを歩いていたら」どうなっていたと筆者は考えていますか。', '["五分ほど早く着いたかもしれないが、川の横の美しい景色には出会えなかっただろう。","道に迷ってしまい、夕方までに古いお寺へ着くことができなかっただろう。","途中で雨が降り出して、服や靴がびしょ濡れになっていただろう。","大通りで別の友人に偶然会って、一緒に食事をしていただろう。"]', 0, 'Cuối đoạn 3 tác giả suy ngẫm: nếu đi đường lớn theo bản đồ trên điện thoại thì có thể đến sớm hơn 5 phút nhưng chắc chắn đã bỏ lỡ khung cảnh tuyệt đẹp ven sông.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-007-Q4', 'N3-R-LONG-007', 4, 'この経験を通して、筆者が伝えたいことは何ですか。', '["旅行に出かけるときは、スマートフォンの予備の電池を必ず二つ以上持つべきだ。","最短距離で移動する便利さも良いが、人に尋ねたり遠回りしたりする中に旅を豊かにする発見がある。","スマートフォンの地図アプリは間違った道を表示することが多いので、使わない方がよい。","郊外の古いお寺へ行くときは、歩いて行くのではなくタクシーを使うべきだ。"]', 1, 'Đoạn 4 kết luận: đi đường ngắn nhất rất cần cho công việc, nhưng khi đi du lịch, việc rời mắt khỏi màn hình để hỏi thăm người dân hay đi đường vòng lại mang đến những khám phá quý giá.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-008-Q1', 'N3-R-LONG-008', 1, '以前の筆者は、提出期限まで時間がある仕事をどのように扱っていましたか。', '["頼まれたその日のうちに、徹夜をしてでも最後まで全部終わらせていた。","自分ではやらずに、いつも隣の席の先輩に頼んで代わりに作ってもらっていた。","毎日三十分ずつ計画を立てて進めて、期限の一週間前には提出していた。","机の隅に置いたまま後回しにしてしまい、締め切りの前日に慌てて残業していた。"]', 3, 'Đoạn 1 nêu rõ: tài liệu còn hạn 2 tuần tác giả cứ để ở góc bàn trì hoãn, đến hôm trước ngày hết hạn mới cuống cuồng làm thêm giờ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-008-Q2', 'N3-R-LONG-008', 2, '隣の席の先輩は、新しい書類の仕事を受け取ったとき、まず何をしていましたか。', '["その日のうちに五分だけ時間を取り、見出しや資料のリストを作るなど小さな最初の作業を済ませていた。","その日の他の仕事をすべてやめて、三時間続けてその書類を完成させていた。","まず休憩室へ行ってコーヒーを飲み、一時間ほどゆっくり休んでから始めていた。","提出期限の三日前になるまで、引き出しの奥にしまって見ないようにしていた。"]', 0, 'Đoạn 2 mô tả: ngay khi nhận việc, tiền bối dành ra 5 phút trong ngày hôm đó để làm bước khởi đầu nhỏ như viết tiêu đề hoặc lập danh sách tài liệu cần dùng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-008-Q3', 'N3-R-LONG-008', 3, '先輩が「ゼロのままにしておくのが一番重荷になる」と言ったのはどういう意味ですか。', '["書類のページ数がゼロのままだと、紙がうすすぎて風で飛んでしまうという意味。","まったく手をつけない状態が一番心の負担が大きく、少しでも始めれば自然と続きを進めやすくなるという意味。","仕事のミスをゼロにしようとすると、緊張して体が疲れてしまうという意味。","残業時間をゼロにするためには、仕事を家に持ち帰るしかないという意味。"]', 1, 'Đoạn 3 giải thích: con người một khi đã bắt tay vào làm một chút sẽ tự nhiên muốn làm tiếp, còn chưa đụng vào chút nào (để ở mức 0) sẽ tạo ra bức tường tâm lý nặng nề nhất.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-008-Q4', 'N3-R-LONG-008', 4, '先輩の話を聞いてから、筆者が守っているルールは何ですか。', '["三時間以上かかる大きな仕事は、最初から引き受けないように断ること。","すべての仕事を締め切りの前日まで待ってから、一気に集中して終わらせること。","どんな仕事でも頼まれた日のうちにファイルを作って一行だけ書き、始めるハードルを下げること。","毎朝先輩に自分の仕事のリストを見せて、順番を決めてもらうこと。"]', 2, 'Đoạn 4 cho biết: tác giả tự đặt quy tắc ngay trong ngày nhận việc phải tạo file và viết thử 1 dòng, nhờ đó xóa bỏ gánh nặng tâm lý và hôm sau làm tiếp rất suôn sẻ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-009-Q1', 'N3-R-LONG-009', 1, '筆者が市民の畑で野菜を育て始めたとき、家族はどのような反応をしましたか。', '["スーパーでいつでもきれいな野菜が安く買えるのに、手間がかかるばかりで無駄だと言った。","健康にとても良いことだと言って、最初から毎日手伝ってくれた。","野菜ではなく、きれいな花や果物の木を植えてほしいと頼んだ。","畑を借りるお金がもったいないと言って、強く反対してやめさせた。"]', 0, 'Cuối đoạn 1 nêu rõ: ban đầu gia đình bảo ra siêu thị lúc nào cũng mua được rau đẹp và rẻ, tự đào đất gieo hạt chỉ tốn công vô ích.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-009-Q2', 'N3-R-LONG-009', 2, '実際に野菜を育ててみて、筆者が大変だと感じたことは何ですか。', '["畑の場所が家から遠すぎて、通うのに毎回二時間もかかること。","毎朝早く起きて草を抜き虫を確かめたり、台風で枝が折れたりすること。","収穫した野菜が多すぎて、近所の人に配っても食べきれないこと。","周りの畑の人たちと話し合わなければならず、人間関係が難しいこと。"]', 1, 'Đoạn 2 mô tả: mùa hè phải dậy sớm nhổ cỏ, lật lá bắt sâu, có khi bão làm gãy mất cành cây đang chăm sóc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-009-Q3', 'N3-R-LONG-009', 3, '自分で野菜を育てたことで、スーパーの野菜に対する筆者の見方はどう変わりましたか。', '["スーパーの野菜は味が薄いので、二度と買いたくないと思うようになった。","曲がった野菜の方が栄養が多いので、真っすぐな野菜は良くないと思うようになった。","形が同じできれいな野菜を育てるために、農家の人々がどれほど手間をかけているか理解できるようになった。","スーパーの野菜の値段は高すぎるので、もっと安くするべきだと思うようになった。"]', 2, 'Cuối đoạn 3 nêu rõ: nhìn những quả hơi cong hay không đều do mình trồng, tác giả thấu hiểu người nông dân đã vất vả nhường nào để trồng ra rau củ đẹp bán ở siêu thị.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-009-Q4', 'N3-R-LONG-009', 4, 'この文章全体で筆者が最も伝えたいことは何ですか。', '["食費を節約するためには、すべての家庭が畑を借りて自給自足をするべきだ。","台風が多い地域では野菜が育たないので、家庭菜園はやめた方がよい。","きゅうりは他の野菜よりも簡単に育つので、初心者にはきゅうりだけをお勧めしたい。","自分の手で野菜を育てる経験は、食べ物や生産者への感謝を教え、食卓を豊かにしてくれる。"]', 3, 'Đoạn 4 tổng kết: tự tay chạm vào đất và hiểu quá trình lớn lên của cây rau giúp nuôi dưỡng lòng biết ơn bữa ăn hằng ngày và làm ấm áp thêm câu chuyện bên mâm cơm gia đình.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-010-Q1', 'N3-R-LONG-010', 1, '以前の筆者が、通勤中にずっとイヤホンで音楽を聞いていたのはなぜですか。', '["外国語の聞き取りの試験に合格するために、毎日勉強しなければならなかったから。","周囲の音を止めて、退屈な移動時間を楽しく過ごすのに一番良い方法だと思っていたから。","電車の中の騒音が大きすぎて、耳が痛くなるのを防ぎたかったから。","知り合いに会ったときに、話しかけられないようにするためだったから。"]', 1, 'Đoạn 1 nêu rõ: tác giả bật nhạc ngăn âm thanh xung quanh vì nghĩ đó là cách tốt nhất để biến thời gian di chuyển nhàm chán trở nên vui vẻ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-010-Q2', 'N3-R-LONG-010', 2, 'イヤホンを忘れて歩いた日、筆者はどのようなことに気づきましたか。', '["音楽がないと歩く速度が遅くなり、会社に遅刻しそうになること。","周りの人も全員イヤホンをしていて、誰も自分のことを見ていないこと。","葉が風に揺れる音や子どもの声など、普段は気づかなかった街の豊かな音があること。","通勤の道に新しい喫茶店やレコード屋がたくさんできていること。"]', 2, 'Đoạn 2 mô tả: tác giả nghe thấy nhiều âm thanh cuộc sống mà ngày thường không nhận ra như tiếng lá xào xạc, tiếng học sinh tiểu học, tiếng chào ở tiệm bánh mì.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-010-Q3', 'N3-R-LONG-010', 3, '駅の階段での出来事について、筆者はどのように振り返っていますか。', '["イヤホンをしていたせいで母親の声に気づかず、手伝うことができなくて後悔した。","他の人が先にベビーカーを運んでくれたので、自分は見ているだけでよかった。","駅の階段は危ないので、エレベーターを使うべきだと母親に注意した。","イヤホンをしていなかったおかげで母親の声にすぐ気づき、ベビーカーを一緒に運ぶことができた。"]', 3, 'Đoạn 3 nêu rõ: nhờ không đeo tai nghe nên tác giả nghe thấy ngay lời nhờ giúp đỡ của người mẹ có xe đẩy em bé và cùng khiêng giúp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-010-Q4', 'N3-R-LONG-010', 4, 'この出来事のあと、筆者はイヤホンの使い方をどう変えましたか。', '["通勤の行きか帰りのどちらか一方はイヤホンをしまい、周囲の音を感じながら歩くようにしている。","イヤホンは危険なので家に捨ててしまい、二度と使わないようにした。","片方の耳だけにイヤホンをつけて、もう片方の耳で周りの音を聞くようにしている。","以前よりも音を大きくして、外の音がまったく聞こえないようにしている。"]', 0, 'Câu cuối đoạn 4 cho biết: từ đó trở đi, vào một trong hai lượt đi hoặc về khi đi làm, tác giả cất tai nghe vào túi để lắng nghe âm thanh xung quanh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-011-Q1', 'N3-R-LONG-011', 1, '現在のスマートフォンのカメラを使った写真の撮り方について、筆者はどのように述べていますか。', '["一枚撮るのにとても時間がかかるため、旅行先ではあまり使われなくなっている。","専門の知識がないときれいに撮れないため、若者にしか使えなくなっている。","同じ場面で何十枚も連続で撮り、あとから一番よく撮れている一枚を選ぶのが当たり前になっている。","撮った写真をすべて紙に印刷してアルバムに貼るのが流行している。"]', 2, 'Đoạn 1 nêu rõ: với camera điện thoại hiện nay, người ta thường bấm máy liên tiếp hàng chục tấm cho một cảnh rồi sau đó mới chọn ra tấm đẹp nhất.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-011-Q2', 'N3-R-LONG-011', 2, '昔のフィルムカメラで写真を撮るとき、筆者の父が慎重に撮っていたのはなぜですか。', '["カメラ本体が重すぎて、何度も持ち上げると腕が痛くなったから。","シャッターの音が大きすぎて、周りの人に邪魔になったから。","雨の日や曇りの日には、写真がまったく写らなかったから。","撮れる枚数が限られており、写真屋で現像するまでどう写っているかわからなかったから。"]', 3, 'Đoạn 2 giải thích: mỗi cuộn phim chỉ chụp được 24 hoặc 36 tấm, lại phải đợi mang ra tiệm tráng rửa mới biết kết quả nên mỗi tấm đều được chụp rất cẩn trọng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-011-Q3', 'N3-R-LONG-011', 3, '古いアルバムの写真を見て、筆者はどのように感じましたか。', '["当時の家族の笑い声や空気感が生き生きと伝わってきて、強い魅力を感じた。","ピントがずれている写真ばかりで、スマートフォンの写真の方がずっと良いと感じた。","自分が赤ちゃんだった頃の写真がなくて、とても寂しいと感じた。","色が古くなっていたので、すべて捨ててしまった方がよいと感じた。"]', 0, 'Đoạn 3 nêu rõ: dù có tấm hơi mờ hay nhắm mắt, nhưng mỗi tấm ảnh đều truyền tải sống động tiếng cười và không khí gia đình thời đó, cuốn hút hơn hẳn hàng trăm bức ảnh trong điện thoại.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-011-Q4', 'N3-R-LONG-011', 4, '次の旅行で、筆者はどのように写真を撮ろうと考えていますか。', '["スマートフォンは家に置いていき、父の古いフィルムカメラだけを持っていく。","すぐにカメラを向けるのではなく、まず自分の目で景色をよく見てから一枚だけ撮る。","これまで以上にたくさんの枚数を撮って、インターネットに全部載せる。","写真は一枚も撮らずに、絵の具と画用紙を持っていって絵を描く。"]', 1, 'Câu cuối đoạn 4 khẳng định: trong chuyến đi tới, thay vì giơ máy lên chụp ngay, tác giả muốn ngắm kỹ cảnh vật bằng mắt mình trước rồi mới bấm chụp một tấm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-012-Q1', 'N3-R-LONG-012', 1, '以前の筆者は、冬の休日の朝をどのように過ごすことが多かったですか。', '["寒さに負けないように、朝早く起きて近くの公園を走っていた。","朝から部屋の掃除や洗濯をして、体を動かして温まっていた。","暖かい南の島へ毎週末のように飛行機で旅行に出かけていた。","部屋が冷たいのを理由に、昼近くまで布団の中でスマートフォンを見て過ごしていた。"]', 3, 'Đoạn 1 nêu rõ: lấy lý do không khí trong phòng lạnh, vào ngày nghỉ tác giả thường nằm lì trong chăn xem điện thoại đến gần trưa.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-012-Q2', 'N3-R-LONG-012', 2, '北のヨーロッパに暮らす友人によると、その国の人々は厳しい冬をどのように過ごしていますか。', '["暖かい色の照明や香り高い飲み物など、家の中の時間を心地よくする工夫を大切にしている。","冬の間は仕事をすべて休みにして、春になるまで一日中眠って過ごす。","家の中にいると気分が暗くなるので、一日中雪の中でスポーツをして過ごす。","暖房を使わずに、冷たい水を浴びて体を強くする習慣がある。"]', 0, 'Đoạn 2 giải thích: người dân Bắc Âu dùng đèn màu ấm áp, uống trà thơm hay ca cao bằng chiếc cốc yêu thích để làm cho thời gian trong nhà thật dễ chịu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-012-Q3', 'N3-R-LONG-012', 3, '友人の話を聞いて、筆者が冬の朝に起きられるようになった工夫は何ですか。', '["目覚まし時計を三つ並べて、大きな音が鳴り続けるようにしたこと。","前の晩に好きなコーヒー豆を用意し、厚手の靴下や毛布を机の周りに置いて楽しみを作ったこと。","朝六時に友人に電話をかけてもらい、無理やり起こしてもらうようにしたこと。","暖房を一晩中一番高い温度でつけっぱなしにして寝るようにしたこと。"]', 1, 'Đoạn 3 nêu rõ: chuẩn bị sẵn cà phê thơm từ tối hôm trước để sáng dậy pha ngay, cùng tất dày và chăn mềm ở bàn giúp tác giả có động lực dậy mỗi sáng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-012-Q4', 'N3-R-LONG-012', 4, 'この文章を通して筆者が最も言いたいことは何ですか。', '["冬の寒さを乗り切るためには、外国の高級な家具や照明を買うべきだ。","コーヒーや紅茶には目を覚ます効果があるので、一日五杯以上飲むとよい。","季節の寒さは変えられなくても、身の回りに小さな楽しみを工夫することで冬を心地よく過ごせる。","寒い地域に住むのは大変なので、できるだけ暖かい場所へ引っ越すべきだ。"]', 2, 'Đoạn 4 đúc kết: dù không thể thay đổi cái lạnh của thời tiết, ta vẫn có thể tạo ra những niềm vui nhỏ quanh mình để biến mùa đông thành mùa dễ chịu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-013-Q1', 'N3-R-LONG-013', 1, '以前の筆者が、疲れていても一人で家事をすべてやろうとしていたのはなぜですか。', '["人に頼らず自分の力だけで完全にやることが、自立した大人だと思っていたから。","他の人が作った料理や掃除の仕方が気に入らなかったから。","近くに頼れる友人や親戚が一人も住んでいなかったから。","家事をすべて一人でやると、運動になって健康に良いと思っていたから。"]', 0, 'Đoạn 1 nêu rõ: tác giả từng quan niệm rằng người lớn tự lập là phải tự làm trọn vẹn mọi việc bằng sức mình mà không dựa vào ai.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-013-Q2', 'N3-R-LONG-013', 2, '風邪で寝込んでいたとき、友人が見舞いに来てくれたことに対して、筆者は最初どう反応しましたか。', '["おかゆではなく、別の料理を買ってきてほしいとわがままを言った。","風邪がうつったら申し訳ないし、邪魔になって恥ずかしいと思って何度も謝った。","誰にも会いたくなかったので、ドアを開けずに帰ってもらった。","友人が来てくれるのは当たり前だと思って、お礼も言わずに食べた。"]', 1, 'Cuối đoạn 2 cho biết: lúc đầu tác giả liên tục xin lỗi vì ngại lây cảm cho bạn và thấy xấu hổ vì làm phiền bạn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-013-Q3', 'N3-R-LONG-013', 3, '友人が「困ったときに助け合うのはお互い様だよ」と言ったのはなぜですか。', '["同じマンションの住民は、必ず順番に料理を作り合う規則になっていたから。","おかゆと果物の代金を、来月筆者に倍にして返してもらうつもりだったから。","友人も先月足にけがをしたときに、筆者に買い物を手伝ってもらって助かった経験があったから。","友人は医者をしており、病気の人を助けるのが仕事だったから。"]', 2, 'Đoạn 3 lời người bạn nhắc lại: tháng trước khi bạn bị thương ở chân cũng đã nhờ tác giả đi chợ giúp rất nhiều.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-013-Q4', 'N3-R-LONG-013', 4, 'この出来事を通して、筆者の考え方はどのように変わりましたか。', '["これからは自分で家事を一切せず、すべて友人にやってもらおうと決めた。","人に頼られるのが嫌になったので、今後は誰の手伝いもしないようにしようと思った。","風邪をひかないように、仕事を辞めて家でゆっくり暮らそうと思った。","一人で無理をしすぎず、困ったときは素直に頼り、元気なときにお返しをする方がよいと気づいた。"]', 3, 'Đoạn 4 kết luận: thay vì cố gồng mình một mình đến mất cả nụ cười, lúc khó khăn hãy thành thật nhờ giúp đỡ và khi khỏe mạnh thì giúp lại người khác, giúp tình cảm giữa người với người thêm ấm áp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-014-Q1', 'N3-R-LONG-014', 1, 'この古い文房具屋では、万年筆や珍しいインクはどのように売られていますか。', '["店の外の箱に積まれており、客が自分で袋に入れてお金を箱に入れる。","ガラスのケースの中に並んでおり、店主のおじいさんに声をかけて出してもらう。","インターネットで事前に予約した人にだけ、郵送で届けられる。","十本入りのセットでしか売っておらず、一本ずつ買うことはできない。"]', 1, 'Cuối đoạn 1 nêu rõ: bút máy và mực màu hiếm được bày trong tủ kính, khách gọi ông chủ tiệm lấy ra giúp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-014-Q2', 'N3-R-LONG-014', 2, '高校生の筆者が万年筆を選んでいたとき、店主のおじいさんはどうしましたか。', '["高校生にはまだ早いと言って、安い鉛筆を買うように勧めた。","店の中で一番値段が高い万年筆を出して、すぐに買うように言った。","使う目的を聞き、試し書きをさせて筆者の手の大きさに合う一本を一緒に選んでくれた。","ケースのガラスが汚れるから触らないでほしいと注意した。"]', 2, 'Đoạn 2 kể lại: ông hỏi mục đích sử dụng, lấy 3 cây bút cho viết thử lên giấy và cùng chọn cây vừa tay tác giả nhất.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-014-Q3', 'N3-R-LONG-014', 3, '社会人になった現在も、筆者が年に一度その店へ行くのはなぜですか。', '["毎年新しい万年筆を十本ずつ買って、古いものを捨てるため。","店主のおじいさんの代わりに、休日の店番を手伝うため。","英語の単語帳や日記帳を、その店でしか買えないから。","高校生のときに買った万年筆のペン先を、店主に調整してもらうため。"]', 3, 'Cuối đoạn 3 nêu rõ: ngay cả khi đã đi làm, mỗi năm 1 lần tác giả vẫn mang bút đến tiệm nhờ ông chỉnh lại ngòi bút.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-014-Q4', 'N3-R-LONG-014', 4, '筆者がこの文房具屋で万年筆を買ってよかったと考えている一番の理由は何ですか。', '["道具を大切に使う知識と、困ったときにいつでも相談できる安心感が得られたから。","インターネットや大きな店で買うよりも、半額以下の安い値段で買えたから。","その万年筆を使ったおかげで、英語の試験で満点が取れたから。","おまけとして高いノートやインクを無料でたくさんもらえたから。"]', 0, 'Đoạn 4 kết luận: dù mua trên mạng có thể rẻ hơn vài trăm yên, nhưng kiến thức giữ gìn món đồ và sự an tâm luôn có nơi tư vấn sửa chữa là giá trị không gì thay thế được.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-015-Q1', 'N3-R-LONG-015', 1, '以前の筆者は、会話を盛り上げるためにどうしなければならないと思っていましたか。', '["相手の話を一言も聞かずに、自分の自慢話だけを大きな声でする。","最初は黙って座っており、相手が怒り出してから話し始める。","自分が面白い話題をたくさん用意して、絶えず話し続けなければならない。","会話の前に、話す内容を紙に書いて相手に配っておく。"]', 2, 'Cuối đoạn 1 nêu rõ: trước đây tác giả cứ ngỡ muốn cuộc trò chuyện sôi nổi thì mình phải chuẩn bị nhiều chủ đề thú vị và nói liên tục.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-015-Q2', 'N3-R-LONG-015', 2, '昼食のとき、山本先輩はどのように会話をしていましたか。', '["自分の趣味や休日の過ごし方について、一時間続けて話し続けた。","同僚の話の途中で間違いを注意し、正しい知識を教えていた。","食事中は一言も話さず、食べ終わってから仕事の注意だけをした。","自分の話はほとんどせず、タイミングよく相づちを打ちながら相手が話しやすい質問をしていた。"]', 3, 'Đoạn 2 mô tả: tiền bối Yamamoto hầu như không nói về mình mà hưởng ứng đúng lúc và đặt những câu hỏi nhỏ giúp đồng nghiệp hào hứng chia sẻ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-015-Q3', 'N3-R-LONG-015', 3, '山本先輩の様子を見て、筆者は会話についてどのようなことに気づきましたか。', '["関心を持って相手の言葉を受け止める「聞く人」がいてこそ、生き生きとした会話が生まれるということ。","普段あまり話さない人とは、どんなに工夫しても会話が盛り上がらないということ。","昼食の時間は仕事の話だけをするべきで、趣味の話はするべきではないということ。","会話を上手にするためには、相づちの言葉を百種類以上暗記しなければならないということ。"]', 0, 'Đoạn 3 giải thích: không phải chỉ người nói mới là nhân vật chính, mà phải có người nghe biết quan tâm và đón nhận lời đối phương thì cuộc trò chuyện mới thực sự sống động.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-015-Q4', 'N3-R-LONG-015', 4, '現在の筆者が、友人と会うときに心がけていることは何ですか。', '["会う前に面白いニュースを十調べておき、順番に話して聞かせること。","次に自分が話すことばかり考えず、相手の表情や声に注意を向けて最後までじっくり聞くこと。","自分は最初から最後まで一言も話さず、うなずくだけにすること。","会話が長くならないように、三十分で必ず帰るようにすること。"]', 1, 'Đoạn 4 nêu rõ: tác giả bỏ thói quen chỉ lo nghĩ câu tiếp theo mình sẽ nói gì, thay vào đó chú ý tới biểu cảm và giọng nói của bạn để lắng nghe trọn vẹn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-016-Q1', 'N3-R-LONG-016', 1, '筆者が東京で一人暮らしを始めてから、冬にみかんを食べなくなっていたのはなぜですか。', '["大人になってから、みかんの酸っぱい味が苦手になってしまったから。","東京のスーパーでは、みかんの値段が高すぎて買えなかったから。","医者から、冬に冷たい果物を食べないように言われたから。","一人暮らしをするようになり、果物を箱で買う習慣がなくなったから。"]', 3, 'Cuối đoạn 1 nêu rõ: từ khi lên Tokyo sống một mình để học đại học, tác giả không còn mua trái cây theo thùng nên thói quen ăn quýt mùa đông cũng mất dần.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-016-Q2', 'N3-R-LONG-016', 2, '母から届いたみかんを食べたとき、筆者はどのような気持ちになりましたか。', '["爽やかな香りと甘酸っぱさが広がり、懐かしい実家の居間の風景を思い出した。","酸っぱすぎて食べられないと思い、すぐに母に電話で文句を言った。","手が黄色くなってしまうので、もう食べたくないと思った。","スーパーで買う高いみかんの方が、形がきれいで味が良いと思った。"]', 0, 'Cuối đoạn 2 mô tả: hương thơm tươi mát và vị chua ngọt dịu dàng lan tỏa làm sống dậy ngay khung cảnh phòng khách thân thương ở quê nhà.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-016-Q3', 'N3-R-LONG-016', 3, '一人で食べ切れないほどたくさんのみかんを、筆者はどうしましたか。', '["すべてジュースにして冷凍庫に入れ、夏まで保存することにした。","職場の同僚や隣の部屋の老夫婦に少しずつ袋に入れて分けた。","傷まないうちに、半分以上をもう一度田舎の母へ送り返した。","近所の八百屋へ持っていって、安い値段で買い取ってもらった。"]', 1, 'Đoạn 3 nêu rõ: vì một mình không thể ăn hết gần 100 quả nên tác giả chia vào túi nhỏ biếu đồng nghiệp và vợ chồng cụ già ở căn hộ bên cạnh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-016-Q4', 'N3-R-LONG-016', 4, 'みかんを周りの人に分けたことで、どのような良いことがありましたか。', '["同僚からお金をもらうことができ、冬の生活費の足しになった。","マンションの管理人から褒められて、来月の家賃が割引になった。","手作りの料理をもらったり、普段挨拶しかしていなかった同僚と話が盛り上がったりして交流が生まれた。","周りの人たちもみんな田舎から果物を取り寄せるようになった。"]', 2, 'Cuối đoạn 3 và đoạn 4 cho biết: nhờ biếu quýt mà tác giả được tặng lại dưa muối tự làm, trò chuyện sôi nổi về quê hương với đồng nghiệp và có thêm sự gắn kết ấm áp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-017-Q1', 'N3-R-LONG-017', 1, '公園を歩き始めた最初の数日間、筆者はどのように感じていましたか。', '["ただ時計を見ながら早足で歩いているだけで、少し退屈だと感じていた。","美しい花がたくさん咲いていて、毎日歩くのが楽しくて仕方がなかった。","朝の空気が冷たすぎて、三十分も歩くと足が痛くなってつらかった。","公園に人が多すぎて、まっすぐ歩くことができず不便だと感じていた。"]', 0, 'Cuối đoạn 1 nêu rõ: mấy ngày đầu chỉ nhìn đồng hồ đi bộ nhanh nên tác giả thấy hơi nhàm chán.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-017-Q2', 'N3-R-LONG-017', 2, '青いぼうしをかぶったお年寄りのグループは、公園で何をしていましたか。', '["公園のベンチに座って、みんなで温かいお茶を飲みながらおしゃべりをしていた。","市のボランティアとして、散歩する人のために草を抜いたり花の手入れをしたりしていた。","花の場所に咲いているチューリップを切って、通行人に一輪百円で売っていた。","毎朝ラジオ体操の音楽を流して、近所の子どもたちに体操を教えていた。"]', 1, 'Đoạn 2 giải thích: các cụ là tình nguyện viên của thành phố, nhổ cỏ và chăm sóc hoa để mọi người đi dạo được dễ chịu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-017-Q3', 'N3-R-LONG-017', 3, 'ボランティアの人たちと話したあと、筆者の朝の散歩はどう変わりましたか。', '["花の邪魔にならないように、公園の中を歩くのをやめて駅前の道を歩くようになった。","毎朝一時間早く起きて、一人で公園中のごみを全部拾うようになった。","花の成長を確かめるのを楽しみにし、ボランティアの人たちに感謝の挨拶をするようになった。","歩く時間を三十分から十分に変えて、すぐに家へ帰るようになった。"]', 2, 'Đoạn 3 nêu rõ: tác giả quan sát từng nụ hoa lớn lên mỗi ngày và chào hỏi, cảm ơn các bác tình nguyện viên.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-017-Q4', 'N3-R-LONG-017', 4, '筆者が来年の春から始めようと考えていることは何ですか。', '["自分の家の庭を広げて、赤いチューリップを百本植えること。","公園で咲いている花の写真を撮って、市の展覧会に出すこと。","健康のために、毎朝の散歩をやめて水泳クラブに通い始めること。","休日の朝に、公園の花を手入れするボランティアの仲間に加えてもらうこと。"]', 3, 'Câu cuối đoạn 4 cho biết: từ mùa xuân năm tới, tác giả dự định xin tham gia cùng nhóm tình nguyện viên chăm sóc hoa vào sáng ngày nghỉ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-018-Q1', 'N3-R-LONG-018', 1, '入社してすぐの頃、筆者は会議の記録をどのように取っていましたか。', '["会議中は一言もメモを取らず、終わったあとに記憶だけを頼りに書いていた。","発言を一つも落とさないよう、ずっとパソコンの画面を見つめて打ち込み続けていた。","録音機を机の上に置いておき、自分は目を閉じて休んでいた。","隣の席の先輩のノートを会議のあとに借りて、そのまま書き写していた。"]', 1, 'Đoạn 1 nêu rõ: hồi mới vào công ty, để không sót lời nào của cấp trên và tiền bối, tác giả nhìn màn hình gõ phím liên tục suốt buổi họp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-018-Q2', 'N3-R-LONG-018', 2, 'パソコンで全ての言葉を打ち込むやり方には、どのような問題がありましたか。', '["キーボードの音がうるさすぎて、周りの人から会議室を出ていくように言われた。","会議の途中でパソコンの電池が切れてしまい、記録が全部消えてしまった。","打つことに気を取られて話を深く理解できず、あとで読んでも大切な結論が一目でわからなかった。","漢字の変換ミスが多すぎて、誰も読めない文章になってしまった。"]', 2, 'Đoạn 2 giải thích: vì mải gõ chữ nên không hiểu sâu nội dung ngay tại cuộc họp để đặt câu hỏi, và bản ghi dài dòng khi đọc lại cũng khó nhìn ra đâu là kết luận quan trọng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-018-Q3', 'N3-R-LONG-018', 3, '課長は筆者に、会議のノートには何を書けばよいと教えましたか。', '["会議室の温度や出席者の服装など、細かい様子をすべて書くこと。","自分の感想や反対意見だけを、赤いペンで大きく書くこと。","会議中は白紙のままにしておき、次の日の朝になってから思い出したことを書くこと。","決定したことと、次に誰が何をするかだけを短い言葉で書き留めること。"]', 3, 'Đoạn 3 lời trưởng phòng khuyên: hãy lắng nghe và hiểu trước, còn trong sổ chỉ ghi ngắn gọn những điều đã quyết định và việc tiếp theo ai sẽ làm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-018-Q4', 'N3-R-LONG-018', 4, '紙のノートに要点だけを書くように変えた結果、筆者はどうなりましたか。', '["話に集中できるようになり、疑問に思ったことをその場で質問して確かめられるようになった。","会議が退屈になり、途中で居眠りをしてしまうことが増えた。","書く量が少なすぎて、会議の内容を翌日にはすべて忘れてしまうようになった。","パソコンの使い方をすっかり忘れてしまい、書類が作れなくなった。"]', 0, 'Đoạn 4 cho biết: giảm lượng chữ viết giúp tác giả tập trung nghe hiểu và hỏi lại ngay những điểm thắc mắc tại cuộc họp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-019-Q1', 'N3-R-LONG-019', 1, '筆者が外国へ旅行に行ったとき、一番楽しみにしていることは何ですか。', '["ガイドブックに載っている有名な城や美術館をすべて見て回ること。","高級なホテルのレストランで、日本料理と同じ味の食事をすること。","その街の人々が普段利用している地元のスーパーや市場を訪れること。","観光地のお土産屋で、高いかばんや時計をたくさん買うこと。"]', 2, 'Đoạn 1 nêu rõ: điều tác giả mong đợi nhất khi du lịch nước ngoài là ghé thăm siêu thị hoặc khu chợ địa phương nơi người dân bản xứ mua sắm hằng ngày.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-019-Q2', 'N3-R-LONG-019', 2, 'アジアの国の朝の市場で、筆者が珍しい果物を眺めていたとき、どのようなことが起きましたか。', '["買わないなら見ないでほしいと、店主から怒られてしまった。","日本語が話せる観光ガイドが偶然通りかかって、通訳をしてくれた。","果物の匂いが強すぎて気分が悪くなり、すぐにホテルへ戻った。","地元の主婦が食べ方を身ぶり手ぶりで教えてくれ、店主が一口切って試食させてくれた。"]', 3, 'Đoạn 2 và 3 kể lại: bà nội trợ địa phương dùng cử chỉ chỉ cách gọt vỏ chấm muối, còn bác chủ sạp cắt một miếng cho tác giả ăn thử.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-019-Q3', 'N3-R-LONG-019', 3, '筆者の心に一番深く残っている思い出は何ですか。', '["言葉は通じなくても、市場の人たちと果物を食べて顔を見合わせて笑った温かい時間。","その国で一番高いタワーの上から見た夕日の景色。","市場で買った珍しいスパイスを日本へ持ち帰って料理を作ったこと。","飛行機の中で隣に座った人と友だちになったこと。"]', 0, 'Cuối đoạn 3 khẳng định: dù bất đồng ngôn ngữ, khoảnh khắc ấm áp khi ăn thử miếng quả và cùng nhìn nhau mỉm cười ở khu chợ đọng lại sâu sắc hơn bất kỳ danh lam thắng cảnh nào.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-019-Q4', 'N3-R-LONG-019', 4, 'この文章全体で筆者が最も伝えたいことは何ですか。', '["外国へ行くときは、現地の言葉を完全に話せるようになってから行くべきだ。","地元の人々の普段の暮らしに足を踏み入れることで、生きた文化や人の優しさに出会える。","観光地のお土産屋は値段が高いので、市場以外では買い物をするべきではない。","外国の珍しい果物は体に合わないことがあるので、食べない方が安全だ。"]', 1, 'Đoạn 4 kết luận: bước chân vào đời sống thường nhật của người dân địa phương giúp ta chạm tới văn hóa sống động và lòng hiếu khách mà sách vở hay internet không thể có được.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-020-Q1', 'N3-R-LONG-020', 1, '以前の筆者が、料理やプログラミングを何年も始められなかったのはなぜですか。', '["近くに専門の学校が一つもなく、通うことができなかったから。","家族から、新しいことを始めると仕事がおろそかになると反対されていたから。","どの分野を勉強すればよいか決められず、毎日迷っていたから。","まとまったお金と時間をかけて学校に通わなければならないと思い、忙しい仕事を理由にしていたから。"]', 3, 'Đoạn 1 nêu rõ: tác giả nghĩ học cái mới phải tốn nhiều tiền và thời gian đi học trường lớp chuyên môn, nên lấy cớ bận việc mà nhiều năm không bắt đầu được.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-020-Q2', 'N3-R-LONG-020', 2, '筆者のおじは、どのようにして木の椅子を作れるようになりましたか。', '["図書館の本とインターネットの無料動画を使い、毎晩三十分ずつ一人で勉強して練習した。","若い頃から家具の工場で四十年間働いて技術を身につけた。","高い授業料を払って、有名な職人の家に半年間住み込んで習った。","組み立てるだけの簡単な木のセットを通信販売で買って作った。"]', 0, 'Đoạn 2 giải thích: người chú mượn 3 cuốn sách ở thư viện và xem video miễn phí trên mạng, tự học mỗi tối 30 phút trong nửa năm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-020-Q3', 'N3-R-LONG-020', 3, 'おじの姿を見て、筆者は自分自身についてどのようなことに気づきましたか。', '["自分には手先を使う木工の才能がまったくないということ。","時間やお金を言い訳にして、始める前から自分で勝手にあきらめていただけだということ。","定年退職する六十歳までは、仕事以外の勉強をするべきではないということ。","本を読むよりも、まず高い道具を全部集めることが大切だということ。"]', 1, 'Đầu đoạn 3 nêu rõ: tác giả nhận ra mình chỉ đang lấy lý do thiếu thời gian, tốn tiền để biện minh và bỏ cuộc trước khi bắt đầu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-LONG-020-Q4', 'N3-R-LONG-020', 4, 'おじに刺激を受けたあと、筆者はどのような行動を取りましたか。', '["会社を辞めて、プログラミングの専門学校に毎日通い始めた。","おじから木工の道具を借りて、自分も木の椅子を作り始めた。","書店でテキストを買い、毎晩寝る前の二十分間だけプログラミングの練習を続けて仕事に活かしている。","図書館で料理の本を十冊借りたが、忙しくてまだ一ページも読んでいない。"]', 2, 'Đoạn 4 cho biết: ngay trên đường về tác giả mua 1 cuốn sách giáo trình, mỗi tối trước khi ngủ luyện lập trình 20 phút và sau nửa năm đã tự làm được công cụ tính toán phục vụ công việc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-001-Q1', 'N3-R-INFO-001', 1, 'みどり市内の会社で働く20人のグループが、土曜日の午後（13:00〜17:00）に「1番会議室」を借りて冷房を使います。料金は全部でいくらになりますか。', '["基本料金の2,000円に冷暖房費の500円を足して、2,500円になる。","冷暖房費は無料なので、基本料金だけの2,000円になる。","市外団体の扱いになるため基本料金が二倍になり、冷暖房費と合わせて4,500円になる。","定員が30名の部屋なので、20人では借りることができない。"]', 0, 'Nhóm làm việc tại công ty trong thành phố Midori (hưởng giá gốc) + Phòng họp số 1 buổi chiều (2,000円) + dùng điều hòa (+500円) = 2,500円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-001-Q2', 'N3-R-INFO-001', 2, 'この体育館の予約や利用について、案内と合っているものはどれですか。', '["当日急に予定が変わった場合でも、午前九時までに電話をすれば無料で取り消しができる。","小体育室を夜間（18:00〜21:00）に借りて暖房を使う場合、500円の追加料金はかからない。","参加メンバーの全員がみどり市民でなければ、基本料金が二倍になってしまう。","放送設備を使って45人で会議をしたい場合は、1番会議室を予約すればよい。"]', 1, 'Ghi chú ※ thứ hai nêu rõ: riêng ca tối của Phòng thể chất nhỏ (小体育室の夜間利用に限り), phí điều hòa đã bao gồm trong giá cơ bản nên không mất thêm 500円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-002-Q1', 'N3-R-INFO-002', 1, '大学生のリンさんは、研修期間が終わったあと、平日の「③午後6:00〜午後10:00（4時間）」に書店スタッフとして働きます。この日の給料（交通費を除く）はいくらですか。', '["基本の1,050円のままなので、4時間で4,200円になる。","カフェスタッフと同じ時給になるので、4時間で4,400円になる。","午後6時以降は時給が1,150円になるので、4時間で4,600円になる。","研修期間が終わっても50円引きになるので、4時間で4,000円になる。"]', 2, 'Đã hết thời gian đào tạo; làm nhân viên hiệu sách ca ③ từ 6:00 tối ~ 10:00 tối (4 tiếng) được cộng thêm 100円/giờ: (1,050 + 100) × 4 = 4,600円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-002-Q2', 'N3-R-INFO-002', 2, 'このアルバイトの条件について、正しいものはどれですか。', '["土曜日と日曜日だけ週2日働きたい大学生でも、カフェスタッフに応募できる。","1日に4時間働く日でも、毎回カフェの飲み物とサンドイッチが無料でもらえる。","高校3年生であれば、親の許可をもらうことで書店スタッフとして働ける。","1日に6時間以上働く日は、カフェの飲み物とサンドイッチが無料で出される。"]', 3, 'Theo ghi chú ※ cuối cùng: vào ngày làm việc từ 6 tiếng trở lên sẽ được cung cấp miễn phí đồ uống và bánh sandwich của quán (phải làm ít nhất 3 ngày/tuần và không tuyển học sinh cấp 3).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-003-Q1', 'N3-R-INFO-003', 1, '田中さんは半年前に「さくら家電」で買ったパソコンにコーヒーをこぼしてしまい、キーボードが動かなくなりました。保証書を持って修理（メニューC）を頼み、代わりのパソコンは借りない場合、全部でいくら払いますか。', '["保証書があるのでチェックの料金は無料で、作業料も半額の5,000円になる。","水をこぼした故障は保証の対象外なので、チェックの料金2,000円と作業料10,000円で12,000円になる。","チェックの料金は無料になるが、作業料は通常の10,000円になる。","他店で買ったパソコンではないので、すべて無料で修理してもらえる。"]', 1, 'Dù mua tại tiệm trong vòng 1 năm và có phiếu bảo hành, nhưng làm đổ nước/cà phê (水をこぼしたり) không được bảo hành nên phải trả phí thông thường: phí kiểm tra 2,000円 + mục C 10,000円 = 12,000円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-003-Q2', 'N3-R-INFO-003', 2, '他店で3年前に買ったパソコンの充電がすぐ切れるようになったため、この店で電池の交換（メニューB）を頼む場合、正しいものはどれですか。', '["パソコンを5日間店に預けなければならず、その間は代わりのパソコンを無料で借りられる。","他店で買ったパソコンはチェックの料金が二倍の4,000円になる。","チェックの料金2,000円と作業料8,000円の合計10,000円がかかり、約90分で当日に受け取れる。","チェックしてもらったあとで修理をやめた場合は、お金を一切払わなくてよい。"]', 2, 'Máy mua ở tiệm khác 3 năm trước tính giá thường: phí kiểm tra (2,000円) + thay pin mục B (8,000円) = 10,000円, và mục B nhận lại máy ngay trong ngày sau khoảng 90 phút.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-004-Q1', 'N3-R-INFO-004', 1, '両親（大人2人）と小学生の子ども1人、4歳の弟の家族4人が、土曜日に「木の家バンガロー」に一晩とまり、前日にバーベキューのセットも1つ予約しました。料金は全部でいくらですか。', '["バンガロー8,000円、管理費1,200円、バーベキュー2,000円で、合計11,200円になる。","4歳の弟にも管理費200円がかかるため、合計13,400円になる。","バーベキューのセットはバンガローの料金に含まれているため、11,200円になる。","バンガロー10,000円、管理費1,200円、バーベキュー2,000円で、合計13,200円になる。"]', 3, 'Ngủ đêm thứ Bảy ở nhà gỗ Bungalow (10,000円) + phí quản lý: 2 người lớn (500×2=1,000円) + 1 học sinh tiểu học (200円) + bé 4 tuổi (0円) = 1,200円 + thuê 1 bộ BBQ đặt trước (2,000円) = 13,200円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-004-Q2', 'N3-R-INFO-004', 2, 'このキャンプ場の利用ルールについて、正しいものはどれですか。', '["バーベキューの道具と火をおこすすみのセットは、当日受付で申し込んでも借りることはできない。","火曜日が祝日の場合はキャンプ場が休みになり、水曜日から営業が始まる。","テントサイトは1区画につき大人4人までしか利用することができない。","夜9時を過ぎても、木の家バンガローの前なら花火をしても構わない。"]', 0, 'Ghi chú ※ thứ hai ghi rõ bộ dụng cụ BBQ phải đặt qua điện thoại chậm nhất từ hôm trước, không nhận đăng ký trong ngày (当日申し込みは不可).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-005-Q1', 'N3-R-INFO-005', 1, '九州の北九州に住む山田さんは、自宅用に「A箱（2,500円）」を2箱まとめて注文し、代金は商品が届いたときに現金で払います。支払う合計金額はいくらですか。', '["りんご代5,000円に送料2,000円と手数料300円を足して、7,300円になる。","送料も届いたときの現金払いの手数料もすべて無料になり、5,000円ちょうどになる。","同じ住所に2箱頼むので送料は無料になり、りんご代5,000円と届いたときの現金払いの手数料300円で5,300円になる。","九州への送料は半額の500円になり、手数料と合わせて5,800円になる。"]', 2, 'Đặt 2 thùng A về cùng địa chỉ nhà mình ở Kyushu nên được miễn phí vận chuyển: tiền táo (2,500 × 2 = 5,000円) + trả tiền mặt khi nhận hàng COD (+300円 phí) = 5,300円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-005-Q2', 'N3-R-INFO-005', 2, '東京（本州）の自宅に「A箱」を1箱、大阪（本州）の友人の家に「B箱」を1箱送り、クレジットカードで払う場合、送料はどうなりますか。', '["合計2箱注文しているので、東京の分も大阪の分も送料は無料になる。","クレジットカードで払うと送料が半額になるため、合計600円の送料がかかる。","贈答用のB箱だけは全国どこでも送料が無料になるため、600円だけかかる。","別々の住所に1箱ずつ送るため無料にはならず、600円ずつ合計1,200円の送料がかかる。"]', 3, 'Ghi chú ※ thứ nhất nêu rõ: nếu gửi mỗi thùng tới một địa chỉ khác nhau thì không được miễn phí ship mà tính phí từng thùng (Honshu: 600円 × 2 = 1,200円).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-006-Q1', 'N3-R-INFO-006', 1, 'このスクールに初めて通う田中さんは、3月10日に「1. 会話・会議コース」を申し込みました。支払う金額は全部でいくらになりますか。', '["入学金は無料で授業料が3,000円引きになり、テキスト代と合わせて36,000円になる。","入学金10,000円、授業料36,000円、テキスト代3,000円で、合計49,000円になる。","入学金とテキスト代の両方が無料になり、33,000円になる。","早期申込なので授業料だけが3,000円引きになり、入学金とテキスト代を合わせて46,000円になる。"]', 0, 'Đăng ký ngày 10/3 (trước 15/3) nên được miễn phí nhập học 10,000円 và giảm 3,000円 học phí: (36,000 - 3,000) + tiền sách 3,000 = 36,000円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-006-Q2', 'N3-R-INFO-006', 2, '急な残業で授業を欠席してしまった場合、どうすることができますか。', '["欠席した回数分の授業料を、月末に現金で返金してもらうことができる。","同じ週の別の曜日のクラスへ変更するか、インターネットで授業の録画を見ることができる。","先生の自宅へ行って、個人レッスンを無料で受けることができる。","一度でも欠席すると、残りの授業を受けることができなくなる。"]', 1, 'Ghi chú ※ thứ hai nêu rõ: buổi vắng mặt có thể đổi sang lớp ngày khác trong cùng tuần hoặc xem video ghi hình trên internet.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-007-Q1', 'N3-R-INFO-007', 1, 'ホテルに泊まらない高橋さんは、地下駐車場に車をとめてホテル内のレストランで3,800円の昼食をとり、ちょうど2時間30分で車を出しました。駐車料金はいくら払いますか。', '["3,000円以上食事をしたので、2時間30分すべて無料になる。","5,000円未満なので割引は使えず、900円を払う。","宿泊客と同じ料金になり、1,200円を払う。","2時間まで無料になり、残りの30分間の料金として200円を払う。"]', 3, 'Ăn hết 3,800円 (từ 3,000円 trở lên và dưới 5,000円) được miễn phí 2 tiếng đầu; đỗ 2 tiếng 30 phút nên chỉ phải trả 30 phút vượt thêm là 200円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-007-Q2', 'N3-R-INFO-007', 2, 'この駐車場の利用について、正しい説明はどれですか。', '["地下駐車場が満車で裏の「1番パーキング」にとめた場合でも、フロントに駐車券を出せば同じ割引が受けられる。","ホテルの宿泊客であれば、翌日の午後3時まで追加料金なしで車をとめておける。","高さが2メートル50センチあるマイクロバスでも、地下駐車場にとめることができる。","喫茶店で500円のコーヒーを1杯飲めば、駐車場が2時間まで無料になる。"]', 0, 'Ghi chú ※ cuối cùng nêu rõ: nếu bãi xe ngầm đầy và phải đỗ ở bãi xe liên kết (1番パーキング), khách mang vé xe đến quầy lễ tân vẫn được hưởng mức giảm giá giống hệt.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-008-Q1', 'N3-R-INFO-008', 1, 'みどり市内に住む30歳の主婦の山本さんは、このフリーマーケットで「子どもが着なくなった服」と「手作りのクッキー」を車で運んで売りたいと考えています。山本さんはどうなりますか。', '["B区画に申し込めば、服と手作りのクッキーの両方を売ることができる。","食べ物の販売は禁止されているため、手作りのクッキーは売ることができないが、服だけならB区画に出店できる。","1世帯で2区画借りれば、片方で服を売り、もう片方でクッキーを売ることができる。","主婦は出店することができないため、どちらも売ることができない。"]', 1, 'Ghi chú ※ thứ nhất nghiêm cấm bán đồ ăn thức uống tự làm (自分で作った食べ物・飲み物の販売は固くお断りします), nên chị Yamamoto chỉ có thể bán quần áo cũ của con tại ô khu B.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-008-Q2', 'N3-R-INFO-008', 2, '出店の手続きやルールについて、案内と合っているものはどれですか。', '["申し込みは電話で受け付けており、先着順ですぐに出店が決まる。","5月18日に雨が降った場合はイベントが中止になり、別の日には行われない。","4月30日までに往復はがきで申し込む必要があり、参加費は当日に会場の受付で払う。","参加費は往復はがきを送るときに、封筒にお金を入れて一緒に送らなければならない。"]', 2, 'Ghi chú ※ thứ hai nêu rõ: phải đăng ký bằng bưu thiếp khứ hồi đến trước ngày 30/4, nếu đông sẽ bốc thăm, và phí tham gia đóng tại quầy lễ tân vào ngày tổ chức.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-009-Q1', 'N3-R-INFO-009', 1, '68歳の父と、40歳の母と、大学生の娘の3人が、6月15日（日）の午前中に前売り券を持たずにこの展覧会へ行きます。父が年齢の証明書を見せた場合、3人の入場料は合計いくらですか。', '["父700円、母1,400円、娘900円で、合計3,000円になる。","3人とも前売り券の値段で買えるので、合計2,900円になる。","父が65歳以上なので家族全員が半額になり、合計1,850円になる。","日曜日の午前中でも夕方割引が使えるので、合計2,800円になる。"]', 0, 'Mua vé trong ngày vào sáng Chủ nhật 15/6: Bố 68 tuổi (>= 65 tuổi, giảm nửa vé người lớn còn 700円) + Mẹ 40 tuổi (vé thường 1,400円) + Con gái sinh viên (900円) = 3,000円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-009-Q2', 'N3-R-INFO-009', 2, '大学生のナムさんが、一番安い料金でこの展覧会を見るにはどうすればよいですか。', '["5月31日までに書店で前売り券（700円）を買っておき、期間中に行く。","6月に入ってから金曜日の午後5時以降に行き、夕方割引（300円引き）で当日券を買う。","5月31日までに前売り券（700円）を買い、さらに金曜日の夕方に窓口で300円返してもらう。","月曜日に行けば学生は無料になるので、月曜日の午前中に行く。"]', 1, 'Vé sinh viên mua trong ngày là 900円; nếu đi sau 5 giờ chiều thứ Sáu hoặc thứ Bảy được giảm 300円 (夕方割引) chỉ còn 600円 — rẻ hơn cả vé đặt trước (700円)! (Và vé đặt trước không được gộp giảm giá).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-010-Q1', 'N3-R-INFO-010', 1, '健康保険証を持っている会社員のキムさんが、同じ日に「1. 基本の検査コース」と「2. 徹底クリーニングコース」の両方を続けて受けます。支払う金額は約いくらですか。', '["クリーニングにも保険が使えるようになり、合計約3,000円になる。","割引はないため、1,500円と6,000円で合計約7,500円になる。","基本の検査1,500円と、1,000円引きになったクリーニング5,000円で、合計約6,500円になる。","2つのコースを同じ日に受けることはできないので、別々の日に予約しなければならない。"]', 2, 'Có thẻ bảo hiểm y tế: gói khám cơ bản (~1,500円) + làm cùng ngày với gói làm sạch chuyên sâu được giảm 1,000円 (6,000 - 1,000 = 5,000円) = khoảng 6,500円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-010-Q2', 'N3-R-INFO-010', 2, 'この歯科医院の利用について、案内と合っているものはどれですか。', '["コーヒーの着色汚れを落とす「徹底クリーニングコース」だけでも、健康保険証を使えば半額になる。","隣町の小学校に通う子どもでも、市内の子どもと同じように無料で「子ども予防コース」が受けられる。","予約をしていなくても、平日の午前中に行けばすぐに基本の検査が受けられる。","予約した日に行けなくなった場合は、前日の午後5時までに電話で連絡する必要がある。"]', 3, 'Ghi chú ※ ở cuối nêu rõ: muốn đổi hoặc hủy lịch hẹn phải gọi điện báo trước 5 giờ chiều ngày hôm trước.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-011-Q1', 'N3-R-INFO-011', 1, '35歳の母親が、1日のうちに自宅から「赤ルート」のバスで病院へ行き、帰りに病院から「青ルート」のバスへ20分後に乗り換えて自宅へ戻ります（合計2回乗車）。一番安く乗るにはどうすればよいですか。', '["1日乗り放題パス（500円）をバスの運転手から買うのが一番安い。","行きの運賃200円、帰りは赤ルートから青ルートへの乗り換え券を使えないので合計400円になるが、乗り放題パスより安い。","行きは200円、帰りは1台目で200円払い、乗り換え券をもらって2台目を100円にする。","バスの車内で2,000円の回数券を買って使う。"]', 1, 'Nếu chỉ đi 2 lượt (lượt đi 200円 + lượt về 200円 = 400円) thì trả tiền từng lượt rẻ hơn mua vé 1 ngày (500円). Trường hợp lượt về phải đi 2 chặng (Đỏ sang Xanh dương trong 20 phút): lượt đi 200円 + lượt về chặng 1 (200円) + chặng 2 có phiếu chuyển tuyến (100円) = 500円, bằng vé ngày.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-011-Q2', 'N3-R-INFO-011', 2, 'このコミュニティバスの乗車券について、正しい説明はどれですか。', '["1日乗り放題パスを使えば、買った日とその翌日の2日間バスに乗ることができる。","70歳以上であれば、他の町に住んでいる人でも「高齢者さわやかパス」を買うことができる。","2,000円の回数券はバスの車内では買えないため、市役所の窓口かバス営業所で買う必要がある。","最初のバスを降りてから1時間後に別のルートのバスに乗る場合でも、乗り換え券で半額になる。"]', 2, 'Mục 2 ghi rõ: Vé tập (回数券) giá 2,000円 chỉ bán tại quầy Ủy ban thành phố hoặc văn phòng xe buýt, không bán trên xe (車内では買えません).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-012-Q1', 'N3-R-INFO-012', 1, '20人の会社が「2. 昼食弁当付き会議プラン」を予約し、プロジェクターとスクリーンも借ります。前日の朝10時に1人減って19人になったと連絡した場合、支払う合計金額はいくらですか。', '["19人分の66,500円にプロジェクター代3,000円を足して、69,500円になる。","1人分のキャンセル料2,000円がかかるため、68,500円になる。","20人分の料金をそのまま払わなければならないため、70,000円になる。","前日の正午までの連絡なのでキャンセル料はかからず、プロジェクター代も無料なので、19人分の66,500円になる。"]', 3, 'Báo giảm người lúc 10 giờ sáng hôm trước (trước 12 giờ trưa) nên không mất phí hủy; Gói 2 được miễn phí máy chiếu & màn chiếu -> chỉ trả tiền cho 19 người: 3,500 × 19 = 66,500円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-012-Q2', 'N3-R-INFO-012', 2, 'これらのプランの規則について、正しいものはどれですか。', '["「3. 夜の食事会プラン」で飲み放題をつける場合、お酒を飲む人だけ申し込むことはできず全員分の申し込みが必要になる。","8人のグループでも、「3. 夜の食事会プラン」に申し込むことができる。","「1. 会議のみプラン」を予約した場合でも、プロジェクターとスクリーンは無料で借りられる。","当日の朝に急病で欠席する人が出た場合でも、キャンセル料は一切かからない。"]', 0, 'Mục 3 ghi rõ: nếu thêm gói uống thỏa thích (+1,500円/người) thì bắt buộc phải đăng ký cho toàn bộ thành viên trong đoàn (全員分のお申し込みが必要です).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-013-Q1', 'N3-R-INFO-013', 1, '4月20日に、木村さんは「羽毛布団2枚」と「毛布1枚」の合計3枚を、自宅への「集配サービス」を使って洗濯だけ頼みます（預かりサービスは使いません）。支払う金額は全部でいくらですか。', '["割引後の7,200円に集配料800円を足して、8,000円を払う。","羽毛布団しか割引にならないため、集配料と合わせて8,800円を払う。","3枚で8,000円になり、1割引きで7,200円。6,000円以上なので集配料は無料になり、7,200円を払う。","通常価格の10,500円から1割引きになり、9,450円を払う。"]', 2, 'Trong đợt chiến dịch: 2 chăn lông vũ (3,500 × 2 = 7,000円) + 1 chăn len (1,000円) = 8,000円. Giặt 3 chiếc được giảm thêm 10% còn 7,200円. Vì 7,200円 >= 6,000円 nên miễn phí giao nhận (集配料無料) -> tổng trả 7,200円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-013-Q2', 'N3-R-INFO-013', 2, 'この布団丸洗いキャンペーンについて、正しいものはどれですか。', '["朝に布団を出せば、その日の夕方には乾いた状態で受け取ることができる。","毛布を3枚まとめて出した場合は、1割引きの対象にはならない。","割引後の洗濯代が5,500円の場合でも、自宅への集配料800円は無料になる。","洗った布団を秋まで専用の部屋で預かってもらう場合は、1枚につき1,000円の追加料金がかかる。"]', 3, 'Ghi chú ※ cuối cùng nêu rõ: thời gian giặt xong khoảng 1 tuần, và nếu dùng dịch vụ giữ chăn tới mùa thu tại phòng chuyên dụng của tiệm thì tính thêm 1,000円/chiếc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-014-Q1', 'N3-R-INFO-014', 1, 'ベトナム出身のアンさんは、在留資格（ビザ）の更新についてベトナム語で相談したいと考えています。アンさんはどうしなければなりませんか。', '["相談日の3日前（水曜日）までに電話かホームページで予約をしてから、3番目の土曜日に行く。","予約は不要なので、3番目の土曜日の午後3時30分までに市民プラザ3階へ直接行く。","ベトナム語の通訳がいないため、自分で通訳を連れていかなければならない。","法律の相談は1回につき3,000円の相談料を窓口で払わなければならない。"]', 0, 'Tư vấn về tư cách lưu trú (mục A) có hỗ trợ tiếng Việt và hoàn toàn miễn phí, nhưng theo ghi chú ※ bắt buộc phải đặt hẹn trước qua điện thoại hoặc trang chủ chậm nhất vào thứ Tư (3 ngày trước buổi tư vấn).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-014-Q2', 'N3-R-INFO-014', 2, 'この無料相談会について、正しい説明はどれですか。', '["1人あたりの相談時間に制限はないため、午前10時から午後4時までずっと相談してもよい。","「B：税金・年金の相談」や「C：子どもの学校の相談」は、予約なしで当日の午後3時30分までに受付をすれば相談できる。","「C：子どもの学校の相談」は、英語でも相談することができる。","相談会は毎週土曜日と日曜日に開かれている。"]', 1, 'Ghi chú ※ nêu rõ: mục B và C không cần đặt hẹn trước, chỉ cần đến làm thủ tục tại quầy tiếp nhận trước 3 giờ 30 chiều ngày tổ chức.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-015-Q1', 'N3-R-INFO-015', 1, '小学3年生の男の子が、初めてこのクラブで「イルカ組」の1回目の期間と2回目の期間の両方を同時に申し込みます。指定のぼうしを持っていない場合、最初に支払う金額は全部でいくらですか。', '["割引がないため12,000円になり、ぼうし代800円を足して12,800円になる。","2回同時に申し込むとぼうしが無料になるため、10,500円になる。","最初に入会金5,000円も払わなければならないため、16,300円になる。","2回分の参加費が10,500円になり、ぼうし代800円を足して11,300円になる。"]', 3, 'Đăng ký cùng lúc cả Đợt 1 và Đợt 2 được giảm 1,500円 còn 10,500円 + chưa có mũ chỉ định của CLB phải mua 1 chiếc (800円) = 11,300円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-015-Q2', 'N3-R-INFO-015', 2, 'この短期水泳教室について、正しいものはどれですか。', '["短期教室を受けたあと、8月中に通常コースへ入会すると入会金5,000円が無料になる。","5歳の小さい子どもでも、25メートル泳ぐ「イルカ組」に入ることができる。","水着もぼうしもすべてクラブ指定のものを新しく買わなければならない。","1回目の期間を終わったあとで2回目の期間を追加で申し込んでも、1,500円の割引が受けられる。"]', 0, 'Ghi chú ※ thứ hai nêu rõ: sau lớp ngắn hạn, nếu nhập hội khóa thường xuyên trong tháng 8 sẽ được miễn phí nhập hội 5,000円 và tặng túi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-016-Q1', 'N3-R-INFO-016', 1, '両親（大人2人）と中学1年生の姉、2歳の弟の家族4人で音楽を聴きに行きたい場合、どのコンサートなら全員一緒に入れますか。また、そのときの合計料金はいくらですか。', '["午後の音楽祭のA席に全員で入れ、合計10,500円になる。","午前の「親子のためのミニコンサート」に全員で入れ、2歳の弟をひざの上に座らせれば合計2,500円になる。","午前のミニコンサートに全員で入れ、4枚以上の割引で1割引きの2,250円になる。","2歳の子どもがいる家族は、午前も午後も会場に入ることができない。"]', 1, 'Có bé 2 tuổi (chưa vào tiểu học) nên không vào được buổi chiều mà phải chọn buổi sáng (親子のためのミニコンサート): 2 người lớn (1,000 × 2 = 2,000円) + chị lớp 7 (500円) + bé 2 tuổi ngồi trên đùi bố mẹ (0円) = 2,500円 (buổi sáng không áp dụng giảm giá 10%).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-016-Q2', 'N3-R-INFO-016', 2, '午後の「秋のクラシック音楽祭」のチケットについて、正しいものはどれですか。', '["大学生4人で「学生席（1,500円）」を4枚まとめて買う場合も、1割引きになって合計5,400円で買える。","小学5年生の子どもは、1,500円の「学生席」を買って入場することができる。","大人4人で1階の「S席（5,000円）」を4枚まとめて買う場合、1割引きになって合計18,000円で買える。","午後のコンサートも全席自由なので、早く並んだ人から前の席に座れる。"]', 2, 'Mua 4 vé ghế hạng S (5,000 × 4 = 20,000円) được giảm 10% (theo ghi chú ※ cuối cùng, chỉ trừ ghế sinh viên và buổi sáng) nên còn 18,000円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-017-Q1', 'N3-R-INFO-017', 1, '東京に住む山田さんは、東北エリアのスキー場へ自分のスキー板1つを送るため、「往復割引パック」を申し込み、行きの荷物を自分で営業所へ直接持ち込みました。支払う料金はいくらですか。', '["片道2,200円の2倍から往復割引400円と持ち込み割引100円を引いて、3,900円になる。","行きも帰りも持ち込み割引になって200円引かれ、3,800円になる。","東北エリアは往復割引が使えないため、4,300円になる。","関東エリアと同じ料金になり、3,100円になる。"]', 0, 'Khu vực Tohoku một chiều là 2,200円 -> khứ hồi (4,400円) trừ giảm giá gói khứ hồi (-400円) và trừ giảm giá tự mang ra bưu cục chiều đi (-100円) = 3,900円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-017-Q2', 'N3-R-INFO-017', 2, '土曜日（15日）に長野県（中部エリア）のスキー場で滑りたい場合、いつまでに荷物を出す必要がありますか。また、友人の分と1つの袋にまとめて送れますか。', '["前日の金曜日（14日）の夜までに出せばよく、2人分を1つの袋にまとめて送ると安くなる。","2日前の木曜日（13日）の午後5時までに出す必要があり、2人分を1つの袋に入れて送ることはできない。","3日前の水曜日（12日）までに出す必要があり、2人分を1つの袋に入れても構わない。","当日の朝に営業所へ持ち込めば、昼までにスキー場へ届けてもらえる。"]', 1, 'Theo ghi chú ※ thứ nhất và thứ ba: gửi đi Chubu cần gửi trước 5 giờ chiều của 2 ngày trước ngày trượt (tức thứ Năm ngày 13), và không được nhét đồ của 2 người vào chung 1 túi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-018-Q1', 'N3-R-INFO-018', 1, '会員登録をしていない山田さんが、日曜日の午前10時から午後5時までの7時間「1日利用」で勉強し、白黒コピーを15枚、カラーコピーを2枚とりました。支払う合計金額はいくらですか。', '["7時間分の2,800円とコピー代で、合計2,930円になる。","1日最大料金の1,800円にカード発行料2,000円が足されて、3,800円以上になる。","1日最大料金の1,800円に、白黒5枚分の50円とカラー2枚分の80円を足して、合計1,930円になる。","コピーはすべて無料なので、1,800円ちょうどになる。"]', 2, 'Ngồi 7 tiếng (400 × 7 = 2,800円 > 1,800円 nên chỉ tính mức trần 1 ngày là 1,800円) + photo đen trắng 15 tờ (10 tờ đầu miễn phí, 5 tờ sau × 10円 = 50円) + photo màu 2 tờ (2 × 40円 = 80円) = 1,930円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-018-Q2', 'N3-R-INFO-018', 2, '会社員のタンさんは、平日の仕事帰り（午後7時〜午後10時）と日曜日だけここで資格の勉強をしたいと考えています。初めて月額会員に申し込む場合、最初の月にいくら払いますか。', '["「C：フルタイムプラン（13,000円）」に入らなければならず、合計15,000円を払う。","カード発行料は無料なので、7,000円だけを払う。","「B：平日昼プラン（8,000円）」で日曜日の昼も利用できるため、10,000円を払う。","「A：夜＆休日プラン（7,000円）」とカード発行料2,000円で、合計9,000円を払う。"]', 3, 'Chỉ học tối ngày thường (19:00~22:00) và Chủ nhật nên chọn gói A (7,000円/tháng) + phí làm thẻ lần đầu (2,000円) = 9,000円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-019-Q1', 'N3-R-INFO-019', 1, 'さくら市内に住む田中さんは、市内の電気店で省エネラベル4つ星の新しいエアコンを税金を入れる前の価格180,000円で買い、自宅に置いて10日後に申請しました。もらえる助けのお金はいくらですか。', '["税金を入れる前の価格180,000円の2割なので、36,000円もらえる。","2割だと36,000円になるが、エアコンの上限が30,000円なので、30,000円もらえる。","冷蔵庫と同じ上限が適用されるので、40,000円もらえる。","置く前に申請しなかったため、助けのお金は1円ももらえない。"]', 1, '20% của 180,000円 là 36,000円, nhưng mức trần trợ cấp cho máy điều hòa là 30,000円 (上限 30,000円) nên nhận được 30,000円.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-019-Q2', 'N3-R-INFO-019', 2, 'この助けのお金の対象になるケースは、次のうちどれですか。', '["さくら市民が、インターネットでの買い物で3つ星の新しい冷蔵庫を安く買って自宅に置いた場合。","隣の町に住んでいる人が、さくら市内の電気店で4つ星のエアコンを買った場合。","さくら市民が、市内にある大型電気店の支店で3つ星の新しい冷蔵庫を買って自宅に置き、2週間後に申請した場合。","さくら市民が、市内のリサイクルショップで中古のエアコンを買って自宅に置いた場合。"]', 2, 'Theo điều kiện ①, ②, ③: phải là công dân thành phố Sakura, mua hàng mới (新品) tại cửa hàng có mặt bằng trong thành phố Sakura (gồm cả chi nhánh 支店), không mua qua mạng hay đồ cũ, và nộp đơn trong vòng 30 ngày sau khi lắp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-020-Q1', 'N3-R-INFO-020', 1, '大学生のマイさんは歴史が好きでこのボランティアに応募したいですが、3月の2番目の土曜日は大学の試験があるため基礎研修を1回休まなければなりません。マイさんはどうなりますか。', '["歴史の知識があれば基礎研修を1回休んでも採用される。","参加費を1,000円払えば、別の日に一人で研修を受けることができる。","大学生は応募資格がないため、最初から申し込むことができない。","3月の基礎研修に3回すべて出席できる人に限られているため、今回は応募することができない。"]', 3, 'Mục Điều kiện ứng tuyển ghi rõ: chỉ giới hạn cho người có thể tham dự đầy đủ cả 3 buổi đào tạo cơ bản vào các ngày thứ Bảy trong tháng 3 (3回すべて出席できる方に限ります).', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-R-INFO-020-Q2', 'N3-R-INFO-020', 2, '採用されたボランティアが、ある日曜日に「①午前の部」と「②午後の部」の両方を続けて活動した場合、何を受け取ることができますか。', '["交通費と、博物館1階の食堂で使える800円分の昼食券がもらえる。","時給1,000円として6時間分の給料6,000円がもらえる。","ボランティアなので、交通費も昼食券も一切出ない。","家族全員で使える博物館の年間パスポートだけがもらえる。"]', 0, 'Theo mục Chế độ đãi ngộ: được nhận tiền hỗ trợ đi lại và nếu làm liên tiếp cả ca sáng lẫn ca chiều trong cùng một ngày sẽ được tặng thêm phiếu ăn trưa 800円 dùng ở nhà ăn tầng 1.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-001-Q1', 'N3-L-TASK-001', 1, '男の人は作品を見せる会の準備でこの後まず何をしますか。', '["説明カードの名前を名簿で確かめます。","会場の机を入口から動かします。","印刷するための紙を買いに行きます。","作品を箱から出して壁に掛けます。"]', 0, 'Bàn do nhân viên hội trường chuyển, việc in do người nữ lo. Người nam cần đối chiếu tên tác giả trên thẻ với danh sách trước khi treo tác phẩm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-002-Q1', 'N3-L-TASK-002', 1, '女の人は登山の出発前にこの後まず何をしますか。', '["八人分の宿泊をすぐ予約します。","参加するか未定の人に返事を聞きます。","帰りのバスの時刻を調べます。","足を痛めた人に参加をすすめます。"]', 1, 'Người đau chân đã báo nghỉ; một người khác chưa quyết định. Người nữ phải hỏi người chưa chốt trước, còn xe buýt do người nam tra và chưa đặt chỗ ngủ ngay.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-003-Q1', 'N3-L-TASK-003', 1, '男の人はパン屋でこの後まず何をしますか。', '["運転手に新しい配達先を連絡します。","学校へパンを運び始めます。","注文書を見てパンの種類別の数を確かめます。","箱に集会所の住所を書きます。"]', 2, 'Địa chỉ mới đã được báo và người nữ ghi lên hộp. Người nam cần kiểm số lượng từng loại theo đơn trước khi đóng túi, không giao tới trường cũ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-004-Q1', 'N3-L-TASK-004', 1, '女の人は修理を頼むためにこの後まず何をしますか。', '["床をふいてからエアコンをつけます。","修理会社に自分で費用を払います。","修理の人が来るまで家で待ちます。","水の跡などを撮影して大家に送ります。"]', 3, 'Chủ nhà sẽ liên lạc công ty và thanh toán. Người nữ cần chụp vết nước cùng toàn bộ điều hòa rồi gửi trước khi lau lại; chưa cần ở nhà chờ thợ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-005-Q1', 'N3-L-TASK-005', 1, '男の人は学校の祭りでこの後まず何をしますか。', '["舞台の横の箱を中身ごと別の部屋へうつします。","入口で来場者の案内を始めます。","音楽が大きく聞こえるように調整します。","道具を箱から出して舞台に並べます。"]', 0, 'Cửa đã giao học sinh năm nhất, âm thanh đã được chỉnh. Người nam phải chuyển nguyên hộp đang chắn lối sang phòng trong trước khi kiểm tra nhạc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-006-Q1', 'N3-L-TASK-006', 1, '女の人はインタビューの準備でこの後まず何をしますか。', '["十この質問を二人分印刷します。","聞く内容を四つに減らして順番を考えます。","インタビュー用のカメラを借りに行きます。","店までの行き方を調べます。"]', 1, 'Thời gian bị rút ngắn nên người nữ cần chọn lại bốn câu và sắp thứ tự trước khi in. Quán gửi ảnh, người nam tra đường.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-007-Q1', 'N3-L-TASK-007', 1, '男の人は予約した店へ行く前にこの後まず何をしますか。', '["全員の魚料理を肉に変更します。","参加者へ集合場所の地図を送ります。","追加で参加する人に食べられない物を確認します。","料理を変えずに七人分頼みます。"]', 2, 'Chưa rõ Yamada không ăn được loại cá nào nên phải hỏi trực tiếp trước khi quyết định đổi món. Người nữ gửi bản đồ; số người báo sau hoặc báo trước nếu chờ lâu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-008-Q1', 'N3-L-TASK-008', 1, '女の人は録音を始める前にこの後まず何をしますか。', '["文章を八ページ全部印刷します。","部屋の窓を閉めます。","追加の文を録音し始めます。","携帯電話が鳴らないようにします。"]', 3, 'Cửa sổ đã đóng; người nam in trang cuối và chuẩn bị máy. Người nữ phải tắt âm điện thoại trước, rồi mới luyện câu thêm và thu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-009-Q1', 'N3-L-TASK-009', 1, '男の人は公民館の教室でこの後まず何をしますか。', '["隣の教室から包丁とまな板を追加で借ります。","届いた野菜を全部洗います。","材料を四つの机に分けます。","今ある道具を棚から出して並べます。"]', 0, 'Có thêm bàn thứ năm nên thiếu một bộ dụng cụ. Người nam phải mượn thêm dao và thớt; người nữ xếp đồ có sẵn, người phụ trách rửa rau.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-010-Q1', 'N3-L-TASK-010', 1, '女の人は水族館への遠足についてこの後まず何をしますか。', '["案内をそのまま親に送ります。","集合場所を体育館に書きかえて先生に見せます。","バス会社に帰着時間を問い合わせます。","当日持参する入館料を案内に加えます。"]', 1, 'Địa điểm đổi sang nhà thể chất, giờ không đổi. Người nữ sửa bản hướng dẫn rồi đưa giáo viên kiểm tra, chưa gửi phụ huynh; người nam xác nhận giờ về.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-011-Q1', 'N3-L-TASK-011', 1, '男の人は忘れ物を受け取るためにこの後まず何をしますか。', '["会社から駅へ直接かばんを取りに行きます。","弟に書類なしで受け取りを頼みます。","自宅に戻って身分を確認できる物を取ります。","受付番号を紙に書いて事務所へ送ります。"]', 2, 'Cặp ở văn phòng đồ thất lạc và cần giấy xác minh. Người nam sẽ về nhà lấy bằng lái trước; không đi thẳng đến ga hay nhờ em không có giấy nhận thay.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-012-Q1', 'N3-L-TASK-012', 1, '女の人は音楽会の受付でこの後まず何をしますか。', '["今の名簿をそのまま二部印刷します。","隣の事務室に券を取りに行きます。","予約客から参加費を集めます。","新しく予約した三人の名前を名簿に加えます。"]', 3, 'Phải thêm ba người mới trước rồi mới sắp theo tên và in. Người nam đi lấy vé, còn khách đặt trước đã trả tiền nên không thu thêm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-013-Q1', 'N3-L-TASK-013', 1, '男の人は畑の作業でこの後まず何をしますか。', '["かたむいた棒の周りの土を水でぬらします。","赤くないトマトも全部収穫します。","細いひもで棒をすぐ結びます。","畑全体に水をまきます。"]', 0, 'Chưa thu cà chua; cần sửa cọc nhưng đất cứng nên người nam tưới quanh gốc cọc trước. Người nữ cắt dây mới và cất thùng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-014-Q1', 'N3-L-TASK-014', 1, '女の人はアルバイトの変更についてこの後まず何をしますか。', '["勤務表に田中さんの名前を書きます。","山田さんに金曜日の代わりを頼めるか聞きます。","土曜日に働くことを先に決めます。","試験を休むと大学へ連絡します。"]', 1, 'Tanaka đi du lịch, lịch chưa được sửa và quản lý sẽ sửa sau. Người nữ phải hỏi Yamada có thay ca thứ sáu được không trước.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-015-Q1', 'N3-L-TASK-015', 1, '男の人は地域の訓練でこの後まず何をしますか。', '["三軒すべてに電話をかけます。","受付の机をそうこに運びます。","机の上の参加者名簿をかばんにしまいます。","入口にある受付の看板を外します。"]', 2, 'Người nữ gọi hộ còn lại; bàn vẫn dùng phát đồ uống, biển chưa tháo. Việc đầu tiên của người nam là cất danh sách vào cặp để không lộ tên.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-016-Q1', 'N3-L-TASK-016', 1, '女の人は借りた会議室を使うためにこの後まず何をしますか。', '["廊下に参加者用の資料を並べます。","全員に開始が遅れると連絡します。","空いている二階の部屋に直接入ります。","受付で別の部屋に変更できるか確認します。"]', 3, 'Chưa quyết định hoãn. Người nữ phải hỏi quầy có đổi sang phòng khác đủ chỗ không; người nam trao đổi nhóm trước rồi hướng dẫn khách.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-017-Q1', 'N3-L-TASK-017', 1, '男の人は水泳大会の係としてこの後まず何をしますか。', '["番号の紙の名前を最新の名簿と合わせて確認します。","選手全員をプールの入口へ呼びます。","欠席者を除いて番号を付け直します。","競技の説明をせずに番号を配ります。"]', 0, 'Phải đối chiếu tên trên giấy với danh sách hôm nay trước khi tách phần người vắng. Người nữ hướng dẫn vị trí chờ; số không được đánh lại và còn giải thích trước khi phát.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-018-Q1', 'N3-L-TASK-018', 1, '女の人は研究発表の準備でこの後まず何をしますか。', '["調査した人数を九十八人に書きかえます。","使わなかった回答について説明を書き加えます。","今のグラフをすぐ印刷して配ります。","自分で発表時間をはかり始めます。"]', 1, 'Đã khảo sát 100 người nhưng chỉ dùng 98 câu trả lời. Cần bổ sung giải thích việc loại hai câu trống, không đổi số người được hỏi; in sau khi sửa và đọc thử.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-019-Q1', 'N3-L-TASK-019', 1, '男の人は落ち葉を集める作業でこの後まず何をしますか。', '["落ち葉を燃えるごみとして門へ運びます。","枝だけを先に集めます。","落ち葉の中にある空き缶を取り除きます。","ぬれた箱に落ち葉をまとめます。"]', 2, 'Lá giữ làm vật liệu cho ruộng, không bỏ rác. Người nam tách lon trước, người nữ gom cành và mượn xe; hộp ướt không dùng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-020-Q1', 'N3-L-TASK-020', 1, '女の人は新商品の紹介についてこの後まず何をしますか。', '["袋の文字が見える写真を自分で撮ります。","今の文章をすぐ店のページにのせます。","値段を変えずに難しい漢字だけ説明します。","現在の価格と変更時期が伝わるように文章を直します。"]', 3, 'Ưu tiên sửa về giá hiện tại và thời điểm đổi giá. Người nam chụp lại ảnh; giải thích từ và đăng bài đều làm sau.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-021-Q1', 'N3-L-TASK-021', 1, '男の人はホテルの研修でこの後まず何をしますか。', '["忘れ物が見つかった部屋と場所を記録します。","時計を持ってすぐ受付へ行きます。","客室のシーツを新しい物にかえます。","時計の持ち主に電話します。"]', 0, 'Hôm nay đổi thứ tự sang tập xử lý đồ thất lạc. Trước khi đóng túi hay mang đến quầy, người nam phải ghi số phòng và vị trí tìm thấy; đây là đồ tập nên không gọi khách.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-022-Q1', 'N3-L-TASK-022', 1, '女の人は犬をかってくれる人を探す活動でこの後まず何をしますか。', '["以前の紙を使って薬の説明を書きます。","担当者に現在の世話の方法を確認します。","写真の大きさを自分で直します。","名前と年齢だけの案内をすぐ配ります。"]', 1, 'Thuốc đã đổi nên không dùng giấy cũ. Người nữ phải hỏi người chăm sóc về nhu cầu hiện tại trước khi soạn và phát; người nam chỉnh ảnh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-023-Q1', 'N3-L-TASK-023', 1, '男の人はキャンプ場でこの後まず何をしますか。', '["小さい荷物から高い場所へ運びます。","川のそばの木の下にテントを張ります。","管理の人に場所の変更が可能かたずねます。","車内の荷物を整理します。"]', 2, 'Muốn tránh sông nhưng vị trí mới khác khu đặt nên phải xin quản lý trước. Người nam đi hỏi, người nữ xếp trong xe; chỉ chuyển đồ và dựng lều sau khi được phép.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-024-Q1', 'N3-L-TASK-024', 1, '女の人はオンライン講座の前にこの後まず何をしますか。', '["元の資料から問題の説明を全部削除します。","答え入りの資料を先に参加者へ送ります。","講座の音声テストを一人で始めます。","資料を別のファイルにも保存して、参加者向けのほうから答えを消します。"]', 3, 'Cần giữ bản giảng viên, tạo bản riêng cho học viên và chỉ bỏ đáp án, không bỏ giải thích giải bài. Người nam kiểm tra người nhận; thử âm thanh làm sau khi gửi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-025-Q1', 'N3-L-TASK-025', 1, '男の人は古本市の準備でこの後まず何をしますか。', '["中に答えが書かれた本を選び出します。","すべての本に百円のシールを貼ります。","本に書かれた名前を自分で消します。","売れない本を紙の回収に出します。"]', 0, 'Người nam phải kiểm tra và tách sách có ghi đáp án trước; người nữ xóa tên. Sách không bán sẽ tặng, không vứt. Dán giá và vận chuyển làm sau.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-026-Q1', 'N3-L-TASK-026', 1, '女の人は電話で受けた注文についてこの後まず何をしますか。', '["以前の住所を使って配達時間を約束します。","注文した客に届け先のくわしい住所を確かめます。","赤い花を選んで包み始めます。","運転手と直接配達の順番を調整します。"]', 1, 'Địa chỉ nghe chưa rõ, không được tự lấy địa chỉ cũ. Người nữ cần gọi xác nhận địa chỉ chi tiết; người nam chọn hoa và điều phối giao.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-027-Q1', 'N3-L-TASK-027', 1, '男の人は博物館の案内係としてこの後まず何をしますか。', '["庭で二十人の団体を待ちます。","日本語の案内を自分で取りに行きます。","集合場所を休憩室に変えて案内板に示します。","英語の紙を全員に配って作品の部屋へ進みます。"]', 2, 'Điểm tập trung cuối cùng là phòng nghỉ do mưa. Người nam sửa bảng và chỉ đường trước; người nữ chuẩn bị giấy và chưa phát tiếng Anh cho tất cả.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-028-Q1', 'N3-L-TASK-028', 1, '女の人は会員へのお知らせについてこの後まず何をしますか。', '["退会者のアドレスを一から調べ直します。","月曜日の変更だけをすぐ全員に送ります。","受付用の紙のお知らせを印刷します。","先生の連絡を確認して木曜日の時刻を追記します。"]', 3, 'Danh sách địa chỉ đã được kiểm tra. Người nữ cần đối chiếu thư giáo viên và thêm giờ thứ năm trước; người nam kiểm bản và in, gửi thư chỉ sau xác nhận.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-029-Q1', 'N3-L-TASK-029', 1, '男の人は公園のベンチを直す作業でこの後まず何をしますか。', '["置き忘れられたかばんを受付に持っていきます。","壊れた板を道具で外し始めます。","そうこへロープを借りに行きます。","かばんを開けて持ち主を調べます。"]', 0, 'Trước sửa phải quây khu vực, nhưng trước cả việc quây cần mang cặp bỏ quên tới quầy, không mở. Dây có sẵn; người nữ kiểm ván trong khi người nam đi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-TASK-030-Q1', 'N3-L-TASK-030', 1, '女の人は旅行の写真集を作るためにこの後まず何をしますか。', '["旅行中に撮った写真を全部相手に送ります。","使いたい写真を付けて写っている人に許可を求めます。","返事を待たずに写真集を注文します。","写真集の大きさと料金を調べます。"]', 1, 'Việc đầu tiên là gửi riêng ảnh định dùng để xin phép người trong ảnh. Người nam tra giá và cỡ; chưa được đặt trước khi có phản hồi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-001-Q1', 'N3-L-POINT-001', 1, '女の人はどうして説明の方法を変えようとしていますか。', '["参加者が遠慮せず疑問を確かめられるようにするためです。","資料を印刷する時間と費用を減らすためです。","掃除を去年より早い時刻に始めるためです。","少ない道具をグループで順番に使うためです。"]', 0, 'Chia nhóm nhằm giúp người tham gia dễ hỏi, không mang thắc mắc vào công việc. Tài liệu, dụng cụ, nơi phụ trách giữ nguyên; không nhằm bắt đầu sớm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-002-Q1', 'N3-L-POINT-002', 1, '女の人が店の順番の決め方で最も大切にしていることは何ですか。', '["一人の客を案内する時間をできるだけ短くすることです。","どの客にも同じ基準が使われていると分かることです。","修理を頼む客を買い物の客より先にすることです。","声を出さずに少人数で案内できることです。"]', 1, 'Cô ấy ưu tiên sự công bằng và minh bạch của cùng một quy tắc. Không ưu tiên khách mua ít, giảm nhân viên hay chỉ thông báo bằng màn hình.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-003-Q1', 'N3-L-POINT-003', 1, '女の人はどうしてアンケートに名前を書くところをなくしましたか。', '["結果を入力する仕事を少なくするためです。","質問の数を減らして早く答えてもらうためです。","働く人が心配せず実際の問題を書けるようにするためです。","一人から何枚でも意見を出してもらうためです。"]', 2, 'Bỏ tên để nhân viên an tâm phản ánh vấn đề thật, dù mất khả năng hỏi lại. Câu hỏi không giảm và mỗi người chỉ nhận một phiếu.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-004-Q1', 'N3-L-POINT-004', 1, '女の人はどうして庭の当番を二人ずつにしましたか。', '["増えた草を短い時間で取り除くためです。","朝以外の時間にも水をやってもらうためです。","二人が毎回同じ時間に作業するためです。","都合が悪い時に当番同士で助け合えるようにするためです。"]', 3, 'Cặp trực giúp hỗ trợ và thay nhau khi bận. Khối lượng không đổi, vẫn làm buổi sáng, không yêu cầu đến cùng lúc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-005-Q1', 'N3-L-POINT-005', 1, '女の人は研修でどのような話をしてほしいと言っていますか。', '["周りに助けを求めて問題を乗り越えた経験です。","一人だけの力で大きな契約を取った経験です。","会社で起こった失敗をできるだけ多く集めた話です。","仕事で使う道具の詳しい操作方法です。"]', 0, 'Điểm chính là kinh nghiệm nhờ người khác rồi cải thiện tình hình, giúp người mới biết cần hỏi sớm. Không phải kể thành tích cá nhân hay hướng dẫn dụng cụ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-006-Q1', 'N3-L-POINT-006', 1, '女の人はどうして演奏会の席を変えましたか。', '["食事に使うお金を残しておきたいからです。","それぞれの楽器が合わさった音を楽しみたいからです。","演奏する人の手の動きを近くで見たいからです。","終了後に出口へ早く移動したいからです。"]', 1, 'Cô ấy ưu tiên nghe tổng thể các nhạc cụ hòa vào nhau. Giá không đổi, không vội ra và không chọn vì nhìn động tác gần.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-007-Q1', 'N3-L-POINT-007', 1, '女の人はバスの調査で何を特に知りたいですか。', '["車内で最も人気がある座席の場所です。","午後の便を減らすと節約できる金額です。","利用したくても現在の運行では使えない事情です。","すべての住民が毎月買い物に使う費用です。"]', 2, 'Cô ấy muốn tìm lý do người có nhu cầu vẫn không dùng được tuyến hiện tại, như có chuyến đi mà không có chuyến về; không chỉ đếm khách để cắt chuyến.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-008-Q1', 'N3-L-POINT-008', 1, '女の人はどうして祖父の話を録音することにしましたか。', '["メモを取らずにすぐ本を完成させるためです。","祖父に長い時間続けて話してもらうためです。","録音した話を選ばず全部公開するためです。","文章だけでは伝わらない話し手の個性を残すためです。"]', 3, 'Cô ấy muốn giữ cá tính qua giọng, nhịp ngừng và tiếng cười, những điều chữ viết không thể hiện. Không ưu tiên nhanh, không nói dài hay công khai toàn bộ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-009-Q1', 'N3-L-POINT-009', 1, '女の人はどうして子供の大会で順位をつけないことにしましたか。', '["賞を取る形に合わせず、自分の考えを試してほしいからです。","賞品に使う費用をなくしたいからです。","参加者が多くて作品を比べる時間がないからです。","上手な子供だけが作品を説明できるようにするためです。"]', 0, 'Cô ấy muốn trẻ thử ý tưởng riêng thay vì bắt chước tác phẩm từng đạt giải. Chi phí gần như cũ và mọi trẻ đều được giải thích sáng kiến.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-010-Q1', 'N3-L-POINT-010', 1, '女の人はどうして山歩きのグループを二つに分けましたか。', '["全員が一台のバスに乗れなくなったからです。","参加者が自分に合った速さで景色を楽しめるようにするためです。","経験の少ない人に短い道を歩かせるためです。","道を案内する係の人数を減らすためです。"]', 1, 'Chia nhóm để mỗi người chọn nhịp phù hợp và thưởng thức cảnh mà không cố chạy theo người khác. Cùng quãng đường, một xe và nhóm nào cũng có hướng dẫn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-011-Q1', 'N3-L-POINT-011', 1, '女の人は町の新聞のどこを変えるつもりですか。', '["写真を小さくして、すべての記事を今より長くします。","ページを増やして、紙だけで詳しい情報を伝えます。","紙では要点を大きな文字で示し、くわしいことは別の方法でも伝えます。","紙の新聞をやめて、すべての情報をネットに移します。"]', 2, 'Kế hoạch mới là bài ngắn, chữ lớn trên giấy; chi tiết qua web hoặc điện thoại. Ảnh không đổi và báo giấy vẫn tồn tại.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-012-Q1', 'N3-L-POINT-012', 1, '女の人はどうして事務所を駅前へ移さなかったのですか。', '["駅前の建物の家賃が予想より高かったからです。","社員全員が今の場所への通勤を希望したからです。","古い事務所の設備に全く問題がなかったからです。","近所の客が気軽に来られる関係を続けたかったからです。"]', 3, 'Cô ấy ưu tiên quan hệ với khách địa phương dễ ghé thăm. Chỗ mới rẻ và tiện hơn, nơi cũ vẫn cần sửa và có điều chỉnh giờ cho nhân viên.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-013-Q1', 'N3-L-POINT-013', 1, '女の人はどうして道具を貸す前に一緒に使ってみる時間を作りましたか。', '["借りる人が使い方を実際に確かめ、後のトラブルを避けるためです。","道具を壊した時に払う金額をその場で決めるためです。","説明書を渡さずに済ませるためです。","毎週の教室に参加する人を増やすためです。"]', 0, 'Dùng thử giúp tự xác nhận cách dùng và tránh rắc rối sau khi mang về. Vẫn có hướng dẫn giấy, không phải lớp hằng tuần hay tính phí hỏng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-014-Q1', 'N3-L-POINT-014', 1, '女の人はどうして見学の後に自由時間を入れましたか。', '["案内する人の説明時間を減らすためです。","説明を聞いた後、自分の関心に合わせて確かめられるようにするためです。","新しい店で必ず買い物をしてもらうためです。","帰りのバスの出発を遅くするためです。"]', 1, 'Giờ tự do để người tham quan nghĩ lại và hỏi/tìm hiểu điều riêng mình quan tâm. Không rút hướng dẫn hay bắt mua quà; giờ xe không đổi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-015-Q1', 'N3-L-POINT-015', 1, '女の人はどうして商品の箱を同じ大きさにしなかったのですか。', '["注文する箱の種類をできるだけ減らすためです。","すべての商品を最も安い送料で送るためです。","受け取った人が処分する不要な物を少なくするためです。","割れやすい物も袋だけで送るためです。"]', 2, 'Cô ấy ưu tiên giảm rác và gánh dọn dẹp cho người nhận, đồng thời vẫn bảo vệ hàng. Không nhằm tiện cho bên gửi hay luôn rẻ nhất.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-016-Q1', 'N3-L-POINT-016', 1, '女の人は翻訳のチームで何を先に決めたいですか。', '["全員が同じ長さの文章を書くことです。","最後に一人だけで全ページを訳すことです。","好きなページを早い者から選ぶことです。","同じ対象に使う名前をチームでそろえることです。"]', 3, 'Cần thống nhất thuật ngữ gọi cùng đối tượng trước khi phân công. Không bắt mọi câu giống độ dài, không giao một người dịch hết hay chọn trang tùy ý.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-017-Q1', 'N3-L-POINT-017', 1, '女の人はどうして忘れ物の写真を全部公開しないのですか。', '["持ち主だけが知る情報で本人かどうか確かめるためです。","駅員が問い合わせに答える仕事をなくすためです。","中身を見なくてもすべての財布を区別できるからです。","忘れ物の数をできるだけ早く減らすためです。"]', 0, 'Giữ lại chi tiết chưa công khai giúp kiểm tra người nhận thật sự là chủ. Không phải bỏ việc xác minh hay ưu tiên trả thật nhanh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-018-Q1', 'N3-L-POINT-018', 1, '女の人はどうして会場で食べ物を配る方法を変えましたか。', '["すべての人に同じ料理を同じ量だけ渡すためです。","参加者が自分に合う料理を組み合わせられるようにするためです。","料理の種類を増やして参加費を上げるためです。","料理を準備する手間を少なくするためです。"]', 1, 'Mục đích là cho từng người chọn món phù hợp; lượng tham khảo và nguyên liệu vẫn được ghi. Không tăng phí, số món hay giảm công chuẩn bị.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-019-Q1', 'N3-L-POINT-019', 1, '男の人はどうして練習の動画を短く分けましたか。', '["携帯で送るための時間を短くするためです。","成功した場面だけを見せて楽しんでもらうためです。","動きを比べながら、次に直す点を絞って考えてもらうためです。","動画を見る時間をすべて実際の練習に使うためです。"]', 2, 'Đoạn ngắn đối chiếu cùng động tác tốt/chưa tốt giúp chọn một điểm sửa. Không do gửi chậm, chỉ khoe thành công hay đổi toàn bộ giờ xem sang tập.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-020-Q1', 'N3-L-POINT-020', 1, '男の人はどうしてオンライン授業でカメラを必ずつけなくてもよいことにしましたか。', '["古いパソコンを使う学生だけを集めるためです。","学生が授業中に好きなことをできるようにするためです。","教師が学生の理解を確認する必要をなくすためです。","学習以外の不安で参加をやめる人を減らすためです。"]', 3, 'Cho tắt camera để lo riêng tư không ngăn người học tham dự. Vẫn kiểm tra tham gia và hiểu bài qua hoạt động; kỹ thuật chỉ là một yếu tố phụ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-021-Q1', 'N3-L-POINT-021', 1, '男の人はどうして店を開く前に一か月だけ試してもらうのですか。', '["実際の客の反応を知り、続け方を自分で考えてもらうためです。","売り上げが一番高い人を選ぶためです。","町がお金をかけずに店を修理してもらうためです。","試す人全員に長期の契約を約束してもらうためです。"]', 0, 'Thử bán để biết phản ứng khách, tự cân nhắc tiếp tục hay đổi hàng trước khi thuê dài. Không thi doanh thu hay bắt cam kết dài hạn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-022-Q1', 'N3-L-POINT-022', 1, '男の人はどうして商品の作り方を店で紹介していますか。', '["有名な職人の商品だと宣伝するためです。","手間や品質を知った上で価格を考えてもらうためです。","客にかばん作りの教室へ申し込んでもらうためです。","注文した客に必ず長く待ってもらうためです。"]', 1, 'Giới thiệu quy trình để khách hiểu công sức và chất lượng đằng sau mức giá. Không quảng bá người nổi tiếng, mở lớp hay chủ yếu giải thích giao hàng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-023-Q1', 'N3-L-POINT-023', 1, '男の人はどうして古い写真に正確な年を書かないのですか。', '["年を調べる作業を最初から省くためです。","見る人に町の変化を自由に想像させないためです。","分かっていないことを確かな情報として伝えないためです。","最も多かった意見を正しい答えにするためです。"]', 2, 'Anh không muốn biến điều chưa chắc thành thông tin xác định. Đã nghiên cứu, vẫn cho mốc thời gian và sẽ cập nhật khi có bằng chứng mới.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-024-Q1', 'N3-L-POINT-024', 1, '男の人はどうして服を受け取る人に自分で選んでもらいますか。', '["手伝う人の数を少なくして早く終えるためです。","一人が好きなだけ服を持ち帰れるようにするためです。","人気の色の服だけを先に配るためです。","受け取る人自身の好みや選ぶ権利を大切にするためです。"]', 3, 'Anh tôn trọng sở thích và quyền lựa chọn của người nhận. Vẫn giới hạn số món, chia đợt; chấp nhận thêm công và chỗ thử.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-025-Q1', 'N3-L-POINT-025', 1, '男の人はどうして仕事の予定を時間ではなく作業ごとに書くことにしましたか。', '["次の担当者へ仕事をつなぐために必要な結果を明確にするためです。","作業の締め切りをすべてなくすためです。","社員が働いた時間の長さだけで評価するためです。","仕事が一番遅い人をすぐ見つけるためです。"]', 0, 'Bảng nhằm làm rõ đầu ra và người nhận tiếp để công việc nhóm tiến triển. Vẫn có hạn, không dùng để đo giờ hay xếp ai nhanh chậm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-026-Q1', 'N3-L-POINT-026', 1, '男の人はどうして音についての案内を書き直しましたか。', '["守らない住民への新しい罰を知らせるためです。","どんな行動に気をつければよいか具体的に分かるようにするためです。","昼間は自由に音を出してよいと伝えるためです。","苦情を出した人の名前を明らかにするためです。"]', 1, 'Thông báo cụ thể hóa hành vi và cách âm truyền sang phòng khác. Không thêm phạt hay cho phép ồn ban ngày, không công khai người than phiền.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-027-Q1', 'N3-L-POINT-027', 1, '男の人はどうして作品に触れる触ってもよい見本を用意しましたか。', '["大人が見学する間に子供だけを遊ばせるためです。","本物の作品に自由に触ってもらうためです。","見る以外の方法で作品の形や特徴を理解してもらうためです。","説明をすべてなくして触ってもよい見本だけを置くためです。"]', 2, 'Mô hình bổ sung cách tiếp nhận bằng xúc giác để hiểu hình và đặc điểm, cho nhiều đối tượng. Không phải chỗ giữ trẻ, không cho sờ đồ thật hay bỏ giải thích.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-028-Q1', 'N3-L-POINT-028', 1, '男の人はどうしてイベントの感想を一週間後にも聞くのですか。', '["当日休んだ人だけに同じ説明を送るためです。","覚えている知識を点数で比べるためです。","イベントが楽しかったという意見だけを集めるためです。","参加後の生活で実際の行動につながったか確かめるためです。"]', 3, 'Khảo sát sau một tuần nhằm xem nội dung có chuyển thành hành động trong đời sống và vì sao chưa hành động. Không thi kiến thức hay chỉ hỏi vui không.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-029-Q1', 'N3-L-POINT-029', 1, '男の人はどうして話し合いの前に意見を書いてもらいますか。', '["他の人に影響される前に一人ずつ考えを整理するためです。","会議の後に記録を作る必要をなくすためです。","誰の意見か最後まで分からなくするためです。","一度書いた意見を途中で変えさせないためです。"]', 0, 'Viết trước tạo không gian tự suy nghĩ trước ảnh hưởng từ người nói nhanh. Vẫn ghi tên, có giải thích và cho phép thay đổi ý sau thảo luận.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-POINT-030-Q1', 'N3-L-POINT-030', 1, '男の人はどうして店の歴史を一人の話だけでまとめないのですか。', '["最も人数の多い意見を歴史の事実にするためです。","店に関わった人たちの異なる見方も伝えるためです。","店主の話だけを短く読みやすくするためです。","資料を調べずに年や値段を決めるためです。"]', 1, 'Anh muốn giữ nhiều góc nhìn của chủ, nhân viên và khách. Số liệu vẫn kiểm bằng tài liệu; không coi đa số là sự thật hay ép mọi cảm nhận theo chủ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-001-Q1', 'N3-L-SUMMARY-001', 1, '日本語の勉強について、この人が最も伝えたいことは何ですか。', '["短い時間でも毎日学ぶことが役に立つ。","電車の時間を使って言葉を覚える工夫。","朝と夜で勉強する内容を分ける工夫。","週末に机に向かって頑張った経験。"]', 0, 'Trọng tâm là thay học dồn bằng học ít nhưng đều; tàu và giờ ngủ chỉ là thời điểm thực hiện.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-002-Q1', 'N3-L-SUMMARY-002', 1, '引っ越した町について、この人は主に何を話していますか。', '["パン屋で教えてもらった町のお祭り。","近所の店での交流が町になじむ助けになったこと。","スーパーと小さな店の値段の違い。","雨を避けるために入った店の様子。"]', 1, 'Các cửa hàng tạo cơ hội kết nối với người và nơi sống mới; mưa, giá và lễ hội là chi tiết phụ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-003-Q1', 'N3-L-SUMMARY-003', 1, '料理教室での経験から、この人は何が大切だと思いましたか。', '["魚を柔らかく作るための火の使い方。","隣の人から先生に質問するよう勧められたこと。","うまくいかなかった経験も人に話すこと。","先生と同じ料理を作るための準備。"]', 2, 'Kinh nghiệm thất bại được chia sẻ trở thành bài học chung; kỹ thuật lửa chỉ là ví dụ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-004-Q1', 'N3-L-SUMMARY-004', 1, '図書館の人は、この集まりをどのような場にしたいですか。', '["子どものころに読んだ本を思い出す場。","料理の本の使い方を細かく説明する場。","上手に本を紹介する練習をする場。","人の話を通して読書の楽しみを広げる場。"]', 3, 'Mục đích là khám phá sách và niềm vui đọc qua giao lưu, không thi đua hay tuyển người giỏi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-005-Q1', 'N3-L-SUMMARY-005', 1, 'この人が会議について一番言いたいことは何ですか。', '["前もってする準備を工夫すると話し合いの時間を生かせる。","資料を前の日に送るための方法。","静かな人が意見を出したときの様子。","会議で一時間を過ごすことの大変さ。"]', 0, 'Lời kết nhấn mạnh chuẩn bị trước để thời gian họp hiệu quả, không cắt bớt ý kiến hay áp thời hạn máy móc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-006-Q1', 'N3-L-SUMMARY-006', 1, '家族旅行を終えて、この人はどんなことを感じていますか。', '["川の近くで食べる昼ご飯は楽しい。","予定を詰めすぎず、その場の楽しみも大事にしたい。","旅行の前には行きたい場所を調べたい。","子どもは石を拾うことが好きだ。"]', 1, 'Trải nghiệm bên sông cho thấy cần lịch linh hoạt có khoảng trống, không phải bỏ kế hoạch hoàn toàn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-007-Q1', 'N3-L-SUMMARY-007', 1, '公園での活動について、この人が主に伝えていることは何ですか。', '["朝の活動には友だちと参加すると行きやすい。","公園の木の下にはごみが集まりやすい。","実際に参加すると身近な環境への意識が変わる。","活動が終わった後の散歩は気持ちがよい。"]', 2, 'Trọng tâm là thay đổi nhận thức và thói quen nhờ trực tiếp tham gia; dậy sớm và bạn rủ là bối cảnh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-008-Q1', 'N3-L-SUMMARY-008', 1, '母親にスマホを教えた経験から、この人は何を伝えたいですか。', '["家族の写真をスマホで見る楽しさ。","便利な機能を一度に覚える難しさ。","写真に短い返事を送る方法。","相手の関心に合うことから教えると学びやすい。"]', 3, 'Chọn việc mẹ quan tâm là xem ảnh cháu giúp mẹ học; bài không cho rằng tuổi tác ngăn học.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-009-Q1', 'N3-L-SUMMARY-009', 1, '食堂の人は、メニューについてどんな考えを話していますか。', '["種類を絞る工夫で質を守りながら無駄も減らしたい。","季節の野菜で作る料理を紹介したい。","昼休みに早く食べたい客を集めたい。","週ごとに料理を変える楽しさを話したい。"]', 0, 'Giới hạn có chủ ý giúp chất lượng, ít lãng phí và phục vụ nhanh; không giảm phần ăn hay cố định món mãi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-010-Q1', 'N3-L-SUMMARY-010', 1, '発表の経験について、この人が一番言いたいことは何ですか。', '["発表の前に紙に順番を書く方法。","覚えたとおりに言うことより、伝える内容と相手を大事にする。","人前で緊張したときの体の様子。","先生に相談するきっかけになった失敗。"]', 1, 'Bài đối chiếu học thuộc máy móc với truyền đạt ý rõ cho người nghe; luyện trình tự là biện pháp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-011-Q1', 'N3-L-SUMMARY-011', 1, '運動を続けることについて、この人の考えはどれですか。', '["友だちと運動の話をすることが楽しい。","足が痛い日は外へ出るのが難しい。","自分に合う無理のない始め方が続ける力になる。","歩くことと走ることでは距離が違う。"]', 2, 'Chọn bước đầu vừa sức mới duy trì được, trái với cố đạt cự ly lớn và so với người khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-012-Q1', 'N3-L-SUMMARY-012', 1, '作品作りを通して、この人は協力について何を学びましたか。', '["作品に使う材料を集める方法。","絵が苦手な人が作業で感じた困りごと。","四人で絵を描いたときにかかった時間。","得意なことを生かして役割を分けるとよい。"]', 3, 'Bài nhấn mạnh phát huy điểm mạnh và phân vai linh hoạt giúp cả nhóm, không đồng nhất công bằng với giống nhau.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-013-Q1', 'N3-L-SUMMARY-013', 1, '写真の話を通して、この人が伝えたいことは何ですか。', '["見方を変えれば身近な場所にも発見がある。","朝と夕方では建物の色が違って見える。","雨の後の道は空を映すことがある。","有名な場所には写真を撮る人が集まる。"]', 0, 'Thời điểm và mưa minh họa góc nhìn mới về chỗ quen; không phải quy định thời gian hay nơi chụp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-014-Q1', 'N3-L-SUMMARY-014', 1, '仕事で質問するとき、この人は何を大切にしていますか。', '["同じ質問を何度もしてしまった経験。","分かった点と疑問を整理してから助けを求める。","先輩が質問にいつも答えてくれること。","説明を短く書くための紙の使い方。"]', 1, 'Chuẩn bị câu hỏi giúp hỗ trợ hiệu quả, không yêu cầu tự giải quyết mọi thứ hay ỷ lại hoàn toàn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-015-Q1', 'N3-L-SUMMARY-015', 1, 'スポーツセンターは、体験の日について何を強調していますか。', '["音楽に合わせて体を動かす時間がある。","会場では柔らかいボールを用意する。","運動に自信がない人も無理なく楽しめる。","参加するときは動きやすい服を着る。"]', 2, 'Thông báo nhấn mạnh hoạt động dễ tiếp cận và không cạnh tranh, không phải huấn luyện bắt buộc.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-016-Q1', 'N3-L-SUMMARY-016', 1, '帰宅後の過ごし方について、この人が伝えたいことは何ですか。', '["机に紙と鉛筆を用意しておく便利さ。","夜遅くまでテレビを見ていた経験。","疲れたときに絵を描くと気分が変わること。","したいことを先に少し始めると時間を生かせる。"]', 3, 'Thay đổi thứ tự bắt đầu giúp có thời gian cho sở thích, không cần chờ lịch trống hoặc cấm tivi.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-017-Q1', 'N3-L-SUMMARY-017', 1, '贈り物について、この人の考えはどう変わりましたか。', '["値段より相手とのつながりを表すことを大事にしたい。","写真を小さな本にまとめる方法を知った。","去年の友だちの誕生日を思い出した。","写真の横に短い文を書く楽しさを知った。"]', 0, 'Quyển ảnh cho thấy ý nghĩa quan hệ và sự quan tâm quan trọng hơn giá tiền.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-018-Q1', 'N3-L-SUMMARY-018', 1, '食堂の取り組みについて、この人が一番伝えたいことは何ですか。', '["運動した後はご飯を多く食べたくなる。","一人一人が量を選べると食べ残しを減らしやすい。","食堂では三つの量から注文できる。","体調によって食べられる量が変わる。"]', 1, 'Điều chỉnh cơ chế lựa chọn phù hợp cá nhân giúp giảm thừa, không chỉ nhắc nhở hay ép chung khẩu phần.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-019-Q1', 'N3-L-SUMMARY-019', 1, '演奏会の案内作りから、この人は何を学びましたか。', '["駅の出口と曲がる角を紙に加えたこと。","案内を作るときに会場を確認したこと。","受け取る人の知識に合わせて情報を確かめること。","演奏会の前に問い合わせが来たこと。"]', 2, 'Cần nhìn bằng mắt người mới để bổ sung đúng thông tin thiếu, không chỉ thêm thật nhiều.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-020-Q1', 'N3-L-SUMMARY-020', 1, '服の買い方について、この人は主に何を話していますか。', '["部屋を片づけると忘れた服が出てくること。","店で好きな色の服を見つける楽しさ。","毎朝着る服を早く選べるようになったこと。","持っている物をよく知ると役立つ買い物ができる。"]', 3, 'Trọng tâm là hiểu đồ sẵn có để chọn thứ dùng được, không phủ nhận mọi mua sắm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-021-Q1', 'N3-L-SUMMARY-021', 1, '町の写真と説明を見て、この人が気づいたことは何ですか。', '["普通の人の思い出からも地域の歴史を理解できる。","昔と今で建物の形が違うこと。","祖父に家族の思い出を聞く楽しさ。","古い写真の横に短い話が書いてあったこと。"]', 0, 'Lời kể đời thường giúp hiểu cảm xúc và lịch sử nơi sống; không chỉ sự kiện nổi tiếng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-022-Q1', 'N3-L-SUMMARY-022', 1, '会話の練習について、この人の考えに合うものはどれですか。', '["週に一度友だちと外国語を話している。","話を続けることと後で直すことを組み合わせたい。","練習の後に短いメモを残している。","話を止められると内容を忘れることがある。"]', 1, 'Bài cân bằng sự trôi chảy và sửa lỗi có chọn lọc, không loại bỏ việc học chính xác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-023-Q1', 'N3-L-SUMMARY-023', 1, '昼休みについて、この人が一番伝えたいことは何ですか。', '["同僚に外を歩こうと誘われた経験。","昼休みにパンを食べていたこと。","短くても仕事から離れる休みがその後に役立つ。","歩けない日は窓のそばでお茶を飲むこと。"]', 2, 'Cần tách thực sự khỏi việc để đổi trạng thái, không phải chỉ thay chỗ tiếp tục làm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-024-Q1', 'N3-L-SUMMARY-024', 1, 'この人は、子どもの本を作るうえで何を大切にしたいですか。', '["動物の絵を子どもに見てもらうこと。","子どもが出した質問を集めて読むこと。","大人が大事だと思う文章を選ぶこと。","答えを伝えるだけでなく子どもの好奇心を引き出す。"]', 3, 'Mục tiêu là khơi gợi mong muốn tìm hiểu, không đơn thuần truyền hết đáp án.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-025-Q1', 'N3-L-SUMMARY-025', 1, '雨の日の話で、この人が伝えたいことは何ですか。', '["状況に合う楽しみを探すと気持ちを変えられる。","雨の公園では葉の色がきれいに見える。","雨の日は家でお茶を飲んで本を読める。","天気予報を見て外出を決めている。"]', 0, 'Mưa minh họa thích ứng hoàn cảnh để tìm niềm vui; không cổ vũ bất chấp thời tiết nguy hiểm.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-026-Q1', 'N3-L-SUMMARY-026', 1, '接客の経験から、この人は何が重要だと考えていますか。', '["商品の使い方を説明するときに失敗したこと。","速さだけでなく確かめた情報を正しく伝えること。","間違った説明をした後で謝ったこと。","待ってもらう理由をお客さんに話すこと。"]', 1, 'Đoạn nhấn mạnh kiểm chứng và trung thực để tạo tin cậy, không tốc độ trả lời bằng mọi giá.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-027-Q1', 'N3-L-SUMMARY-027', 1, '道具を持ち寄る会について、この人が伝えたいことは何ですか。', '["一人で暮らすと大きな鍋を使う機会が少ない。","会場でお金を使わず物を受け取れる。","使わない物を人につなぐと新たな役割が生まれる。","もらった物について前に使っていた人と話せる。"]', 2, 'Trọng tâm là tái sử dụng bằng kết nối đúng người, không tích trữ hay chỉ tìm lợi về giá.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-028-Q1', 'N3-L-SUMMARY-028', 1, '新人に教えた経験から、この人は何を学びましたか。', '["道具の場所を知らない人がいたこと。","相手が何度もうなずいていたこと。","自分が覚えた順番で仕事を説明したこと。","相手の理解を確かめながら教え方を調整すること。"]', 3, 'Cần xác nhận hiểu thực tế và điều chỉnh, không đồng nhất gật đầu với thành thạo.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-029-Q1', 'N3-L-SUMMARY-029', 1, '手帳に記録することについて、この人が最も伝えたいことは何ですか。', '["小さな成功を認めるとまた頑張ろうと思える。","月末に手帳を開く習慣を作った。","苦手な料理を一度作ることができた。","久しぶりの友だちに連絡する楽しさを知った。"]', 0, 'Những ghi nhận nhỏ giúp thấy tiến bộ và muốn tiếp tục; không phải kiểm điểm thiếu sót hay chạy theo thành tích lớn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-SUMMARY-030-Q1', 'N3-L-SUMMARY-030', 1, 'バスの意見交換会で、この人が大切だと感じたことは何ですか。', '["子ども連れの人が屋根を望んでいること。","いろいろな利用者の声を聞いて改善を考えること。","学生が学校の時間に合うバスを必要としていること。","足の悪い人が停留所までの道を心配していること。"]', 1, 'Nhiều trải nghiệm giúp thấy nhu cầu đa dạng; tăng chuyến chỉ là một phần, không phải lời giải duy nhất.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-001-Q1', 'N3-L-UTTERANCE-001', 1, '相手の会社の担当者に、そのページをメールで送ってもらいたいとき、何と言いますか。', '["足りないページをお送りいただけますか。","足りないページをお送りいたしましょうか。","足りないページをご覧になりました。"]', 0, 'Nhờ đối tác thực hiện nên dùng お送りいただけますか. いたしましょうか là người nói đề nghị tự gửi; câu còn lại chỉ thuật lại việc xem.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-002-Q1', 'N3-L-UTTERANCE-002', 1, '部屋の場所を知らないお客様に、ついて来てもらうとき何と言いますか。', '["会議室からお帰りになりますか。","私が会議室までご案内いたします。","会議室まで私をご案内ください。"]', 1, 'Tự dẫn khách dùng ご案内いたします; yêu cầu khách dẫn mình đảo vai, hỏi về không phù hợp mục đích.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-003-Q1', 'N3-L-UTTERANCE-003', 1, '誘ってくれたことに感謝しながら断るとき、何と言いますか。', '["お誘いありがとうございます、今夜は必ず伺います。","今夜の食事は、私から皆さんにお知らせします。","お誘いありがとうございます、あいにく今夜は都合がつきません。"]', 2, 'Đáp án vừa cảm ơn vừa từ chối khéo vì bận; nhận lời đến hoặc nhận thông báo sai ý.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-004-Q1', 'N3-L-UTTERANCE-004', 1, '先ほど伝えた金額を直してから説明を続けたいとき、何と言いますか。', '["申し訳ありません、先ほどの金額を直させてください。","先ほどの金額について、もう一度説明していただけますか。","先ほどの金額で間違いございません。"]', 0, 'Xin phép sửa thông tin mình đưa ra là 直させてください. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-005-Q1', 'N3-L-UTTERANCE-005', 1, '先輩が自分のために選んでくれたことにお礼を言いたいとき、何と言いますか。', '["お土産を選んでいただきましょうか。","わざわざ選んでくださって、ありがとうございます。","わざわざ選んでさしあげて、ありがとうございます。"]', 1, 'Tiền bối làm cho mình nên dùng くださって; さしあげて đảo chiều cho nhận, phương án cuối là đề nghị tương lai.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-006-Q1', 'N3-L-UTTERANCE-006', 1, '重い荷物を持っているお客様に、申し出るとき何と言いますか。', '["そのお荷物、私の部屋まで運んでいただけますか。","そのお荷物は、こちらでお買い求めになりましたか。","そのお荷物、私がお持ちいたしましょうか。"]', 2, 'Tự đề nghị làm cho khách dùng お持ちいたしましょうか. Câu nhờ khách làm đảo vai, câu kể đã cho mượn sai tình huống.. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-007-Q1', 'N3-L-UTTERANCE-007', 1, '店員に確認を頼みたいとき、何と言いますか。', '["注文した色と違うようなので、確かめていただけますか。","注文した色と同じなので、確かめる必要はありません。","注文した色を私からお決めいたします。"]', 0, 'Nêu khác màu và nhờ kiểm tra đúng mục đích; khẳng định cùng màu hoặc tự quyết màu không xử lý sai hàng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-008-Q1', 'N3-L-UTTERANCE-008', 1, '失礼にならないように、先に帰る必要を伝えるとき何と言いますか。', '["次の約束には、お客様だけでお出かけください。","次の約束がございますので、そろそろ失礼させていただきます。","次の約束がございますので、もっと長くお話しください。"]', 1, 'Nêu lý do rồi xin phép rời đi phù hợp; kéo dài hoặc bảo khách đi thay không đúng.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-009-Q1', 'N3-L-UTTERANCE-009', 1, '上司が戻ったら自分から電話をかけ直すと伝えたいとき、何と言いますか。', '["戻り次第、もう一度お電話いただけますでしょうか。","担当者はただいま外出中でございます。","戻り次第、こちらからお電話いたします。"]', 2, 'こちらからお電話いたします diễn đạt bên mình gọi lại. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-010-Q1', 'N3-L-UTTERANCE-010', 1, '工場の中では写真を撮らないよう、丁寧に頼むとき何と言いますか。', '["工場内での撮影は、ご遠慮ください。","工場内では、自由に撮影してくださって結構です。","工場の写真は、受付でお受け取りください。"]', 0, 'ご遠慮ください yêu cầu kiêng chụp lịch sự. Câu cho phép ngược quy định. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-011-Q1', 'N3-L-UTTERANCE-011', 1, '何と言いますか。', '["この数字はそのままで、見直さなくてもいいよ。","この数字だけ、もう一度見直してもらえるかな。","この数字について、あとで私が説明しておくよ。"]', 1, 'Câu nhờ xem lại nhẹ nhàng phù hợp. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-012-Q1', 'N3-L-UTTERANCE-012', 1, '話し始める前に、質問する許可を求めるとき何と言いますか。', '["何かご質問がございましたら、お知らせください。","質問はございませんので、次へ進んでください。","一点、質問させていただいてもよろしいでしょうか。"]', 2, 'Xin phép mình hỏi dùng 質問させていただいても. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-013-Q1', 'N3-L-UTTERANCE-013', 1, '何と言いますか。', '["資料の整理なら、私が引き受けようか。","私の資料も、あなたが整理しておいて。","資料の整理は終わったことにしておこう。"]', 0, 'Nhận giúp là 引き受けようか; giao thêm việc hoặc giả vờ đã làm không phải giúp đỡ.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-014-Q1', 'N3-L-UTTERANCE-014', 1, '参加者が先生の話を聞くために来たことを伝えるとき何と言いますか。', '["先生は皆さんのお話を伺ってくださいました。","皆さん、先生のお話を伺うためにいらっしゃいました。","皆さん、先生にお話を聞いていただくために参りました。"]', 1, '伺う đặt người tham dự ở phía nghe giáo viên; hai câu khác đổi vai người nói và người nghe.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-015-Q1', 'N3-L-UTTERANCE-015', 1, '直接注意せず、フロントに部屋の状況を確かめてもらいたいとき何と言いますか。', '["隣の部屋の方に、もっと大きな声を出していただきたいです。","隣の部屋には、私がお泊まりになっています。","隣の部屋の声が聞こえるので、様子を見ていただけませんか。"]', 2, 'Nhờ lễ tân xem tình hình đúng mục đích; nói to hơn ngược nhu cầu, câu cuối không yêu cầu và sai vai.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-016-Q1', 'N3-L-UTTERANCE-016', 1, 'これまで教えてもらったことに感謝を伝えるとき何と言いますか。', '["これまでいろいろ教えていただき、本当にありがとうございました。","これからも、この会社でよろしくお願いいたします。","これまで教えてさしあげたことを覚えていますか。"]', 0, '教えていただき cảm ơn việc mình nhận được. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-017-Q1', 'N3-L-UTTERANCE-017', 1, '先輩の作業が終わってから貸してもらうよう頼むとき何と言いますか。', '["お使いになる前に、私に貸していただけますか。","お使いになったあとで、少し貸していただけますか。","今すぐ使うので、作業をやめてください。"]', 1, 'Tôn kính hành động tiền bối bằng お使いになったあと, rồi nhờ cho mượn. Ép dừng ngay trái yêu cầu chờ xong.. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-018-Q1', 'N3-L-UTTERANCE-018', 1, '相手の希望を先に聞いてから、自分の予定を調べたいとき何と言いますか。', '["こちらで日を決めましたので、ご希望は結構です。","こちらの予定をご確認いただいてから、お知らせください。","ご希望の日を伺ってから、こちらの予定を確認いたします。"]', 2, 'Hỏi ngày đối tác trước rồi tự kiểm lịch đúng thứ tự. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-019-Q1', 'N3-L-UTTERANCE-019', 1, 'けんかにならないように、部屋の外で話してもらいたいとき何と言いますか。', '["すみませんが、お電話は外でお願いできますか。","よろしければ、ここでもっと長くお話しください。","お電話の内容を、私にも教えていただけますか。"]', 0, 'Đề nghị ra ngoài lịch sự bằng すみませんが. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-020-Q1', 'N3-L-UTTERANCE-020', 1, '来たことだけ担当者に伝えてもらうとき、受付で何と言いますか。', '["担当の方が戻られるまで、こちらで待たせてください。","私が伺ったことを、お伝えいただけますでしょうか。","私が来たことは、担当者には伝えないでください。"]', 1, 'Mình đến dùng 伺った, nhờ lễ tân chuyển lời bằng お伝えいただけますか. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-021-Q1', 'N3-L-UTTERANCE-021', 1, 'すぐに新しい物を持ってくると伝えるとき何と言いますか。', '["申し訳ございません、新しい物を持ってきていただきます。","お客様がこぼされたので、そのままで結構です。","申し訳ございません、すぐに新しい物をお持ちいたします。"]', 2, 'Tự nhận lỗi và mang đồ mới là お持ちいたします; nhờ khách mang hoặc đổ lỗi trái tình huống.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-022-Q1', 'N3-L-UTTERANCE-022', 1, '翌日、迷惑をかけたこととお礼を伝えるとき何と言いますか。', '["急に任せてしまってごめんね、助かりました。","急に任せてくれてありがとう、私が助けました。","昨日は私が代わりにやってあげたんだよ。"]', 0, 'Nhận mình giao việc và cảm ơn đúng vai; hai câu còn lại tự nhận người giúp.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-023-Q1', 'N3-L-UTTERANCE-023', 1, '忙しそうなので、時間があるときに短く教えてもらうよう頼むとき何と言いますか。', '["今すぐ、私の感想を最後までお聞きください。","お時間のあるときに、一言ご感想をいただければ幸いです。","先生のご感想を、ほかの学生に伝えておきましょうか。"]', 1, 'Nhờ nhận xét khi rảnh đúng mục đích và lịch sự. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-024-Q1', 'N3-L-UTTERANCE-024', 1, '自分が奥で調べるので、少し待ってもらいたいとき何と言いますか。', '["奥で確認いたしますので、一緒に来ていただけますか。","お客様が奥でお調べになってから、お戻りください。","奥で確認してまいりますので、少々お待ちください。"]', 2, 'Tự đi và trở lại dùng てまいります, xin khách đợi. Bảo khách tự kiểm không đúng vai phục vụ.. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-025-Q1', 'N3-L-UTTERANCE-025', 1, '大きく変える必要はありませんが、一か所だけ相談して直したいとき何と言いますか。', '["全体はこのままでいいから、この部分だけ相談しよう。","全部やり直して、相談はしなくてもいいよ。","一か所も変えられないから、見せないでね。"]', 0, 'Giữ tổng thể và cùng bàn một phần đúng yêu cầu; làm lại hết hoặc không được đổi đều trái ý.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-026-Q1', 'N3-L-UTTERANCE-026', 1, '空港まで自分が車で迎えに行くと申し出るとき、何と言いますか。', '["空港まで、私をお迎えになってください。","空港まで、私がお迎えに参りましょうか。","空港までの道を、私に教えていただけますか。"]', 1, 'Mình đến đón dùng お迎えに参る. Hai câu kia đảo vai hoặc dùng tôn kính cho bản thân.. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-027-Q1', 'N3-L-UTTERANCE-027', 1, '一度持ち帰って同僚と相談したいとき何と言いますか。', '["今ここで決まりましたので、相談は不要です。","ご意見には賛成ですから、検討はいたしませんでした。","一度持ち帰って、社内で検討させていただけますか。"]', 2, 'Xin xem xét nội bộ thể hiện chưa kết luận; hai câu khác khẳng định đã quyết hoặc đã đồng ý.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-028-Q1', 'N3-L-UTTERANCE-028', 1, '誰から紹介されたかを丁寧に伝えるとき何と言いますか。', '["山田さんからご紹介いただき、ご連絡いたしました。","山田さんをご紹介したく、ご連絡いたしました。","山田さんにご連絡いただけますでしょうか。"]', 0, 'Nhận giới thiệu dùng ご紹介いただき, tự liên hệ dùng ご連絡いたしました. Hai câu khác sai quan hệ.. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-029-Q1', 'N3-L-UTTERANCE-029', 1, '案内してくれた担当者に、仕事の様子がよく分かったことを伝えてお礼を言うとき何と言いますか。', '["案内は必要ありませんでしたから、もう帰ります。","ご案内のおかげで、仕事の様子がよく分かりました。","ご案内してさしあげたので、よく分かってください。"]', 1, 'Nêu ơn người hướng dẫn đúng vai; tự nhận đã hướng dẫn hoặc bác bỏ việc hướng dẫn không cảm ơn.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-UTTERANCE-030-Q1', 'N3-L-UTTERANCE-030', 1, 'その日は遅れて着くため、最初からは担当できないと伝えるとき何と言いますか。', '["最初から行けるから、受付は全部任せて。","受付の場所は、私が先に調べておくね。","手伝いたいんだけど、着くのが遅いから最初からは難しいんだ。"]', 2, 'Nêu thiện chí và giới hạn thời gian để từ chối phần đầu. Đáp án khác đổi người thực hiện, mục đích hoặc thời điểm nên không diễn đạt đúng ý định trong tranh.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-001-Q1', 'N3-L-RESPONSE-001', 1, '何と答えますか。', '["じゃあ、今日中に資料を仕上げなくてもよさそうだね。","会議の資料は、もう全部印刷してあるよ。","来週は別の会議にも出る予定だよ。"]', 0, '延びた nghĩa hoãn. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-002-Q1', 'N3-L-RESPONSE-002', 1, '何と答えますか。', '["部長の書類は、あとで私にも見せてね。","わかった、戻っていらしたらお渡しするね。","この書類は、部長が作ってくれたんだよ。"]', 1, '〜てもらっといて nhờ sắp xếp để trưởng phòng xem tài liệu. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-003-Q1', 'N3-L-RESPONSE-003', 1, '何と答えますか。', '["その鍵なら、昨日新しいのを買ったよ。","机の上は、あとで片づけておくね。","机の下に落ちてるのは、それじゃない？"]', 2, 'Người nói tìm chìa đã để đây, nên chỉ nơi có thể thấy chìa phù hợp.. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-004-Q1', 'N3-L-RESPONSE-004', 1, '何と答えますか。', '["そんな日もあるよ、次は一緒に練習しよう。","発表の会場は、駅から近くて便利だったね。","練習なら、先週一人でやっておいたよ。"]', 0, 'An ủi và đề nghị luyện cho lần sau đáp tâm trạng sau thất bại. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-005-Q1', 'N3-L-RESPONSE-005', 1, '何と答えますか。', '["一人で全部終わったんだね、お疲れさま。","じゃあ、半分は私が引き受けようか。","その仕事は、来月から始まるそうだよ。"]', 1, 'Ngụ ý cần giúp, nên đề nghị nhận một nửa. Câu chúc mừng hiểu nhầm đã xong.. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-006-Q1', 'N3-L-RESPONSE-006', 1, '何と答えますか。', '["そうだね、値段が安ければ全部おいしいね。","この店の場所なら、前から知っていたよ。","そうだね、さっきのスープは少し薄かったね。"]', 2, 'わけじゃない phủ định khái quát tất cả ngon. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-007-Q1', 'N3-L-RESPONSE-007', 1, '何と答えますか。', '["いや、かばんを持って別の部屋へ行っただけだよ。","田中さんのかばん、私も同じのが欲しいな。","うん、田中さんは今日はまだ来ていないよ。"]', 0, 'Người nghe đính chính suy đoán bằng giải thích nơi đến. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-008-Q1', 'N3-L-RESPONSE-008', 1, '何と答えますか。', '["そのパンなら、駅の店でよく買うよ。","うん、台所の袋に入れてあるよ。","昨日はパンよりご飯が食べたかったな。"]', 1, '〜っけ hỏi xác nhận nhớ lại. Xác nhận đã mua và chỉ chỗ để trả lời rõ.. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-009-Q1', 'N3-L-RESPONSE-009', 1, '何と答えますか。', '["じゃあ、雨が強くても外でできるんだね。","外で使ういすは、先週買っておいたよ。","じゃあ、もう少し天気の様子を見ようか。"]', 2, 'さえやめば đặt điều kiện tạnh mưa. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-010-Q1', 'N3-L-RESPONSE-010', 1, '何と答えますか。', '["一枚は残しといて、もう一枚だけ消して。","同じ写真なら、私も旅行で撮ったことがあるよ。","その写真は、友達がメールで送ってくれたんだ。"]', 0, 'Xin phép xóa bản trùng. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-011-Q1', 'N3-L-RESPONSE-011', 1, '何と答えますか。', '["では、悪い案だと決まったんですね。","では、明日までにもう一度検討しましょう。","その案を考えたのは、田中さんだそうですよ。"]', 1, 'Chưa thể quyết ngay không có nghĩa bác bỏ. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-012-Q1', 'N3-L-RESPONSE-012', 1, '何と答えますか。', '["乗れなかったんだね、次を待とう。","その電車は、一時間に二本出ているよ。","間に合ってよかったね、ずいぶん急いだんだね。"]', 2, 'ところだった là suýt xảy ra nhưng đã tránh. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-013-Q1', 'N3-L-RESPONSE-013', 1, '何と答えますか。', '["日付で分けてみたら、探しやすいんじゃない？","新しい机は、来週会社に届くらしいよ。","書類を作るのは、いつも私の仕事なんだ。"]', 0, 'Người nói cần phân biệt tài liệu mới. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-014-Q1', 'N3-L-RESPONSE-014', 1, '何と答えますか。', '["期待したとおりで、全部よかったんだね。","そうなんだ、どんなところが物足りなかった？","映画の時間は、インターネットで調べられるよ。"]', 1, 'ほどじゃなかった biểu thị chưa đạt kỳ vọng. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-015-Q1', 'N3-L-RESPONSE-015', 1, '何と答えますか。', '["直してほしくないと言われたんだね。","その資料なら、私も昨日読んだよ。","急だね、手伝える所があれば言ってね。"]', 2, 'Thể bị động và ちゃって thể hiện khó xử vì hạn gấp. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-016-Q1', 'N3-L-RESPONSE-016', 1, '何と答えますか。', '["分かった、無理しないでゆっくり休んでね。","分かった、必ず来るって伝えておくね。","飲み会の店は、駅のそばだったよね。"]', 0, '遠慮しとく trong ngữ cảnh là từ chối tham gia. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-017-Q1', 'N3-L-RESPONSE-017', 1, '何と答えますか。', '["駅までなら、今日は歩いて行くつもりだよ。","いいよ、途中のポストに入れてくるね。","その切手は、近くの店でも買えるよ。"]', 1, '依頼 là bỏ thư tiện đường. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-018-Q1', 'N3-L-RESPONSE-018', 1, '何と答えますか。', '["うん、正式に決まったからもう待たなくていいね。","その話をした人とは、去年知り合ったんだ。","うん、正式な連絡が来るまでは待ったほうがいいね。"]', 2, 'Hạn chế thông tin và suy đoán chưa quyết dẫn đến nên chờ xác nhận. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-019-Q1', 'N3-L-RESPONSE-019', 1, '何と答えますか。', '["うん、念のためメールアドレスを確かめてもらえる？","届いた資料は、もう全部読ませてもらったよ。","送る気がなかったっていうことだね。"]', 0, 'Người nói tưởng đã gửi nhưng đối phương chưa nhận. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-020-Q1', 'N3-L-RESPONSE-020', 1, '何と答えますか。', '["長く歩けるなら、その靴で出かけようよ。","足が痛くなるなら、別のをはいたほうがいいよ。","その靴は、駅前の店でも見かけたよ。"]', 1, 'ちょっとね ngụ ý khó dùng để đi lâu. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-021-Q1', 'N3-L-RESPONSE-021', 1, '何と答えますか。', '["そうだね、経験がない人だけに頼もう。","その仕事は、説明の資料があるらしいよ。","そうだね、山田さんに相談してみよう。"]', 2, 'Câu hỏi phủ định đề nghị giao người có kinh nghiệm. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-022-Q1', 'N3-L-RESPONSE-022', 1, '何と答えますか。', '["今からでも、予約できるか聞いてみようか。","先に予約したおかげで、並ばずに済んだね。","予約の電話番号は、案内に書いてあったよ。"]', 0, '後悔 vì chưa đặt. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-023-Q1', 'N3-L-RESPONSE-023', 1, '何と答えますか。', '["全部よく分かったなら、説明はいらないね。","どこがはっきりしなかったか、一緒に整理しよう。","田中さんは、説明するのが仕事なんだよ。"]', 1, 'Lưỡng lự vì hiểu chưa chắc, nên cùng làm rõ. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-024-Q1', 'N3-L-RESPONSE-024', 1, '何と答えますか。', '["うん、帰る道は電車よりバスのほうが近いよ。","今日は早く帰ったほうがよかったんだね。","気にしないで、最後まで一緒にやりたかったから。"]', 2, 'なくてもよかったのに thể hiện áy náy cho người ở lại. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-025-Q1', 'N3-L-RESPONSE-025', 1, '何と答えますか。', '["そうだね、少しずつ覚えていくしかないね。","仕事に慣れた人は、もう全員帰ったよ。","仕事の名前は、受付で聞いてみるといいよ。"]', 0, 'Nhận định khó lúc chưa quen. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-026-Q1', 'N3-L-RESPONSE-026', 1, '何と答えますか。', '["確かに、本人には聞かずに決めよう。","確かに、うわさだけで決めるのはよくないね。","本人の住所なら、ここに書いてあるよ。"]', 1, 'Đề nghị kiểm với người trong cuộc. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-027-Q1', 'N3-L-RESPONSE-027', 1, '何と答えますか。', '["急ぐ必要はないって言ってるんだね。","受付の仕事は、先月から友達がしているよ。","じゃあ、買い物はあとにして先に受付へ行こう。"]', 2, 'なくちゃ là phải làm, ちゃう biểu thị lo lỡ. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-028-Q1', 'N3-L-RESPONSE-028', 1, '何と答えますか。', '["気にしないで、無理に食べなくても大丈夫だよ。","私もその料理は、旅行先で食べたことがあるよ。","料理の作り方は、あとで送っておくね。"]', 0, 'Lời xin lỗi vì phụ công người nấu. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-029-Q1', 'N3-L-RESPONSE-029', 1, '何と答えますか。', '["名前の読み方なら、先生に聞けば分かるよ。","名前のほかに、連絡先も書いてね。","名前を書いた人は、さっき帰ったよ。"]', 1, 'だっけ nhờ nhớ lại yêu cầu. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9'),
('N3-L-RESPONSE-030-Q1', 'N3-L-RESPONSE-030', 1, '何と答えますか。', '["うん、最後まで参加すると伝えておくね。","会場の場所は、メールで送ってあるよ。","ありがとう、今日は休ませてもらうね。"]', 2, 'ことない là không cần. Các phương án còn lại không đáp đúng ý hoặc chuyển sang thông tin khác.', 'AI_CHECKED', 1, 'bc8b069c0ce9')
